// Content for If, When & Whether (node g59, ages 22+, Chapter 7): NEW v2 build to GDD 59 (mechanic-embodying),
// the reproductive-decision heart of Chapter 7 and the adult version of My Choices (g29): whether to have children,
// when, and how many: made with real knowledge, together, and free of pressure in ANY direction. 84 researched,
// India-grounded scenarios across whether-and-why → fertility-for-real → when-and-spacing → if-its-hard →
// free-of-pressure → tools-and-help, each encoded as one of the shared v2 play actions (strike-rewrite / branch /
// sort / reflect / match / role-play / spot): no binary "tap the right card". Lead: strike-rewrite (bust the
// myth), branch (your move), sort. Six modes: whether & why (children are an if/when/whether CHOICE, not the
// assumed default; childfree is a complete, valid life; busts "a woman who doesn't want kids is selfish"), fertility
// for real (calm, honest fertility awareness: the fertile window, age trends for women AND men, preconception
// health & folic acid; busts both "there's always time" and "it just happens instantly"; refuses scare tactics),
// when & spacing (timing, readiness as honest reflection not perfection, spacing & contraception, your own timeline
// not the crowd's), if it's hard (infertility with compassion & realism: ~1 in 6 people, men & women roughly
// equally; options like IVF help many but aren't guaranteed; no false hope, no shame; routes to Many Ways to Family
// g60), free of pressure (the couple's autonomy; resisting "good news" pressure; confronting son-preference and
// sex-selection, ILLEGAL under the PCPNDT Act; refusing a weaponised fertility clock), tools & help (a
// decision-reflection tool, fertility basics, RKSK/public services & clinicians). Even-handed and non-coercive: NO
// pressure toward children or against; childfree and many-paths-to-parenthood equally valid; medically accurate but
// panic-free; NOT medical advice: points to clinicians. Builds on My Choices (g29); pairs with Many Ways to Family
// (g60). India: intense pressure to have children soon and ideally a son; infertility heavily stigmatised
// (especially for women, though male factor is common); sex selection illegal (PCPNDT Act); RKSK & public
// reproductive-health services. gameId "if-when-whether".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"iw-001","cat":"whether-and-why","type":"strike-rewrite","hook":"\"Having children is just what everyone does; it's not really a choice.\"","myth":{"un":"Having children is just what everyone does; it's not really a choice.","re":"Whether to have children is a genuine, personal choice, not a foregone conclusion.","why":"A default isn't the same as a decision."},"relearn":"Whether to have children is a real, personal choice, not an automatic default.","persona":"Sneha","source":"whether is real"},
  {"id":"iw-002","cat":"whether-and-why","type":"strike-rewrite","hook":"\"A woman who doesn't want children is selfish or incomplete.\"","myth":{"un":"A woman who doesn't want children is selfish or incomplete.","re":"Choosing not to have children is a valid, complete life; womanhood is not the same as motherhood.","why":"Worth isn't measured by parenthood."},"relearn":"Choosing to be childfree is a valid, complete life; it isn't selfish or incomplete.","persona":"Sneha","source":"childfree is complete"},
  {"id":"iw-003","cat":"whether-and-why","type":"sort","hook":"Lensy: sort each one: a valid reason to shape this decision, or outside pressure that shouldn't?","items":[{"id":"a","text":"What you and your partner actually want"},{"id":"b","text":"Relatives asking for 'good news'"},{"id":"c","text":"Your readiness and circumstances"},{"id":"d","text":"Neighbours' expectations"},{"id":"e","text":"The life you're honestly building together"},{"id":"f","text":"\"Everyone in the family had kids by now\""}],"bins":[{"id":"valid","label":"Yours to weigh","valence":"pos"},{"id":"pressure","label":"Outside pressure","valence":"neg"}],"key":{"a":"valid","b":"pressure","c":"valid","d":"pressure","e":"valid","f":"pressure"},"relearn":"Your own wishes and readiness are yours to weigh; relatives', neighbours' and the family's expectations are outside pressure.","persona":"any","source":"yours vs pressure"},
  {"id":"iw-004","cat":"whether-and-why","type":"branch","persona":"Karthik","source":"ask whether","hook":"You've never actually asked yourself whether you want children, only when.","steps":[{"prompt":"A friend asks casually if you and your partner want kids. What goes through your mind?","options":[{"text":"That it's fair, and you haven't truly answered it yet","then":"The realisation catches you off guard, and stays with you after.","best":true},{"text":"That of course you want kids. Everyone eventually does","then":"The assumption slides by unexamined, same as always."},{"text":"That you should probably have an answer ready by now","then":"You feel pressure to decide quickly, rather than honestly."},{"text":"That it doesn't really matter, since it'll happen eventually","then":"The real question stays unasked, though it nags enough to raise with your partner tonight."}],"why":"Admitting you haven't answered 'whether' turns a default into a real question."},{"prompt":"That evening, you mention the question to your partner. What do you say?","options":[{"text":"That you'd like to actually ask 'whether', honestly, together","then":"She looks relieved. 'I've wondered too,' she says.","best":true},{"text":"That you assume she already wants kids anyway","then":"She's surprised you never actually checked with her."},{"text":"That it's probably too late to ask that now","then":"The question quietly gets shelved instead of answered."},{"text":"That you'll just go along with whatever she decides","then":"She's quiet for a moment, wishing you'd said what you actually think."}],"why":"Bringing the real question to her, honestly, makes it a shared decision."},{"prompt":"A week later, she brings up the question again and asks what you've concluded so far. What do you tell her?","options":[{"text":"That you're genuinely still working through it, honestly","then":"She nods. 'Good, let's keep talking,' she says.","best":true},{"text":"That you've decided yes, since that's simpler for now","then":"She's surprised by the sudden certainty, and wonders what changed."},{"text":"That you'd rather not revisit it again so soon","then":"The unanswered question just waits for another day."},{"text":"That whatever she wants is fine with you, really","then":"She's left holding a decision meant to be shared."}],"why":"Staying honestly in the process keeps it a real decision, not a shortcut."}],"debrief":"The 'whether' is worth asking deliberately, before the 'when'.","relearn":"Ask the 'whether' question first; don't let a default decide a life-defining choice."},
  {"id":"iw-005","cat":"whether-and-why","type":"match","hook":"Lensy: match each path to what it can be.","pairs":[{"left":"Choosing to have children","right":"A valid, joyful path"},{"left":"Choosing to be childfree","right":"An equally valid, full life"},{"left":"Still deciding","right":"A fine place to be, no rush"},{"left":"Building family another way","right":"A real, chosen route"},{"left":"Choosing never","right":"A settled, respected answer"}],"relearn":"Having children, being childfree, another way, still deciding and 'never' are all valid; none is a failure.","persona":"any","source":"all valid"},
  {"id":"iw-006","cat":"whether-and-why","type":"strike-rewrite","hook":"\"You'll definitely regret it if you don't have children.\"","myth":{"un":"You'll definitely regret it if you don't have children.","re":"Many childfree people live happy, fulfilled lives; regret is not guaranteed in any direction.","why":"Fear of regret isn't a reason to decide either way."},"relearn":"Childfree people can be happy and fulfilled; guaranteed regret is a myth, not a fact.","persona":"Sneha","source":"regret isn't certain"},
  {"id":"iw-007","cat":"whether-and-why","type":"reflect","hook":"Lensy: this is your decision and your partner's, no one else's. How does owning it feel?","prompt":"What do you think?","options":["It's ours","Freeing","Owning it"],"affirm":"Whether and when to have children belongs to you and your partner, not to family or society.","relearn":"Whether and when to have children is yours and your partner's to decide, no one else's.","persona":"any","source":"yours to own"},
  {"id":"iw-008","cat":"whether-and-why","type":"spot","hook":"Lensy: spot the two unhealthy ways the 'whether' question gets decided.","scene":[{"id":"a","text":"Talking it through honestly together","trick":false},{"id":"b","text":"Letting shame decide it for you","trick":true},{"id":"c","text":"Giving yourself permission to choose either way","trick":false},{"id":"d","text":"Caving to pressure just to stop the questions","trick":true},{"id":"e","text":"Knowing either answer can be a good life","trick":false}],"why":"Letting shame decide and caving to pressure are the unhealthy ways; honest talk and permission to choose are healthy.","relearn":"Approach 'whether' with honest talk and permission to choose either way, not shame or pressure.","persona":"any","source":"healthy approach"},
  {"id":"iw-009","cat":"whether-and-why","type":"branch","persona":"Karthik","source":"face the difference","hook":"You and your partner want different things about having children, and it's tense.","steps":[{"prompt":"She brings it up again at dinner, clearly wanting to talk. What do you do?","options":[{"text":"Stay and have the honest conversation, even though it's hard","then":"It's tense, but you both stay in the room and keep talking.","best":true},{"text":"Say you're too tired to talk about any of it tonight","then":"The tension carries into another quiet dinner."},{"text":"Agree with whatever she says, just to avoid the conflict","then":"You said yes to something you don't actually feel."},{"text":"Change the subject to something lighter instead","then":"The real conversation waits for a night that keeps not coming."}],"why":"Honest, repeated talks face a real difference with care, not avoidance."},{"prompt":"A few days later, sensing it isn't fully settled, she asks what's actually underneath your side of things. What do you say?","options":[{"text":"Your honest reasons, even the uncomfortable ones","then":"She listens carefully, and the conversation goes somewhere real.","best":true},{"text":"That you're honestly still not sure what you want","then":"She's left without much to actually respond to."},{"text":"That it's really about timing, not the bigger question","then":"The real difference stays underneath, unnamed."},{"text":"That you'd rather not get into it right now","then":"She feels shut out of something that affects you both."}],"why":"Naming the real reasons, even uncomfortable ones, gets you somewhere true."},{"prompt":"A few days later, you're both calmer. What do you suggest?","options":[{"text":"Keep having these talks regularly until you find common ground","then":"She agrees, relieved the conversation isn't a one-time thing.","best":true},{"text":"Let it rest for now and hope it resolves itself","then":"The difference quietly resurfaces weeks later, unresolved."},{"text":"Ask a mutual friend to help you decide","then":"A friend's opinion adds noise to a choice that's really yours."},{"text":"Say whoever feels more strongly should just decide","then":"One of you gets the answer, and the other carries it quietly."}],"why":"Ongoing talk, instead of silence, keeps the difference something you're working through."}],"debrief":"Differences about children need honest, ongoing conversation, not avoidance.","relearn":"Talk through differences about children honestly; this is too big to avoid."},
  {"id":"iw-010","cat":"whether-and-why","type":"sort","hook":"Lensy: sort each one: a complete, valid life, or a 'failure' the way pressure frames it?","items":[{"id":"a","text":"A fulfilling childfree life"},{"id":"b","text":"'She never had kids, poor thing'"},{"id":"c","text":"A chosen, content single life"},{"id":"d","text":"'They're incomplete without a child'"},{"id":"e","text":"A peaceful life on your own terms"},{"id":"f","text":"'A real family needs a baby'"}],"bins":[{"id":"complete","label":"Complete & valid","valence":"pos"},{"id":"framed","label":"Pressure's false frame","valence":"neg"}],"key":{"a":"complete","b":"framed","c":"complete","d":"framed","e":"complete","f":"framed"},"relearn":"A childfree or chosen single life is complete and valid; 'poor thing', 'incomplete' and 'needs a baby' are pressure's false frames.","persona":"Sneha","source":"complete not failure"},
  {"id":"iw-011","cat":"whether-and-why","type":"reflect","hook":"Lensy: 'not yet', 'never', and 'another way' are all real, respectable answers. Permission granted?","prompt":"What's your take?","options":["Granted","All valid","Good to hear"],"affirm":"'Not yet', 'never' and 'another way' are all legitimate answers to the children question.","relearn":"'Not yet', 'never' and 'another way' are all real, respectable answers.","persona":"any","source":"permission granted"},
  {"id":"iw-012","cat":"whether-and-why","type":"role-play","persona":"Pooja","source":"good-news boundary","hook":"A relative keeps circling back to when you'll start a family.","setup":"At a family visit, she brings it up once more.","steps":[{"prompt":"She asks: \"So, any good news to share yet?\"","options":[{"text":"\"When and whether we have children is something we'll decide ourselves. Thanks for caring.\"","then":"She nods slowly. \"Alright, I understand,\" she says.","best":true},{"text":"\"Soon, soon. Don't worry. It's really not far off now.\"","then":"She smiles, pleased, and mentions it to another relative."},{"text":"\"That's really not something you should be asking about.\"","then":"She looks stung, though she meant it warmly."},{"text":"\"We're thinking about it, actually, more than you'd guess.\"","then":"She treats that as a promising sign and checks in again soon."}],"why":"A warm \"we'll decide ourselves\" holds the boundary without a fight."},{"prompt":"She adds: \"I just want to see the family grow. That's all.\"","options":[{"text":"\"We hear that, and we'll decide it on our own time.\"","then":"She softens, comforted even as the boundary stays firm.","best":true},{"text":"\"You're right. Maybe we shouldn't wait too long now.\"","then":"The comment quietly starts shaping a plan that isn't yours yet."},{"text":"\"That's really our call to make, not yours to weigh in on.\"","then":"She looks hurt, though she only meant to share her hope."},{"text":"\"We'll see how things go, and let you know eventually.\"","then":"She takes the vagueness as room to bring it up again."}],"why":"Naming that you hear her care, while holding the boundary, keeps things warm."},{"prompt":"A week later, she asks gently: \"Have you two thought more about it?\"","options":[{"text":"\"We have, and it's still something we'll decide for ourselves.\"","then":"She nods. \"That's good to hear,\" she says, and lets it rest.","best":true},{"text":"\"Not really. We've been really quite busy lately.\"","then":"She takes 'busy' as a reason to check in sooner next time."},{"text":"\"You really don't need to keep asking about this.\"","then":"She apologises, but the warmth between you cools slightly."},{"text":"\"Honestly, we're really not sure yet, still figuring it all out.\"","then":"She offers her own opinion on what you 'should' decide."}],"why":"A steady, calm answer, held firmly, is what finally settles the question."}],"relearn":"A warm 'we'll decide ourselves' holds the boundary on a deeply personal choice without a fight."},
  {"id":"iw-013","cat":"whether-and-why","type":"strike-rewrite","hook":"\"If you love each other, having children is the obvious next step.\"","myth":{"un":"If you love each other, having children is the obvious next step.","re":"Love is complete in itself; having children is a separate, deliberate choice, not a proof of love.","why":"A relationship doesn't require children to be whole."},"relearn":"Having children is a separate, deliberate choice, not the automatic proof or next step of love.","persona":"any","source":"love needs no proof"},
  {"id":"iw-014","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"There's always plenty of time; fertility doesn't really change with age.\"","myth":{"un":"There's always plenty of time; fertility doesn't really change with age.","re":"Fertility does gradually decline with age, sooner for women, and somewhat for men too, so it's worth knowing for planning.","why":"Knowing the facts helps you plan, calmly."},"relearn":"Fertility gradually declines with age (sooner for women, somewhat for men); knowing this helps calm planning.","persona":"any","source":"age matters, calmly"},
  {"id":"iw-015","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Pregnancy just happens instantly whenever you decide you're ready.\"","myth":{"un":"Pregnancy just happens instantly whenever you decide you're ready.","re":"Conception can take several months even when all is well, and isn't guaranteed on a schedule.","why":"Real timelines are more variable than the movies suggest."},"relearn":"Conception can take months even when all is well; it doesn't happen instantly on demand.","persona":"any","source":"not instant"},
  {"id":"iw-016","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Fertility 'awareness' is really just scaring women into rushing.\"","myth":{"un":"Fertility 'awareness' is really just scaring women into rushing.","re":"Honest fertility facts are tools for your own planning, calm information, never a scare tactic or a deadline imposed on you.","why":"Information empowers; panic manipulates."},"relearn":"Honest fertility facts are calm planning tools you own, not scare tactics or an imposed deadline.","persona":"Sneha","source":"facts not fear"},
  {"id":"iw-017","cat":"fertility-for-real","type":"sort","hook":"Sort: an honest fertility fact, or a panic-driven myth?","items":[{"id":"a","text":"Fertility declines gradually with age"},{"id":"b","text":"After 30 it's basically over"},{"id":"c","text":"Conception can take a few months"},{"id":"d","text":"One 'wrong' year ruins everything"},{"id":"e","text":"Both partners' health can matter"},{"id":"f","text":"Stopping contraception means instant pregnancy"}],"bins":[{"id":"fact","label":"Honest fact","valence":"pos"},{"id":"panic","label":"Panic myth","valence":"neg"}],"key":{"a":"fact","b":"panic","c":"fact","d":"panic","e":"fact","f":"panic"},"relearn":"Gradual decline, months to conceive and both partners mattering are facts; 'over after 30', 'one year ruins it' and instant pregnancy are panic myths.","persona":"any","source":"fact vs panic"},
  {"id":"iw-018","cat":"fertility-for-real","type":"match","hook":"Match each fertility basic to what it means.","pairs":[{"left":"The fertile window","right":"The few days each cycle conception is likeliest"},{"left":"Age and fertility","right":"A gradual decline, faster later for women"},{"left":"Preconception health","right":"Getting healthy before trying helps"},{"left":"Folic acid","right":"Taken before and early in pregnancy, it helps protect development"},{"left":"Both partners","right":"Fertility is a shared matter, never only hers"}],"relearn":"The fertile window, age trends, preconception health, folic acid and both partners are the calm basics of fertility awareness.","persona":"any","source":"fertility basics"},
  {"id":"iw-019","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Preconception health doesn't matter; you only think about health once pregnant.\"","myth":{"un":"Preconception health doesn't matter; you only think about health once pregnant.","re":"Getting healthy before trying, including folic acid, helps; folic acid before and early in pregnancy cuts certain birth defects sharply.","why":"The months before conception count."},"relearn":"Preconception health matters; folic acid before and early in pregnancy sharply cuts certain birth defects.","persona":"Pooja","source":"preconception counts"},
  {"id":"iw-020","cat":"fertility-for-real","type":"reflect","hook":"Lensy: knowing your fertility facts is power, to plan on your terms, not to panic. Sit right?","prompt":"What do you think?","options":["Sits right","On my terms","Power not panic"],"affirm":"Fertility knowledge is for planning on your own terms, calmly, not for panic or pressure.","relearn":"Fertility facts are power to plan on your terms, not a reason to panic.","persona":"any","source":"power not panic"},
  {"id":"iw-021","cat":"fertility-for-real","type":"spot","hook":"Spot the two manipulative fertility lines to catch, among the calm, honest ones.","scene":[{"id":"a","text":"\"Here are the facts, plan your way\"","trick":false},{"id":"b","text":"\"Hurry or you'll miss your only chance\"","trick":true},{"id":"c","text":"\"Both partners' health and age can matter\"","trick":false},{"id":"d","text":"\"Panic now, it's almost too late for you\"","trick":true},{"id":"e","text":"\"A clinician can answer your questions\"","trick":false}],"why":"The caught lines rush and scare you with 'your only chance' and 'too late'; the rest inform calmly.","relearn":"Honest messaging informs and includes both partners; the manipulative kind rushes, scares and cries 'too late'.","persona":"Sneha","source":"honest message"},
  {"id":"iw-022","cat":"fertility-for-real","type":"branch","persona":"Pooja","source":"calm sources","hook":"Late at night, you keep scrolling through fertility posts trying to make sense of it all.","steps":[{"prompt":"Two articles say opposite things about your fertility. What do you do first?","options":[{"text":"Book a clinician slot for real questions","then":"The clinic has an opening next week, and you write down what worries you most.","best":true},{"text":"Read ten more articles until one makes sense","then":"The tenth site says something new, and you feel just as unsure as before."},{"text":"Ask a confident friend what she does","then":"She shares her routine kindly, though your body may not match hers at all."},{"text":"Close the tabs and try not to think about it","then":"The questions quiet down for now, and return again at night."}],"why":"A clinician answers your real questions; ten more articles just add more noise."},{"prompt":"A cousin forwards a message claiming a home remedy fixes fertility fast. What do you do?","options":[{"text":"Check with a clinician, not the forward","then":"She explains kindly what helps, and what is just a forward.","best":true},{"text":"Try the remedy quietly, just in case it works","then":"Nothing changes, and you're unsure if you wasted the weeks."},{"text":"Forward it back asking if anyone has tried it","then":"Relatives reply with more forwards, and nobody has real answers."},{"text":"Ignore it, hoping it doesn't matter","then":"The forward keeps circulating, and doubt lingers with it."}],"why":"A clinician can weigh a home remedy honestly; a forward can't."},{"prompt":"A week later you do see a clinician, and she asks what you most want to know. What do you ask first?","options":[{"text":"Ask about your own fertility plainly","then":"She answers plainly and points you to what comes next.","best":true},{"text":"Ask what a friend's numbers were, for comparison","then":"She says every body differs; your own numbers still wait."},{"text":"Say you're fine and skip past the questions","then":"You leave the clinic with the same doubts you walked in with."},{"text":"Ask her to just confirm everything is normal","then":"She offers to go deeper, but you wave it off to save time."}],"why":"Your own questions, asked plainly, get you real answers instead of comparisons."}],"debrief":"Get fertility facts from a clinician, not panic or false-comfort articles.","relearn":"Seek calm, accurate fertility info from a clinician; skip the panic and false comfort."},
  {"id":"iw-023","cat":"fertility-for-real","type":"match","hook":"Match each partner factor to the calm truth.","pairs":[{"left":"Women's age","right":"Gradual decline, faster after the mid-30s"},{"left":"Men's age and health","right":"Can affect fertility too, it's not only women"},{"left":"Lifestyle","right":"Health habits can support fertility for both"},{"left":"Shared questions","right":"Best taken together to a clinician"},{"left":"Their timeline","right":"Decided by the two of them, on their terms"}],"relearn":"Fertility involves both partners: women's and men's age and health, shared habits, joint questions and their own timeline, calmly understood.","persona":"Karthik","source":"both partners"},
  {"id":"iw-024","cat":"fertility-for-real","type":"reflect","hook":"Lensy: fertility is something to understand, not fear, and it's never only the woman's concern. Agree?","prompt":"What's your take?","options":["Agree","Both of us","Understand not fear"],"affirm":"Fertility is to be understood calmly by both partners, not feared or pinned on women alone.","relearn":"Fertility is a both-partners matter to understand calmly, not to fear or pin on women.","persona":"any","source":"not only her"},
  {"id":"iw-025","cat":"fertility-for-real","type":"sort","hook":"Sort: supports calm, real planning, or feeds anxiety unhelpfully?","items":[{"id":"a","text":"Learning the basics from a clinician"},{"id":"b","text":"Doomscrolling fertility scare posts"},{"id":"c","text":"Both partners getting informed"},{"id":"d","text":"Treating a guideline as a personal deadline"},{"id":"e","text":"Noting your own cycle gently"},{"id":"f","text":"Comparing yourself to every friend's bump"}],"bins":[{"id":"calm","label":"Calm planning","valence":"pos"},{"id":"anxiety","label":"Feeds anxiety","valence":"neg"}],"key":{"a":"calm","b":"anxiety","c":"calm","d":"anxiety","e":"calm","f":"anxiety"},"relearn":"Clinician basics, both partners informed and gentle cycle notes support calm planning; doomscrolling, self-imposed deadlines and bump-comparing feed anxiety.","persona":"any","source":"calm vs anxiety"},
  {"id":"iw-026","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"You must have children immediately after marriage.\"","myth":{"un":"You must have children immediately after marriage.","re":"Timing is yours to choose; there's no rule that children must follow a wedding at once.","why":"A wedding date isn't a fertility deadline."},"relearn":"When to have children is yours to time; there's no rule they must follow marriage immediately.","persona":"Pooja","source":"timing is yours"},
  {"id":"iw-027","cat":"when-and-spacing","type":"sort","hook":"Sort: a sound reason to time or space children, or someone else's agenda?","items":[{"id":"a","text":"Your readiness and stability"},{"id":"b","text":"Relatives wanting a grandchild now"},{"id":"c","text":"Health and recovery between pregnancies"},{"id":"d","text":"Keeping up with friends' families"},{"id":"e","text":"Both partners agreeing on the timing"},{"id":"f","text":"An aunt's 'auspicious year' deadline"}],"bins":[{"id":"sound","label":"Sound reason","valence":"pos"},{"id":"agenda","label":"Someone else's agenda","valence":"neg"}],"key":{"a":"sound","b":"agenda","c":"sound","d":"agenda","e":"sound","f":"agenda"},"relearn":"Your readiness, health and shared agreement are sound reasons to time children; relatives, peers and imposed deadlines are their agenda.","persona":"any","source":"sound vs agenda"},
  {"id":"iw-028","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"Readiness means having everything perfect first.\"","myth":{"un":"Readiness means having everything perfect first.","re":"No one is ever fully 'ready'; readiness is honest reflection on the essentials, not perfection.","why":"Waiting for perfect can mean waiting forever."},"relearn":"Readiness is honest reflection on the essentials, not having everything perfect first.","persona":"Sneha","source":"readiness not perfection"},
  {"id":"iw-029","cat":"when-and-spacing","type":"branch","persona":"Pooja","source":"space on your terms","hook":"You feel pressured to have a second child quickly, though you and your partner want to space them.","steps":[{"prompt":"Your mother-in-law asks when the second one is coming. What do you say?","options":[{"text":"Say the timing is yours and your partner's to decide","then":"She pauses, surprised, then changes the subject for now.","best":true},{"text":"Promise it'll happen soon, just to end the awkward moment","then":"She smiles and brings it up again within the week."},{"text":"Go through your health details so she'll agree to wait","then":"She answers each point, saying relatives will help you recover anyway."},{"text":"Leave it to your husband to deal with her, without talking it through","then":"He mumbles something vague, and the question lands on you again anyway."}],"why":"Naming it as your and your partner's call holds the timing without a fight."},{"prompt":"A cousin mentions she had hers close together and turned out fine. What do you focus on?","options":[{"text":"What spacing actually suits your own health and plans","then":"You realise her timeline was never really about yours.","best":true},{"text":"Whether you're being too cautious compared to her","then":"You start doubting a plan that was working for you."},{"text":"Telling her your reasons in detail to justify yourself","then":"She nods, then asks a few more questions about the reasons."},{"text":"Changing the subject to avoid comparing at all","then":"The comparison stays unspoken, and quietly nags at you."}],"why":"Your own health and plans decide spacing, not a cousin's different story."},{"prompt":"At a family dinner, someone jokes you're 'taking too long' with the second one. What do you do?","options":[{"text":"Say lightly that you're planning it on your own health and terms","then":"The joke lands flat, and the table moves on to other news.","best":true},{"text":"Laugh along and let the comment pass without saying anything","then":"The joke becomes a running line at every dinner after."},{"text":"Snap back that it's really none of anyone's business here","then":"The table goes quiet, and you feel the awkwardness linger."},{"text":"Explain the medical reasons in full detail to justify the wait","then":"Everyone nods, but now they expect updates each time."}],"why":"A light, firm line closes the joke without opening a debate about your body."}],"debrief":"Space children on your own health and circumstances, not on family pressure.","relearn":"Decide spacing on your health and choice; relatives' wishes don't set the timeline."},
  {"id":"iw-030","cat":"when-and-spacing","type":"match","hook":"Match each spacing tool or idea to its role.","pairs":[{"left":"Contraception for spacing","right":"Choosing the gap between children"},{"left":"Recovery time","right":"Health between pregnancies"},{"left":"Honest readiness check","right":"Deciding when, together"},{"left":"A clinician's input","right":"Calm facts on recovery"},{"left":"Revisiting later","right":"Updating as life changes"}],"relearn":"Contraception, recovery time, an honest check, a clinician and revisiting are how couples plan when and how many, on their terms.","persona":"any","source":"spacing tools"},
  {"id":"iw-031","cat":"when-and-spacing","type":"reflect","hook":"Lensy: 'when' and 'how many' are yours to set, revisited as life changes. Feel ownable?","prompt":"What do you think?","options":["Ownable","Mine to set","Yes"],"affirm":"Timing and number of children are yours to decide and revisit as your life and circumstances change.","relearn":"When and how many children are yours to set and revisit as life changes.","persona":"any","source":"yours to set"},
  {"id":"iw-032","cat":"when-and-spacing","type":"spot","hook":"Spot the two things that don't belong in a 'when are we ready' check.","scene":[{"id":"a","text":"Your relationship stability and wishes","trick":false},{"id":"b","text":"Whether the neighbours approve","trick":true},{"id":"c","text":"Your health and practical circumstances","trick":false},{"id":"d","text":"Beating a friend's baby news","trick":true},{"id":"e","text":"What you both actually want","trick":false}],"why":"The neighbours' approval and beating a friend's news don't belong; your relationship, health and shared wishes do.","relearn":"A readiness check is your relationship, wishes, health and circumstances, not others' approval or rivalry.","persona":"any","source":"real readiness check"},
  {"id":"iw-033","cat":"when-and-spacing","type":"branch","persona":"Sneha","source":"own timeline","hook":"Friends are all having babies and you feel behind, though you're not actually ready.","steps":[{"prompt":"A friend announces her second pregnancy in the group chat. What do you do?","options":[{"text":"Congratulate her and check in with your own readiness","then":"You type a warm reply, and notice you don't feel the same pull she does.","best":true},{"text":"Congratulate her and start wondering if you're falling behind","then":"The chat moves on, but the comparison sits with you all evening."},{"text":"Mute the chat so you stop seeing the updates","then":"The updates stop, but the question underneath doesn't."},{"text":"Ask your partner if you should 'catch up' too","then":"He looks confused. 'Catch up to what?' he asks."}],"why":"Checking your own readiness, not the group chat, keeps the choice honestly yours."},{"prompt":"At a work lunch, a colleague asks when you're 'joining the club'. What do you focus on?","options":[{"text":"What you and your partner actually want, not others' timing","then":"You realise you haven't actually asked yourselves that question yet.","best":true},{"text":"How many of your friends already have kids by now","then":"The count makes you feel further behind than before."},{"text":"A vague joke to deflect the question entirely","then":"The table laughs, and the real question stays unanswered."},{"text":"Whether you'd regret waiting too long to decide","then":"The worry gets louder, though nothing about your life has changed."}],"why":"Naming what you actually want beats measuring yourself against a headcount."},{"prompt":"Your partner asks, gently, why you seem unsettled lately. What do you say?","options":[{"text":"That you've been comparing your timeline to everyone else's","then":"He nods. 'Let's figure out what we actually want,' he says.","best":true},{"text":"That everyone else seems ready and you're not, somehow","then":"He reassures you, but the comparison keeps driving the worry."},{"text":"Nothing much, and quickly change the subject instead","then":"The unsettled feeling stays, unnamed, for another week."},{"text":"That maybe you should just start trying already","then":"He agrees, though neither of you has really decided this yet."}],"why":"Naming the real comparison lets you decide from readiness, not fear."}],"debrief":"Set your own timeline for children; don't have one just to keep pace with friends.","relearn":"Honour your own readiness; comparison isn't a reason to have a child now."},
  {"id":"iw-034","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"More children is always better, regardless of what the parents want or can manage.\"","myth":{"un":"More children is always better, regardless of what the parents want or can manage.","re":"How many children is the parents' choice, weighing their wishes, health and circumstances, not a number to maximise.","why":"Family size is a personal decision."},"relearn":"How many children is the parents' choice based on their wishes and circumstances, not a number to maximise.","persona":"any","source":"how many is yours"},
  {"id":"iw-035","cat":"when-and-spacing","type":"reflect","hook":"Lensy: there's no universal 'right time', only your right time, decided together. Land okay?","prompt":"What's your take?","options":["Lands okay","My right time","Together"],"affirm":"There is no universal right time for children, only the time that's right for you, decided together.","relearn":"There's no universal right time for children, only yours, decided together.","persona":"any","source":"your right time"},
  {"id":"iw-036","cat":"when-and-spacing","type":"role-play","persona":"Karthik","source":"timing talk","hook":"You'd like to wait a bit longer before trying for a baby.","setup":"You bring it up gently over the weekend.","steps":[{"prompt":"She asks: \"I feel ready. Are we starting soon?\"","options":[{"text":"\"I want this with you. Can we talk through timing that works for us both?\"","then":"She softens. \"Okay, let's actually talk,\" she says.","best":true},{"text":"\"Fine, whatever you want. I really don't mind either way.\"","then":"She pauses. \"I don't want it to just be my decision,\" she says."},{"text":"\"Not yet, and honestly that's final, so let's leave it there.\"","then":"She looks hurt. \"Can we at least talk about why?\" she asks."},{"text":"\"I guess we could, if you're really that set on starting right now, sure.\"","then":"She hears the hesitation, unsure what you actually want."}],"why":"Naming both the shared want and your timing need opens a fair, honest talk."},{"prompt":"She asks: \"What would need to change for you to feel ready?\"","options":[{"text":"\"Give me a moment. Let me actually think it through honestly.\"","then":"She waits, and your real answer turns out more specific than you thought.","best":true},{"text":"\"I don't know. I just feel like it's too soon.\"","then":"She's left without much to plan around."},{"text":"\"Work needs to calm down first. That's all.\"","then":"She wonders if work will ever feel calm enough."},{"text":"\"Nothing really. I'm just nervous.\"","then":"She nods, though the nervousness alone doesn't tell her much."}],"why":"Asking for real time, honestly, is more useful to her than a guess right now."},{"prompt":"She asks: \"Can we set a rough timeline together, then?\"","options":[{"text":"\"Yes, let's check in every few months and adjust as we go.\"","then":"She smiles. \"That feels fair,\" she says.","best":true},{"text":"\"Sure, whatever date works for you.\"","then":"She's still not sure the plan reflects what you actually want."},{"text":"\"Let's just wait and see how things go.\"","then":"She's left with no real plan to hold onto."},{"text":"\"Only if you promise not to bring it up again till then.\"","then":"She agrees, though it feels more like a truce than a plan."}],"why":"A shared check-in date keeps the timeline something you both actually own."}],"relearn":"Naming both the shared want and your timing need opens a fair conversation instead of a silent concession."},
  {"id":"iw-037","cat":"if-its-hard","type":"strike-rewrite","hook":"\"Infertility is rare and always the woman's fault.\"","myth":{"un":"Infertility is rare and always the woman's fault.","re":"Infertility is common, affecting around 1 in 6 people, and involves men and women roughly equally, male factors are in about a third or more of cases.","why":"It's common, and it's not a woman's fault."},"relearn":"Infertility is common (about 1 in 6) and involves men and women roughly equally; it isn't 'the woman's fault'.","persona":"Reshma","source":"common, not her fault"},
  {"id":"iw-038","cat":"if-its-hard","type":"strike-rewrite","hook":"\"If you're struggling to conceive, you just aren't trying hard enough.\"","myth":{"un":"If you're struggling to conceive, you just aren't trying hard enough.","re":"Difficulty conceiving usually has medical causes and is no one's failing; a clinician can help find out why.","why":"Effort isn't the issue; biology often is."},"relearn":"Trouble conceiving usually has medical causes and is no one's failing; a clinician can help investigate.","persona":"Reshma","source":"not a failing"},
  {"id":"iw-039","cat":"if-its-hard","type":"sort","hook":"Sort: a compassionate, realistic truth about infertility, or a harmful myth?","items":[{"id":"a","text":"Both partners should be evaluated"},{"id":"b","text":"It's shameful and must be hidden"},{"id":"c","text":"Options exist but aren't guaranteed"},{"id":"d","text":"IVF always works if you really want it"},{"id":"e","text":"It's common and no one's fault"},{"id":"f","text":"It's always the woman's failing"}],"bins":[{"id":"true","label":"Compassionate truth","valence":"pos"},{"id":"myth","label":"Harmful myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Both checked, honest options, common and no fault are truths; shame, 'IVF always works', and 'her failing' are myths.","persona":"Reshma","source":"truth vs myth"},
  {"id":"iw-040","cat":"if-its-hard","type":"strike-rewrite","hook":"\"IVF and treatments are a guaranteed fix, so there's nothing to think through.\"","myth":{"un":"IVF and treatments are a guaranteed fix, so there's nothing to think through.","re":"Treatments like IVF help many but don't always succeed and can be demanding; honest, realistic expectations matter.","why":"Real hope is honest, not absolute."},"relearn":"Treatments like IVF help many but aren't guaranteed and can be demanding; realistic expectations matter.","persona":"Reshma","source":"honest hope"},
  {"id":"iw-041","cat":"if-its-hard","type":"branch","persona":"Reshma","source":"get evaluated","hook":"A year of trying hasn't worked, and you're scared and unsure what to do.","steps":[{"prompt":"Your mother-in-law hints it must be something wrong with you. What do you do?","options":[{"text":"Suggest to your husband that you both get evaluated","then":"He agrees quietly, relieved you said it first.","best":true},{"text":"Assume it must be your fault somehow","then":"The assumption settles in, though nothing is actually known yet."},{"text":"Apologise to her, as if it's your fault","then":"She accepts the apology, though nothing is actually known yet."},{"text":"Take a relative's advice to 'just relax more'","then":"The advice offers no real answers, and the worry stays unresolved."}],"why":"Going together for an evaluation turns fear into facts for you both."},{"prompt":"At the health centre, the nurse asks who will be tested first. What do you say?","options":[{"text":"Say you'll both be checked, one after the other","then":"The nurse nods, and books appointments for you both.","best":true},{"text":"Say just check me. It's probably me","then":"Only your part gets checked, and half the picture stays missing."},{"text":"Ask if your husband really needs to come","then":"The nurse explains gently that checking only one side misses half."},{"text":"Say you'll come back another day to decide","then":"The visit ends without either of you being checked."}],"why":"Checking you both together gives an honest, complete picture, not half of one."},{"prompt":"You notice he's been quiet about getting checked himself. What do you say to him?","options":[{"text":"Say it's normal, and you're in this together","then":"He relaxes a little, and agrees to book the test that week.","best":true},{"text":"Tell him not to worry. It's probably nothing","then":"He nods, but the topic quietly drops without a plan."},{"text":"Say you'll go first so he doesn't have to yet","then":"The delay leaves half the picture still missing."},{"text":"Push him to just get it over with","then":"He feels rushed, and puts it off a little longer instead."}],"why":"Naming it together, calmly, keeps you both moving forward as a team."},{"prompt":"Weeks later, nothing feels settled, and you're back at the health centre with the nurse. What do you do?","options":[{"text":"Ask the nurse calmly what the honest next steps are","then":"The nurse lays out real options, without false promises either way.","best":true},{"text":"Decide nothing will ever work","then":"The assumption feels certain, though nothing has actually been decided."},{"text":"Blame yourself for how slow this all feels","then":"The blame settles in, though the slowness points at no one."},{"text":"Decide to just stop asking questions","then":"The uncertainty stays, with nowhere left to take it."}],"why":"Asking for honest next steps keeps you moving, even when the cause isn't clear."}],"debrief":"Infertility is never your fault; get an honest evaluation together instead of blaming yourself.","relearn":"See a clinician together when conceiving is hard; it beats self-blame."},
  {"id":"iw-042","cat":"if-its-hard","type":"match","hook":"Match each route when conceiving is hard to what it offers.","pairs":[{"left":"Medical evaluation","right":"Finding out why, for both partners"},{"left":"Assisted reproduction (e.g. IVF)","right":"An option for some, not a guarantee"},{"left":"Many Ways to Family (g60)","right":"Adoption and other routes to family"},{"left":"A counsellor","right":"Support to carry the feelings"},{"left":"RKSK / public hospital","right":"Affordable evaluation and guidance"}],"relearn":"Evaluation, assisted reproduction, adoption (g60), counselling, and RKSK are all real routes when conceiving is hard.","persona":"Reshma","source":"routes when hard"},
  {"id":"iw-043","cat":"if-its-hard","type":"reflect","hook":"Lensy: infertility is common, it's no one's shame, and you don't have to face it alone. Hear that?","prompt":"What do you think?","options":["I hear it","Not my shame","Not alone"],"affirm":"Infertility is common and never shameful; support, evaluation and options exist, and you needn't face it alone.","relearn":"Infertility is common and no one's shame; support and options exist, and you're not alone.","persona":"Reshma","source":"not your shame"},
  {"id":"iw-044","cat":"if-its-hard","type":"spot","hook":"Spot the two red flags: the harmful responses to a couple facing infertility.","scene":[{"id":"a","text":"\"It's common, and it's not your fault\"","trick":false},{"id":"b","text":"\"You must be doing something wrong\"","trick":true},{"id":"c","text":"\"Let's look at the options calmly together\"","trick":false},{"id":"d","text":"\"One of you is clearly to blame\"","trick":true},{"id":"e","text":"\"You're not alone. We'll get help\"","trick":false}],"why":"'You must be doing something wrong' and 'one of you is to blame' are the red flags. Both shame, neither helps.","relearn":"Catch the blame-and-shame lines; support says 'it's common, not your fault', never 'you're doing it wrong'.","persona":"Reshma","source":"supportive response"},
  {"id":"iw-045","cat":"if-its-hard","type":"strike-rewrite","hook":"\"A couple without a biological child has failed.\"","myth":{"un":"A couple without a biological child has failed.","re":"A family can be whole in many forms; a biological child is one path to family, not the measure of one.","why":"Family is defined by love, not biology alone."},"relearn":"A couple without a biological child hasn't failed; family takes many whole forms.","persona":"Razia","source":"many forms whole"},
  {"id":"iw-046","cat":"if-its-hard","type":"reflect","hook":"Lensy: there are many ways to build a family, and we explore them fully in the next node. Comforting?","prompt":"What's your take?","options":["Comforting","Many ways","Good to know"],"affirm":"Biological children are one route to family; Many Ways to Family (g60) covers the others, all valid.","relearn":"There are many valid ways to build a family; a biological child is one route, not the only one.","persona":"any","source":"many ways"},
  {"id":"iw-047","cat":"if-its-hard","type":"branch","persona":"Razia","source":"stand with her","hook":"Relatives keep shaming your friend Lata for not conceiving yet.","steps":[{"prompt":"At a family function, an aunt loudly asks Lata what's 'wrong' with her. What do you do?","options":[{"text":"Say it's no one's business, and change the subject","then":"Lata glances at you, visibly relieved someone spoke up.","best":true},{"text":"Stay quiet, not wanting to make a scene at the table","then":"Lata stands alone under the whole table's stares."},{"text":"Laugh along nervously to smooth over the moment","then":"The aunt takes the laugh as agreement, and keeps going."},{"text":"Loudly scold the aunt in front of everyone","then":"The scene draws more attention to Lata, not less."}],"why":"Saying it's no one's business and moving on protects her without making a scene."},{"prompt":"Later, Lata quietly tells you the comments have been going on for months. What do you say?","options":[{"text":"Say it's not her fault; offer to go to a clinic together","then":"She exhales, relieved, and says she might take you up on that.","best":true},{"text":"Say she should just try to ignore them completely","then":"She nods, though the comments clearly haven't gotten easier."},{"text":"Ask what she thinks is actually wrong with her","then":"The question lands like another version of the same shame."},{"text":"Tell her to see a doctor immediately, before it gets worse","then":"The advice feels rushed, more about ending the topic than her."}],"why":"Naming it as not her fault, and offering help on her terms, is what she needed most."},{"prompt":"At the next gathering, the same aunt starts up again in front of the whole room. What do you do?","options":[{"text":"Step in calmly, and stay near Lata all evening","then":"The aunt quiets down, and Lata isn't left to face it alone.","best":true},{"text":"Let Lata handle it herself this time","then":"She handles it, though clearly wishes she wasn't alone in it."},{"text":"Avoid the gathering to dodge the tension","then":"Lata faces the same comments, without you there this time."},{"text":"Confront the aunt privately after everyone's left","then":"The private talk changes little for how Lata was treated tonight."}],"why":"Standing beside her in the moment protects her better than a talk after the fact."}],"debrief":"Support someone facing infertility and push back on the shame; never add to the 'good news' pressure.","relearn":"Stand with someone facing infertility; don't join the shaming."},
  {"id":"iw-048","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"It's the family's right to decide when you have children.\"","myth":{"un":"It's the family's right to decide when you have children.","re":"Whether and when to have children is the couple's own decision; family can have feelings but not the final say.","why":"Reproductive choices belong to those who live them."},"relearn":"Whether and when to have children is the couple's decision; family doesn't get the final say.","persona":"Pooja","source":"couple decides"},
  {"id":"iw-049","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"You must keep trying until you have a son.\"","myth":{"un":"You must keep trying until you have a son.","re":"Son-preference is harmful and unjust; daughters and sons are equally valued, and sex selection is illegal in India.","why":"A child's worth has nothing to do with sex."},"relearn":"Son-preference is unjust; daughters and sons are equally valued, and sex selection is illegal in India.","persona":"Razia","source":"no son-preference"},
  {"id":"iw-050","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"Finding out and choosing the baby's sex before birth is a private family matter.\"","myth":{"un":"Finding out and choosing the baby's sex before birth is a private family matter.","re":"Prenatal sex determination and sex selection are illegal in India under the PCPNDT Act, to stop the loss of girls.","why":"The law protects daughters from being selected away."},"relearn":"Prenatal sex determination and sex selection are illegal in India under the PCPNDT Act.","persona":"Razia","source":"PCPNDT"},
  {"id":"iw-051","cat":"free-of-pressure","type":"sort","hook":"Sort: respects the couple's reproductive autonomy, or violates it?","items":[{"id":"a","text":"The couple deciding whether and when"},{"id":"b","text":"Pressure to produce a son"},{"id":"c","text":"Choosing your own family size"},{"id":"d","text":"Demands to conceive on the family's schedule"},{"id":"e","text":"The two of you setting your own timeline"},{"id":"f","text":"Relatives insisting on a grandchild now"}],"bins":[{"id":"respects","label":"Respects autonomy","valence":"pos"},{"id":"violates","label":"Violates it","valence":"neg"}],"key":{"a":"respects","b":"violates","c":"respects","d":"violates","e":"respects","f":"violates"},"relearn":"The couple deciding whether, when and how many respects autonomy; son-pressure and forced schedules violate it.","persona":"Pooja","source":"autonomy or not"},
  {"id":"iw-052","cat":"free-of-pressure","type":"branch","persona":"Pooja","source":"hold the choice","hook":"Your in-laws pressure you and Rohit constantly to conceive, and quickly.","steps":[{"prompt":"At dinner, your mother-in-law asks again when you'll 'start trying'. What do you say?","options":[{"text":"Hold kindly that it's yours and Rohit's to decide","then":"She goes quiet, though her expression stays doubtful.","best":true},{"text":"Say you'll think about it soon, to ease the moment","then":"She takes it as a promise and asks again within the week."},{"text":"Snap that it's none of anyone's business","then":"The table goes tense, and dinner ends earlier than planned."},{"text":"Change the subject to work instead","then":"She lets it go tonight, but circles back at the next meal."}],"why":"A kind, firm boundary protects the choice without a fight or a fake promise."},{"prompt":"Your father-in-law starts mentioning it at every family call. What do you do?","options":[{"text":"Hold a calm boundary each time he brings it up","then":"He notices the boundary holds, and slowly asks less often.","best":true},{"text":"Give him a vague timeline to satisfy him","then":"He repeats the timeline back to you the next time he calls."},{"text":"Avoid his calls to dodge the topic","then":"He mentions it to Rohit instead, and the pressure just shifts."},{"text":"Ask Rohit to handle every call from now on","then":"Rohit fields it alone, and the boundary never quite gets said."}],"why":"A boundary repeated calmly and consistently holds better than dodging or a vague date."},{"prompt":"Rohit tells you the pressure is starting to wear him down too. What do you do together?","options":[{"text":"Agree on one shared line to hold together","then":"You feel steadier, knowing neither of you is holding it alone.","best":true},{"text":"Tell him to just handle his side of the family","then":"He feels alone with it, and the pressure lands harder on him."},{"text":"Suggest avoiding all family events for a while","then":"The pressure pauses, but waits for you at the next gathering."},{"text":"Agree to just give them a rough date to end it","then":"The date becomes a deadline neither of you actually chose."}],"why":"One shared line, held together, is steadier than either of you holding it alone."},{"prompt":"Months later, an aunt announces at a function that 'it's about time' for news. What do you do?","options":[{"text":"Hold a calm boundary, in front of everyone","then":"The room moves on, and the boundary holds in public too.","best":true},{"text":"Laugh it off to avoid an awkward scene","then":"The laugh reads as agreement, and the comments continue."},{"text":"Pull her aside to argue about it privately","then":"The argument settles nothing, and she brings it up again next time."},{"text":"Give a vague answer so the function stays comfortable","then":"The vague answer gets repeated as gossip by the following week."}],"why":"Holding the same calm line in public keeps it as steady as it is in private."}],"debrief":"Hold kindly but firmly that whether and when to conceive is yours; don't surrender it to pressure.","relearn":"Hold your reproductive choice kindly but firmly; don't surrender it to end the pressure."},
  {"id":"iw-053","cat":"free-of-pressure","type":"reflect","hook":"Lensy: a fertility 'clock' should never be weaponised against you, by anyone. This is your decision. Clear?","prompt":"What do you think?","options":["Clear","My decision","Not weaponised"],"affirm":"Your reproductive timeline is yours; a fertility clock should never be used as a weapon to pressure you.","relearn":"Your fertility timeline is yours; it should never be weaponised to pressure you.","persona":"Sneha","source":"not weaponised"},
  {"id":"iw-054","cat":"free-of-pressure","type":"spot","hook":"Spot the two lines that are pressure dressed up as care (the red flags).","scene":[{"id":"a","text":"\"We just want grandchildren now\" pushed relentlessly","trick":true},{"id":"b","text":"Genuine, no-strings support either way","trick":false},{"id":"c","text":"\"When's the good news?\" at every meeting","trick":true},{"id":"d","text":"\"Whatever you decide, we're proud\"","trick":false},{"id":"e","text":"\"Take your time; no rush from us\"","trick":false}],"why":"Relentless grandchild demands and constant 'good news' jabs are pressure; genuine no-strings support is care.","relearn":"Relentless pushing for grandchildren or 'good news' is pressure, not the support it pretends to be.","persona":"any","source":"pressure vs care"},
  {"id":"iw-055","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"Once you have a child, you have to immediately have another so they're not alone.\"","myth":{"un":"Once you have a child, you have to immediately have another so they're not alone.","re":"Whether and when to have another child stays the parents' choice; an only child can thrive too.","why":"Each decision is still yours to make."},"relearn":"Whether to have another child stays the parents' choice; an only child can thrive too.","persona":"Sneha","source":"still your choice"},
  {"id":"iw-056","cat":"free-of-pressure","type":"match","hook":"Match each pressure line to a calm, autonomous reply.","pairs":[{"left":"\"When's the good news?\"","right":"\"We'll share our news in our own time.\""},{"left":"\"You need a son.\"","right":"\"We'll love any child equally.\""},{"left":"\"Hurry, you're not young.\"","right":"\"We're deciding this on our own terms.\""},{"left":"\"The family should decide.\"","right":"\"This stays between the two of us.\""},{"left":"\"You'll regret having no kids.\"","right":"\"My choice is settled; please respect it.\""}],"relearn":"Each pressure line has a calm, autonomous reply that holds your choice without a fight.","persona":"any","source":"calm replies"},
  {"id":"iw-057","cat":"free-of-pressure","type":"reflect","hook":"Lensy: no pressure toward children, no pressure against, just your honest, free choice. Feel respected?","prompt":"What's your take?","options":["Respected","My free choice","No pressure"],"affirm":"The node pushes no answer in any direction; the goal is your honest, free, well-informed choice.","relearn":"No pressure toward children or against, just your honest, free, informed choice.","persona":"any","source":"free choice"},
  {"id":"iw-058","cat":"tools-and-help","type":"branch","persona":"Karthik","source":"reflection tool","hook":"You and your partner keep circling the children question without ever landing on an answer.","steps":[{"prompt":"A friend suggests just picking a date and sticking to it. What do you do?","options":[{"text":"Use a reflection tool for your wishes, readiness and facts","then":"You both sit down and the decision starts to feel like yours.","best":true},{"text":"Pick a date anyway, since it sounds decisive","then":"The date arrives with the same uncertainty still underneath."},{"text":"Ask your parents what they think is right","then":"Your parents say sooner is better, and their answer starts to drown out yours."},{"text":"Avoid deciding and let time pass instead","then":"Another year slips by without the question actually being weighed."}],"why":"A calm reflection of wishes, readiness and facts makes the decision genuinely yours."},{"prompt":"One evening, your partner asks what's really on your mind about children. What do you say?","options":[{"text":"Name your honest readiness, not outside pressure","then":"Your partner nods, recognising the same honest uncertainty in themselves.","best":true},{"text":"Say you're worried what relatives will think","then":"The conversation drifts toward managing others, not deciding for yourselves."},{"text":"Say nothing's holding you back, really","then":"The talk stalls, since the real feeling stays unnamed."},{"text":"Say you just want to match your friends' timeline","then":"The comparison sets the pace, instead of your own readiness."}],"why":"Naming your real readiness, not outside pressure, keeps the reflection honest."},{"prompt":"A relative later asks if you've finally decided. How do you answer?","options":[{"text":"Say you're weighing it calmly, on your own timeline","then":"The relative nods, and the question doesn't turn into pressure.","best":true},{"text":"Say you'll decide once everyone stops asking","then":"The relative laughs, and keeps asking at every visit."},{"text":"Give a vague answer to end the conversation quickly","then":"The vagueness invites the same question again at the next visit."},{"text":"Say you're basically decided, just to satisfy them","then":"The half truth feels easier now, and harder to walk back later."}],"why":"Naming your own calm timeline keeps the decision yours, not something rushed for others."}],"debrief":"Work the decision through a calm reflection of your wishes, readiness and facts.","relearn":"Use a calm reflection of wishes, readiness and facts; don't let pressure and panic decide."},
  {"id":"iw-059","cat":"tools-and-help","type":"match","hook":"Match each tool or service to what it's for.","pairs":[{"left":"The decision-reflection tool","right":"Thinking it through, pressure-free"},{"left":"Fertility basics & a clinician","right":"Accurate facts and real care"},{"left":"Public services (e.g. RKSK)","right":"Reproductive health support in India"},{"left":"Many Ways to Family","right":"Adoption and other paths"},{"left":"A firm, calm boundary","right":"Holding off the 'good news' pressure"}],"relearn":"A reflection tool to decide, a clinician for facts, RKSK for support, g60 for other paths, and a boundary against pressure.","persona":"any","source":"the toolkit"},
  {"id":"iw-060","cat":"tools-and-help","type":"strike-rewrite","hook":"\"This is medical advice you can just follow off an app.\"","myth":{"un":"This is medical advice you can just follow off an app.","re":"This game gives general information to help you think and ask better questions; a clinician gives medical advice.","why":"An app informs; a doctor diagnoses."},"relearn":"This is general information to help you think and ask, not medical advice; a clinician gives that.","persona":"any","source":"not medical advice"},
  {"id":"iw-061","cat":"tools-and-help","type":"sort","hook":"Sort: a healthy support for this decision, or a harmful pressure to avoid?","items":[{"id":"a","text":"Accurate facts from a clinician"},{"id":"b","text":"Scare-tactic fertility posts"},{"id":"c","text":"Honest talk with your partner"},{"id":"d","text":"Relatives' constant deadlines"},{"id":"e","text":"Public services like RKSK"},{"id":"f","text":"'Good news' pressure from neighbours"}],"bins":[{"id":"support","label":"Healthy support","valence":"pos"},{"id":"pressure","label":"Harmful pressure","valence":"neg"}],"key":{"a":"support","b":"pressure","c":"support","d":"pressure","e":"support","f":"pressure"},"relearn":"Clinician facts, honest partner talk and RKSK support the decision; scare posts, relatives' deadlines and 'good news' pressure it.","persona":"any","source":"support vs pressure"},
  {"id":"iw-062","cat":"tools-and-help","type":"reflect","hook":"Lensy: whether, when, how many, and what if it's hard, you've now got calm ways through all of it. Ready?","prompt":"What do you think?","options":["Ready","Calm ways through","Got it"],"affirm":"Whether, when, how many and the if-it's-hard path each now have calm, informed ways through.","relearn":"You hold calm, informed ways through whether, when, how many, and if it's hard.","persona":"any","source":"ways through"},
  {"id":"iw-063","cat":"tools-and-help","type":"branch","persona":"Reshma","source":"ask early","hook":"You're not sure if a worry about fertility or conceiving needs a doctor yet.","steps":[{"prompt":"A relative says worrying this early is silly. What do you do?","options":[{"text":"Ask a clinician anyway: you needn't be sure first","then":"You call and get a same-week appointment with a clinician.","best":true},{"text":"Wait and worry until it feels like a crisis","then":"The worry sits unanswered a while longer, growing heavier, until you finally go."},{"text":"Agree it's probably silly and drop it","then":"The worry doesn't actually leave, and it quietly brings you to the clinic anyway."},{"text":"Ask the relative what she thinks it might be","then":"She guesses kindly, though you go to the clinic anyway for a real answer."}],"why":"Asking a clinician gives real clarity; you don't need to be certain first to ask."},{"prompt":"At the clinic, the doctor asks how long you've been worried. What do you say?","options":[{"text":"Answer honestly, whatever the timeline has been","then":"She takes the worry seriously and checks it properly.","best":true},{"text":"Say it's been ages, to sound more serious","then":"The exaggeration doesn't change the check, just adds an odd note."},{"text":"Say you're not really sure, maybe overreacting a bit","then":"She reassures you gently, though the actual worry stays half explained."},{"text":"Downplay it so the visit feels shorter","then":"The shortened version means she misses part of what's bothering you."}],"why":"Answering honestly, however short the worry's been, gets you the fullest, most useful answer."},{"prompt":"A friend later asks if it was worth bothering the doctor about it. What do you say?","options":[{"text":"Say you needn't be sure to get checked","then":"Your friend nods, and quietly notes the clinic's number for herself.","best":true},{"text":"Say maybe it was a bit much to bother the doctor","then":"Your friend decides she won't bother a doctor with her own worry either."},{"text":"Laugh it off and change the subject","then":"Your friend lets it go, and never mentions her own worry."},{"text":"Say it's only worth going once you're sure","then":"Your friend nods, and decides to wait until she's certain."}],"why":"Naming that you needn't be certain first shows her early clarity is worth seeking too."}],"debrief":"You can see a clinician while unsure; you needn't be certain to get checked or reassured.","relearn":"See a clinician while unsure; you needn't wait for a crisis to get checked."},
  {"id":"iw-064","cat":"tools-and-help","type":"match","hook":"Match a moment to the tool that fits it.","pairs":[{"left":"Deciding whether or when","right":"The reflection tool, pressure-free"},{"left":"Wanting real fertility facts","right":"A clinician or trusted service"},{"left":"Facing pressure or shame","right":"A boundary line and support"},{"left":"Trouble conceiving","right":"RKSK or a health centre"},{"left":"Wondering about other paths","right":"Many Ways to Family"}],"relearn":"Each moment has a fit: reflection to decide, a clinician for facts, a boundary against pressure, RKSK for trouble, g60 for other paths.","persona":"any","source":"moment to tool"},
  {"id":"iw-065","cat":"tools-and-help","type":"spot","hook":"Spot the two red-flag ways to make this big decision.","scene":[{"id":"a","text":"Honest reflection plus accurate facts","trick":false},{"id":"b","text":"A panicked rush to beat a 'deadline'","trick":true},{"id":"c","text":"Deciding with your partner, on your terms","trick":false},{"id":"d","text":"Letting relatives' pressure decide it","trick":true},{"id":"e","text":"Asking a clinician what you don't know","trick":false}],"why":"A panicked rush to beat a deadline and letting relatives decide both surrender the choice; reflection, partnership and a clinician keep it yours.","relearn":"Make this decision through honest reflection, facts and partnership, not a panicked rush or relatives' pressure.","persona":"any","source":"sustainable decision"},
  {"id":"iw-066","cat":"tools-and-help","type":"reflect","hook":"Lensy: this is one of life's biggest choices, and now it's an informed, unpressured, shared one. Feel ready to own it?","prompt":"What's your take?","options":["Ready to own it","Informed & free","Yes"],"affirm":"The whether/when/how-many decision is best made informed, unpressured and shared; now you're equipped to own it.","relearn":"This big choice is now an informed, unpressured, shared one, and it's yours to own.","persona":"any","source":"own the choice"},
  {"id":"iw-067","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"set the tone","hook":"The children question has never really been discussed between you two.","setup":"You want to set the tone together.","steps":[{"prompt":"They ask: \"So, how do we even start thinking about this?\"","options":[{"text":"\"Let's decide it with honest facts, no pressure.\"","then":"They nod, relieved. \"Just the two of us. I like that.\"","best":true},{"text":"\"Let's see what everyone else expects of us first.\"","then":"They frown. \"Their opinions again? I'd rather hear what we think.\""},{"text":"\"Let's not get into this. What's for dinner?\"","then":"They sigh. \"Every time I bring it up, we change the subject. I'd like us to actually talk.\""},{"text":"\"Whatever you think is fine with me.\"","then":"They pause. \"I don't want to carry this alone. What do you think?\""}],"why":"Naming honest facts and no pressure sets a tone that's genuinely shared from the start."},{"prompt":"They ask: \"What if we don't agree once we actually start?\"","options":[{"text":"\"We talk it through and revisit it as we grow.\"","then":"They relax, hearing that disagreement isn't a dead end.","best":true},{"text":"\"Then I guess one of us gives in.\"","then":"They go quiet. \"One of us? Which one?\""},{"text":"\"Let's just avoid disagreeing, then.\"","then":"They shift in their seat. \"We can't just never disagree.\""},{"text":"\"We'll cross that bridge if it happens, I suppose.\"","then":"They nod slowly. \"Okay. I still wish we knew what happens then.\""}],"why":"Naming that you'll talk it through and revisit it answers the fear of disagreement honestly."},{"prompt":"Later, a relative asks: \"So what have you two actually decided?\"","options":[{"text":"\"We're deciding it together, on our own time.\"","then":"The relative nods, and the question doesn't return that visit.","best":true},{"text":"\"We haven't yet. Everyone keeps asking though.\"","then":"The relative sighs. \"We only ask because we care.\""},{"text":"\"Whatever works out, I suppose.\"","then":"The relative leans in. \"Works out how? Are you trying?\""},{"text":"\"That's really between us, isn't it?\"","then":"The relative stiffens. \"I only asked. No need for that tone.\""}],"why":"Naming it as a shared, unhurried decision keeps the answer calm and genuinely yours."}],"relearn":"Setting an informed, pressure-free, revisitable tone keeps the decision yours rather than the family's."},
  {"id":"iw-068","cat":"tools-and-help","type":"strike-rewrite","hook":"\"There's no real way to make this choice well; you just hope it works out.\"","myth":{"un":"There's no real way to make this choice well; you just hope it works out.","re":"You can make it well, with honest reflection, accurate facts, partnership and freedom from pressure.","why":"Big choices are navigable with the right tools."},"relearn":"You can make this choice well using honest reflection, accurate facts, partnership and freedom from pressure.","persona":"any","source":"navigable choice"},
  {"id":"iw-069","cat":"whether-and-why","type":"role-play","persona":"Sneha","source":"reassure childfree","hook":"A friend has been carrying something heavy, unsure how you'll react.","setup":"She looks at you and takes a breath before speaking.","steps":[{"prompt":"She says: \"I don't think I want kids, and I feel awful even saying it.\"","options":[{"text":"\"That's a completely valid choice. You don't owe anyone children.\"","then":"She exhales, and some of the guilt visibly lifts from her face.","best":true},{"text":"\"You'll change your mind. Everyone eventually does, you know.\"","then":"She nods politely, but something in her closes off."},{"text":"\"Are you sure? That's a pretty big thing to decide.\"","then":"She feels she now has to defend a feeling she'd trusted you with."},{"text":"\"Don't feel guilty, honestly. It's really not a big deal.\"","then":"She nods, but her shoulders stay tense, the guilt still sitting there."}],"why":"Affirming that childfree is valid, plainly, lets her decide free of guilt."},{"prompt":"She adds: \"My mother keeps saying I'll be lonely without kids.\"","options":[{"text":"\"That's her worry talking, not a fact about your actual life.\"","then":"She nods slowly, like something's clicking into place.","best":true},{"text":"\"She might honestly have a bit of a point, though.\"","then":"Her face falls; that's the exact worry she was hoping you'd talk her out of."},{"text":"\"Just ignore her. Honestly, it's easier that way.\"","then":"The worry keeps quietly resurfacing, unaddressed."},{"text":"\"Maybe you should explain your reasons to her properly.\"","then":"She sighs. \"I don't want to have to defend this to her,\" she says."}],"why":"Naming her mother's worry as fear, not fact, helps the guilt actually lift."},{"prompt":"Weeks later, she says: \"The guilt crept back in again.\"","options":[{"text":"\"It's valid. I'll say it as many times as you need.\"","then":"She smiles. \"Thank you. It helps to hear it,\" she says.","best":true},{"text":"\"Maybe talk to someone else. I'm not sure I'm the right person.\"","then":"She's a little surprised; she came to you, and this feels like a redirect."},{"text":"\"I thought we'd already settled this the other week.\"","then":"She feels a little embarrassed for needing reassurance again."},{"text":"\"It'll pass eventually. Honestly, don't worry about it.\"","then":"The guilt isn't really addressed, just waved off."}],"why":"Steady, warm support is what makes it land, however often it's needed."}],"relearn":"Affirming that childfree is valid, with no 'you'll change your mind', lets her decide free of guilt."},
  {"id":"iw-070","cat":"fertility-for-real","type":"role-play","persona":"Karthik","source":"shared learning","hook":"Your partner Ritu brushes off learning fertility basics, calling it 'her department'.","setup":"Tonight she's quiet after work, then finally looks up.","steps":[{"prompt":"Ritu says: \"I found a fertility app. I'll just handle it. Don't worry.\"","options":[{"text":"\"It's both of us. Let's learn this together.\"","then":"She pauses, then says, \"Okay, let's go through it together.\"","best":true},{"text":"\"Sure, you're better at this stuff anyway.\"","then":"She shrugs. \"If you say so.\" She closes the app without another word."},{"text":"\"Just tell me the important parts later.\"","then":"She nods. \"Sure.\" The learning stays entirely hers."},{"text":"\"I trust you to sort it all out.\"","then":"She smiles, tired. \"Someone has to,\" she says quietly."}],"why":"Naming it as both-of-us turns 'her department' into something you actually share."},{"prompt":"A week later, Ritu asks: \"Did you actually read any of what I sent you?\"","options":[{"text":"\"Yes, I had a question about folic acid.\"","then":"She brightens and pulls up the article to go through it together.","best":true},{"text":"\"Not yet, but I will this weekend.\"","then":"She sighs. \"That's what you said last weekend too.\""},{"text":"\"Why does it matter if I read it or not?\"","then":"She stiffens. \"Because I'm tired of carrying this alone.\""},{"text":"\"I skimmed it, looked fine to me.\"","then":"She frowns. \"Skimming isn't really reading it.\""}],"why":"A real question shows you actually engaged with what she shared."},{"prompt":"At the clinic, the doctor asks a general question and looks between you both. Ritu says: \"Go ahead, jump in.\"","options":[{"text":"\"Let's answer this one together.\"","then":"The doctor nods, and Ritu relaxes beside you, pleased you jumped in.","best":true},{"text":"\"I'll let Ritu answer. She knows it better.\"","then":"Ritu answers alone, a little disappointed you stepped back."},{"text":"\"I'm not totally sure, but I think it's fine.\"","then":"The doctor waits, and the moment feels shakier than it needed to."},{"text":"\"Can we come back to that question later?\"","then":"The doctor moves on, and the question goes unanswered for now."}],"why":"Jumping in together shows the learning was actually shared, not just promised."}],"relearn":"Framing fertility as a both-of-us thing corrects the 'her department' default and shares the planning."},
  {"id":"iw-071","cat":"fertility-for-real","type":"branch","persona":"Pooja","source":"calm not panic","hook":"An influencer's fertility video has left you spiraling about being too late at 33.","steps":[{"prompt":"The post says your fertility 'ends' this year. What do you do right now?","options":[{"text":"Close the app and book time with a clinician","then":"You trade the scare for a real conversation about your own body.","best":true},{"text":"Share the post with your partner in a panic","then":"He gets anxious too, and neither of you has real facts yet."},{"text":"Search for ten more posts to check if it's true","then":"Every post disagrees with the last, and the panic only grows."},{"text":"Decide to start trying immediately, ready or not","then":"You rush into a huge decision before you've caught your breath."}],"why":"A clinician gives facts about your own body; a scare post never can."},{"prompt":"A few days later, you sit down with a clinician. What do you say when she asks what's worrying you?","options":[{"text":"Share the post's claim and ask what's actually true for you","then":"She explains gently how fertility really changes with age.","best":true},{"text":"Say nothing and ask her to just check everything","then":"She checks what she can, and mentions gently that fertility changes gradually, though your specific worry stays unspoken."},{"text":"Downplay it and say you're only there out of curiosity","then":"She keeps the visit general, but you leave with a calmer sense of how fertility actually works."},{"text":"Ask her to confirm the post's exact numbers","then":"She says the post oversimplifies; your own facts differ."}],"why":"Naming the actual worry gets you an answer that fits you, not the post."},{"prompt":"A week later, the same influencer posts an even scarier claim. What's your move?","options":[{"text":"Remember what the clinician told you and let the post go","then":"The claim loses its grip, since you already have your own facts.","best":true},{"text":"Screenshot it to ask the clinician urgently again","then":"She reassures you again, kindly, with the same calm facts as before."},{"text":"Panic all over again and doubt what you were told","then":"The fear returns, even though nothing about your body has changed."},{"text":"Mute the influencer without processing the worry","then":"The post is gone, but the leftover doubt quietly stays."}],"why":"Facts you already have outlast a scarier post; you don't need new ones."}],"debrief":"Replace fertility panic with calm facts from a clinician, not a rushed fear-decision.","relearn":"Get calm, personal facts from a clinician; don't let a scare post rush a huge decision."},
  {"id":"iw-072","cat":"when-and-spacing","type":"role-play","persona":"Pooja","source":"second-child reply","hook":"Family keeps hinting that you should hurry your family planning along.","setup":"At a family gathering, someone brings it up again.","steps":[{"prompt":"A relative asks: \"So when's the second one coming?\"","options":[{"text":"\"We'll decide if and when, on what's right for us. Thanks for the love.\"","then":"She smiles and moves on to other family news.","best":true},{"text":"\"Soon, I suppose, whenever you all want it to happen.\"","then":"She takes it as good as confirmed and tells the next relative."},{"text":"\"Why does everyone keep asking me this same question?\"","then":"She looks taken aback. \"I'm just curious, beta,\" she says."},{"text":"\"We're still thinking about it, honestly, nothing decided quite yet.\"","then":"She treats 'thinking about it' as a decision already leaning yes."}],"why":"\"If and when, on our terms\" needs no explaining and holds the timing calmly."},{"prompt":"Another relative, overhearing, adds: \"You shouldn't wait too long, you know.\"","options":[{"text":"\"We're planning this on our own terms, and we're at peace with it.\"","then":"She nods slowly, unsure how to argue with that.","best":true},{"text":"\"Maybe you're right. We should probably hurry things along a bit.\"","then":"The comment quietly starts to worry you more than it should."},{"text":"\"That's really not your decision to make, if I'm honest.\"","then":"She looks stung, though she meant it as care."},{"text":"\"I guess whatever happens will happen.\"","then":"She takes the vagueness as room to keep asking."}],"why":"Naming that you're at peace with the plan answers the push without a fight."},{"prompt":"At the end of the evening, your mother-in-law asks quietly: \"Is everything alright, timing-wise?\"","options":[{"text":"\"Everything's fine. We're just deciding together, in our own time.\"","then":"She relaxes. \"That's all I wanted to know,\" she says.","best":true},{"text":"\"Everything's fine. Don't worry about it.\"","then":"She isn't fully reassured, and asks again a few weeks later."},{"text":"\"Honestly, we're a bit tired of the questions.\"","then":"She apologises, though the tiredness lingers between you."},{"text":"\"I don't really know, to be honest.\"","then":"She looks a little worried on your behalf."}],"why":"Naming that you're deciding together, calmly, closes the worry kindly."}],"relearn":"A light 'if and when, on what's right for us' holds your timing without conflict."},
  {"id":"iw-073","cat":"when-and-spacing","type":"sort","hook":"Sort: a healthy input into timing, or pressure to ignore?","items":[{"id":"a","text":"Your own readiness and health"},{"id":"b","text":"A festival 'auspicious' deadline imposed on you"},{"id":"c","text":"Your partner's honest view"},{"id":"d","text":"Competing with a cousin's family"},{"id":"e","text":"A clinician's note on recovery"},{"id":"f","text":"A scary post saying 'hurry, it's too late'"}],"bins":[{"id":"healthy","label":"Healthy input","valence":"pos"},{"id":"ignore","label":"Pressure to ignore","valence":"neg"}],"key":{"a":"healthy","b":"ignore","c":"healthy","d":"ignore","e":"healthy","f":"ignore"},"relearn":"Your readiness, health, partner's view and a clinician's note are healthy inputs; imposed deadlines, competition and scare posts are pressure.","persona":"any","source":"input vs pressure"},
  {"id":"iw-074","cat":"when-and-spacing","type":"match","hook":"Match each 'when' question to who it really belongs to.","pairs":[{"left":"Whether you're ready","right":"You and your partner"},{"left":"How to space children","right":"You, with health guidance"},{"left":"Your family size","right":"Your decision, not the relatives'"},{"left":"When to revisit the plan","right":"Yours, as life changes"},{"left":"The relatives' preferred date","right":"A wish, not a rule"}],"relearn":"Readiness, spacing, family size and revisiting belong to the couple; the relatives' date is only a wish.","persona":"any","source":"whose when"},
  {"id":"iw-075","cat":"if-its-hard","type":"role-play","persona":"Karthik","source":"hold them","hook":"You and your partner just got a hard fertility result.","setup":"Tonight you sit close and hold them gently.","steps":[{"prompt":"Your partner says: \"I feel like such a failure.\"","options":[{"text":"\"This isn't failure. We face it together, with help.\"","then":"They lean into you, and their breathing slows a little.","best":true},{"text":"\"Maybe we just weren't meant to have this happen at all.\"","then":"They go quiet, and the words seem to confirm their fear."},{"text":"\"Don't say that. You're being dramatic.\"","then":"They pull back slightly, feeling dismissed rather than heard."},{"text":"\"The doctor will figure something out.\"","then":"They nod slowly. \"I know. But right now it just feels heavy.\""}],"why":"Saying it isn't failure and you'll face it together, with help, meets the feeling instead of brushing past it."},{"prompt":"A little later they ask: \"Do you still see a future with me in it?\"","options":[{"text":"\"Yes, in every version I picture, no matter what.\"","then":"They finally cry, the fear behind the question let out.","best":true},{"text":"\"Of course, why would you even ask that?\"","then":"They shrink a little, sorry for having asked at all."},{"text":"\"Let's not talk about the future right now, please.\"","then":"The question hangs there, unanswered, and they feel smaller."},{"text":"\"We'll see how the treatment goes first.\"","then":"It sounds like a condition, though you didn't mean it that way."}],"why":"A plain, unconditional yes answers the real fear under the question."},{"prompt":"The next morning they say: \"I don't want to talk about this with anyone else yet.\"","options":[{"text":"\"That's your call. I'll follow your pace on this.\"","then":"They relax, glad the choice is actually theirs.","best":true},{"text":"\"But my mother will keep asking. What do I say?\"","then":"They tense up, feeling their wish weighed against others already."},{"text":"\"Okay, but we should tell someone eventually.\"","then":"The eventually lands like a deadline they didn't ask for."},{"text":"\"Fine, I won't say a word to anyone ever.\"","then":"They go quiet. \"Never? I didn't ask for never. Just not yet.\""}],"why":"Following their pace, without conditions, respects a choice that's really theirs to make."}],"relearn":"Naming that it's not a failure, and facing it together with help, holds your partner and keeps you a team."},
  {"id":"iw-076","cat":"if-its-hard","type":"branch","persona":"Reshma","source":"choose with care","hook":"Treatment hasn't worked yet, and you're exhausted, unsure whether to continue.","steps":[{"prompt":"Your husband asks gently how you're really feeling about it. What do you tell him?","options":[{"text":"Say you're exhausted, and need space to grieve","then":"He nods, and sits with you quietly instead of rushing ahead.","best":true},{"text":"Say you're fine, and should just push on","then":"He believes you, though the exhaustion doesn't actually lift."},{"text":"Say you don't know, and change the subject","then":"The real feeling stays unspoken between you both."},{"text":"Say it's hopeless and you'll decide tonight, exhausted","then":"The decision feels final before you've really talked it through."}],"why":"Naming the exhaustion honestly opens space to grieve before deciding anything."},{"prompt":"A relative says stopping treatment would mean 'giving up too easily'. What do you say?","options":[{"text":"Say either choice here is caring, not giving up","then":"She pauses, unsure how to argue with something said so plainly.","best":true},{"text":"Agree, and push yourself to continue anyway","then":"You push on for now, carrying more than you actually have room for."},{"text":"Get angry that she'd say that at all","then":"The anger passes, but the real question stays unanswered."},{"text":"Avoid her, so she can't say it again","then":"The comment lingers, unanswered, in the back of your mind."}],"why":"Naming either choice as caring, not giving up, protects your real decision."},{"prompt":"At the clinic, the counsellor asks what honest information would help you decide. What do you ask?","options":[{"text":"Ask honestly what the next round would really involve","then":"She explains plainly, without promising more than is true.","best":true},{"text":"Ask her to just tell you what to do","then":"She gently says it has to be your decision, not hers."},{"text":"Ask if there's a guaranteed way to make it work","then":"She explains kindly that nothing here can be guaranteed."},{"text":"Avoid asking anything, feeling too tired to hear it","then":"You leave with the same uncertainty you walked in with."}],"why":"Asking for honest information is what lets you choose from care, not fear."},{"prompt":"That night, your husband asks what you're leaning toward. What do you say?","options":[{"text":"Say you need a little more time before deciding","then":"He says that's fine, and there's no rush from his side.","best":true},{"text":"Say you'll decide whatever he thinks is best","then":"He hesitates, not wanting the whole choice to rest on him."},{"text":"Say you'll tell the family your final answer tomorrow","then":"He asks gently whether the two of you have decided yet, or you just want the questions to stop."},{"text":"Say you'll continue, so no one can say you gave up","then":"He goes quiet, and asks whether that reason is yours or theirs."}],"why":"Taking real time to decide protects the choice from being made out of exhaustion."},{"prompt":"A week later, you and your husband sit down to actually decide. How do you begin?","options":[{"text":"Share honestly what you each want, without pressure","then":"Between you, the decision starts to feel like it's actually yours.","best":true},{"text":"Let him decide, since he's been steadier through it","then":"The choice becomes his, though it was meant to be shared."},{"text":"Decide quickly, just to end the uncertainty","then":"The quick decision settles the waiting, but not the doubt underneath."},{"text":"Ask the relative what she would do in your place","then":"She gives a firm view, and the choice starts to feel like the family's."}],"why":"Sharing honestly, without pressure, is what makes the choice truly yours together."}],"debrief":"When treatment is hard, allow grief and honest counsel and choose without shame.","relearn":"Continuing or stopping treatment is a caring choice, not 'giving up'."},
  {"id":"iw-077","cat":"if-its-hard","type":"sort","hook":"Sort: a compassionate truth to hold onto, or a cruel myth to drop?","items":[{"id":"a","text":"Infertility is common and not your fault"},{"id":"b","text":"It's a punishment you deserve"},{"id":"c","text":"Family can take many whole forms"},{"id":"d","text":"You're 'less of a man or woman'"},{"id":"e","text":"Support and options both exist"},{"id":"f","text":"It's a curse you must hide"}],"bins":[{"id":"hold","label":"Compassionate truth","valence":"pos"},{"id":"drop","label":"Cruel myth","valence":"neg"}],"key":{"a":"hold","b":"drop","c":"hold","d":"drop","e":"hold","f":"drop"},"relearn":"'Common, not your fault', 'family takes many forms', 'support exists' are truths; punishment, 'less of a person', and 'a curse' are cruel myths.","persona":"Reshma","source":"hold vs drop"},
  {"id":"iw-078","cat":"free-of-pressure","type":"role-play","persona":"Razia","source":"heir pressure","hook":"An elder pulls you aside at a family function, eyes serious.","setup":"He says it plainly, expecting quick agreement.","steps":[{"prompt":"Elder says: \"Every family needs an heir. Ideally a boy, you understand.\"","options":[{"text":"\"We'll welcome any child equally. That's our choice.\"","then":"He pauses, clearly not expecting that answer.","best":true},{"text":"\"We'll keep trying until we get a boy, then.\"","then":"He nods, satisfied, and starts naming boy names already."},{"text":"\"That's a really outdated way to think.\"","then":"He bristles. \"I'm only saying what's always been true.\""},{"text":"\"We'll see what happens, I suppose.\"","then":"He takes the vagueness as quiet agreement."}],"why":"Naming equal value and your own choice answers the pressure without a fight."},{"prompt":"He continues: \"Your father would have wanted a grandson too.\"","options":[{"text":"\"He would have wanted us happy, whoever we have.\"","then":"The elder softens slightly, caught off guard by the answer.","best":true},{"text":"\"Maybe you're right. I hadn't thought of that.\"","then":"He presses further, sensing the door has opened a little."},{"text":"\"Don't bring my father into this.\"","then":"The air between you tenses, and the real point gets lost in the reaction."},{"text":"\"We'll try to make everyone happy somehow.\"","then":"The vague promise leaves the pressure exactly where it was."}],"why":"Reframing what your father would have wanted answers gently without conceding."},{"prompt":"Later, he says to the room: \"Well, we'll just have to wait and see what they have.\"","options":[{"text":"\"Whatever we have will be equally loved.\"","then":"The room moves on, and the comment doesn't return that evening.","best":true},{"text":"\"Let's hope for a boy, eh.\"","then":"A few relatives laugh along, and the assumption stands unchallenged."},{"text":"\"Can we please stop talking about this?\"","then":"The room goes quiet, awkward rather than settled."},{"text":"\"It's really none of anyone's business.\"","then":"The comment lands sharply, and the mood cools for the evening."}],"why":"Naming the settled truth again, calmly, closes it better than a plea or a sharp line."}],"relearn":"A calm 'any child equally, ours to decide' rejects son-preference and holds your autonomy at once."},
  {"id":"iw-079","cat":"free-of-pressure","type":"branch","persona":"Razia","source":"refuse sex selection","hook":"At a scan, the technician exchanges a knowing look, and lingers a little too long near your chart.","steps":[{"prompt":"He lowers his voice and offers to tell you the baby's sex, for a fee. What do you do?","options":[{"text":"Refuse. Telling the sex is illegal, and every child is equal","then":"He backs off, and you leave with the sex still unknown.","best":true},{"text":"Say knowing just for yourself is harmless","then":"He smiles and names a price, though even 'just to know' is illegal and often brings pressure to act on it."},{"text":"Report him loudly right there in the waiting room","then":"The room stares, and he denies it flatly in front of everyone."},{"text":"Tell yourself it's normal, since the staff offers it","then":"The offer starts to feel ordinary, though it is illegal however common it looks."}],"why":"A firm, calm no protects any child equally, and it's what the law asks too."},{"prompt":"Your mother-in-law asks if 'the doctor said anything useful' about the baby. What do you say?","options":[{"text":"Say it doesn't matter to you. Every child is welcome","then":"She looks surprised, but doesn't push it further today.","best":true},{"text":"Tell her what the technician offered, just to see her reaction","then":"She lights up, and starts asking when you'll find out."},{"text":"Say maybe you should find out, to keep the peace","then":"She brightens, but even a quiet find-out is illegal, and her questions would not stop."},{"text":"Apologise to her for having nothing to tell","then":"She sighs, and you feel her asking is your doing, though it never was."}],"why":"Naming that any child is welcome answers the pressure without inviting more of it."},{"prompt":"At the next visit, a different staff member hints at the same offer. What do you do?","options":[{"text":"Refuse plainly, then tell someone you trust","then":"She notes the refusal, and someone you trust listens, so you feel less alone with it.","best":true},{"text":"Decide it must be normal here, since the clinic offers it","then":"You start to accept it, though even a normal-looking offer is illegal and never yours to carry."},{"text":"Tell yourself refusing will only cause trouble at the clinic","then":"The worry grows, though refusing is your right, and the offer is not your fault."},{"text":"Ask your mother-in-law whether you should accept","then":"She hopes you say yes, and you feel more pressed than before."}],"why":"Refusing plainly, and telling someone you trust, means you're not carrying it alone."}],"debrief":"Refuse prenatal sex determination; it's illegal under the PCPNDT Act and unjust. The pressure around it is never your fault.","relearn":"Refuse illegal sex determination and selection; law and justice both forbid it."},
  {"id":"iw-080","cat":"free-of-pressure","type":"match","hook":"Match each form of pressure to what actually counters it.","pairs":[{"left":"Son-preference","right":"Valuing every child equally"},{"left":"'Good news' nagging","right":"A calm 'in our own time'"},{"left":"A weaponised fertility clock","right":"Your own informed timeline"},{"left":"\"The family decides\"","right":"The couple's own choice"},{"left":"\"You'll change your mind\"","right":"A choice valid as it stands"}],"relearn":"Son-preference, nagging and a weaponised clock are each countered by equality, calm boundaries and your own timeline.","persona":"any","source":"countering pressure"},
  {"id":"iw-081","cat":"free-of-pressure","type":"spot","hook":"Spot the two responses that surrender your choice (the red flags).","scene":[{"id":"a","text":"Holding your timeline kindly but firmly","trick":false},{"id":"b","text":"Conceiving on demand to silence relatives","trick":true},{"id":"c","text":"Refusing son-preference outright","trick":false},{"id":"d","text":"Agreeing to a sex test to please elders","trick":true},{"id":"e","text":"Sharing your news in your own time","trick":false}],"why":"Conceiving on demand and agreeing to a sex test surrender your choice; holding your timeline and refusing son-preference keep it yours.","relearn":"Keep the choice yours: hold your timeline and refuse son-preference, don't conceive on demand or test.","persona":"Pooja","source":"keep it yours"},
  {"id":"iw-082","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"shared front","hook":"Relatives and friends keep asking you and your partner when you'll have children.","setup":"Back home after a cousin's wedding, your partner kicks off their shoes.","steps":[{"prompt":"They ask: \"So what do we tell people next time?\"","options":[{"text":"\"Let's agree one calm line, and both stick to it.\"","then":"They nod slowly. \"Okay. Same words from both of us.\"","best":true},{"text":"\"Let's just tell people whatever they want to hear.\"","then":"They frown. \"So we say 'soon', and they ask again next month?\""},{"text":"\"You handle your side. I'll handle mine.\"","then":"They hesitate. \"And if your mother asks me instead?\""},{"text":"\"Let's just stop seeing everyone for a while.\"","then":"They laugh tiredly. \"Even your cousin's engagement next week?\""}],"why":"One calm line you both stick to keeps the pressure from splitting you apart."},{"prompt":"They ask: \"And what if someone asks whether something's wrong with us?\"","options":[{"text":"\"We say it's our decision, and leave it there.\"","then":"They repeat it quietly, testing the words. \"Our decision. Okay.\"","best":true},{"text":"\"We tell them the full story, so they stop.\"","then":"They wince. \"Everything? Even the parts we haven't settled?\""},{"text":"\"We say it's none of their business.\"","then":"They raise an eyebrow. \"To my grandmother? She'll cry for a week.\""},{"text":"\"We make up a medical reason, so they back off.\"","then":"They look uneasy. \"Then that story follows us to every function.\""}],"why":"A calm 'it's our decision' answers even the prying question, without a fight or a made-up story."},{"prompt":"At the next family function, they whisper: \"Here we go again. Ready?\"","options":[{"text":"\"Ready. Same answer from both of us, okay?\"","then":"They squeeze your hand. \"Same answer. Let's go in.\"","best":true},{"text":"\"Honestly, I'd rather just avoid them tonight.\"","then":"They sigh. \"We can't hide in the car all evening.\""},{"text":"\"You go first. I'll back you up.\"","then":"They hesitate. \"Why me? You're better with your aunts.\""},{"text":"\"Let's just see how it goes.\"","then":"They look unsure. \"So we might end up saying different things?\""}],"why":"Walking in with one shared answer means neither of you faces the questions alone."}],"relearn":"A shared front, one calm line and leaning on each other keeps the pressure from splitting you."},
  {"id":"iw-083","cat":"tools-and-help","type":"role-play","persona":"Sneha","source":"guide simply","hook":"A worried younger cousin comes to you feeling overwhelmed by the whole question.","setup":"She sits beside you on the terrace, phone in hand.","steps":[{"prompt":"She asks: \"Where do I even begin with all this?\"","options":[{"text":"\"Start with what you actually want, no rush.\"","then":"She looks relieved, like she'd been waiting for permission to slow down.","best":true},{"text":"\"Just do what your parents think is best.\"","then":"She bites her lip. \"But what if what they want isn't what I want?\""},{"text":"\"Honestly, you'll figure it out eventually.\"","then":"She nods, but still looks lost. \"Okay, but where do I start?\""},{"text":"\"Follow whatever your friends are doing.\"","then":"She frowns. \"Half of them are married and half aren't.\""}],"why":"Starting with what she actually wants, with no rush, puts the choice back in her hands."},{"prompt":"She asks: \"But how do I know what's even true about fertility?\"","options":[{"text":"\"Get honest facts from a clinician, not forwards.\"","then":"She nods, relieved there's a real place to check things.","best":true},{"text":"\"Follow a few fertility pages on Instagram.\"","then":"She scrolls, frowning. \"Every page says something different.\""},{"text":"\"Ask your mother. She'll know.\"","then":"She makes a face. \"Mummy still thinks it's all written in the stars.\""},{"text":"\"It probably doesn't matter that much yet, does it?\"","then":"She hesitates. \"It matters to me, though.\""}],"why":"Pointing her to honest facts from a clinician gives her something actually reliable to build on."},{"prompt":"She asks: \"What if I decide something my family doesn't like?\"","options":[{"text":"\"It's still your choice, whatever you decide.\"","then":"She sits a little taller, hearing the choice is genuinely hers.","best":true},{"text":"\"Then maybe don't tell them for now.\"","then":"She looks down. \"I can't keep it a secret forever.\""},{"text":"\"You'll probably have to compromise somewhere eventually.\"","then":"Her shoulders drop. \"So I don't really get a say?\""},{"text":"\"They'll come around in time. Don't worry.\"","then":"She frowns. \"And if they don't?\""}],"why":"Naming it as her choice, whatever she decides, hands her the autonomy she was really asking about."}],"relearn":"A simple 'your wants, honest facts, your choice, no rush' hands her the calm method, not the pressure."},
  {"id":"iw-084","cat":"tools-and-help","type":"sort","hook":"Sort: a trustworthy source for this decision, or one to be wary of?","items":[{"id":"a","text":"A qualified clinician"},{"id":"b","text":"A clinic promising guaranteed babies"},{"id":"c","text":"Public health services like RKSK"},{"id":"d","text":"Scare-driven social media"},{"id":"e","text":"Honest expectations about odds"},{"id":"f","text":"An offer to reveal the baby's sex"}],"bins":[{"id":"trust","label":"Trustworthy","valence":"pos"},{"id":"wary","label":"Be wary","valence":"neg"}],"key":{"a":"trust","b":"wary","c":"trust","d":"wary","e":"trust","f":"wary"},"relearn":"A clinician, RKSK and honest odds are trustworthy; 'guaranteed baby' clinics, scare media and sex-reveal offers aren't.","persona":"any","source":"trust vs wary"},
  {"id":"iw-990","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"A man's fertility never changes, so age is purely the woman's problem.\"","myth":{"un":"A man's fertility never changes, so age is purely the woman's problem.","re":"A man's fertility also shifts somewhat with age and health; it isn't only a woman's matter.","why":"Both partners' bodies are part of the picture."},"relearn":"Men's fertility shifts somewhat with age and health too; it's never only the woman's matter.","persona":"Karthik","source":"men age too"},
  {"id":"iw-991","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"If it doesn't happen in the first month or two, something must be wrong with you.\"","myth":{"un":"If it doesn't happen in the first month or two, something must be wrong with you.","re":"Many couples take several months to conceive even when everything is healthy; a slow start isn't a verdict.","why":"Timelines vary widely between healthy couples."},"relearn":"Taking several months to conceive is common and healthy; a slow start isn't proof something is wrong.","persona":"Pooja","source":"months are normal"},
  {"id":"iw-992","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Folic acid only matters once the pregnancy test is positive.\"","myth":{"un":"Folic acid only matters once the pregnancy test is positive.","re":"Folic acid before and in early pregnancy helps protect the baby's developing spine and brain, so it's worth starting before you see a test.","why":"The earliest weeks shape key development."},"relearn":"Folic acid before and in early pregnancy protects the developing spine and brain; start before a positive test.","persona":"any","source":"start early"},
  {"id":"iw-993","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"A 'fertile window' is a myth; any day of the cycle is equally likely.\"","myth":{"un":"A 'fertile window' is a myth; any day of the cycle is equally likely.","re":"Conception is likeliest on the few days around ovulation, so the cycle isn't uniform; knowing this is calm planning, not pressure.","why":"It helps you understand your own cycle."},"relearn":"Conception is likeliest on the few days around ovulation; knowing your window is calm planning.","persona":"any","source":"the window"},
  {"id":"iw-994","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"A guideline age is a hard deadline; miss it and your chance is gone forever.\"","myth":{"un":"A guideline age is a hard deadline; miss it and your chance is gone forever.","re":"A guideline describes general trends, not a personal cut-off; many paths and timings remain open after it.","why":"Averages aren't your individual fate."},"relearn":"A guideline age is a general trend, not a personal deadline; many timings stay open after it.","persona":"Sneha","source":"not a deadline"},
  {"id":"iw-995","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Tracking my cycle is pointless obsessing that just makes things worse.\"","myth":{"un":"Tracking my cycle is pointless obsessing that just makes things worse.","re":"Gently knowing your own cycle can be a calm planning tool you own; it only becomes pressure if a guideline is treated as a verdict.","why":"Information is yours to use lightly."},"relearn":"Knowing your cycle gently is a calm planning tool you own; it's only pressure if treated as a verdict.","persona":"any","source":"gentle tracking"},
  {"id":"iw-996","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Healthy habits make zero difference to fertility, so why bother before trying.\"","myth":{"un":"Healthy habits make zero difference to fertility, so why bother before trying.","re":"For both partners, everyday health habits can gently support fertility; it's care, not a guarantee or a blame game.","why":"Small habits support the whole picture."},"relearn":"Everyday health habits can gently support both partners' fertility; it's care, not a guarantee or blame.","persona":"Karthik","source":"habits help both"},
  {"id":"iw-997","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"One scary post online means you've already left it far too late.\"","myth":{"un":"One scary post online means you've already left it far too late.","re":"A scare post is built to alarm, not to inform you personally; a clinician can give calm facts for your own situation.","why":"Panic content isn't personal advice."},"relearn":"A scare post is built to alarm, not inform you; a clinician gives calm facts for your own situation.","persona":"Pooja","source":"posts aren't advice"},
  {"id":"iw-998","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Fertility is too private and scary to ever ask a doctor about before trying.\"","myth":{"un":"Fertility is too private and scary to ever ask a doctor about before trying.","re":"A pre-pregnancy check is a normal, calm conversation; you can ask a clinician questions while you're still just thinking about it.","why":"Asking early is ordinary, not alarming."},"relearn":"A pre-pregnancy check is a normal calm chat; you can ask a clinician while still just thinking about it.","persona":"any","source":"asking is normal"},
  {"id":"iw-999","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Knowing fertility facts will only make me anxious, so ignorance is safer.\"","myth":{"un":"Knowing fertility facts will only make me anxious, so ignorance is safer.","re":"Honest facts, held calmly, are power to plan on your own terms; it's panic framing, not the facts themselves, that breeds anxiety.","why":"Calm knowledge steadies decisions."},"relearn":"Honest facts held calmly are power to plan on your terms; panic framing, not facts, breeds anxiety.","persona":"Sneha","source":"facts steady you"},
  {"id":"iw-1000","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Fertility is the wife's homework; a husband never needs to learn any of it.\"","myth":{"un":"Fertility is the wife's homework; a husband never needs to learn any of it.","re":"Understanding fertility is a shared, both-of-you matter; a partner learning the basics is owning his half, not 'helping' with hers.","why":"Shared knowledge means shared decisions."},"relearn":"Fertility is a shared both-of-you matter; a partner learning the basics owns his half, not just 'helps'.","persona":"Karthik","source":"his half too"},
  {"id":"iw-1001","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Stopping contraception means pregnancy is guaranteed the very next cycle.\"","myth":{"un":"Stopping contraception means pregnancy is guaranteed the very next cycle.","re":"After stopping contraception it can still take time to conceive; that wait is normal and not a sign of a problem.","why":"A return to fertility isn't instant for everyone."},"relearn":"After stopping contraception, conceiving can still take time; that wait is normal, not a problem.","persona":"Pooja","source":"not instant after"},
  {"id":"iw-1002","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"Fertility falls off a cliff at one exact birthday for everyone.\"","myth":{"un":"Fertility falls off a cliff at one exact birthday for everyone.","re":"Fertility shifts gradually, sooner for women and somewhat for men, not at one magic age; it's a slope, not a cliff.","why":"Gradual change calms the panic."},"relearn":"Fertility shifts gradually, sooner for women and somewhat for men; it's a slope, not a cliff at one age.","persona":"any","source":"a slope not a cliff"},
  {"id":"iw-1003","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"You can't possibly plan fertility, so just leave it entirely to fate.\"","myth":{"un":"You can't possibly plan fertility, so just leave it entirely to fate.","re":"You can't control everything, but calm facts and a clinician's input let you plan on your own terms instead of only guessing.","why":"Some planning beats pure guesswork."},"relearn":"Calm facts and a clinician let you plan fertility on your own terms, instead of leaving it all to fate.","persona":"any","source":"plan, don't guess"},
  {"id":"iw-1004","cat":"fertility-for-real","type":"strike-rewrite","hook":"\"If two friends conceived fast, your body should match their exact timeline.\"","myth":{"un":"If two friends conceived fast, your body should match their exact timeline.","re":"Every couple's timeline differs; a friend's quick pregnancy says nothing about how long yours will or should take.","why":"Other people's timelines aren't yours."},"relearn":"Every couple's timeline differs; a friend conceiving fast says nothing about how long yours should take.","persona":"any","source":"not their timeline"},
  {"id":"iw-1005","cat":"fertility-for-real","type":"sort","hook":"Sort: an honest fertility fact, or a panic-driven myth?","items":[{"id":"a","text":"Fertility shifts gradually with age"},{"id":"b","text":"One late year ruins your only chance"},{"id":"c","text":"Conception can take several months"},{"id":"d","text":"After one birthday it's all over"},{"id":"e","text":"Both partners' health can matter"},{"id":"f","text":"Stopping contraception means instant pregnancy"}],"bins":[{"id":"fact","label":"Honest fact","valence":"pos"},{"id":"panic","label":"Panic myth","valence":"neg"}],"key":{"a":"fact","b":"panic","c":"fact","d":"panic","e":"fact","f":"panic"},"relearn":"Gradual shift, months to conceive and both partners mattering are facts; cliffs, 'one year ruins it' and instant pregnancy are panic.","persona":"any","source":"fact vs panic"},
  {"id":"iw-1006","cat":"fertility-for-real","type":"sort","hook":"Sort: calm planning you own, or anxiety being fed?","items":[{"id":"a","text":"Asking a clinician your own questions"},{"id":"b","text":"Reading scare posts at 2am"},{"id":"c","text":"Both partners learning the basics"},{"id":"d","text":"Counting down to a 'deadline' birthday"},{"id":"e","text":"Noting your cycle gently"},{"id":"f","text":"Comparing yourself to every friend's bump"}],"bins":[{"id":"calm","label":"Calm planning","valence":"pos"},{"id":"anxiety","label":"Feeds anxiety","valence":"neg"}],"key":{"a":"calm","b":"anxiety","c":"calm","d":"anxiety","e":"calm","f":"anxiety"},"relearn":"Clinician questions, shared basics and gentle cycle notes are calm planning; scare posts, deadline countdowns and bump-comparing feed anxiety.","persona":"any","source":"calm vs anxiety"},
  {"id":"iw-1007","cat":"fertility-for-real","type":"sort","hook":"Sort: whose job is it to understand fertility?","items":[{"id":"a","text":"Both partners learning together"},{"id":"b","text":"'It's only her department'"},{"id":"c","text":"A husband asking the doctor too"},{"id":"d","text":"'Men never need to know any of this'"},{"id":"e","text":"Sharing what each one reads"},{"id":"f","text":"Leaving all the worry to the wife"}],"bins":[{"id":"shared","label":"Shared matter","valence":"pos"},{"id":"hers","label":"Pinned on her","valence":"neg"}],"key":{"a":"shared","b":"hers","c":"shared","d":"hers","e":"shared","f":"hers"},"relearn":"Learning together, a husband asking too and sharing reading are shared; 'her department', 'men needn't know' and leaving her the worry pin it on her.","persona":"Karthik","source":"shared not hers"},
  {"id":"iw-1008","cat":"fertility-for-real","type":"sort","hook":"Sort: a calm fertility step you own, or panic talking?","items":[{"id":"a","text":"Booking a pre-pregnancy chat"},{"id":"b","text":"Rushing a huge decision from fear"},{"id":"c","text":"Starting folic acid before trying"},{"id":"d","text":"Believing one scare post over a doctor"},{"id":"e","text":"Writing down your real questions"},{"id":"f","text":"Skipping sleep to doomscroll forums"}],"bins":[{"id":"calm","label":"Calm step","valence":"pos"},{"id":"panic","label":"Panic talking","valence":"neg"}],"key":{"a":"calm","b":"panic","c":"calm","d":"panic","e":"calm","f":"panic"},"relearn":"A pre-pregnancy chat, folic acid and listing questions are calm steps; fear-rushing, trusting a scare post and doomscrolling are panic talking.","persona":"Pooja","source":"step vs panic"},
  {"id":"iw-1009","cat":"fertility-for-real","type":"sort","hook":"Sort: who decides what to do with your fertility facts?","items":[{"id":"a","text":"You and your partner, together"},{"id":"b","text":"Whichever aunty heard a rumour"},{"id":"c","text":"You, with a clinician's input"},{"id":"d","text":"A panic post's 'hurry up' order"},{"id":"e","text":"The two of you, on your own timeline"},{"id":"f","text":"Relatives counting your months"}],"bins":[{"id":"yours","label":"Yours to use","valence":"pos"},{"id":"theirs","label":"Someone else's","valence":"neg"}],"key":{"a":"yours","b":"theirs","c":"yours","d":"theirs","e":"yours","f":"theirs"},"relearn":"You, your partner and a clinician decide on your own timeline; aunties' rumours, panic orders and relatives counting months aren't yours to obey.","persona":"any","source":"yours to use"},
  {"id":"iw-1010","cat":"fertility-for-real","type":"sort","hook":"Sort: a trustworthy place for fertility facts, or noise?","items":[{"id":"a","text":"A qualified clinician"},{"id":"b","text":"A viral 'you're too old' reel"},{"id":"c","text":"A public health service like RKSK"},{"id":"d","text":"A miracle-fix advert"},{"id":"e","text":"A calm, expert-reviewed explainer"},{"id":"f","text":"A forum stranger's scary guess"}],"bins":[{"id":"trust","label":"Trustworthy","valence":"pos"},{"id":"noise","label":"Just noise","valence":"neg"}],"key":{"a":"trust","b":"noise","c":"trust","d":"noise","e":"trust","f":"noise"},"relearn":"A clinician, RKSK and an expert-reviewed explainer are trustworthy; viral 'too old' reels, miracle adverts and a stranger's scary guess are noise.","persona":"any","source":"trust vs noise"},
  {"id":"iw-1011","cat":"fertility-for-real","type":"sort","hook":"Sort: honest fertility awareness, or a weaponised clock?","items":[{"id":"a","text":"'Here are facts, plan your way'"},{"id":"b","text":"'Your clock is ticking, hurry'"},{"id":"c","text":"'Both of you can learn this calmly'"},{"id":"d","text":"'Decide now or lose your chance'"},{"id":"e","text":"'A clinician can answer your questions'"},{"id":"f","text":"'Every wasted month is your fault'"}],"bins":[{"id":"honest","label":"Honest awareness","valence":"pos"},{"id":"weapon","label":"Weaponised clock","valence":"neg"}],"key":{"a":"honest","b":"weapon","c":"honest","d":"weapon","e":"honest","f":"weapon"},"relearn":"'Here are facts', 'learn calmly' and 'a clinician can help' are honest; 'clock ticking', 'decide now' and 'your fault' weaponise the clock.","persona":"Sneha","source":"awareness vs weapon"},
  {"id":"iw-1012","cat":"fertility-for-real","type":"sort","hook":"Sort: a real preconception basic, or a made-up rule?","items":[{"id":"a","text":"Folic acid before and in early pregnancy"},{"id":"b","text":"'Only women need any check-up'"},{"id":"c","text":"A calm pre-pregnancy clinician chat"},{"id":"d","text":"'Health habits make no difference at all'"},{"id":"e","text":"Both partners looking at their health"},{"id":"f","text":"'A secret food guarantees a baby'"}],"bins":[{"id":"real","label":"Real basic","valence":"pos"},{"id":"madeup","label":"Made-up rule","valence":"neg"}],"key":{"a":"real","b":"madeup","c":"real","d":"madeup","e":"real","f":"madeup"},"relearn":"Folic acid, a pre-pregnancy chat and both partners' health are real basics; 'only women', 'habits don't matter' and 'magic foods' are made up.","persona":"Pooja","source":"basic vs made-up"},
  {"id":"iw-1013","cat":"fertility-for-real","type":"match","hook":"Match each fertility idea to its calm, honest meaning.","pairs":[{"left":"The fertile window","right":"The few days each cycle when conception is likeliest"},{"left":"Age and fertility","right":"A gradual shift, sooner for women, somewhat for men"},{"left":"Preconception health","right":"Getting healthy before trying, including folic acid"},{"left":"A guideline age","right":"A general trend, not your personal deadline"},{"left":"Both partners","right":"Fertility is a shared matter, never only hers"}],"relearn":"The window, age trend, preconception health, a guideline-as-trend, and both partners: the calm basics.","persona":"any","source":"calm basics"},
  {"id":"iw-1014","cat":"fertility-for-real","type":"match","hook":"Match each panic line to the calm fact that answers it.","pairs":[{"left":"'It's basically over after 30'","right":"Fertility shifts gradually, not at a cliff"},{"left":"'It should happen the first month'","right":"Conception can take healthy months"},{"left":"'Only her age matters'","right":"A man's age and health count too"},{"left":"'A guideline is a hard deadline'","right":"It's a trend you can plan around"},{"left":"'Just ignore it and hope'","right":"Calm facts let you plan your way"}],"relearn":"Each scary line has a calm answer: gradual shift, months are normal, both count, trends aren't deadlines.","persona":"any","source":"panic answered"},
  {"id":"iw-1015","cat":"fertility-for-real","type":"match","hook":"Match each partner's part to the shared, calm truth.","pairs":[{"left":"Her age and health","right":"One real part of the picture, not the whole blame"},{"left":"His age and health","right":"Can play a part in fertility too"},{"left":"Their shared habits","right":"Everyday health can gently support both"},{"left":"Their questions","right":"Best taken together to a clinician"},{"left":"Their timeline","right":"Decided by the two of them, on their terms"}],"relearn":"Her health, his health, shared habits, joint questions and their own timeline make fertility a both-of-you matter, never only hers.","persona":"Karthik","source":"both of you"},
  {"id":"iw-1016","cat":"fertility-for-real","type":"match","hook":"Match each fertility worry to where calm help really lives.","pairs":[{"left":"'Am I leaving it too late?'","right":"A clinician, for facts about you"},{"left":"'Where do I even start?'","right":"A public service like RKSK"},{"left":"'Is this scare post true?'","right":"An expert source, not a viral reel"},{"left":"'Should I take folic acid?'","right":"A clinician's advice, before pregnancy"},{"left":"'Is it just my problem?'","right":"A shared chat; both partners matter"}],"relearn":"Worries route to help: a clinician for your facts, RKSK to start, expert sources over reels, a shared chat.","persona":"Pooja","source":"route to help"},
  {"id":"iw-1017","cat":"fertility-for-real","type":"match","hook":"Match each habit to whether it's calm planning or feeding panic.","pairs":[{"left":"Noting your cycle gently","right":"Calm self-knowledge"},{"left":"Doomscrolling fertility forums","right":"Feeding needless panic"},{"left":"Listing questions for a clinician","right":"Planning you own"},{"left":"Treating a guideline as a verdict","right":"A self-imposed deadline"},{"left":"Sharing the learning with a partner","right":"Making it a shared matter"}],"relearn":"Cycle notes, a question list and shared learning are calm planning; doomscrolling and 'guideline as verdict' feed panic.","persona":"any","source":"calm vs panic habits"},
  {"id":"iw-1018","cat":"fertility-for-real","type":"match","hook":"Match each calm message to why it's honest, not a scare.","pairs":[{"left":"'Here are the facts'","right":"It informs, so you can plan your own way"},{"left":"'Both of you can learn this'","right":"It includes the partner, not just her"},{"left":"'A clinician can answer that'","right":"It routes you to real, personal help"},{"left":"'There's no single right time'","right":"It hands the timing back to you"},{"left":"'A guideline isn't a deadline'","right":"It calms the clock instead of weaponising it"}],"relearn":"Honest messages inform, include the partner, route to help, hand back the timing, calm the clock.","persona":"Sneha","source":"honest messages"},
  {"id":"iw-1019","cat":"fertility-for-real","type":"match","hook":"Match each step to the calm fertility goal it serves.","pairs":[{"left":"Starting folic acid early","right":"Supporting healthy early development"},{"left":"A pre-pregnancy clinician chat","right":"Getting facts for your own situation"},{"left":"Both partners getting checked","right":"Sharing the picture, not blaming one"},{"left":"Gentle cycle awareness","right":"Understanding your own body calmly"},{"left":"Skipping the scare posts","right":"Protecting your peace while you plan"}],"relearn":"Folic acid aids development, a chat gets your facts, shared checks share the picture, skipping scares keeps your peace.","persona":"any","source":"step to goal"},
  {"id":"iw-1020","cat":"fertility-for-real","type":"match","hook":"Match each true-or-false fertility line to its honest verdict.","pairs":[{"left":"'Conception is always instant'","right":"False: it can take several months"},{"left":"'Fertility shifts gradually with age'","right":"True, sooner for women, somewhat for men"},{"left":"'Only the woman's body counts'","right":"False: both partners can matter"},{"left":"'A guideline is your deadline'","right":"False: it's a general trend"},{"left":"'Calm facts help you plan'","right":"True, on your own terms"}],"relearn":"'Instant', 'only her body' and 'guideline as deadline' are false; gradual shift and 'calm facts help you plan' are true.","persona":"any","source":"true or false"},
  {"id":"iw-1021","cat":"fertility-for-real","type":"reflect","hook":"Lensy: fertility facts are a calm tool you own, not a clock someone else winds. Sit right?","prompt":"What do you think?","options":["Sits right","A tool I own","Not their clock"],"affirm":"Fertility facts are yours to hold calmly and use on your own terms, never a clock others get to wind for you.","relearn":"Fertility facts are a calm tool you own, used on your terms, not a clock for others to wind.","persona":"any","source":"my tool"},
  {"id":"iw-1022","cat":"fertility-for-real","type":"reflect","hook":"Lensy: it's okay to learn the basics without a panic attached. How's that land?","prompt":"What's your take?","options":["Lands well","Calm is allowed","No panic needed"],"affirm":"You can learn fertility basics calmly; knowledge and panic are not the same thing, and you get to keep the first without the second.","relearn":"You can learn fertility basics calmly; knowledge and panic aren't the same, and you keep one without the other.","persona":"Sneha","source":"calm is allowed"},
  {"id":"iw-1023","cat":"fertility-for-real","type":"reflect","hook":"Lensy: understanding this together, as a couple, can feel lighter than carrying it alone. True for you?","prompt":"What's your view?","options":["True for me","Lighter together","Worth sharing"],"affirm":"Fertility is a shared matter, and learning it together can lift the load off one person and make the planning genuinely joint.","relearn":"Fertility is shared; learning it together lifts the load off one person and makes the planning joint.","persona":"Karthik","source":"lighter together"},
  {"id":"iw-1024","cat":"fertility-for-real","type":"reflect","hook":"Lensy: a guideline is a general trend, not your personal deadline. Does that ease anything?","prompt":"How does that sit?","options":["Eases it","Trend, not deadline","Still my pace"],"affirm":"A guideline describes averages, not your fate; you can plan around it at your own pace without treating it as a countdown.","relearn":"A guideline is an average, not your deadline; you plan around it at your own pace, no countdown.","persona":"any","source":"my pace"},
  {"id":"iw-1025","cat":"fertility-for-real","type":"reflect","hook":"Lensy: you're allowed to close the scary tab and ask a real person instead. Feel okay?","prompt":"What do you feel?","options":["Feels okay","I can close it","Ask a real person"],"affirm":"You can step away from the panic feed any time and take your real questions to a clinician who answers for your own situation.","relearn":"You can leave the panic feed and take real questions to a clinician who answers for your own situation.","persona":"Pooja","source":"close the tab"},
  {"id":"iw-1026","cat":"fertility-for-real","type":"reflect","hook":"Lensy: knowing your own cycle can feel like quietly knowing yourself, not a test. Agree?","prompt":"What's your take?","options":["Agree","Knowing myself","Not a test"],"affirm":"Gently knowing your cycle is part of knowing your own body; it's information for you, not an exam you can pass or fail.","relearn":"Gently knowing your cycle is part of knowing your body; it's information for you, not a pass-or-fail test.","persona":"any","source":"knowing myself"},
  {"id":"iw-1027","cat":"fertility-for-real","type":"reflect","hook":"Lensy: there's no shame in asking a clinician a 'too early' question. Sit right?","prompt":"What do you think?","options":["Sits right","No shame in asking","Early is fine"],"affirm":"Asking a clinician before you've even decided is completely normal; you don't have to wait for certainty or a worry to deserve answers.","relearn":"Asking a clinician before you've decided is normal; you needn't wait for certainty to deserve answers.","persona":"any","source":"early is fine"},
  {"id":"iw-1028","cat":"fertility-for-real","type":"reflect","hook":"Lensy: facts can quiet the noise, instead of adding to it. How does that land?","prompt":"What's your view?","options":["Lands well","Quiets the noise","Facts steady me"],"affirm":"Honest facts, held calmly, tend to settle the mind rather than stir it; the noise comes from panic framing, not from the facts themselves.","relearn":"Honest facts held calmly settle the mind; the noise comes from panic framing, not the facts themselves.","persona":"any","source":"facts steady me"},
  {"id":"iw-1029","cat":"fertility-for-real","type":"spot","hook":"Spot the two lines that weaponise the clock (the ones to catch).","scene":[{"id":"a","text":"\"Here are the facts, plan your own way\"","trick":false},{"id":"b","text":"\"Your clock is ticking, hurry up now\"","trick":true},{"id":"c","text":"\"Both of you can learn this, calmly\"","trick":false},{"id":"d","text":"\"Decide now or lose your only chance\"","trick":true},{"id":"e","text":"\"A clinician can answer your questions\"","trick":false}],"why":"The caught lines rush and scare you with a ticking clock; the rest inform calmly and route to help.","relearn":"Honest messaging informs and routes to help; 'hurry now' and 'lose your only chance' weaponise the clock.","persona":"Sneha","source":"catch the clock"},
  {"id":"iw-1030","cat":"fertility-for-real","type":"spot","hook":"Spot the two fertility myths to catch, among the honest facts.","scene":[{"id":"a","text":"\"Conception can take several healthy months\"","trick":false},{"id":"b","text":"\"It's all over the day you turn a certain age\"","trick":true},{"id":"c","text":"\"Fertility shifts gradually, sooner for women\"","trick":false},{"id":"d","text":"\"Stop contraception and pregnancy is guaranteed\"","trick":true},{"id":"e","text":"\"Both partners' age and health can matter\"","trick":false}],"why":"The caught lines are myths: fertility doesn't end at one age, and conceiving isn't guaranteed at once.","relearn":"Gradual shift, months to conceive and both partners are facts; 'over at one age' and 'guaranteed' are myths.","persona":"any","source":"catch the myth"},
  {"id":"iw-1031","cat":"fertility-for-real","type":"spot","hook":"Spot the two lines that dump fertility on the woman alone (catch them).","scene":[{"id":"a","text":"\"Let's learn the basics together, it's a both-of-us thing\"","trick":false},{"id":"b","text":"\"That's honestly her department, not mine\"","trick":true},{"id":"c","text":"\"I'll come to the clinic and ask questions too\"","trick":false},{"id":"d","text":"\"Men never need to know any of this\"","trick":true},{"id":"e","text":"\"We can share whatever each of us reads\"","trick":false}],"why":"The caught lines pin fertility on her alone; the rest treat it as a shared matter both partners own.","relearn":"Fertility is a both-of-you matter; 'her department' and 'men needn't know' dump it on the woman alone.","persona":"Karthik","source":"catch the dump"},
  {"id":"iw-1032","cat":"fertility-for-real","type":"spot","hook":"Spot the two panic moves to catch, among the calm planning steps.","scene":[{"id":"a","text":"\"I'll book a pre-pregnancy chat with a clinician\"","trick":false},{"id":"b","text":"\"I'll rush a huge decision tonight out of fear\"","trick":true},{"id":"c","text":"\"I'll write down my real questions first\"","trick":false},{"id":"d","text":"\"I'll trust one scary post over my doctor\"","trick":true},{"id":"e","text":"\"I'll start folic acid before we try\"","trick":false}],"why":"The caught moves are panic: fear-rushing a decision and trusting a scare post over a doctor.","relearn":"A clinician chat, a question list and folic acid are calm steps; fear-rushing and a scare post over a doctor are panic.","persona":"Pooja","source":"catch the panic"},
  {"id":"iw-1033","cat":"fertility-for-real","type":"spot","hook":"Spot the two false 'fertility hacks' to catch, among the honest basics.","scene":[{"id":"a","text":"\"Folic acid before and in early pregnancy helps\"","trick":false},{"id":"b","text":"\"This one secret food guarantees a baby fast\"","trick":true},{"id":"c","text":"\"A pre-pregnancy clinician chat is normal\"","trick":false},{"id":"d","text":"\"Skip the doctor, this miracle tea is all you need\"","trick":true},{"id":"e","text":"\"Both partners' health is worth a look\"","trick":false}],"why":"The caught lines are false hacks selling a guaranteed shortcut; honest basics route to a clinician.","relearn":"Folic acid, a clinician chat and both partners' health are honest; secret foods and miracle teas aren't.","persona":"any","source":"hack"},
  {"id":"iw-1034","cat":"fertility-for-real","type":"spot","hook":"Spot the two doomscroll traps to catch, among calm ways to use information.","scene":[{"id":"a","text":"\"I'll note my cycle gently and move on\"","trick":false},{"id":"b","text":"\"I'll refresh fertility horror forums till 2am\"","trick":true},{"id":"c","text":"\"I'll save my real questions for the clinic\"","trick":false},{"id":"d","text":"\"I'll treat that scary guideline as my verdict\"","trick":true},{"id":"e","text":"\"I'll read one calm, expert-reviewed explainer\"","trick":false}],"why":"The caught lines are doomscroll traps: horror forums at 2am and 'guideline as verdict'.","relearn":"Cycle notes, saved questions and one calm explainer use info well; horror forums and 'verdict' are traps.","persona":"any","source":"catch the doomscroll"},
  {"id":"iw-1035","cat":"fertility-for-real","type":"spot","hook":"Spot the two scare-merchant lines to catch, among the genuinely caring ones.","scene":[{"id":"a","text":"\"Take your time, here are calm facts for later\"","trick":false},{"id":"b","text":"\"Every month you wait is wasted forever\"","trick":true},{"id":"c","text":"\"A clinician can talk this through with you both\"","trick":false},{"id":"d","text":"\"Panic now, soon it'll be too late\"","trick":true},{"id":"e","text":"\"There's no single right time, only yours\"","trick":false}],"why":"The caught lines are scare-merchants trading on 'wasted months' and 'too late'; care gives facts and a clinician.","relearn":"Care gives calm facts, time and a clinician; wasted-months and too-late lines are scare pressure.","persona":"Sneha","source":"scare"},
  {"id":"iw-1036","cat":"fertility-for-real","type":"branch","persona":"Sneha","source":"reel vs clinician","hook":"At 34, a reel just told you your fertility 'ended yesterday'.","steps":[{"prompt":"The reel has millions of views and zero nuance. What's your first move?","options":[{"text":"Breathe, then book a calm chat with a clinician about you","then":"You trade a stranger's script for real facts about your own body.","best":true},{"text":"Comment on the reel asking if it's really true","then":"Strangers argue in the replies, and none of it is about you."},{"text":"Believe it and mourn the future you'd planned","then":"You grieve something a reel never actually confirmed."},{"text":"Screenshot it and forward it to your sister","then":"She worries with you, and neither of you knows more than before."}],"why":"A clinician can see your own body; a viral reel never could."},{"prompt":"A few days later, you see a clinician, who asks your age and what worried you. What do you tell her?","options":[{"text":"Say your age plainly and name what the reel claimed","then":"She walks you through what's actually true for someone your age.","best":true},{"text":"Say you're fine, just there for a routine check","then":"The visit stays general, but she still shares how fertility changes with age."},{"text":"Mention it vaguely and let her guess the rest","then":"She gently asks more questions, and the visit still covers the general facts."},{"text":"Mention the reel but insist it's probably nonsense","then":"She still answers kindly with the general facts, though you talked over her a little."}],"why":"Naming your age and the actual claim gets you an answer built for you."},{"prompt":"That evening the same reel appears again on your feed. What do you do?","options":[{"text":"Recall what the clinician actually told you and scroll on","then":"The reel has no power left over facts you already hold.","best":true},{"text":"Rewatch it a few times to check if you missed something","then":"Nothing new appears, only the same scare in a longer loop."},{"text":"Send it to a friend to see if she panics too","then":"She panics, and now two of you are carrying the same myth."},{"text":"Report it, then keep thinking about it anyway","then":"The video's gone, but the worry it planted is still there."}],"why":"Real facts from a clinician outlast a reel that resurfaces on your feed."}],"debrief":"A scary reel isn't personal advice; a clinician gives calm facts about you.","relearn":"Swap a scary reel for a clinician's calm, personal facts; a clip can't see your body."},
  {"id":"iw-1037","cat":"fertility-for-real","type":"branch","persona":"Pooja","source":"prepare together","hook":"You and your partner Aman want to start trying soon and wonder how to prepare.","steps":[{"prompt":"You bring it up over dinner. What do you suggest first?","options":[{"text":"Book a pre-pregnancy chat together and ask about folic acid","then":"Aman agrees, and you both add it to the calendar that night.","best":true},{"text":"Say you'll read up and tell him what he needs to do","then":"He nods, relieved to leave the whole plan to you."},{"text":"Wait and think about it once you're already trying","then":"The evening ends warmly. Days later, Aman suggests seeing a clinician first anyway."},{"text":"Ask his mother what worked for her generation","then":"She shares her memories kindly, though little of it still applies."}],"why":"A shared appointment and folic acid start you both informed together."},{"prompt":"A few days later, you and Aman see a clinician. She asks who's taking notes on the plan. What do you say?","options":[{"text":"Say you both are, and hand Aman half the questions","then":"He steps in and asks two questions you hadn't thought of.","best":true},{"text":"Say you are, since you organised the visit","then":"The doctor answers you mainly, and Aman half listens beside you."},{"text":"Say it doesn't matter, whoever remembers","then":"Nobody quite remembers everything once you're back home."},{"text":"Ask Aman to just confirm what you already decided","then":"He agrees easily, without really weighing in himself."}],"why":"Splitting the questions makes the planning genuinely shared, not just attended."},{"prompt":"A week later, the folic acid you bought is still unopened on the counter. What do you do?","options":[{"text":"Set a shared daily reminder. You take it, and he checks in","then":"The bottle empties steadily, and neither of you forgets it's happening.","best":true},{"text":"Start it alone, since you're the one who'll carry","then":"You remember most days, and Aman doesn't know to help you remember."},{"text":"Wait for a better time to begin","then":"The unopened bottle sits there for another few weeks."},{"text":"Ask Aman to remind you, without a plan of his own","then":"He forgets more often than he remembers."}],"why":"A shared reminder keeps the habit shared, not one more thing you carry alone."},{"prompt":"A relative asks Aman what 'his part' in all this even is. What do you do?","options":[{"text":"Let him name his own part, and back him in it","then":"Aman speaks for himself, and the moment becomes about what he's willing to take on next.","best":true},{"text":"Jump in and answer for him","then":"You cover for him instead, and his own part stays unnamed."},{"text":"Laugh along, since it's easier than explaining","then":"The old joke lands again, and nothing shifts."},{"text":"Stay quiet and let the awkward moment pass","then":"The question goes unanswered, and so does what he actually does."}],"why":"Letting him speak for himself starts sharing the responsibility openly."}],"debrief":"A shared pre-pregnancy chat and folic acid are calm prep both partners own.","relearn":"Prepare together: a pre-pregnancy chat, folic acid, both partners owning the planning."},
  {"id":"iw-1038","cat":"fertility-for-real","type":"branch","persona":"Karthik","source":"own your half","hook":"Your partner Meera says fertility is 'her thing' and you don't need to get involved.","steps":[{"prompt":"She mentions a fertility awareness app she's using alone. What do you do?","options":[{"text":"Ask to look at it together and learn the basics with her","then":"She's surprised, then starts explaining what she's learned.","best":true},{"text":"Say that sounds sensible. She's got it covered","then":"She nods, a little tired, and closes the app without a word."},{"text":"Ask her to just summarise it for you later","then":"She summarises briefly, and the learning stays entirely hers."},{"text":"Joke that this is 'her department' anyway","then":"She laughs along, but something in her face doesn't quite match it."}],"why":"Learning it with her turns 'her thing' into something you actually share."},{"prompt":"A friend asks what you know about fertility basics. What do you say?","options":[{"text":"Say you don't know much yet, but you mean to learn","then":"Your friend seems glad you plan to be in it, not leave it all to Meera.","best":true},{"text":"Say that's really more Meera's area","then":"Your friend nods, and the old line goes unquestioned again."},{"text":"Guess at an answer without being sure","then":"You get it half right, and make a mental note to actually learn it."},{"text":"Change the subject to something you're surer of","then":"The question passes, and so does another chance to know it."}],"why":"Admitting you don't know yet, and meaning to learn, is honest and keeps you in it."},{"prompt":"At a check-up, the doctor asks Meera a question and looks at you too. What do you do?","options":[{"text":"Answer alongside her, filling in what you can","then":"The doctor nods, and Meera relaxes, not carrying it alone.","best":true},{"text":"Stay back, telling yourself it's really her question to answer","then":"She answers alone, and wishes you'd spoken up too."},{"text":"Step in and answer for her without checking","then":"She corrects you gently, wishing you'd asked her first."},{"text":"Ask the doctor to write it all down for Meera to share later","then":"The doctor writes it up for Meera, and you leave without hearing any of it yourself."}],"why":"Answering alongside her, not for her, is what owning your half looks like."}],"debrief":"Fertility is a both-of-us matter; owning your half makes the planning shared.","relearn":"Reframe fertility as a both-of-us matter and learn the basics together; don't leave it to her."},
  {"id":"iw-1039","cat":"fertility-for-real","type":"branch","persona":"Pooja","source":"steady not spiral","hook":"A few months of trying with no result, and panic is starting to creep in.","steps":[{"prompt":"Your period arrives again this month. What's your first reaction?","options":[{"text":"Remind yourself a few months is often normal, and note it","then":"You breathe easier, and jot the month down without alarm.","best":true},{"text":"Assume something is seriously wrong already","then":"Worry takes over, though nothing has actually been confirmed."},{"text":"Search online for exactly how many months is 'too long'","then":"Every site gives a different number, and the worry only grows."},{"text":"Avoid thinking about it at all this week","then":"The feeling gets pushed down, and quietly resurfaces later."}],"why":"A few months is often within the normal range, worth noting calmly."},{"prompt":"Your mother asks gently if everything is okay with 'baby news'. What do you say?","options":[{"text":"Say you're taking your time and it's going fine","then":"She smiles, relieved, and doesn't push further.","best":true},{"text":"Tell her the exact number of months so far","then":"She starts counting along with you, and the pressure doubles."},{"text":"Snap that it's none of her business","then":"She looks hurt, and the conversation ends tensely."},{"text":"Say nothing and change the subject fast","then":"She senses something's off, and worries quietly on her own."}],"why":"A calm, general answer holds the boundary without inviting more worry in."},{"prompt":"It's now been several months. What's the calm next step?","options":[{"text":"Ask a clinician for reassurance and next steps","then":"She confirms it's still within a normal range, and outlines what's next.","best":true},{"text":"Wait a few more months before doing anything","then":"The waiting stretches on, with no new information either way."},{"text":"Assume the worst and start researching treatments alone","then":"You spiral through options before knowing if you even need them."},{"text":"Ask around for home remedies that 'worked for others'","then":"Everyone's story is different, and none of it answers yours."}],"why":"A clinician's reassurance is steadier than guessing at what several months means."}],"debrief":"Conception can take several healthy months; a clinician can reassure you.","relearn":"A few months trying is often normal; stay steady and ask a clinician for reassurance."},
  {"id":"iw-1040","cat":"fertility-for-real","type":"branch","persona":"any","source":"skip the hype","hook":"Your friend Divya swears a 'miracle' fertility tea worked for her instantly.","steps":[{"prompt":"She hands you a packet of the tea at lunch. What do you do?","options":[{"text":"Thank her, and ask a clinician later if it's evidence based","then":"You keep the packet, but the real question goes to someone qualified.","best":true},{"text":"Buy three more packets on the way home","then":"You spend more than planned on something still unproven."},{"text":"Say you'll try it exactly like she did","then":"You start the tea, expecting her result without knowing your own."},{"text":"Politely say no and drop the subject","then":"The tea's forgotten, but so is the actual question underneath it."}],"why":"A clinician knows what's evidence based; a friend's story is just her own."},{"prompt":"A few days later, Divya brings the tea up again. What do you tell her?","options":[{"text":"Say you're checking with a clinician about it","then":"She says that's fair, and asks what the clinician says after.","best":true},{"text":"Say you'll start it, to make her happy","then":"She's thrilled, though it's far too soon to know anything really."},{"text":"Stay vague about whether you're trying it","then":"She keeps recommending it, expecting you to start any day."},{"text":"Avoid the question and talk about something else","then":"She senses you're dodging it, and brings it up again later."}],"why":"Being honest about checking first keeps the friendship easy and the facts straight."},{"prompt":"At a routine appointment, you ask the clinician about the tea. She says there's no real evidence behind it. What do you do?","options":[{"text":"Thank her for the honest answer and let the tea go","then":"You feel settled, without the tea and without the doubt.","best":true},{"text":"Ask if it's fine to keep it around, just in case","then":"She says it isn't shown to help, and suggests checking any product with her first."},{"text":"Decide to try it anyway, just in case","then":"You spend more weeks on something not shown to help."},{"text":"Feel annoyed she couldn't 'prove' it wrong outright","then":"She stays patient, and repeats that there's no evidence either way."}],"why":"An honest 'no evidence' from a clinician is worth more than a hopeful maybe."},{"prompt":"Weeks later, Divya brings up the tea again. What do you say?","options":[{"text":"Share what the clinician told you about the evidence","then":"She's a little surprised, and asks what the clinician suggested instead.","best":true},{"text":"Say you'll think about it more","then":"She keeps recommending it, unaware you already asked a clinician."},{"text":"Say it's probably fine, no harm either way","then":"She takes it as encouragement, and buys her sister a packet too."},{"text":"Avoid the topic to not seem like you're judging her choice","then":"The talk moves on, and she never hears what you found out."}],"why":"Sharing what the clinician actually said helps her make her own informed choice too."}],"debrief":"Skip the miracle hype; ask a clinician what's actually evidence-based.","relearn":"Miracle teas sell hope, not facts; ask a clinician for evidence-based guidance."},
  {"id":"iw-1041","cat":"fertility-for-real","type":"branch","persona":"any","source":"your terms","hook":"Relatives keep reminding you that your fertility is fading, so you should hurry.","steps":[{"prompt":"At a wedding, an aunt brings it up again. What's your response?","options":[{"text":"Say your timeline is yours, not theirs to rush","then":"She looks unsure how to respond, and lets the topic drop.","best":true},{"text":"Nod along to avoid an argument at the wedding","then":"She takes the nod as agreement, and brings it up again later."},{"text":"Argue loudly that the comment is outdated","then":"The argument draws attention, and nobody actually feels heard."},{"text":"Laugh it off without saying anything real","then":"The laugh buys a moment, but the comment lands anyway."}],"why":"Naming your own timeline holds the boundary better than a nod or a fight."},{"prompt":"A cousin mentions a 'family friend' who waited too long and regretted it. What do you do?","options":[{"text":"Note it, then ask a clinician for your own facts","then":"You get real information instead of one secondhand story.","best":true},{"text":"Let the story worry you into rushing a decision","then":"One story starts to feel like a deadline it was never meant to be."},{"text":"Argue that her story doesn't prove anything","then":"The cousin gets defensive, and the actual worry goes unaddressed."},{"text":"Repeat the story to your partner as a warning","then":"He worries too, based on a story neither of you can verify."}],"why":"One relative's story isn't a fact about your body; a clinician's answer is."},{"prompt":"Months later the same relatives ask if you've 'finally decided'. What do you say?","options":[{"text":"Say the decision is still yours, made calmly","then":"They quiet down this time, though you know the topic isn't settled for good.","best":true},{"text":"Give them a rough timeline just to satisfy them","then":"The timeline becomes something they now expect you to keep."},{"text":"Apologise for not deciding faster","then":"You feel smaller for something that was never theirs to rush."},{"text":"Avoid family gatherings to dodge the question","then":"The question waits for you at the next one anyway."}],"why":"Standing firm on your own decision holds better than a fake timeline or an apology."}],"debrief":"Relatives' 'hurry' isn't a fact; keep the decision yours with a clinician's calm input.","relearn":"Family 'hurry' isn't a fact; keep the choice yours and get calm facts from a clinician."},
  {"id":"iw-1042","cat":"fertility-for-real","type":"branch","persona":"any","source":"take peace back","hook":"Late-night fertility forums have been costing you sleep for weeks now.","steps":[{"prompt":"It's past midnight and you're deep in a new thread. What do you do?","options":[{"text":"Close the tab and write down your real questions instead","then":"The scrolling stops, and you have something useful for the clinic.","best":true},{"text":"Keep reading until you find a reassuring post","then":"One post calms you, until the next one undoes it entirely."},{"text":"Message a stranger in the thread for advice","then":"They reply kindly, though they know nothing about your body."},{"text":"Screenshot the scariest post to look at again tomorrow","then":"Tomorrow arrives with the same fear, saved and ready to reopen."}],"why":"Real questions for a clinician beat another scroll through strangers' stories."},{"prompt":"Your partner notices you're exhausted and asks what's wrong. What do you say?","options":[{"text":"Admit the forums are keeping you up, and ask for help stopping","then":"He offers to remind you to log off, and you feel less alone in it.","best":true},{"text":"Say you're fine, just a busy week","then":"He believes you, and the late nights continue unnoticed."},{"text":"Say you're only stressed about work","then":"He offers comfort for the wrong worry, and the real one stays hidden."},{"text":"Show him the scariest thread to explain","then":"He worries too, and now two of you are losing sleep over it."}],"why":"Naming the real habit out loud is what makes it easier to actually change."},{"prompt":"A few days later, you're at the clinic with a fresh list of questions in hand. What do you do?","options":[{"text":"Ask every question on your list, one by one","then":"You get calm, direct answers and leave with real information, not a night of dread.","best":true},{"text":"Only ask the easy ones, and save the rest for later","then":"You leave with partial answers, and the harder questions wait for another night."},{"text":"Ask about the scariest post instead of your real worries","then":"She addresses it, but your actual questions go unanswered."},{"text":"Skip most of them, feeling silly for having asked","then":"You leave with fewer answers than you came in hoping for."}],"why":"The written questions, actually asked, turn a bad night into real answers."}],"debrief":"Trade late-night forums for written questions and a clinician's calm answers.","relearn":"Close the forums; take written questions to a clinician for calm, personal answers."},
  {"id":"iw-1043","cat":"fertility-for-real","type":"branch","persona":"Sneha","source":"hold lightly","hook":"You're not sure yet if you even want children, but fertility keeps coming up around you.","steps":[{"prompt":"A colleague mentions egg freezing over coffee. What's your first thought?","options":[{"text":"Learn the calm basics now, even while you're still unsure","then":"You note a few facts, committing to nothing yet.","best":true},{"text":"Decide it's pointless to learn until you're sure","then":"You stay in the dark, and the uncertainty doesn't shrink at all."},{"text":"Assume you'll figure it out whenever the time comes","then":"The basics stay unlearned, waiting for a moment that keeps moving."},{"text":"Feel behind for not already knowing all this","then":"The coffee break ends with worry instead of any real facts."}],"why":"You can learn calm basics while undecided; facts don't commit you to anything."},{"prompt":"You mention it to a friend, who wonders why you'd think about something you're not sure about. What do you say?","options":[{"text":"Say facts now keep your choices open later","then":"She nods, and admits she's been avoiding the same basics herself.","best":true},{"text":"Say knowing the facts means you've basically decided","then":"She nods and assumes you've decided, and the conversation moves on."},{"text":"Say you just like collecting information generally","then":"She laughs it off, missing the actual reason behind it."},{"text":"Admit you're not sure why, just felt like it","then":"She shrugs, and the moment passes without much meaning."}],"why":"Naming that facts keep choices open is the real reason, not just curiosity."},{"prompt":"A friend passes along a clinician who does short, no-pressure chats. What do you do?","options":[{"text":"Book the chat and be upfront that you're unsure","then":"She answers warmly, with no pressure toward any direction.","best":true},{"text":"Book it, but pretend you're already planning to try soon","then":"She tailors advice for a plan you don't actually have yet."},{"text":"Decide it's not worth booking yet","then":"The chat waits, and the questions stay unanswered for now."},{"text":"Book it, but stay too embarrassed to ask anything real","then":"You leave with less than you'd hoped to understand."}],"why":"Being upfront about being unsure gets you honest, pressure-free answers."},{"prompt":"Months later, a relative asks if you've 'decided' yet. What's your answer?","options":[{"text":"Say you're still deciding, and that's completely fine","then":"She's surprised by how calm you sound, and lets it be.","best":true},{"text":"Say yes, just to end the conversation quickly","then":"She's delighted, and now expects news that isn't coming."},{"text":"Say you're leaning toward children to sound more certain","then":"The half-truth follows you into the next family gathering."},{"text":"Avoid the question by leaving the room","then":"She corners you again at the very next function."}],"why":"Staying honestly undecided is a complete answer, not one you owe an apology for."}],"debrief":"You can learn fertility basics calmly while undecided; facts keep choices open.","relearn":"You can learn fertility basics while unsure; calm facts keep choices open."},
  {"id":"iw-1044","cat":"fertility-for-real","type":"role-play","persona":"Sneha","source":"expiry date reply","hook":"At a wedding, an aunty keeps eyeing you across the table as the toasts wind down.","setup":"She leans in, expecting you to look worried.","steps":[{"prompt":"Aunty says: \"Beta, the clock is ticking. You should get moving.\"","options":[{"text":"\"I'll get my facts from a clinician.\"","then":"She blinks, unsure how to answer that, and changes the topic.","best":true},{"text":"\"You're right. Maybe I should hurry up.\"","then":"She nods, satisfied, and says she'll spread the word to the family."},{"text":"\"That's such an old-fashioned thing to say.\"","then":"She looks offended. \"I'm only saying it out of love.\""},{"text":"\"Mind your own business, Aunty.\"","then":"The table goes quiet, and she looks hurt beside you."}],"why":"Naming a clinician, not a clock, answers the pressure without a fight or a retreat."},{"prompt":"Later, she corners you near the buffet and says: \"So when should we expect the good news?\"","options":[{"text":"\"We don't owe anyone an answer.\"","then":"She sighs, but moves on to the next relative in line.","best":true},{"text":"\"Maybe next year. We'll see.\"","then":"She repeats 'next year' to three other relatives before dessert."},{"text":"\"Nothing yet, but we'll let you know.\"","then":"She nods, already looking forward to being told first."},{"text":"\"I don't know. Ask my mother.\"","then":"Your mother gets pulled into the same conversation instead."}],"why":"No one is owed an answer, and saying so closes the question cleanly."},{"prompt":"Weeks later at another function, the same aunty says: \"Still no news, hmm?\"","options":[{"text":"\"Nothing to share, and that's fine.\"","then":"She shrugs, and finally seems to let the topic rest.","best":true},{"text":"\"I know, I know. We're really trying hard.\"","then":"She takes it as a promise, and asks again at the next function."},{"text":"\"Why do you even keep asking me this?\"","then":"She looks taken aback. \"I'm just curious, beta.\""},{"text":"\"Please, can we talk about something else?\"","then":"She agrees, but circles back to it before the evening ends."}],"why":"Staying calm and settled closes the question better than a promise or a deflection."}],"relearn":"Meet the 'expiry date' clock-pressure with a calm line: facts come from a clinician, and the timing is yours."},
  {"id":"iw-1045","cat":"fertility-for-real","type":"role-play","persona":"Karthik","source":"both of us","hook":"Your partner Aisha tends to wave off fertility planning as something she'll just handle.","setup":"She says it lightly, already changing the subject.","steps":[{"prompt":"Aisha says: \"It's fine. This is more my area anyway.\"","options":[{"text":"\"It's a both-of-us thing. Let's learn it together.\"","then":"She pauses, surprised, then says, \"Okay, where do we start?\"","best":true},{"text":"\"Fine, I'll just leave it all to you then.\"","then":"She nods, though something in her shoulders sags a little."},{"text":"\"You're probably better at this than me anyway.\"","then":"She laughs it off, but the comment settles the old pattern deeper."},{"text":"\"I'll help if you tell me exactly what to do.\"","then":"She hesitates. \"I don't want to have to manage that too.\""}],"why":"Both-of-us, said plainly, is what actually turns the old pattern around."},{"prompt":"A few days later, Aisha asks: \"Did you look at anything I sent you?\"","options":[{"text":"\"Yes, I read it and had a question about timing.\"","then":"She lights up. \"Let's go through it together tonight.\"","best":true},{"text":"\"Not yet. I'll get to it soon.\"","then":"She says: \"That's what you said last time too.\""},{"text":"\"Can you just summarise it for me instead?\"","then":"She summarises it, and the learning stays mostly hers again."},{"text":"\"Does it really matter if I read it myself?\"","then":"She stiffens. \"It matters that I'm not doing this alone.\""}],"why":"Actually engaging with what she sent shows the sharing is real, not just said."},{"prompt":"At a family lunch, an uncle jokes: \"Leave the baby planning to the ladies, no?\"","options":[{"text":"\"Actually, it's ours to plan together. I'm joining in.\"","then":"The uncle looks surprised, and Aisha smiles beside you.","best":true},{"text":"\"Ha, you're right. That's more her department.\"","then":"The table laughs, and Aisha's smile doesn't quite reach her eyes."},{"text":"\"Uncle, that's a bit outdated, isn't it?\"","then":"The uncle shrugs it off, and the actual point gets lost."},{"text":"\"Depends on the couple, I suppose.\"","then":"The uncle nods vaguely, and nothing really gets said either way."}],"why":"Saying you're joining in answers the joke better than a vague reply."},{"prompt":"That night, Aisha says quietly: \"That lunch got to me a bit.\"","options":[{"text":"\"Sorry it got to you. It's ours to share.\"","then":"She rests her head on your shoulder, visibly lighter.","best":true},{"text":"\"It's really not a big deal.\"","then":"She smiles, but seems to want the moment to land more than that."},{"text":"\"I just didn't want Uncle to think badly of us.\"","then":"Her smile fades slightly at the real reason behind it."},{"text":"\"I'm trying, but I still have a lot to learn.\"","then":"She nods, but her feeling about the lunch goes unaddressed."}],"why":"Naming it as truly shared, not brushing it off, is what actually lands for her."}],"relearn":"Reframe 'a woman's topic' as a both-of-us thing, and invite your partner to learn the basics together."},
  {"id":"iw-1046","cat":"fertility-for-real","type":"role-play","persona":"any","source":"steady a friend","hook":"Your friend Naina forwards a panic post claiming it's 'too late for us after 30'.","setup":"She messages you straight after, clearly rattled.","steps":[{"prompt":"Naina writes: \"See, we're basically doomed already, aren't we?\"","options":[{"text":"\"That post is built to scare, not inform.\"","then":"She exhales. \"Okay. I guess I panicked a little.\"","best":true},{"text":"\"You might be right. That's a scary thought.\"","then":"She spirals further. \"So what do we even do now?\""},{"text":"\"Just don't read stuff like that.\"","then":"She sends another post two minutes later anyway."},{"text":"\"I'm sure it's fine. Don't worry about it.\"","then":"She isn't reassured, since nothing was actually explained."}],"why":"Naming the post as built to scare opens the door to real facts instead of fear."},{"prompt":"Naina asks: \"Okay, so what should I actually believe?\"","options":[{"text":"\"Fertility shifts gradually. Let's ask a clinician for the real facts.\"","then":"She agrees, and you both note down questions to bring.","best":true},{"text":"\"Honestly, I don't really know either.\"","then":"She stays unsure, and the post's claim lingers unanswered."},{"text":"\"Whatever your gut tells you, probably.\"","then":"Her gut is still running on the scare from the post."},{"text":"\"Just trust me. It's not that bad.\"","then":"She wants to believe you, but isn't sure why she should."}],"why":"Pointing her to a clinician gets her real facts instead of your guess or hers."},{"prompt":"A week later, Naina says: \"I saw the clinician. She said the post was way off.\"","options":[{"text":"\"That's a relief. How are you feeling about it now?\"","then":"She exhales. \"Actually a lot calmer, thank you.\"","best":true},{"text":"\"See, I told you it would be fine.\"","then":"She nods, though it feels more about being right than about her."},{"text":"\"So no more panicking then, alright?\"","then":"She laughs. \"I'll try. Old habits die hard.\""},{"text":"\"Good, now maybe you'll stop reading that stuff.\"","then":"She nods, though it feels more like a scolding than support."}],"why":"Asking how she's feeling keeps the moment about her, not about being right."}],"relearn":"Answer a 'too late after 30' panic with calm truth: fertility shifts gradually, and a clinician gives real facts."},
  {"id":"iw-1047","cat":"fertility-for-real","type":"role-play","persona":"Pooja","source":"ask the doctor","hook":"At a check-up, you almost say 'no questions' out of shyness, though you have several.","setup":"The doctor pauses, waiting, pen ready.","steps":[{"prompt":"The doctor asks: \"Do you have any questions for me today?\"","options":[{"text":"\"Yes, we're thinking ahead. What about folic acid?\"","then":"She nods and pulls out a leaflet to go through with you.","best":true},{"text":"\"No, no questions, sorry to bother you.\"","then":"She closes her notes, and your real questions stay unasked."},{"text":"\"Just whatever you think is important, really.\"","then":"She covers the basics, though not quite what you wanted."},{"text":"\"I probably shouldn't take up your time with mine.\"","then":"She reassures you gently, but the real questions still go unasked."}],"why":"Naming the actual question, even while just thinking ahead, gets you the answer you came for."},{"prompt":"A moment later, she asks: \"Is there anything else on your mind?\"","options":[{"text":"\"Yes, how long does conception usually take?\"","then":"She explains gently that it can take several months.","best":true},{"text":"\"No, that covers it, thank you.\"","then":"You leave it there, though the other questions linger."},{"text":"\"Whatever's normal for someone my age, I guess.\"","then":"She gives a general answer that doesn't quite fit what you wanted to know."},{"text":"\"I don't want to take up more of your time.\"","then":"She says she has time, but the moment to ask has passed."}],"why":"Asking your real question, even now, gets you the answer you came for."},{"prompt":"As you're leaving, she says: \"Feel free to write down anything for next time.\"","options":[{"text":"\"I will, thank you. That's really useful.\"","then":"You start a running list on your phone that same evening.","best":true},{"text":"\"I'm sure I won't forget anything important.\"","then":"You forget two questions before you're even home."},{"text":"\"I don't want to seem like I'm over-asking.\"","then":"She smiles. \"That's exactly what these visits are for.\""},{"text":"\"Maybe, if I remember to.\"","then":"The list never quite gets started."}],"why":"Taking her up on it keeps your real questions from slipping away next time."}],"relearn":"You can ask a clinician preconception questions even while just thinking ahead; that's exactly what the visit is for."},
  {"id":"iw-1048","cat":"fertility-for-real","type":"role-play","persona":"any","source":"pull them out","hook":"Your spouse Dev is doomscrolling fertility forums again, well past midnight.","setup":"He's hunched over his phone, jaw tight.","steps":[{"prompt":"Dev mutters: \"This thread says it's worse than we thought.\"","options":[{"text":"\"Let's close this and note our questions.\"","then":"He hesitates, then sets the phone face down on the table.","best":true},{"text":"\"Keep reading. Maybe it gets clearer.\"","then":"He scrolls further, and the thread only gets grimmer."},{"text":"\"You should stop reading that stuff.\"","then":"He gets defensive. \"I'm just trying to understand it.\""},{"text":"\"It's probably nothing. Don't worry.\"","then":"He isn't reassured, since nothing was actually addressed."}],"why":"Closing the thread and naming real questions ends the spiral instead of feeding it."},{"prompt":"The next night, Dev reaches for his phone again and says: \"I just want to check one more thing.\"","options":[{"text":"\"Let's write it down instead of scrolling for it.\"","then":"He nods slowly, and starts a note on your phone together.","best":true},{"text":"\"Fine, but just one thing, okay?\"","then":"One thing turns into an hour, like it did before."},{"text":"\"You always say that and then you don't stop.\"","then":"He gets defensive, and reaches for the phone anyway."},{"text":"\"I can't keep watching you do this.\"","then":"He puts the phone down, but feels judged rather than helped."}],"why":"Turning the urge into a written question works better than a rule or a guilt trip."},{"prompt":"At the clinic, the doctor asks: \"What's been on your minds lately?\" Dev looks at you first.","options":[{"text":"\"We've got a few things on our minds, actually.\"","then":"The doctor nods, and you both start naming what's been worrying you.","best":true},{"text":"\"He's had a rough time online. Ask him.\"","then":"Dev looks put on the spot, unsure where to start."},{"text":"\"Nothing really. We're just here for a check.\"","then":"The real worries go unmentioned, and the visit stays general."},{"text":"\"Let's just wait and see if it settles on its own.\"","then":"The visit passes without addressing what's actually been on your minds."}],"why":"Naming what's actually on your minds is what a clinician can help with."},{"prompt":"That evening, Dev says: \"I still catch myself wanting to check those forums.\"","options":[{"text":"\"That's fine, and let's write it into a list for next time.\"","then":"He relaxes. \"That actually helps, having somewhere to put it.\"","best":true},{"text":"\"You really shouldn't do that anymore.\"","then":"He nods, but doesn't say what he'll do instead."},{"text":"\"Just delete the app if it's that bad.\"","then":"He deletes it, though the underlying worry stays unaddressed."},{"text":"\"I thought we were past that already.\"","then":"He feels judged, and the honesty behind his comment fades."}],"why":"Meeting the honesty with a plan works better than a rule or a hint of disappointment."}],"relearn":"Help a spiralling partner by closing the forums and saving real questions for a clinician, not feeding the panic."},
  {"id":"iw-1049","cat":"fertility-for-real","type":"role-play","persona":"any","source":"not a competition","hook":"A relative insists a friend's bahu conceived in one month, so you should too.","setup":"She brings it up again at Sunday lunch.","steps":[{"prompt":"She says: \"One month, imagine that! Why is it taking you longer?\"","options":[{"text":"\"Every couple's timeline is different. That's not unusual.\"","then":"She pauses, unsure how to argue with that.","best":true},{"text":"\"Maybe something's wrong with us. I don't know.\"","then":"She nods seriously. \"You should get that checked then.\""},{"text":"\"That's a rude thing to compare, honestly.\"","then":"She looks stung. \"I'm only trying to help, beta.\""},{"text":"\"I don't know. Maybe we're just unlucky.\"","then":"She starts offering remedies for your 'bad luck'."}],"why":"Naming timelines as different closes the comparison without a fight or self-doubt."},{"prompt":"She adds: \"That bahu also saw a special doctor.\"","options":[{"text":"\"We'll see our own doctor, on our own terms.\"","then":"She seems satisfied that you're not ignoring it entirely.","best":true},{"text":"\"Maybe we should see her doctor too then.\"","then":"She lights up, eager to arrange the introduction herself."},{"text":"\"We don't need a doctor. We're fine.\"","then":"She frowns. \"Then why is it taking so long?\""},{"text":"\"We'll think about it, no promises.\"","then":"She takes the noncommittal answer as a yes, and starts talking dates."}],"why":"Naming your own doctor, on your own terms, ends the comparison without arguing."},{"prompt":"At the next family function, she asks: \"Any progress since we last spoke?\"","options":[{"text":"\"There's nothing to share, and that's fine as it is.\"","then":"She sighs, but doesn't push it further this time.","best":true},{"text":"\"Still nothing. Honestly, it's starting to worry me too.\"","then":"She takes the worry as an opening to bring up the bahu again."},{"text":"\"Why do you keep asking me this every time?\"","then":"She looks hurt. \"I'm just interested. That's all.\""},{"text":"\"We're seeing the bahu's doctor next week actually.\"","then":"She's delighted, and now feels involved in a decision that wasn't hers."}],"why":"Keeping it low-key protects your own pace, without inviting more questions."}],"relearn":"Each couple's timeline differs; one person's quick pregnancy isn't a benchmark you owe anyone."},
  {"id":"iw-1050","cat":"fertility-for-real","type":"role-play","persona":"any","source":"decline the hype","hook":"A salesman at a health expo waves you over toward his fertility supplement stall.","setup":"He holds out a bottle, already reaching for your card.","steps":[{"prompt":"He says: \"This is guaranteed to work. Everyone who tries it sees results.\"","options":[{"text":"\"No guarantees. I'll ask a clinician.\"","then":"He shrugs, but keeps the bottle held out just in case.","best":true},{"text":"\"That sounds promising. Tell me more.\"","then":"He launches into a longer pitch, still with no real evidence behind it."},{"text":"\"I'll take it. Can't hurt to try, right?\"","then":"He hands it over, pleased, and pockets your payment."},{"text":"\"That sounds fake. Get away from me.\"","then":"He steps back, but lingers nearby, still pitching to someone else."}],"why":"Naming that no guarantee is real ends the pitch without buying into the hype."},{"prompt":"A different vendor calls out: \"Best offer today. Don't miss it!\"","options":[{"text":"\"No, thank you. A clinician can judge proof.\"","then":"He nods and lets you walk on.","best":true},{"text":"\"Fine, just this once then.\"","then":"You leave with a bottle and the same doubts you walked in with."},{"text":"\"If you can show me proof, I'll buy one.\"","then":"He waves a page of customer testimonials, and you feel the pull to say yes."},{"text":"\"Maybe I'll think about it and come back.\"","then":"He keeps the bottle aside, expecting you to return for it."}],"why":"A calm no, with proof left to a clinician, beats letting the seller judge his own product."},{"prompt":"Later, a friend at the expo asks: \"Is that fertility booster someone was selling worth getting?\"","options":[{"text":"\"I'll check with a clinician about it.\"","then":"She nods. \"Let me know what she says.\"","best":true},{"text":"\"Maybe. It can't hurt, right?\"","then":"She encourages you to go get one, and the hype spreads a little further."},{"text":"\"Everyone says it works, so why not.\"","then":"She buys one too, based on the crowd rather than any evidence."},{"text":"\"I don't know. It seemed a bit much.\"","then":"The doubt lingers, without a real answer to replace it."}],"why":"Naming the clinician as the real source keeps the hype from spreading to a friend too."}],"relearn":"No product 'guarantees' a baby; decline the hype and ask a clinician what's actually evidence-based."},
  {"id":"iw-1260","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"A real family needs at least one son to carry the name.\"","myth":{"un":"A real family needs at least one son to carry the name.","re":"A family is complete with daughters, sons, or no children; no son is owed to anyone, and son-preference is unjust.","why":"A child's worth never depends on their sex."},"relearn":"A family is whole with daughters or sons; no son is owed, and son-preference is unjust.","persona":"Razia","source":"no son owed"},
  {"id":"iw-1261","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"An unmarried woman past thirty has clearly missed her chance.\"","myth":{"un":"An unmarried woman past thirty has clearly missed her chance.","re":"A woman's worth has no expiry date; single and childfree are full lives, not missed chances.","why":"No one's value runs out on a calendar."},"relearn":"A woman's worth has no expiry; single and childfree are full lives, not a missed chance.","persona":"Sneha","source":"no expiry"},
  {"id":"iw-1262","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"You can find out the baby's sex quietly at a private clinic, no one will know.\"","myth":{"un":"You can find out the baby's sex quietly at a private clinic, no one will know.","re":"Prenatal sex determination is illegal under India's PCPNDT Act, secret or not; it exists to stop the loss of girls.","why":"The law protects daughters from being selected away."},"relearn":"Prenatal sex determination is illegal under the PCPNDT Act, however quietly it is done.","persona":"Razia","source":"PCPNDT secret"},
  {"id":"iw-1263","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"Your clock is ticking, so just hurry up and have one already.\"","myth":{"un":"Your clock is ticking, so just hurry up and have one already.","re":"A fertility clock is not a weapon; 'hurry up' is pressure, not care, and whether and when stays yours.","why":"Panic-talk is not the same as support."},"relearn":"A fertility clock is not a weapon; 'hurry up' is pressure, not care.","persona":"Sneha","source":"clock not weapon"},
  {"id":"iw-1317","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"You owe the family good news by your first anniversary.\"","myth":{"un":"You owe the family good news by your first anniversary.","re":"No answer and no timeline is owed to the 'good news' chorus; whether and when is the couple's own.","why":"A wedding date doesn't start anyone's clock but yours."},"relearn":"No 'good news' and no timeline is owed to anyone; whether and when is the couple's own.","persona":"Pooja","source":"no good news owed"},
  {"id":"iw-1264","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"Two daughters? You really should try once more for a boy.\"","myth":{"un":"Two daughters? You really should try once more for a boy.","re":"There is no duty to 'try for a son'; daughters are not a shortfall, and the couple decides if they want more at all.","why":"Daughters are whole, not a problem to fix."},"relearn":"There is no duty to try for a son; daughters are not a shortfall to correct.","persona":"Razia","source":"daughters whole"},
  {"id":"iw-1265","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"If you don't want children, something must be wrong with you.\"","myth":{"un":"If you don't want children, something must be wrong with you.","re":"Not wanting children is a valid, healthy choice; childfree is complete, not a flaw to diagnose.","why":"A life can be full without children."},"relearn":"Not wanting children is a valid, healthy choice; childfree is complete, not a flaw.","persona":"Sneha","source":"childfree complete"},
  {"id":"iw-1266","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"The whole family voted, so now it's settled when you'll conceive.\"","myth":{"un":"The whole family voted, so now it's settled when you'll conceive.","re":"No family vote decides your body; whether and when to conceive is the couple's own, not put to the household.","why":"This choice isn't anyone else's to cast a vote on."},"relearn":"No family vote decides when you conceive; that choice is the couple's own.","persona":"Pooja","source":"no family vote"},
  {"id":"iw-1267","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"Standing up to the in-laws on this will start a huge family war.\"","myth":{"un":"Standing up to the in-laws on this will start a huge family war.","re":"A calm, firm boundary can hold without a fight; you can decline pressure warmly and still keep the peace.","why":"Saying 'this is ours' is not declaring war."},"relearn":"A calm, firm boundary can hold without a war; you can decline pressure and keep the peace.","persona":"any","source":"boundary not war"},
  {"id":"iw-1268","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"Once you have a daughter, a son must come next to balance the family.\"","myth":{"un":"Once you have a daughter, a son must come next to balance the family.","re":"No 'balance' is owed; a family of daughters needs no correcting, and son-preference is unjust.","why":"Children aren't a set you complete by sex."},"relearn":"No son is owed to 'balance' a family; daughters need no correcting.","persona":"Razia","source":"no balancing son"},
  {"id":"iw-1269","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"A childfree woman will surely regret it and die alone.\"","myth":{"un":"A childfree woman will surely regret it and die alone.","re":"'You'll regret it' is a scare, not a fact; a childfree life is full, connected, and a valid choice as it stands.","why":"No one can hand you your future regrets in advance."},"relearn":"'You'll regret it' is a scare, not a fact; childfree is a full, valid life.","persona":"Sneha","source":"regret scare"},
  {"id":"iw-1270","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"You'll change your mind about children, everyone does eventually.\"","myth":{"un":"You'll change your mind about children, everyone does eventually.","re":"'You'll change your mind' isn't reassurance; your choice today is valid as it stands, and only you get to revisit it.","why":"Predicting your future doesn't override your present."},"relearn":"'You'll change your mind' isn't reassurance; your choice is valid as it stands.","persona":"any","source":"change mind"},
  {"id":"iw-1271","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"Getting a sex-determination test done abroad is a clever way around the law.\"","myth":{"un":"Getting a sex-determination test done abroad is a clever way around the law.","re":"Sex selection is wrong and illegal under the PCPNDT Act; routing around it is not clever, it harms daughters.","why":"The harm is the same wherever the test is done."},"relearn":"Sex selection is wrong and illegal under the PCPNDT Act; there's no clever way around it.","persona":"Razia","source":"no loophole"},
  {"id":"iw-1272","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"A good daughter-in-law gives the family a grandchild without making them ask.\"","myth":{"un":"A good daughter-in-law gives the family a grandchild without making them ask.","re":"Your worth isn't measured by producing a grandchild on cue; whether and when is yours and your partner's.","why":"You are not a duty to be performed on schedule."},"relearn":"Your worth isn't producing a grandchild on cue; whether and when is yours.","persona":"Pooja","source":"not on cue"},
  {"id":"iw-1273","cat":"free-of-pressure","type":"strike-rewrite","hook":"\"Tell the relatives you're 'trying' so they stop asking, even if you're not.\"","myth":{"un":"Tell the relatives you're 'trying' so they stop asking, even if you're not.","re":"You don't owe relatives an explanation true or false; a calm 'we'll share in our own time' is a complete answer.","why":"No account of your plans is owed to the chorus."},"relearn":"You owe relatives no explanation; 'we'll share in our own time' is a complete answer.","persona":"any","source":"no account owed"},
  {"id":"iw-1274","cat":"free-of-pressure","type":"sort","hook":"Sort each line: pressure dressed as care, or genuine support?","items":[{"id":"a","text":"\"When's the good news? Don't wait too long!\""},{"id":"b","text":"\"Whatever you two decide, we're with you.\""},{"id":"c","text":"\"You need a son to be complete.\""},{"id":"d","text":"\"Take your time; there's no rush from us.\""},{"id":"e","text":"\"Your clock is ticking, hurry up.\""},{"id":"f","text":"\"We'll love any grandchild, or none, equally.\""}],"bins":[{"id":"pressure","label":"Pressure","valence":"neg"},{"id":"support","label":"Genuine support","valence":"pos"}],"key":{"a":"pressure","b":"support","c":"pressure","d":"support","e":"pressure","f":"support"},"relearn":"'Good news' nagging, son-pressure and a ticking clock are pressure; no-strings 'whatever you decide' is real support.","persona":"any","source":"pressure vs support"},
  {"id":"iw-1275","cat":"free-of-pressure","type":"sort","hook":"Sort: legal in India, or illegal under the PCPNDT Act?","items":[{"id":"a","text":"A clinician explaining fertility to a couple"},{"id":"b","text":"A scan to reveal the baby's sex before birth"},{"id":"c","text":"Choosing your own family size together"},{"id":"d","text":"A test to select a baby's sex"},{"id":"e","text":"Folic acid advice before pregnancy"},{"id":"f","text":"Aborting because the baby is a girl"}],"bins":[{"id":"legal","label":"Legal","valence":"pos"},{"id":"illegal","label":"Illegal (PCPNDT)","valence":"neg"}],"key":{"a":"legal","b":"illegal","c":"legal","d":"illegal","e":"legal","f":"illegal"},"relearn":"Care, planning and folic-acid advice are legal; revealing or selecting a baby's sex before birth is illegal under the PCPNDT Act.","persona":"Razia","source":"legal vs PCPNDT"},
  {"id":"iw-1276","cat":"free-of-pressure","type":"sort","hook":"Sort: holds your choice, or surrenders it to pressure?","items":[{"id":"a","text":"\"We'll share our news in our own time.\""},{"id":"b","text":"Conceiving now just to silence the aunties"},{"id":"c","text":"Refusing son-preference outright"},{"id":"d","text":"Agreeing to a sex test to please elders"},{"id":"e","text":"Deciding family size with your partner"},{"id":"f","text":"Trying for a boy because relatives insist"}],"bins":[{"id":"holds","label":"Holds your choice","valence":"pos"},{"id":"surrenders","label":"Surrenders it","valence":"neg"}],"key":{"a":"holds","b":"surrenders","c":"holds","d":"surrenders","e":"holds","f":"surrenders"},"relearn":"Sharing in your own time, refusing son-preference and deciding together hold your choice; conceding to pressure surrenders it.","persona":"Pooja","source":"holds vs surrenders"},
  {"id":"iw-1277","cat":"free-of-pressure","type":"sort","hook":"Sort: whose decision is it, really?","items":[{"id":"a","text":"Whether to have children"},{"id":"b","text":"How many children you'll have"},{"id":"c","text":"When you'll start a family"},{"id":"d","text":"Which neighbour you should keep up with"},{"id":"e","text":"What the relatives wish you'd do"},{"id":"f","text":"What society expects of a 'real' woman"}],"bins":[{"id":"yours","label":"Yours / the couple's","valence":"pos"},{"id":"noise","label":"Outside noise","valence":"neutral"}],"key":{"a":"yours","b":"yours","c":"yours","d":"noise","e":"noise","f":"noise"},"relearn":"Whether, when and how many are yours and the couple's; keeping up with others, relatives' wishes and 'society' are just noise.","persona":"any","source":"yours vs noise"},
  {"id":"iw-1278","cat":"free-of-pressure","type":"sort","hook":"Sort each reply to son-pressure: equal-value reply, or gives in?","items":[{"id":"a","text":"\"We'll love any child equally.\""},{"id":"b","text":"\"Fine, we'll keep trying for a boy.\""},{"id":"c","text":"\"A daughter is not less than a son.\""},{"id":"d","text":"\"You're right, we need a male heir.\""},{"id":"e","text":"\"Our family is complete as it is.\""},{"id":"f","text":"\"We'll do the test you suggested.\""}],"bins":[{"id":"equal","label":"Equal value","valence":"pos"},{"id":"givesin","label":"Gives in","valence":"neg"}],"key":{"a":"equal","b":"givesin","c":"equal","d":"givesin","e":"equal","f":"givesin"},"relearn":"'Any child equally', 'a daughter is not less', and 'complete as we are' hold equal value; agreeing to try for a boy or test gives in.","persona":"Razia","source":"equal vs gives in"},
  {"id":"iw-1279","cat":"free-of-pressure","type":"sort","hook":"Sort: a reason that's yours, or someone else's agenda?","items":[{"id":"a","text":"You both feel ready and steady"},{"id":"b","text":"Relatives want a grandchild now"},{"id":"c","text":"Your own health and recovery"},{"id":"d","text":"Keeping up with friends' families"},{"id":"e","text":"The two of you talked it through"},{"id":"f","text":"Elders are tired of waiting"}],"bins":[{"id":"yours","label":"Your reason","valence":"pos"},{"id":"theirs","label":"Their agenda","valence":"neg"}],"key":{"a":"yours","b":"theirs","c":"yours","d":"theirs","e":"yours","f":"theirs"},"relearn":"Your readiness, health and a shared talk are your reasons; relatives wanting it now or keeping up with friends are someone else's agenda.","persona":"any","source":"yours vs agenda"},
  {"id":"iw-1280","cat":"free-of-pressure","type":"sort","hook":"Sort: a calm boundary that holds, or a fight that flares?","items":[{"id":"a","text":"\"We hear you; this stays our decision.\""},{"id":"b","text":"Shouting back to win the argument"},{"id":"c","text":"\"Let's change the subject for now.\""},{"id":"d","text":"Storming out every family dinner"},{"id":"e","text":"\"We'll share when we're ready.\""},{"id":"f","text":"Cutting off relatives over one comment"}],"bins":[{"id":"boundary","label":"Calm boundary","valence":"pos"},{"id":"fight","label":"Flares a fight","valence":"neg"}],"key":{"a":"boundary","b":"fight","c":"boundary","d":"fight","e":"boundary","f":"fight"},"relearn":"'This stays ours', 'change the subject' and 'when we're ready' hold calmly; shouting, storming out or cutting off flare a fight.","persona":"any","source":"boundary vs fight"},
  {"id":"iw-1281","cat":"free-of-pressure","type":"branch","persona":"any","source":"good news reply","hook":"At every gathering, an aunt loudly asks when the 'good news' is coming.","steps":[{"prompt":"She asks again in front of the whole table this time. What do you say?","options":[{"text":"Say you'll share in your own time, then change the subject","then":"The table moves on to dessert, and the moment passes easily.","best":true},{"text":"Give a fake date just to end the moment quickly","then":"The fake date gets repeated by three relatives before you leave."},{"text":"Explain in detail why it's a private matter","then":"The explanation invites more questions instead of fewer."},{"text":"Ignore the question completely and look away","then":"She repeats it louder, assuming you didn't hear."}],"why":"A warm, brief answer plus a subject change closes it without a fight or a lie."},{"prompt":"Later, she catches you alone and asks more quietly this time. What do you do?","options":[{"text":"Answer calmly and briefly, then let it go","then":"She nods slowly, and seems to finally hear it.","best":true},{"text":"Open up more, since she's asking privately now","then":"The private answer becomes the next public topic within the week."},{"text":"Get visibly frustrated at being asked again","then":"She looks hurt, and the tension follows you both back to the table."},{"text":"Say something vague to end the moment fast","then":"The vague answer leaves the question open for next time."}],"why":"A calm, brief answer holds better than opening up or getting frustrated."},{"prompt":"At the next family function, a cousin repeats the exact question. What's your move?","options":[{"text":"Give a calm, brief answer, and let it go","then":"The cousin shrugs, and the moment passes without much fuss.","best":true},{"text":"Ask her why everyone keeps asking the same thing","then":"The question turns into a longer, more awkward conversation."},{"text":"Answer differently this time, just to seem less repetitive","then":"The new answer invites new questions you didn't want either."},{"text":"Skip the next few family events to avoid it","then":"The question is simply waiting for you at the one after that."}],"why":"Staying calm and brief is what finally makes the question stop."}],"debrief":"A warm 'in our own time' plus a subject change holds without a fight.","relearn":"'We'll share in our own time' answers the 'good news' chorus calmly, no fight and no fake timeline."},
  {"id":"iw-1282","cat":"free-of-pressure","type":"branch","persona":"Razia","source":"try for boy reply","hook":"Before you've even started trying, your mother-in-law is already hinting the first child should be a boy.","steps":[{"prompt":"She brings it up again at a family dinner, patting your hand. What do you say?","options":[{"text":"Say gently that any child is equally loved, and it's ours to decide","then":"She goes quiet for a moment, and says nothing more tonight.","best":true},{"text":"Agree quietly, to keep the peace at home","then":"She takes the agreement seriously, and starts planning around it."},{"text":"Snap that the comment is deeply unfair","then":"She looks wounded, and the table goes quiet for a moment."},{"text":"Laugh it off without really answering","then":"The laugh reads as agreement, and she brings it up again soon."}],"why":"Naming equal value, calmly, rejects the pressure without a fight or false agreement."},{"prompt":"Your husband later says his mother wants you to 'try for a boy first, just to be safe'. What do you say to him?","options":[{"text":"Say every child is equal, and this is ours to decide","then":"He goes quiet, then admits he was just repeating what he'd heard.","best":true},{"text":"Agree, since he seems to actually want it too","then":"The decision starts drifting toward pressure neither of you named."},{"text":"Get angry that he'd even suggest it","then":"He gets defensive, and the real conversation never quite happens."},{"text":"Say nothing and let the comment pass","then":"The idea quietly settles in, unchallenged, for later."}],"why":"Naming it plainly to your husband keeps the pressure from settling in at home too."},{"prompt":"At a temple visit, a priest blesses the family 'for a grandson soon'. How do you respond?","options":[{"text":"Thank him, and say any child will be equally welcome","then":"He nods, a little surprised, and moves on to the next blessing.","best":true},{"text":"Accept the blessing without comment","then":"The blessing goes unchallenged, and the assumption stands."},{"text":"Explain at length why the blessing is wrong","then":"The queue behind you grows restless, and little actually changes."},{"text":"Avoid temple visits with that priest from now on","then":"The comment goes unanswered, waiting for the next visit instead."}],"why":"A polite correction in the moment answers the assumption without a scene."},{"prompt":"A young cousin overhears the comments and asks why everyone wants a boy so badly. What do you tell her?","options":[{"text":"Tell her every child would be loved exactly the same","then":"She nods, and says that sounds fair to her.","best":true},{"text":"Say some people just prefer boys, and leave it there","then":"She grows quiet, turning the comment over in her head."},{"text":"Say it's complicated and change the subject","then":"The question stays unanswered, and she stops asking, not wondering."},{"text":"Say maybe it will be a boy anyway","then":"The comment leans back toward the pressure you'd been holding off."}],"why":"Naming equal value plainly answers the real question underneath hers."}],"debrief":"'Any child equally, ours to decide' rejects son-preference and holds your choice.","relearn":"Meet son-pressure with equal value and 'ours to decide', never a sex test."},
  {"id":"iw-1283","cat":"free-of-pressure","type":"branch","persona":"Sneha","source":"clock reply","hook":"A relative warns your clock is ticking, and you must conceive this year or regret it.","steps":[{"prompt":"She says it firmly at a cousin's wedding reception. What do you say?","options":[{"text":"Thank her, then say your timeline is calm and yours","then":"She looks unsure how to respond to that, and moves along.","best":true},{"text":"Panic and agree you should probably start right away","then":"The panic follows you home, and settles in uninvited."},{"text":"Argue that fertility clocks aren't real at all","then":"She digs in further, and the conversation turns into a debate."},{"text":"Laugh nervously and say nothing real","then":"The nervous laugh reads as agreement, and she repeats it to others."}],"why":"Naming your own calm timeline answers the pressure without panic or an argument."},{"prompt":"Weeks later, she sends you an article about 'the ticking clock'. What do you do?","options":[{"text":"Thank her for thinking of you, and set it aside unread","then":"She doesn't send another one for a while after that.","best":true},{"text":"Read it late at night and let it worry you","then":"The worry follows you into the next few days."},{"text":"Reply arguing against every point in the article","then":"She sends back two more articles to make her point again."},{"text":"Forward it to a friend to see if she's worried too","then":"Now your friend is carrying the same worry you were handed."}],"why":"Acknowledging it kindly and setting it aside keeps the worry from taking hold."},{"prompt":"At the next family gathering, she asks if you've 'thought more' about it. What's your answer?","options":[{"text":"Say you're keeping your own pace, calmly","then":"She nods, and this time seems to actually accept it.","best":true},{"text":"Say you've decided to try sooner, to end the topic","then":"The decision feels rushed, made more for her than for you."},{"text":"Ask her, a little sharply, to just drop it already","then":"She looks hurt, and brings it up again at the next family call anyway."},{"text":"Avoid her for the rest of the gathering","then":"She corners you again just as you're leaving."}],"why":"A steady, unchanged answer holds better than a rushed decision or an avoided one."}],"debrief":"A fertility clock is not a weapon; 'my timeline, decided calmly' holds.","relearn":"Name the ticking-clock line as pressure; keep your own timeline, decided calmly."},
  {"id":"iw-1284","cat":"free-of-pressure","type":"branch","persona":"Razia","source":"refuse tout","hook":"At a clinic, a man lingers near the waiting room, watching you a beat too long.","steps":[{"prompt":"He offers, for a fee, to tell you the baby's sex right now. What do you do?","options":[{"text":"Refuse flatly. It's illegal, and you won't be part of it","then":"He backs away, and you're left waiting in peace, sex still unknown.","best":true},{"text":"Consider it, since your in-laws keep asking","then":"You weigh it, even though it was never a fair thing to ask for."},{"text":"Report him loudly in front of other patients","then":"The room turns to stare, and the moment becomes about the scene."},{"text":"Think it may be harmless, and take his number just in case","then":"He expects a call, and the offer stays open for later."}],"why":"A flat refusal protects any child equally, and it's what the law requires too."},{"prompt":"Your mother-in-law calls that evening asking what you 'found out'. What do you say?","options":[{"text":"Say you're not finding out. Any child is welcome","then":"She's quiet for a moment, then says she just worries about you.","best":true},{"text":"Mention the tout's offer, just to see her reaction","then":"She grows curious, and asks if you'll reconsider next time."},{"text":"Say maybe you should find out, to ease her worry","then":"She brightens, but even a quiet find-out is illegal, and her worry would not end there."},{"text":"Apologise to her for having nothing to tell","then":"She sighs, and you feel her asking is your doing, though it never was."}],"why":"Saying plainly that any child is welcome answers the question without a workaround."},{"prompt":"At your next visit, a staff member who wasn't there before asks if anyone's approached you about it. What do you do?","options":[{"text":"Tell them honestly, then share it with someone you trust","then":"They thank you and note it, and telling someone leaves you less alone with it.","best":true},{"text":"Tell yourself it's not your place to raise it","then":"The offer goes unmentioned, though it was never your job to stop it."},{"text":"Describe him vaguely without giving real detail","then":"They can't act on a description that doesn't say enough."},{"text":"Ask a family member to handle telling them instead","then":"The message never quite gets passed along."}],"why":"Telling staff and someone you trust helps, and the offer was never your fault."}],"debrief":"Refuse prenatal sex determination outright; it's illegal under the PCPNDT Act and harms daughters.","relearn":"Refuse off-the-record sex determination flatly; it's illegal under the PCPNDT Act."},
  {"id":"iw-1285","cat":"free-of-pressure","type":"branch","persona":"Sneha","source":"not a waiting room","hook":"Single at 33, you're tired of relatives treating your life like an unfinished waiting room.","steps":[{"prompt":"At a cousin's engagement, an uncle asks when your 'turn' is coming. What do you say?","options":[{"text":"Say calmly your life is full right now","then":"He pauses, unsure how to respond to something so certain.","best":true},{"text":"Apologise and promise you'll 'sort it out' soon","then":"The apology invites the same question again at the next function."},{"text":"Say you're too busy with work to think about it","then":"He nods, but treats it as a delay rather than a real answer."},{"text":"Joke that no one wants to marry you anyway","then":"The joke gets an easy laugh, but it stings more than it lets on."}],"why":"Naming your life as complete answers the comment without apologising for it."},{"prompt":"Your mother says quietly she just worries you'll be 'alone in old age'. What do you say?","options":[{"text":"Reassure her your life is full, with people who matter","then":"She softens, and admits she hadn't thought of it that way.","best":true},{"text":"Get defensive and end the conversation","then":"The worry stays between you, unresolved."},{"text":"Agree it's a real risk, to ease her mind","then":"She worries more, now that you've echoed the fear back to her."},{"text":"Tell her not to worry, without saying why","then":"The reassurance feels thin, and she keeps circling back to it."}],"why":"Naming what actually fills your life reassures her more than brushing off the worry."},{"prompt":"A colleague asks if you're 'still looking', with a hint of pity. What do you say?","options":[{"text":"Say your life is already good, whatever happens next","then":"She seems surprised, then a little relieved to hear it said plainly.","best":true},{"text":"Apologise that you haven't found anyone yet","then":"She softens with pity, and the apology suggests your life needs excusing."},{"text":"Deflect with a joke about your terrible dating history","then":"The joke lands, but it leaves the real answer unsaid."},{"text":"Say you'll start looking soon, if that helps her","then":"She nods, and now expects you to report back on your search."}],"why":"Naming that your life is already good removes the pity from the question."},{"prompt":"Months later, the same uncle asks again, more gently this time. What do you say?","options":[{"text":"Say plainly that your life is full as is","then":"He nods this time, like he's actually heard it.","best":true},{"text":"Give him an update on your dating life to satisfy him","then":"The update becomes something he now expects every time."},{"text":"Ask him why it matters so much to him","then":"The question turns into a longer, more tiring conversation."},{"text":"Tell him maybe he's right and you've left it late","then":"He nods, and the doubt he has planted follows you home."}],"why":"A steady answer, given whenever the question comes, is what finally lets it rest."}],"debrief":"A single, childfree life is complete now, not a waiting room; affirm it.","relearn":"A single life is full and complete now, not a waiting room to apologise for."},
  {"id":"iw-1286","cat":"free-of-pressure","type":"branch","persona":"Pooja","source":"partner repeats it","hook":"Your partner Rohit has started repeating his family's 'we need a son' line at home.","steps":[{"prompt":"He says it again, almost automatically, over breakfast. What do you say?","options":[{"text":"Say you want to talk it through. It isn't fair to any child","then":"He pauses, and admits he'd never really thought about the words.","best":true},{"text":"Let it slide, since he's just repeating what he's heard","then":"The line settles quietly into how he talks about the future."},{"text":"Get angry that he'd say something like that","then":"He gets defensive, and the real conversation gets lost in the fight."},{"text":"Joke about it to lighten the moment","then":"The joke passes, but the line comes back again a few days later."}],"why":"Naming it and talking it through keeps son-preference from settling in at home."},{"prompt":"A few days later, unprompted, he brings up that his mother always said this growing up. What do you say?","options":[{"text":"Say you get where it's from, but every child is equal, so no such talk","then":"He nods slowly, and says he'll try to catch himself.","best":true},{"text":"Say that's not a good enough reason","then":"He gets defensive, and the conversation stalls there."},{"text":"Drop it, since it's clearly not really his idea","then":"The old words keep slipping out, unchallenged."},{"text":"Suggest he talk to his mother about it instead","then":"The conversation gets pushed onto someone else entirely."}],"why":"Understanding where it's from, then naming every child as equal, moves things forward."},{"prompt":"A month later, his mother says the same line directly to you both. What do you do?","options":[{"text":"Say it plainly: every child will be equally loved","then":"She looks between you both. Rohit nods, a beat behind you.","best":true},{"text":"Let Rohit answer alone, since it's his mother","then":"He answers carefully, though he seems to want you beside him."},{"text":"Stay quiet, to avoid a conflict with her","then":"The line goes unanswered, and settles further into the family."},{"text":"Argue with her directly, without Rohit's support","then":"The argument turns tense, and Rohit stays quiet through it."}],"why":"Saying it plainly draws a clear line, whether or not he joins in immediately."}],"debrief":"Name son-preference as unjust together; align on every child being equal.","relearn":"If son-pressure enters your home, name it together and align on equal value."},
  {"id":"iw-1287","cat":"free-of-pressure","type":"branch","persona":"Sneha","source":"regret friend","hook":"You've decided you don't want children. Your close friend Meher keeps insisting you'll regret it.","steps":[{"prompt":"She brings it up again over coffee, gently but firmly. What do you say?","options":[{"text":"Thank her, and say the choice is settled","then":"She pauses, then says she hears you, and lets it be.","best":true},{"text":"Promise to reconsider, just so she drops it","then":"The fake promise invites her to check in on it again soon."},{"text":"Get frustrated that she won't just accept it","then":"The coffee turns tense, and neither of you feels heard."},{"text":"Change the subject before she can say more","then":"The subject waits for her to bring up again another day."}],"why":"A settled, respectful answer holds better than a promise you don't mean."},{"prompt":"A few weeks later, Meher sends an article about women who 'regretted' the choice. What do you do?","options":[{"text":"Thank her for caring, and say your answer stands","then":"She replies that she just worries, and finally lets it rest.","best":true},{"text":"Read it and let it plant some doubt","then":"The doubt lingers, even though nothing about your answer changed."},{"text":"Reply with an angry message about the article","then":"The reply starts an argument neither of you really wanted."},{"text":"Ignore the message completely","then":"She wonders if she's upset you, and brings it up again to check."}],"why":"A calm, unchanged answer closes the loop better than reading it or ignoring it."},{"prompt":"At your birthday, another friend asks Meher if you've 'come around yet'. What do you do?","options":[{"text":"Step in and say the choice was settled already","then":"Meher looks relieved she didn't have to answer for you.","best":true},{"text":"Let Meher answer, since she knows how you feel","then":"Meher fumbles the answer, unsure how much is hers to share."},{"text":"Laugh it off without really answering","then":"The laugh leaves the question open for someone to ask again."},{"text":"Get upset that it's being discussed at your birthday","then":"The moment turns tense, and the party mood dips with it."}],"why":"Speaking for yourself keeps the settled choice from becoming someone else's to explain."}],"debrief":"'You'll regret it' isn't a fact. Affirm your settled choice, and ask for respect.","relearn":"Your childfree choice is valid as it stands. Ask for respect, not a defence."},
  {"id":"iw-1288","cat":"free-of-pressure","type":"branch","persona":"Pooja","source":"family meeting","hook":"Elders propose a 'family meeting' to decide when you and Rohit should conceive.","steps":[{"prompt":"Your father-in-law calls to schedule it for Sunday. What do you say?","options":[{"text":"Thank him for caring; this one is private","then":"He pauses, then says he understands, a little surprised.","best":true},{"text":"Agree to attend, to keep the peace for now","then":"The meeting gets scheduled, and the decision starts slipping away."},{"text":"Say you're too busy that Sunday specifically","then":"He simply suggests another date instead."},{"text":"Ask Rohit to handle the call for you","then":"Rohit fields it alone, and the real answer never quite gets said."}],"why":"Naming it as a private decision, warmly, keeps the choice with the two of you."},{"prompt":"Your mother-in-law says the whole family just wants to 'help plan'. What do you say?","options":[{"text":"Welcome their care, but say it's private","then":"She nods slowly, though she still looks a little unconvinced.","best":true},{"text":"Let her explain her plan, just to hear her out","then":"Her plan starts sounding like something you're now expected to follow."},{"text":"Say the family should stay out of it entirely","then":"She looks hurt, and the tension lingers past the phone call."},{"text":"Suggest a smaller meeting instead, just the parents","then":"The smaller meeting still ends up deciding for you."}],"why":"Welcoming their care while naming the decision as private holds the boundary kindly."},{"prompt":"At the next family lunch, the topic comes up anyway, in front of everyone. What do you do?","options":[{"text":"Hold a calm boundary, in front of the table","then":"The table moves on, and the boundary holds in public too.","best":true},{"text":"Let the conversation happen, since it's already started","then":"The conversation drifts into a full unofficial planning session."},{"text":"Leave the table to avoid the conversation","then":"The topic continues without you, and decides more than you'd like."},{"text":"Answer with a joke to defuse the moment","then":"The joke gets a laugh, but the topic returns before dessert."}],"why":"The same calm boundary, held in public, is what makes it stick."},{"prompt":"Rohit later says his parents asked him separately to 'convince' you. What do you do together?","options":[{"text":"Agree to answer future asks with one voice","then":"You both feel steadier, no longer approached one at a time.","best":true},{"text":"Tell Rohit to just handle his own parents","then":"He's left carrying the pressure alone, without you beside him."},{"text":"Suggest avoiding his parents for a while","then":"The avoidance postpones the pressure without actually settling it."},{"text":"Agree to just set a rough date to end the asking","then":"The rough date becomes a deadline neither of you chose."}],"why":"Answering as one voice keeps either of you from being pressured alone."},{"prompt":"Months later, an aunt notes that the family has mostly stopped asking. What's your next move?","options":[{"text":"Take it as a cue to keep trusting your own pace","then":"The quiet lets you both settle, and you plan around your own readiness, not anyone's date.","best":true},{"text":"Quietly worry you disappointed the whole family","then":"The guilt lingers, even though the decision was always yours to make."},{"text":"Stay braced for the pressure to start again any day","then":"You stay on edge, and the calm months feel less calm than they are."},{"text":"Push the whole thing out of your mind and move on","then":"Something you hadn't quite worked through stays quietly unresolved."}],"why":"Trusting your own pace now is what carries the decision forward, whatever got you here."}],"debrief":"Whether and when is the couple's own; decline the 'family meeting' warmly.","relearn":"No family meeting decides when you conceive; keep that decision the couple's own."},
  {"id":"iw-1289","cat":"free-of-pressure","type":"reflect","hook":"Lensy: every child is valued equally, daughter or son. No one is owed a 'try for a boy'. Sit with that.","prompt":"What feels true?","options":["Every child, equal","No son owed","A daughter is whole"],"affirm":"Every child is valued equally; there's no duty to keep trying for a son, and a daughter is whole as she is.","relearn":"Every child is valued equally; no one is owed a 'try for a son'.","persona":"Razia","source":"equal value reflect"},
  {"id":"iw-1290","cat":"free-of-pressure","type":"reflect","hook":"Lensy: your worth has no expiry date, married or not, children or not. Let that settle.","prompt":"What sits with you?","options":["No expiry","Worth as I am","Full life now"],"affirm":"Your worth has no expiry date; an unmarried or childfree life is full and complete as it is, right now.","relearn":"Your worth has no expiry date; unmarried or childfree is a full life as it is.","persona":"Sneha","source":"no expiry reflect"},
  {"id":"iw-1291","cat":"free-of-pressure","type":"reflect","hook":"Lensy: you owe no answer to the 'good news' chorus. The choice is legitimate exactly as it stands.","prompt":"What's your take?","options":["No answer owed","Legitimate as it is","My own time"],"affirm":"You owe no answer to the 'good news' chorus; your choice is legitimate as it stands, on your own time.","relearn":"You owe no answer to the 'good news' chorus; the choice stands as it is.","persona":"any","source":"no answer reflect"},
  {"id":"iw-1292","cat":"free-of-pressure","type":"reflect","hook":"Lensy: a boundary can hold without a family war. Calm and firm can live together.","prompt":"How does that land?","options":["Calm and firm","No war needed","I can hold this"],"affirm":"A boundary can be calm and firm at once; you can decline pressure warmly and still keep the peace.","relearn":"A boundary can hold calmly and firmly, without starting a family war.","persona":"any","source":"calm firm reflect"},
  {"id":"iw-1293","cat":"free-of-pressure","type":"reflect","hook":"Lensy: whether and when to have children is the couple's own, not the family's, relatives', or society's.","prompt":"What feels right?","options":["The couple's own","Not the family's","Ours to decide"],"affirm":"Whether and when to have children is the couple's own decision; family, relatives and society don't get the final say.","relearn":"Whether and when is the couple's own; family and society don't get the final say.","persona":"Pooja","source":"couple's own reflect"},
  {"id":"iw-1294","cat":"free-of-pressure","type":"reflect","hook":"Lensy: a fertility clock is never a weapon to hurry you. Your timeline is yours to set.","prompt":"What lands?","options":["Not a weapon","My timeline","No rush owed"],"affirm":"A fertility clock is never a weapon to pressure you; your timeline is yours to set, calmly and on your terms.","relearn":"A fertility clock is never a weapon; your timeline is yours to set.","persona":"Sneha","source":"clock reflect"},
  {"id":"iw-1295","cat":"free-of-pressure","type":"reflect","hook":"Lensy: 'you'll change your mind' isn't a reason to doubt yourself. Your choice today is valid as it stands.","prompt":"What sits with you?","options":["Valid as it stands","My choice today","Mine to revisit"],"affirm":"'You'll change your mind' isn't reassurance; your choice is valid as it stands, and only you get to revisit it.","relearn":"'You'll change your mind' isn't a reason to doubt; your choice is valid as it stands.","persona":"any","source":"change mind reflect"},
  {"id":"iw-1296","cat":"free-of-pressure","type":"reflect","hook":"Lensy: pressure dressed as care is still pressure. You're allowed to name it and set it down.","prompt":"What feels true?","options":["I can name it","Still pressure","Set it down"],"affirm":"Pressure dressed as care is still pressure; you can name it gently and set it down, without owing a fight.","relearn":"Pressure dressed as care is still pressure; you can name it and set it down.","persona":"any","source":"name pressure reflect"},
  {"id":"iw-1297","cat":"free-of-pressure","type":"spot","hook":"Spot the two lines that are pressure dressed as care (the red flags).","scene":[{"id":"a","text":"\"You're not getting any younger, hurry up.\"","trick":true},{"id":"b","text":"\"Whatever you two decide, we support it.\"","trick":false},{"id":"c","text":"\"A son would really complete this family.\"","trick":true},{"id":"d","text":"\"Take all the time you need.\"","trick":false},{"id":"e","text":"\"We're proud of you either way.\"","trick":false}],"why":"'You're not getting younger' and 'a son would complete this' are pressure; no-strings support is genuine care.","relearn":"A ticking-clock jab and a 'need a son' hint are pressure dressed as care; no-strings support is real.","persona":"any","source":"spot pressure"},
  {"id":"iw-1298","cat":"free-of-pressure","type":"spot","hook":"Spot the two moves that are illegal or unjust (the red flags to catch).","scene":[{"id":"a","text":"A couple choosing their own family size","trick":false},{"id":"b","text":"A scan to reveal the baby's sex before birth","trick":true},{"id":"c","text":"A clinician giving calm fertility facts","trick":false},{"id":"d","text":"Aborting because the baby is a girl","trick":true},{"id":"e","text":"Loving a daughter and a son equally","trick":false}],"why":"Revealing a baby's sex before birth and aborting a girl are illegal under the PCPNDT Act and unjust; the rest are fine.","relearn":"Pre-birth sex reveal and sex-selective abortion are illegal under the PCPNDT Act; care and equal love are not.","persona":"Razia","source":"spot illegal"},
  {"id":"iw-1299","cat":"free-of-pressure","type":"spot","hook":"Spot the two replies that surrender your choice (the red flags).","scene":[{"id":"a","text":"\"We'll share our news in our own time.\"","trick":false},{"id":"b","text":"\"Fine, we'll start trying this month to please you.\"","trick":true},{"id":"c","text":"\"A daughter is not less than a son.\"","trick":false},{"id":"d","text":"\"Okay, we'll do the sex test you want.\"","trick":true},{"id":"e","text":"\"This decision stays ours.\"","trick":false}],"why":"Trying on demand and agreeing to a sex test surrender your choice; the calm boundaries keep it yours.","relearn":"Conceding to 'try this month' or to a sex test surrenders your choice; calm boundaries keep it yours.","persona":"Pooja","source":"spot surrender"},
  {"id":"iw-1300","cat":"free-of-pressure","type":"spot","hook":"Spot the two lines that pressure a single, childfree woman (the red flags).","scene":[{"id":"a","text":"\"Your life isn't complete until you marry.\"","trick":true},{"id":"b","text":"\"Your work and friends sound wonderful.\"","trick":false},{"id":"c","text":"\"Better hurry before it's too late for kids.\"","trick":true},{"id":"d","text":"\"It's your life to live as you choose.\"","trick":false},{"id":"e","text":"\"We're glad you're happy.\"","trick":false}],"why":"'Not complete until you marry' and 'before it's too late' are pressure; an unmarried, childfree life is whole.","relearn":"'Not complete until you marry' and 'too late for kids' are pressure; a childfree life is already whole.","persona":"Sneha","source":"spot single pressure"},
  {"id":"iw-1301","cat":"free-of-pressure","type":"spot","hook":"Spot the two things that aren't your reason to decide timing (the red flags).","scene":[{"id":"a","text":"Your own readiness and stability","trick":false},{"id":"b","text":"Keeping up with your cousin's family","trick":true},{"id":"c","text":"Your health and recovery between pregnancies","trick":false},{"id":"d","text":"Relatives bored of waiting for good news","trick":true},{"id":"e","text":"A talk the two of you had together","trick":false}],"why":"Keeping up with a cousin and bored relatives aren't your reasons; your readiness, health and a shared talk are.","relearn":"Keeping up with others and relatives' boredom aren't your reasons; readiness, health and a shared talk are.","persona":"any","source":"spot not your reason"},
  {"id":"iw-1302","cat":"free-of-pressure","type":"spot","hook":"Spot the two ways the 'good news' question is wrongly framed (the red flags).","scene":[{"id":"a","text":"\"You owe us a grandchild by next year.\"","trick":true},{"id":"b","text":"\"We're here whenever you want to talk.\"","trick":false},{"id":"c","text":"\"A woman's only real job is to be a mother.\"","trick":true},{"id":"d","text":"\"Your choice, on your timeline.\"","trick":false},{"id":"e","text":"\"No pressure from us, truly.\"","trick":false}],"why":"'You owe us a grandchild' and 'a woman's only job is motherhood' are false framings; the rest respect your choice.","relearn":"'You owe a grandchild' and 'motherhood is a woman's only job' are false; whether and when is yours.","persona":"any","source":"spot wrong framing"},
  {"id":"iw-1303","cat":"free-of-pressure","type":"spot","hook":"Spot the two comments that hide son-preference (the red flags).","scene":[{"id":"a","text":"\"Maybe next time you'll be luckier with a boy.\"","trick":true},{"id":"b","text":"\"Your daughter is such a joy.\"","trick":false},{"id":"c","text":"\"A house needs a son to truly carry on.\"","trick":true},{"id":"d","text":"\"Two healthy girls, how lovely.\"","trick":false},{"id":"e","text":"\"Whatever children you have, we'll adore.\"","trick":false}],"why":"'Luckier with a boy' and 'a house needs a son' hide son-preference; the others value daughters fully.","relearn":"'Luckier with a boy' and 'a house needs a son' hide son-preference; every child is valued equally.","persona":"Razia","source":"spot son-preference"},
  {"id":"iw-1304","cat":"free-of-pressure","type":"spot","hook":"Spot the two responses that turn a boundary into a war (the red flags).","scene":[{"id":"a","text":"\"We hear you; this stays our decision.\"","trick":false},{"id":"b","text":"Screaming insults back across the room","trick":true},{"id":"c","text":"\"Let's talk about something else now.\"","trick":false},{"id":"d","text":"Cutting off the whole family forever","trick":true},{"id":"e","text":"\"We'll share when we're ready.\"","trick":false}],"why":"Screaming insults and cutting everyone off escalate; calm 'this stays ours' lines hold the boundary in peace.","relearn":"Insults and total cut-offs flare a war; calm 'this stays ours' lines hold the boundary in peace.","persona":"any","source":"spot escalation"},
  {"id":"iw-1305","cat":"free-of-pressure","type":"match","hook":"Match each pressure line to a calm reply that holds your choice.","pairs":[{"left":"\"When's the good news?\"","right":"\"We'll share in our own time.\""},{"left":"\"You need a son.\"","right":"\"We'll love any child equally.\""},{"left":"\"Your clock is ticking.\"","right":"\"Our timeline is ours to set.\""},{"left":"\"The family should decide this.\"","right":"\"This one is just for us two.\""},{"left":"\"You'll regret no children.\"","right":"\"My choice is settled, please respect it.\""}],"relearn":"Each pressure line meets a calm reply: in our own time, any child equally, our timeline, just for us, settled and respected.","persona":"any","source":"pressure to reply"},
  {"id":"iw-1306","cat":"free-of-pressure","type":"match","hook":"Match each form of pressure to what truly counters it.","pairs":[{"left":"Son-preference","right":"Valuing every child equally"},{"left":"A weaponised fertility clock","right":"Your own informed timeline"},{"left":"The 'good news' chorus","right":"A calm 'in our own time'"},{"left":"\"You'll change your mind\"","right":"Your choice, valid as it stands"},{"left":"\"The family decides\"","right":"The couple's own decision"}],"relearn":"Equality counters son-preference, your timeline the clock, a calm line the chorus, validity the 'change your mind', the couple the family.","persona":"Razia","source":"pressure to counter"},
  {"id":"iw-1307","cat":"free-of-pressure","type":"match","hook":"Match each phrase to whether it's the law or just pressure.","pairs":[{"left":"Sex selection before birth","right":"Illegal under the PCPNDT Act"},{"left":"\"Hurry, your clock is ticking\"","right":"Pressure, not the law"},{"left":"Revealing a baby's sex on a scan","right":"Banned to protect girls"},{"left":"\"You owe us a grandchild\"","right":"A demand you can decline"},{"left":"Choosing your own family size","right":"Your lawful right"}],"relearn":"Sex selection and pre-birth sex reveal are banned by the PCPNDT Act; clock-talk and grandchild demands are pressure you can decline.","persona":"Razia","source":"law vs pressure"},
  {"id":"iw-1308","cat":"free-of-pressure","type":"match","hook":"Match each pressuring person to a boundary that holds without a war.","pairs":[{"left":"Aunt asking 'good news?' loudly","right":"\"We'll share in our own time.\""},{"left":"In-law pushing for a son","right":"\"We love any child equally.\""},{"left":"Elder calling a 'family meeting'","right":"\"This one is ours to decide.\""},{"left":"Relative naming a deadline","right":"\"Our timeline, set calmly.\""},{"left":"Friend insisting you'll regret it","right":"\"My choice is settled, thanks.\""}],"relearn":"Each pusher meets a calm boundary: our own time, any child equally, ours to decide, our timeline, settled.","persona":"any","source":"person to boundary"},
  {"id":"iw-1309","cat":"free-of-pressure","type":"match","hook":"Match each value to the truth that backs it.","pairs":[{"left":"Every child equal","right":"A daughter is whole, no son owed"},{"left":"Worth has no expiry","right":"Single and childfree are full lives"},{"left":"The couple decides","right":"Family doesn't get the final say"},{"left":"No answer is owed","right":"Your choice is legitimate as it stands"},{"left":"A boundary can be gentle","right":"Calm and firm hold without a war"}],"relearn":"Equal value, no expiry, the couple's say, no answer owed, and a gentle boundary each rest on a clear truth.","persona":"any","source":"value to truth"},
  {"id":"iw-1318","cat":"free-of-pressure","type":"match","hook":"Match each 'caring' line to the pressure hiding inside it.","pairs":[{"left":"\"We just want to see you settled.\"","right":"Marry-and-breed-now expectation"},{"left":"\"Don't leave it too late.\"","right":"A weaponised fertility clock"},{"left":"\"Every house needs a son.\"","right":"Son-preference dressed as tradition"},{"left":"\"People will start talking.\"","right":"Shame used to hurry you"},{"left":"\"Your cousin already has two.\"","right":"Keeping-up comparison"}],"relearn":"'Settled', 'too late', 'needs a son', 'people will talk' and 'your cousin has two' each hide a pressure you can name.","persona":"any","source":"caring to pressure"},
  {"id":"iw-1319","cat":"free-of-pressure","type":"match","hook":"Match each life choice to why it's complete on its own.","pairs":[{"left":"Childfree by choice","right":"A full life, not a missing piece"},{"left":"Single at any age","right":"Worth with no expiry date"},{"left":"One child, no more","right":"A whole family, no quota owed"},{"left":"\"Not yet\"","right":"A real answer, revisitable later"},{"left":"A family of daughters","right":"Complete, no son to 'add'"}],"relearn":"Childfree, single, one child, 'not yet' and a family of daughters are each complete; none owes anyone a correction.","persona":"Sneha","source":"choice to complete"},
  {"id":"iw-1320","cat":"free-of-pressure","type":"match","hook":"Match each pushy question to the calm subject-change that ends it.","pairs":[{"left":"\"Any baby plans yet?\"","right":"\"We'll let you know; how's your garden?\""},{"left":"\"Trying for a boy soon?\"","right":"\"Any child suits us; more chai?\""},{"left":"\"Aren't you getting old for this?\"","right":"\"We're not in a rush; nice weather today.\""},{"left":"\"Shouldn't the family decide?\"","right":"\"This one's ours; tell me your news.\""},{"left":"\"When's number two?\"","right":"\"In our own time; how's work going?\""}],"relearn":"Each pushy question meets a warm answer plus a subject-change that holds your boundary and keeps the peace.","persona":"any","source":"question to deflect"},
  {"id":"iw-1310","cat":"free-of-pressure","type":"role-play","persona":"any","source":"good news lunch","hook":"At a family lunch, an aunt loves to make your 'good news' the table's business.","setup":"Every head at the table turns toward you.","steps":[{"prompt":"Aunty announces: \"So, when's the good news coming, hm?\"","options":[{"text":"\"We'll share in our own time. Pass the rice?\"","then":"She blinks, then actually passes the rice.","best":true},{"text":"\"Soon, soon. We're working on it.\"","then":"She beams and tells the table to expect news 'very soon'."},{"text":"\"Why does everyone ask that at lunch?\"","then":"The table goes quiet, and lunch turns a little awkward."},{"text":"\"That's for the elders to decide, not me.\"","then":"Aunty nods approvingly, and now the family feels entitled to decide it."}],"why":"A warm 'our own time' plus a subject change closes it without a fight or a promise."},{"prompt":"An uncle chimes in: \"Come on, give us a hint at least.\"","options":[{"text":"\"No hints today, just good food.\"","then":"He laughs and lets it go, reaching for the rice himself.","best":true},{"text":"\"Fine, maybe by next year.\"","then":"'Next year' becomes the table's new expectation."},{"text":"\"There's really nothing, so stop asking.\"","then":"He nods slowly, but the bluntness leaves a small chill at the table."},{"text":"\"Can we talk about literally anything else?\"","then":"The table shifts, though the question feels unanswered, not closed."}],"why":"A light, firm line ends the teasing without opening a new question."},{"prompt":"As lunch wraps up, Aunty says quietly: \"I do hope you'll tell me first, when it happens.\"","options":[{"text":"\"We're keeping this just between us for now.\"","then":"She takes the 'for now' as a sign it's coming eventually."},{"text":"\"Of course, you'll be the very first to know.\"","then":"She holds you to that promise at every lunch after."},{"text":"\"We'll share whatever we choose to, if and when we choose.\"","then":"She's a little surprised, but nods and lets it be.","best":true},{"text":"\"I really can't promise anything right now.\"","then":"She takes the uncertainty as a sign something's actually happening."}],"why":"'If and when we choose' promises nothing and owes no timeline."}],"relearn":"'We'll share in our own time' answers the 'good news' question without owing a timeline or a fight."},
  {"id":"iw-1311","cat":"free-of-pressure","type":"role-play","persona":"Razia","source":"grandson reply","hook":"Your father-in-law has been dropping hints about a grandson for weeks now.","setup":"He says it warmly, like it's simply expected.","steps":[{"prompt":"He says: \"A grandson would really complete the family.\"","options":[{"text":"\"We'll welcome any child equally, Papa. No grandson is owed.\"","then":"He looks thoughtful, though not fully convinced yet.","best":true},{"text":"\"We'll try our best for a boy, Papa.\"","then":"He smiles widely, already picturing the grandson."},{"text":"\"That's a strange thing to say, honestly.\"","then":"He looks hurt. \"I only meant it fondly, beta.\""},{"text":"\"We'll see what we're blessed with.\"","then":"He nods, hearing it as a hopeful sign toward a boy."}],"why":"Naming equal value plainly answers the wish without agreeing to chase it."},{"prompt":"He adds: \"Meena next door already has two boys.\"","options":[{"text":"\"That's their family. Ours will be equally loved too.\"","then":"He pauses, weighing the comparison against the answer.","best":true},{"text":"\"Maybe we should ask her what she did differently.\"","then":"He lights up to compare notes, though no diet, timing or ritual decides a baby's sex."},{"text":"\"That comparison really isn't fair.\"","then":"He shrugs it off. \"I was only making conversation.\""},{"text":"\"I know. Everyone keeps mentioning it.\"","then":"The comparison lingers, unanswered, in the room."}],"why":"Naming the comparison and answering it directly stops it from repeating."},{"prompt":"At a temple visit, he tells the priest: \"Pray for a grandson for us, please.\"","options":[{"text":"\"Pray for our child, girl or boy.\"","then":"The priest nods and blesses accordingly, without objection.","best":true},{"text":"\"Yes, a boy would be wonderful, thank you.\"","then":"The priest's blessing leans toward the wish, unchallenged."},{"text":"\"Please don't ask for that kind of prayer.\"","then":"The moment turns tense in front of the priest."},{"text":"\"Whatever will be, will be, I suppose.\"","then":"The specific wish for a grandson stands as the prayer."}],"why":"Redirecting the prayer to any child, girl or boy, answers the wish without a scene."},{"prompt":"Months later, he says quietly: \"I hope I didn't push too hard about all this.\"","options":[{"text":"\"A little, Papa. Any child of ours is loved equally.\"","then":"He nods slowly. \"Thank you for saying so, beta.\"","best":true},{"text":"\"No, no, it was nothing. Please don't worry about it, Papa.\"","then":"He relaxes, though the old pattern stays unnamed."},{"text":"\"Yes, you really did push too hard. It wore us down.\"","then":"He goes quiet. \"I see,\" he says, and the talk ends there."},{"text":"\"Every family's like that. Don't overthink it, Papa. It's fine.\"","then":"He nods, relieved, but nothing about the pattern actually changes."}],"why":"Naming it gently and restating equal love lets him hear it without a fight."}],"relearn":"'Any child equally; no grandson is owed' rejects son-preference while staying calm and respectful."},
  {"id":"iw-1312","cat":"free-of-pressure","type":"role-play","persona":"Sneha","source":"time running out","hook":"A colleague keeps remarking on your single life during breaks at work.","setup":"She says it half joking, stirring her coffee.","steps":[{"prompt":"She says: \"You're 35 and single. Isn't your time running out?\"","options":[{"text":"\"My worth has no expiry. My timeline is mine.\"","then":"She blinks, then changes the subject to the coffee.","best":true},{"text":"\"I know. I really need to hurry and settle down.\"","then":"She nods sympathetically, and brings it up again next week."},{"text":"\"That's a really rude thing to say.\"","then":"She backtracks. \"I was only joking. Relax.\""},{"text":"\"Maybe. Who knows? We'll see.\"","then":"She takes the shrug as quiet agreement with her worry."}],"why":"Naming your worth as timeless answers the comment without panic or a fight."},{"prompt":"At the next team lunch, she says in front of others: \"Still no news on the settling down front?\"","options":[{"text":"\"Nothing to report, and that's completely fine.\"","then":"The table moves on, and no one else picks it up.","best":true},{"text":"\"You're right. I should probably get moving.\"","then":"She repeats the comment, now with an audience backing her up."},{"text":"\"Can we not discuss my life at lunch?\"","then":"She waves it off. \"Oh, come on. It's just a question.\""},{"text":"\"Ha, we'll see, won't we?\"","then":"The joke buys silence for now, but not for next time."}],"why":"A calm, complete answer closes it in front of others without a scene."},{"prompt":"Weeks later she says, more kindly: \"I didn't mean to upset you before.\"","options":[{"text":"\"I appreciate that, but my timeline is mine.\"","then":"She nods. \"Fair enough, noted.\"","best":true},{"text":"\"It's fine. Don't worry about it.\"","then":"The comment goes unaddressed, and something similar slips out later."},{"text":"\"You did upset me, actually, quite a bit.\"","then":"She looks guilty and says sorry again, but your timeline still hasn't been named."},{"text":"\"You're right. I probably overreacted.\"","then":"She looks relieved, and the boundary never gets said."}],"why":"Accepting the apology while restating the boundary makes sure it's actually heard."}],"relearn":"'My worth has no expiry. My timeline is mine' refuses the running-out script with calm dignity."},
  {"id":"iw-1313","cat":"free-of-pressure","type":"role-play","persona":"Pooja","source":"meeting decline","hook":"An elder has strong opinions about when you and Rohit should start a family.","setup":"He suggests it kindly, sure everyone should weigh in.","steps":[{"prompt":"He says: \"Let's all sit together and plan this out properly.\"","options":[{"text":"\"Thank you for caring, but this one's for us privately.\"","then":"He pauses, then nods slowly, a little surprised.","best":true},{"text":"\"Okay, let's all sit and plan it together.\"","then":"He is pleased and starts sounding out dates, though nothing is fixed yet."},{"text":"\"That's a strange idea, honestly.\"","then":"He looks taken aback. \"I only meant to help.\""},{"text":"\"Maybe. Let me think about it.\"","then":"He takes the maybe as an opening, and starts planning anyway."}],"why":"A warm decline keeps the decision private without dismissing his care."},{"prompt":"He adds: \"Family always plans these things together, you know.\"","options":[{"text":"\"I know, but it's just for the two of us.\"","then":"He accepts it, sensing you mean it.","best":true},{"text":"\"Fine, one meeting, if it really matters that much.\"","then":"The meeting turns into an ongoing expectation for updates."},{"text":"\"Why does it have to involve the whole family?\"","then":"He explains his reasoning, and the actual point gets lost."},{"text":"\"We'll see, maybe some other time.\"","then":"He takes it as a yes for a later date instead of a no."}],"why":"Stating the boundary calmly is what actually makes it stick."},{"prompt":"An aunt asks: \"So, has the family managed to plan your timeline yet?\"","options":[{"text":"\"No, and that's staying between us.\"","then":"The aunt nods, and the topic settles for now.","best":true},{"text":"\"Actually, maybe we should all plan it together.\"","then":"The aunt gets hopeful, and the family planning idea resurfaces."},{"text":"\"That's really not something to discuss here.\"","then":"The aunt tilts her head. \"But surely the elders should know.\""},{"text":"\"I'm honestly not sure what everyone's been told.\"","then":"The vague answer leaves the boundary looking uncertain."}],"why":"Confirming that the decision stays private is what keeps it from being reopened."}],"relearn":"'Thank you, but the two of us decide this privately' keeps the choice the couple's, warmly."},
  {"id":"iw-1314","cat":"free-of-pressure","type":"role-play","persona":"Razia","source":"refuse quiet test","hook":"A relative keeps hinting that knowing the baby's sex early would put everyone's mind at ease.","setup":"She lowers her voice, sure you'll want to know.","steps":[{"prompt":"She says: \"I know someone who can arrange it quietly, if you want.\"","options":[{"text":"\"No. That's illegal, and we want any child equally.\"","then":"She's surprised by the firmness, and goes quiet for now.","best":true},{"text":"\"Maybe. Let me think about it.\"","then":"She takes the maybe as encouragement to arrange it anyway."},{"text":"\"How dare you even suggest that.\"","then":"She looks stung. \"I only meant to help, really.\""},{"text":"\"I'll ask my husband what he thinks.\"","then":"The question gets passed along, unresolved either way."}],"why":"A flat, clear refusal protects any child equally, and it's what the law asks too."},{"prompt":"She pushes gently: \"It's very discreet. No one would ever know.\"","options":[{"text":"\"Discreet or not, we're simply not doing it.\"","then":"She nods, finally understanding the answer won't change.","best":true},{"text":"\"Well, if no one would know, maybe.\"","then":"She takes it as a maybe, and starts asking around just in case."},{"text":"\"You shouldn't even know people who do that.\"","then":"The comment shifts the focus onto her, not the actual answer."},{"text":"\"I'll think about the discreet part.\"","then":"The 'discreet' framing quietly reopens a door you'd closed."}],"why":"Naming that discretion doesn't change the answer keeps the refusal firm."},{"prompt":"Later, with your husband beside you, she says: \"I offered to help her find out.\"","options":[{"text":"\"No, and I'd like us to answer together.\"","then":"He nods, and she looks between you both and finally seems to accept it.","best":true},{"text":"\"He can decide that on his own, actually.\"","then":"She senses a gap between you two, and presses him separately."},{"text":"\"Why would you go around me like that?\"","then":"The moment turns into a conflict about her, not the actual issue."},{"text":"\"It's fine. He can tell you what we think.\"","then":"The answer stays unclear, since neither of you said it directly."}],"why":"Answering together shows the refusal is shared, not just yours to repeat alone."},{"prompt":"Months later, she says: \"I still don't understand why you wouldn't just find out.\"","options":[{"text":"\"Any child we have is equally wanted, no test needed.\"","then":"She's quiet for a moment, then nods slowly.","best":true},{"text":"\"Because it's illegal. That's the only reason.\"","then":"She wonders if you'd have done it otherwise, if you could."},{"text":"\"You really don't need to understand it.\"","then":"The refusal stands, but the actual reason stays unheard."},{"text":"\"Honestly, I've stopped trying to explain it.\"","then":"The explanation gets left unfinished, and the question lingers."}],"why":"Naming that any child is equally wanted answers the real question behind hers."}],"relearn":"'No, that's illegal and we want any child equally' refuses sex determination plainly and justly."},
  {"id":"iw-1315","cat":"free-of-pressure","type":"role-play","persona":"Sneha","source":"regret reply","hook":"A friend can't understand your choice not to have kids, and keeps circling back to it.","setup":"She says it again, this time over dinner.","steps":[{"prompt":"She says: \"You'll regret choosing not to have kids.\"","options":[{"text":"\"This is settled for me, and I'd like it respected.\"","then":"She pauses, then nods and changes the subject.","best":true},{"text":"\"Maybe you're right. Maybe I'll change my mind.\"","then":"She takes it as an opening and brings it up again soon."},{"text":"\"You don't get to decide that for me.\"","then":"She gets defensive. \"I'm just worried about you.\""},{"text":"\"Who knows what the future holds, really.\"","then":"The vague answer leaves the door open for more of the same."}],"why":"Naming the choice as settled asks for respect without a fight or a maybe."},{"prompt":"A week later, she tries again: \"I just don't want you to wake up one day with regrets.\"","options":[{"text":"\"I understand, and my answer is settled for me.\"","then":"She sighs, but seems to finally accept it.","best":true},{"text":"\"You might be right. I do wonder sometimes.\"","then":"She takes the wondering as a sign to keep pushing."},{"text":"\"Stop bringing this up, seriously.\"","then":"She backs off, but the tension lingers between you."},{"text":"\"I don't want to talk about it anymore.\"","then":"The topic pauses, but the actual answer never quite lands."}],"why":"Acknowledging her worry while restating the settled answer holds the boundary kindly."},{"prompt":"At a reunion, she tells a mutual friend: \"She still says she doesn't want kids. Can you believe it?\"","options":[{"text":"\"I can, since it's my honest choice.\"","then":"The mutual friend nods, and the topic quietly moves on.","best":true},{"text":"\"I know. It's a bit strange, isn't it.\"","then":"The comment makes your own choice sound uncertain to everyone listening."},{"text":"\"Why are you discussing this with her?\"","then":"The reunion turns a little tense over something small."},{"text":"\"It's complicated, I guess.\"","then":"The vague answer leaves your friend still not quite believing you."}],"why":"Owning the choice plainly, even in front of others, keeps it from sounding uncertain."}],"relearn":"'This is settled, please respect it' holds a childfree choice without owing a defence or a debate."},
  {"id":"iw-1316","cat":"free-of-pressure","type":"role-play","persona":"Pooja","source":"partner echo","hook":"Your husband Rohit has started echoing something his family always says.","setup":"He says it quietly, almost to himself.","steps":[{"prompt":"Rohit mutters: \"Maybe we should just keep trying for a boy.\"","options":[{"text":"\"Every child is equal. This is ours to decide.\"","then":"He pauses, and admits he was just repeating what he'd heard.","best":true},{"text":"\"Fine, if the family really wants a boy, let's try.\"","then":"The comment settles into an unspoken plan between you."},{"text":"\"I can't believe you'd even say that out loud.\"","then":"He gets defensive, and the real conversation stalls."},{"text":"\"Whatever you think is best, honestly. I'll go along.\"","then":"The decision drifts toward his family's wish, unnamed."}],"why":"Naming equal value stops the family's line before it settles into your own home."},{"prompt":"A few days later, unprompted, he says: \"It's just what I grew up hearing, I think.\"","options":[{"text":"\"I get it. Every child is equal, so let's drop it.\"","then":"He nods. \"Fair. I'll try to catch myself next time.\"","best":true},{"text":"\"That's not really an excuse for saying it, though.\"","then":"He gets defensive, and the conversation stalls there."},{"text":"\"It's fine. I know you don't really mean it.\"","then":"The line keeps slipping out, quietly unchallenged."},{"text":"\"Maybe talk to your parents about it instead of me.\"","then":"The conversation gets pushed onto someone else entirely."}],"why":"Understanding where it's from, then dropping the line together, actually shifts it."},{"prompt":"At his parents' house, his mother says: \"You two should really keep trying for a boy.\"","options":[{"text":"\"Any child is equally loved. That's ours to decide.\"","then":"His mother looks between you both. Rohit nods, a beat behind you.","best":true},{"text":"\"Rohit will explain it. He knows how we feel.\"","then":"Rohit fumbles the answer, unsure how much is his to say alone."},{"text":"\"Let's just not answer that right now, please.\"","then":"The silence gets read as an opening, not a boundary."},{"text":"\"We'll see what happens, honestly. Nobody can say.\"","then":"The vague answer leaves the old line standing unchallenged."}],"why":"Saying it plainly draws the line, whether or not he's fully caught up yet."}],"relearn":"Naming son-preference and 'every child is equal, ours to decide' keeps you and your partner aligned."},
  {"id":"iw-1170","cat":"if-its-hard","type":"strike-rewrite","hook":"\"If conceiving takes long, the problem is always the wife's.\"","myth":{"un":"If conceiving takes long, the problem is always the wife's.","re":"Trouble conceiving can come from male factors, female factors, both, or no clear cause; male factors are common.","why":"Blaming only the wife leaves half the picture unchecked."},"relearn":"Trouble conceiving isn't always 'her' problem; male factors are common too.","persona":"Reshma","source":"not always her"},
  {"id":"iw-1171","cat":"if-its-hard","type":"strike-rewrite","hook":"\"Only the woman needs tests when a couple can't conceive.\"","myth":{"un":"Only the woman needs tests when a couple can't conceive.","re":"Both partners should be evaluated together; a simple semen check for the man is an early, easy step.","why":"Checking only one partner can miss the real cause entirely."},"relearn":"Both partners should be evaluated when conceiving is hard; the man's check is an early, easy step.","persona":"Reshma","source":"both get checked"},
  {"id":"iw-1172","cat":"if-its-hard","type":"strike-rewrite","hook":"\"A woman who can't conceive is cursed or has done something wrong.\"","myth":{"un":"A woman who can't conceive is cursed or has done something wrong.","re":"Infertility has medical causes, not moral ones; it is not a curse, a punishment, or anyone's wrongdoing.","why":"Bodies aren't moral verdicts, and shame helps no one heal."},"relearn":"Infertility has medical causes, not moral ones; it is not a curse or anyone's wrongdoing.","persona":"Reshma","source":"no curse"},
  {"id":"iw-1173","cat":"if-its-hard","type":"strike-rewrite","hook":"\"You're young, so it can't be infertility. Just keep trying for years.\"","myth":{"un":"You're young, so it can't be infertility. Just keep trying for years.","re":"Young couples can have fertility issues too; if a year of trying hasn't worked, a check-up is reasonable, not premature.","why":"Age lowers the odds of a problem but doesn't rule one out."},"relearn":"Young couples can face fertility issues too; a check-up after about a year of trying is reasonable.","persona":"Reshma","source":"young too"},
  {"id":"iw-1174","cat":"if-its-hard","type":"strike-rewrite","hook":"\"Adopting means you gave up. A 'real' family is only a biological one.\"","myth":{"un":"Adopting means you gave up. A 'real' family is only a biological one.","re":"Adoption builds a real, whole family; it is a chosen path, not a consolation prize. Many Ways to Family explores it fully.","why":"Family is made of love and care, not only of biology."},"relearn":"Adoption builds a real, whole family. It's a chosen path, not a consolation prize.","persona":"any","source":"adoption is real"},
  {"id":"iw-1175","cat":"if-its-hard","type":"strike-rewrite","hook":"\"More expensive treatment always means a better chance of a baby.\"","myth":{"un":"More expensive treatment always means a better chance of a baby.","re":"Cost doesn't equal success; the right step depends on the cause, and a clinic should explain odds honestly, not upsell.","why":"A bigger bill is not the same as a better outcome."},"relearn":"Cost doesn't equal success; the right step depends on the cause, with honest odds, not an upsell.","persona":"Reshma","source":"cost isn't odds"},
  {"id":"iw-1176","cat":"if-its-hard","type":"strike-rewrite","hook":"\"If the first IVF cycle fails, it'll never work, so give up.\"","myth":{"un":"If the first IVF cycle fails, it'll never work, so give up.","re":"One cycle not working doesn't doom the rest; a clinician can review what happened and discuss honest next options.","why":"A single attempt isn't the whole story, in either direction."},"relearn":"One IVF cycle failing doesn't doom the rest; a clinician can review and discuss honest next options.","persona":"Reshma","source":"one cycle isn't all"},
  {"id":"iw-1177","cat":"if-its-hard","type":"strike-rewrite","hook":"\"Stress is the only reason you're not conceiving. Just relax.\"","myth":{"un":"Stress is the only reason you're not conceiving. Just relax.","re":"'Just relax' isn't a diagnosis; there can be real medical reasons worth checking with a clinician.","why":"Telling someone to relax often adds guilt without finding the cause."},"relearn":"'Just relax' isn't a diagnosis; real medical reasons are worth checking with a clinician.","persona":"Reshma","source":"not just relax"},
  {"id":"iw-1178","cat":"if-its-hard","type":"strike-rewrite","hook":"\"Treatment failing means there's something wrong with you as a person.\"","myth":{"un":"Treatment failing means there's something wrong with you as a person.","re":"A treatment not working is a medical outcome, not a verdict on your worth, your love, or your relationship.","why":"Your value was never up for testing in a clinic."},"relearn":"A treatment not working is a medical outcome, not a verdict on your worth or your relationship.","persona":"Karthik","source":"not a verdict"},
  {"id":"iw-1179","cat":"if-its-hard","type":"strike-rewrite","hook":"\"A second marriage is the fix if his wife can't have children.\"","myth":{"un":"A second marriage is the fix if his wife can't have children.","re":"Abandoning a wife over fertility is cruel and unjust; the couple can get evaluated and choose a path together.","why":"A marriage isn't a fertility contract, and she isn't disposable."},"relearn":"Abandoning a wife over fertility is cruel; the couple can get evaluated and choose a path together.","persona":"Razia","source":"not disposable"},
  {"id":"iw-1180","cat":"if-its-hard","type":"strike-rewrite","hook":"\"Talking about infertility out loud only makes it worse. Stay silent.\"","myth":{"un":"Talking about infertility out loud only makes it worse. Stay silent.","re":"Silence and isolation often deepen the pain; honest support, between partners or with a counsellor, helps you carry it.","why":"Shared weight is lighter than a secret carried alone."},"relearn":"Silence deepens the pain; honest support between partners or with a counsellor helps you carry it.","persona":"Reshma","source":"break the silence"},
  {"id":"iw-1181","cat":"if-its-hard","type":"strike-rewrite","hook":"\"A miscarriage means your body failed and it was your fault.\"","myth":{"un":"A miscarriage means your body failed and it was your fault.","re":"Most early miscarriages happen for reasons outside anyone's control and are no one's fault; gentle care and support help.","why":"Grief deserves comfort, not blame."},"relearn":"Most early miscarriages are outside anyone's control and no one's fault; you deserve care, not blame.","persona":"Reshma","source":"not your fault"},
  {"id":"iw-1182","cat":"if-its-hard","type":"strike-rewrite","hook":"\"You must keep trying treatment forever. Stopping means failing.\"","myth":{"un":"You must keep trying treatment forever. Stopping means failing.","re":"Choosing to pause or stop, after honest counsel, is a valid, caring decision, not a failure, and not giving up on a full life.","why":"Knowing when enough is enough is its own kind of strength."},"relearn":"Pausing or stopping treatment, after honest counsel, is a valid caring choice, not a failure.","persona":"Reshma","source":"stopping is okay"},
  {"id":"iw-1183","cat":"if-its-hard","type":"strike-rewrite","hook":"\"Home remedies and fasts will surely cure infertility, skip the doctor.\"","myth":{"un":"Home remedies and fasts will surely cure infertility. Skip the doctor.","re":"There's no guaranteed home cure; a qualified clinician finds the actual cause and the options that fit it.","why":"Delaying real evaluation can quietly cost time that matters."},"relearn":"There's no guaranteed home cure for infertility; a clinician finds the cause and the fitting options.","persona":"Reshma","source":"see a clinician"},
  {"id":"iw-1184","cat":"if-its-hard","type":"strike-rewrite","hook":"\"Couples without children must have a sad, empty marriage.\"","myth":{"un":"Couples without children must have a sad, empty marriage.","re":"A marriage can be loving and full whether or not children come; a family is whole in many forms.","why":"A relationship's worth was never measured by a cradle."},"relearn":"A marriage can be loving and full with or without children; a family is whole in many forms.","persona":"any","source":"full either way"},
  {"id":"iw-1185","cat":"if-its-hard","type":"branch","persona":"Karthik","source":"go together","hook":"You and Meera have tried for over a year with no luck, and you're unsure what's next.","steps":[{"prompt":"Meera suggests getting checked. What do you say?","options":[{"text":"Say you'll go together, both of you evaluated","then":"She looks relieved you said 'both', not just her.","best":true},{"text":"Say she should go first, since it's usually the woman's side","then":"She agrees, though it feels lopsided, and the visit gets put off a few weeks."},{"text":"Suggest waiting another few months first","then":"The waiting continues, without any real information gained."},{"text":"Say you're sure it's nothing, so testing feels unnecessary","then":"Meera goes along with it, though the question clearly hasn't left her."}],"why":"Going together checks both of you, since either side can be part of it."},{"prompt":"Weeks later, worry finally brings you both to a clinic. The receptionist assumes only Meera needs testing. What do you do?","options":[{"text":"Say you're both here to be tested, together","then":"The receptionist books both of you in without further question.","best":true},{"text":"Let the assumption stand, to avoid a correction","then":"Meera gets tested that day; you quietly book your own test for another time."},{"text":"Say you'll wait outside while Meera goes in","then":"Meera gets tested, and you promise yourself you'll come back for your own test soon."},{"text":"Get annoyed at the assumption itself","then":"The moment turns tense, but the receptionist still books you both in properly."}],"why":"Correcting the assumption plainly gets you both properly checked, not just her."},{"prompt":"Weeks later, the results come back. There's a factor on your side too. How do you take it?","options":[{"text":"Say you're glad you both got checked, whatever it shows","then":"Meera relaxes, no longer carrying the question alone.","best":true},{"text":"Feel ashamed and avoid discussing it further","then":"The shame settles in, though the fact itself is common and shared."},{"text":"Say you're surprised it wasn't just her","then":"The comment lands awkwardly, as if it should have been hers alone."},{"text":"Ask about a quick fix instead of understanding it fully","then":"The clinician offers real options, but you're still avoiding what it actually means."}],"why":"A factor is common and no one's fault; being glad you both got checked turns it into next steps."}],"debrief":"After about a year of trying, both partners getting evaluated together turns worry into facts.","relearn":"After a year, both partners get evaluated together. It beats sending only her."},
  {"id":"iw-1186","cat":"if-its-hard","type":"branch","persona":"Reshma","source":"no guarantee","hook":"A clinic promises a 'guaranteed baby' if you pay the full package upfront.","steps":[{"prompt":"The agent pushes you to decide before you leave the office. What do you do?","options":[{"text":"Ask for honest success rates before deciding","then":"He hesitates, then gives a vaguer answer than the promise suggested.","best":true},{"text":"Pay the full amount, trusting the guarantee","then":"You commit the whole package on the strength of a promise no clinic can keep."},{"text":"Sign a smaller deposit to hold your place","then":"The deposit locks you in before you've asked a single real question."},{"text":"Say yes for now, planning to ask questions later","then":"You leave without asking anything, still telling yourself you will."}],"why":"Asking for honest rates protects your money before you pay for a promise no clinic can keep."},{"prompt":"A health worker at the local centre asks what you know about the clinic's offer. What do you say?","options":[{"text":"Ask if a second opinion is possible nearby","then":"She points you to a clinic that offers one at no extra cost.","best":true},{"text":"Ask her to confirm the clinic's guarantee is real","then":"She looks uneasy, unable to promise something no clinic can guarantee."},{"text":"Ask her not to worry. You've already decided","then":"She stays quiet, unsure how to raise her concern now."},{"text":"Brush off her question without really answering","then":"The offer stays unchecked, with no second opinion sought."}],"why":"A second opinion is worth asking for before any big, irreversible payment."},{"prompt":"Your husband brings up the savings again, unsure about all this. What do you say?","options":[{"text":"Say you want honest facts before committing more","then":"He agrees, relieved someone said it out loud.","best":true},{"text":"Say the guarantee makes it worth the risk","then":"The savings move toward a promise that was never really real."},{"text":"Say it's your decision alone to make","then":"He feels shut out of a decision that affects you both."},{"text":"Avoid the money question entirely for now","then":"The savings sit at risk, with the real question still unasked."}],"why":"Getting honest facts before committing more protects the family's savings."},{"prompt":"The second opinion you eventually sought turns up lower success rates than the promise. How do you respond?","options":[{"text":"Thank them for the honest numbers, and decide from there","then":"You choose your next step with real information, not a false promise.","best":true},{"text":"Go back to the first clinic for the guaranteed version","then":"You return to a promise the honest numbers already contradicted."},{"text":"Put the numbers away and refuse to look again","then":"With the numbers put away, the real choices they opened stay closed."},{"text":"Feel torn and ask a third clinic to break the tie","then":"The third clinic adds one more opinion, but the real numbers still say the same thing."}],"why":"Honest numbers, even lower ones, are worth more than a comforting guarantee."}],"debrief":"No clinic can guarantee a baby; ask for honest numbers, get a second opinion, and never sign under pressure.","relearn":"No clinic can guarantee a baby. Ask honest success rates and get a second opinion."},
  {"id":"iw-1187","cat":"if-its-hard","type":"branch","persona":"Razia","source":"stand with her","hook":"Your sister-in-law Meena is being shamed by relatives for not conceiving, and you're in the room.","steps":[{"prompt":"An aunt asks loudly why Meena still has no news. What do you do?","options":[{"text":"Gently change the subject and catch her eye","then":"The talk moves on, and Meena gives you a small, grateful nod.","best":true},{"text":"Stay quiet and hope it blows over","then":"The questions keep coming, and Meena stares at her plate."},{"text":"Laugh it off and say she's still young","then":"The room laughs too, but the pressure doesn't actually lift."},{"text":"Tell the aunt to stop, loudly, in front of everyone","then":"The room goes silent, and Meena looks more exposed, not less."}],"why":"Shifting the talk quietly protects her without turning the room's eyes on her further."},{"prompt":"Later, you find a moment alone with Meena. What do you say first?","options":[{"text":"Say it isn't her fault and you're there for her","then":"She exhales and starts talking, relieved someone finally said it.","best":true},{"text":"Tell her not to let them get to her","then":"She nods but stays closed, like the advice missed the point."},{"text":"Push her to see a doctor soon, so the talk stops","then":"She stiffens, hearing the family's pressure in your voice."},{"text":"Say nothing, hoping she knows you care","then":"She sits beside you in silence, still unsure what you think of the aunt's words."}],"why":"Saying it isn't her fault and staying beside her tells her plainly she's not alone."},{"prompt":"A cousin later asks you privately what's really wrong with Meena. How do you respond?","options":[{"text":"Say no one's to blame, and it's their private matter","then":"The cousin drops it, and the rumour loses its fuel.","best":true},{"text":"Say you don't know. Maybe she's just stressed","then":"The cousin nods but keeps guessing to others anyway."},{"text":"Say the cousin should just ask Meena directly","then":"The cousin corners Meena at the next function, and she has to answer all over again."},{"text":"Mention you heard they've been trying for a while","then":"The detail spreads further, and Meena's privacy shrinks a little more."}],"why":"Refusing the blame and keeping it private stops the gossip instead of feeding it."}],"debrief":"Shift the talk, tell her privately it's not her fault, and keep her situation out of the gossip.","relearn":"Shift the talk and offer private support to someone being shamed; don't add to it."},
  {"id":"iw-1188","cat":"if-its-hard","type":"branch","persona":"Reshma","source":"decide together","hook":"Treatment has been exhausting and costly, and you're torn about whether to continue.","steps":[{"prompt":"Your partner asks what you're feeling about the next round. What do you say?","options":[{"text":"Say you're unsure and want to decide together","then":"He nods and suggests you both talk it through properly tonight.","best":true},{"text":"Say you'll push through no matter what","then":"He agrees quietly, though he looks as tired as you feel."},{"text":"Announce you're stopping, whatever he thinks","then":"He goes still. \"We haven't even talked about it yet.\""},{"text":"Change the subject and hope the question passes","then":"The moment passes, and the question sits unanswered between you."}],"why":"Naming the uncertainty and choosing together keeps this decision honest, not rushed."},{"prompt":"A few days later, the clinic offers you a session with a counsellor before the next round. What do you do?","options":[{"text":"Book it for you both and bring every doubt along","then":"The counsellor helps you each say what the rounds have cost, and he admits he's worn out too.","best":true},{"text":"Go on your own, so he isn't burdened with it","then":"The session helps you, but at home he is still guessing where you stand."},{"text":"Skip it. You can decide this without outside help","then":"The next round's date comes closer, and the same question loops, unanswered, at home."},{"text":"Ask the doctor to just tell you both what to do","then":"She lays out the medical options, but says the choice to go on is yours to make."}],"why":"Talking it through with a counsellor, together, lets you choose from care, not pressure or false hope."},{"prompt":"A relative later asks when you'll try again. How do you answer?","options":[{"text":"Say you're deciding it together, in your own time","then":"The relative nods, and the question doesn't return that day.","best":true},{"text":"Say it's up to whatever the doctor thinks best","then":"The relative moves on, though you and he still haven't decided anything."},{"text":"Say probably never again, honestly","then":"The relative's face falls, and word reaches your partner before you've both chosen."},{"text":"Say you don't know. Ask him","then":"The relative corners your partner at dinner, and he fumbles for an answer alone."}],"why":"Naming it as a shared, unhurried decision keeps the choice yours, not the relative's."}],"debrief":"Whether to continue or pause treatment is the couple's caring choice, made with honest counsel.","relearn":"Continuing or pausing treatment is the couple's caring choice."},
  {"id":"iw-1189","cat":"if-its-hard","type":"branch","persona":"Reshma","source":"listen first","hook":"A friend Radha confides she might be infertile and is terrified to tell anyone.","steps":[{"prompt":"She whispers it, then asks if you think less of her now. What do you say?","options":[{"text":"Say nothing changes, and you're glad she told you","then":"She lets out a breath she seems to have held for weeks.","best":true},{"text":"Reassure her it's probably nothing to worry about","then":"She smiles faintly, though the fear doesn't actually leave her face."},{"text":"Suggest a home remedy a relative once used","then":"She nods politely, but the real fear stays unanswered underneath."},{"text":"Ask why she didn't get checked sooner","then":"She flinches slightly, and the question feels like blame she didn't ask for."}],"why":"Saying nothing changes and that you're glad she told you meets her fear with plain support."},{"prompt":"A few days later she texts asking if you've told anyone. What do you reply?","options":[{"text":"Confirm you haven't. It's hers to share, not yours","then":"She replies with a relieved string of thankful messages.","best":true},{"text":"Say no, but you'd like to ask your mother's advice","then":"She begs you not to, worried it will reach her in-laws."},{"text":"Suggest telling a few close people might help her feel less alone","then":"She says she's not ready, and the suggestion sits heavy on her."},{"text":"Sound offended that she'd even ask","then":"The sharp tone startles her, though nothing was actually shared."}],"why":"Confirming her privacy is hers alone earns back the trust she risked by telling you."},{"prompt":"She finally asks whether she should actually see a doctor. What do you say?","options":[{"text":"Say yes, and that she needn't be certain first","then":"She writes down a clinic's number that same evening.","best":true},{"text":"Say only if it gets a lot worse","then":"She puts it off, deciding today still isn't bad enough."},{"text":"Offer to book it for her without asking further","then":"She hesitates, unsure if she's ready to hand the step over."},{"text":"Suggest waiting to see if it happens naturally","then":"Another month passes, and the same fear returns unanswered."}],"why":"Telling her she needn't be certain first makes the step feel possible right now."},{"prompt":"Weeks later, she's still carrying quiet shame about the whole thing. What do you say?","options":[{"text":"Say it's common, and it was never her fault","then":"Something in her shoulders finally seems to loosen.","best":true},{"text":"Tell her not to worry about it so much","then":"She nods, though the shame doesn't actually leave with the words."},{"text":"Say plenty of people go through the same thing","then":"She nods at the fact, but says she still feels like she failed."},{"text":"Say everyone feels that way and it'll pass","then":"She goes quiet, and doesn't bring up the shame with you again."}],"why":"Naming it as common and not her fault answers the shame directly, not just the facts."}],"debrief":"Listen without judgement, protect her privacy, and remind her infertility is common and never her fault.","relearn":"Listen without judgement and remind her infertility is common and not her fault."},
  {"id":"iw-1190","cat":"if-its-hard","type":"branch","persona":"Karthik","source":"as a team","hook":"Your wife just got a hard fertility result and you want to respond well.","steps":[{"prompt":"She says it must be her fault. What do you say first?","options":[{"text":"Say it's not her fault, and you'll face it as a team","then":"She looks up, and for the first time today, she doesn't look alone.","best":true},{"text":"Say the doctor probably knows more than either of you","then":"She nods, though the blame she's carrying doesn't actually shift."},{"text":"Say it's probably nothing serious. Don't worry","then":"She wants to believe you, but the numbers say otherwise."},{"text":"Stay quiet, unsure what to say","then":"The silence stretches, and she reads it as agreement."}],"why":"Naming it as not her fault, together, answers the blame she's carrying directly."},{"prompt":"The next morning she asks if you'll get checked too. What do you say?","options":[{"text":"Say yes, and book your own appointment that day","then":"She looks relieved that this isn't only on her.","best":true},{"text":"Say you probably don't need to, but she should","then":"She hears the old assumption again, even though you meant well."},{"text":"Say you'll go eventually, once she's done first","then":"She nods, but notices you haven't named a date."},{"text":"Ask if it's really necessary for you specifically","then":"The question lands like doubt, right when she needs a partner."}],"why":"Getting checked yourself, not just her, makes it a real team effort, not just words."},{"prompt":"At the next visit, the doctor explains what tests come next and asks if you have questions. What do you do?","options":[{"text":"Ask what your own tests involve and how to support her","then":"The doctor nods and starts building a fuller, fairer picture of you both.","best":true},{"text":"Say the tests are her side, since the result was about her","then":"The doctor explains men are checked too, and waits for your answer."},{"text":"Say you'd rather wait outside for this part","then":"You miss what the doctor explains, and she carries it back to you second-hand."},{"text":"Ask only what the tests will cost","then":"The doctor answers, but the rest of the picture goes unasked."}],"why":"Asking about your own tests and how to support her keeps the whole picture shared and fair."},{"prompt":"A relative later asks you privately whose fault it really is. How do you respond?","options":[{"text":"Say it's no one's fault, and you're in it together","then":"The relative looks surprised, and the question stops there.","best":true},{"text":"Say you'd rather not discuss it","then":"The relative drops it, though the blame question lingers unanswered elsewhere."},{"text":"Say it's probably something genetic on her side","then":"The comment travels further than you meant it to."},{"text":"Say you're honestly not sure yet","then":"The relative takes that as a maybe, and repeats the question to your mother."}],"why":"Naming it as no one's fault, out loud, protects her from blame that isn't hers to carry."}],"debrief":"Say it's not her fault, share the load, and get evaluated yourself too.","relearn":"Tell her it's not her fault, face it as a team, and get checked yourself too."},
  {"id":"iw-1191","cat":"if-its-hard","type":"branch","persona":"Reshma","source":"affordable routes","hook":"You can't afford private fertility treatment and feel hopeless about your options.","steps":[{"prompt":"A friend mentions a private clinic's price and your stomach drops. What do you do?","options":[{"text":"Ask a government hospital or RKSK about low-cost evaluation","then":"The nurse there explains a plan you can actually afford.","best":true},{"text":"Assume nothing is possible and stop looking","then":"You stop looking, and the worry settles in, unspoken."},{"text":"Borrow heavily from relatives to afford the private clinic","then":"The loan weighs on you before treatment has even begun."},{"text":"Wait until you've saved the full private amount","then":"Months pass while savings creep up slowly, and nothing else moves."}],"why":"A public hospital or RKSK can start the evaluation for far less than you feared."},{"prompt":"At a family function, a relative says couples who truly want a child find the money somehow. What do you say?","options":[{"text":"Say wanting a child isn't measured by what you spend","then":"The relative pauses, and the comment loses its sting.","best":true},{"text":"Agree quietly, and feel ashamed of what you can afford","then":"The shame follows you home, heavier than any bill."},{"text":"Explain every financial detail to justify yourself","then":"The relative picks at each number, and you leave more drained."},{"text":"Say you'll borrow more if that's what it takes","then":"The relative approves, and the debt starts to feel like a duty."}],"why":"How much you spend isn't how much you want a child; saying so keeps the pressure off."},{"prompt":"A friend later asks how the search for care is actually going. What do you say?","options":[{"text":"Tell her honestly, and ask if she knows low-cost care","then":"She gives you the number of a public clinic her sister used.","best":true},{"text":"Say it's all sorted, to sound less worried","then":"She says she's glad, and changes the topic to her own news."},{"text":"Say you'd rather not talk about the cost of it","then":"She respects that, and doesn't bring it up again."},{"text":"Say you're not sure what's next, and leave it there","then":"She squeezes your arm, and the talk drifts to other things."}],"why":"Being honest and asking for leads lets a friend point you to care you haven't found yet."}],"debrief":"Public hospitals and RKSK offer low-cost evaluation; cost shouldn't end the conversation.","relearn":"Government hospitals and RKSK offer low-cost help; cost alone shouldn't end your options."},
  {"id":"iw-1192","cat":"if-its-hard","type":"branch","persona":"Reshma","source":"protect the bond","hook":"After two years of trying, the worry is straining your marriage and you're drifting apart.","steps":[{"prompt":"You notice you've stopped really talking at dinner. What do you do?","options":[{"text":"Name the strain out loud and suggest counselling too","then":"Your partner looks relieved someone finally said it.","best":true},{"text":"Bury the tension and hope it passes on its own","then":"Dinner stays quiet, until your partner brings up seeing someone together."},{"text":"Blame the stress entirely on the fertility struggle","then":"Your partner agrees it's the stress, then says you could both use outside support."},{"text":"Suggest a distraction like a trip, and avoid the topic","then":"The trip helps briefly, but afterward your partner raises seeing a counsellor."}],"why":"Naming the strain and getting support protects the bond, not just the fertility plan."},{"prompt":"A session is booked for next week, and your partner worries it will turn into blaming each other. What do you say?","options":[{"text":"Say it's to understand each other, not to blame","then":"Your partner exhales, and agrees to say the hard things gently.","best":true},{"text":"Say maybe you should cancel if it feels risky","then":"You both hesitate, then keep the appointment, uneasy."},{"text":"Promise to keep the hard things to yourself there","then":"Your partner looks relieved, though you already feel yourself holding back."},{"text":"Say the counsellor will tell you who's right","then":"Your partner goes quiet, bracing for a verdict instead of a talk."}],"why":"Going to understand each other, not to blame, keeps the session about protecting the bond."},{"prompt":"At the first session, the counsellor asks what you each miss most. What do you say?","options":[{"text":"Say plainly how you miss just talking, not planning","then":"Your partner nods hard, saying the exact same thing.","best":true},{"text":"Say you miss nothing, since you're managing fine","then":"The session moves on without touching what's actually true."},{"text":"Say what your partner must miss, not what you do","then":"Your partner looks startled, and the session goes on without either real answer."},{"text":"Let your partner answer first and just agree","then":"The session hears one voice, not both of yours."}],"why":"Naming what you actually miss, plainly, gives the session something real to work with."},{"prompt":"A friend later asks how you two are really doing. What do you say?","options":[{"text":"Say honestly that you're working on it together","then":"Your friend offers to just check in sometimes, no advice.","best":true},{"text":"Say everything is perfect, no issues at all","then":"The friend believes you, and the real support stays out of reach."},{"text":"Vent every detail of the struggle at length","then":"You feel lighter briefly, though your partner wasn't part of that choice."},{"text":"Say you'd rather not talk about it at all","then":"Your friend nods and stops asking, and you carry it alone a while longer."}],"why":"An honest, together answer keeps support open without oversharing what's private to you both."}],"debrief":"Name the strain and seek counselling alongside medical help; the relationship matters too.","relearn":"Name the strain together and consider counselling too; the bond matters as well."},
  {"id":"iw-1193","cat":"if-its-hard","type":"branch","persona":"Reshma","source":"no miracle fee","hook":"A relative offers a miracle baba who guarantees a child for a large donation.","steps":[{"prompt":"The relative says it worked for someone she knows. What do you say?","options":[{"text":"Decline politely and say you'll stick with a clinician","then":"She looks disappointed but doesn't push further today.","best":true},{"text":"Agree to visit, just to see what it's about","then":"The visit costs money and time you can't easily spare, and the baba asks for more."},{"text":"Say you'll think about it, to end the conversation","then":"She takes it as interest and follows up again soon."},{"text":"Get angry that she'd even suggest it","then":"She feels hurt, and the real concern behind it goes unheard."}],"why":"A clear, polite no keeps your money and hope with a route that's actually honest."},{"prompt":"A few days later, she mentions the baba needs an answer by the weekend. What do you do?","options":[{"text":"Say calmly that it's a no, deadline or not","then":"She sighs, and the pressure finally eases off.","best":true},{"text":"Pay once, since it worked for her friend","then":"The donation is paid, and the baba is already asking for more before the weekend is out."},{"text":"Ask your partner to decide instead, to dodge it","then":"Your partner faces the same pressure, now alone."},{"text":"Promise to decide after visiting your actual doctor","then":"She agrees to wait, and asks again the day after your appointment."}],"why":"A calm, clear no stops a made-up deadline from deciding for you."},{"prompt":"At your next appointment, the clinician asks if anyone has suggested other remedies. What do you say?","options":[{"text":"Mention the baba offer and ask for her honest view","then":"She's honest with you and offers real, grounded next steps.","best":true},{"text":"Say nothing, feeling too embarrassed to bring it up","then":"She moves on to your test results, and the baba never comes up."},{"text":"Say the baba's blessing can run alongside her treatment","then":"She says prayer is your own affair, but asks what was promised and for how much."},{"text":"Ask her to just guarantee results like the baba did","then":"She's honest that no one, including her, can promise that."}],"why":"Naming the offer to your clinician gets you an honest check on it, not just your own doubt."}],"debrief":"A 'miracle' fee guarantees nothing. Say no calmly, and ask your clinician about any offer.","relearn":"No 'miracle' can guarantee a child; trust a qualified clinician's honest options."},
  {"id":"iw-1194","cat":"if-its-hard","type":"branch","persona":"Karthik","source":"knowing opens doors","hook":"Your partner wants to start fertility tests but you're scared of what they might find.","steps":[{"prompt":"She asks gently if you're ready to book the tests. What do you say?","options":[{"text":"Say you're scared, but you'll go anyway","then":"She takes your hand, and you book the appointment together.","best":true},{"text":"Say you'd rather wait a bit longer","then":"She agrees to wait, and a month later you book the tests yourself."},{"text":"Say you're fine, no need to worry","then":"She takes you at your word, and you book the tests together, your fear unspoken."},{"text":"Suggest she go first and tell you the results","then":"She goes first, and comes home saying the doctor would like to see you too, so you book it."}],"why":"Naming the fear and going anyway trades dread for real information you can act on."},{"prompt":"At the clinic, the doctor asks if you have any questions before the tests begin. What do you ask?","options":[{"text":"Ask what the results would mean for your options","then":"She explains clearly, and the unknown feels smaller already.","best":true},{"text":"Ask nothing, hoping to just get it over with","then":"The test proceeds, but your questions stay unanswered."},{"text":"Ask how long the results usually take to arrive","then":"She answers kindly, though the bigger question stays unasked."},{"text":"Ask her to call only if something's wrong","then":"She agrees, and every quiet day of waiting feels heavier."}],"why":"Asking what the results would mean turns fear into something concrete you can plan for."},{"prompt":"The results come back and your partner asks how you're feeling. What do you say?","options":[{"text":"Say it's a relief to know, whatever it shows","then":"She agrees, and you talk through what comes next together.","best":true},{"text":"Say you wish you'd never asked","then":"She holds your hand, but you both sit in the dread instead of the plan."},{"text":"Say you're fine, and change the subject fast","then":"The results sit between you, unprocessed and unspoken."},{"text":"Say you'll leave the next steps to her and the doctor","then":"She's caught off guard, left to plan what comes next on her own."}],"why":"Naming the relief in knowing keeps you facing this together, not retreating from it."}],"debrief":"Fear is understandable, but getting checked opens options rather than closing them.","relearn":"Getting checked opens options; the fear is real, but avoiding the test only prolongs worry."},
  {"id":"iw-1195","cat":"if-its-hard","type":"branch","persona":"Reshma","source":"ask while unsure","hook":"You're unsure whether your trouble conceiving even warrants seeing a doctor yet.","steps":[{"prompt":"A neighbour says it's probably too early to worry. What do you do?","options":[{"text":"See a clinician now. You needn't be certain first","then":"You book a visit to get real clarity instead of more guessing.","best":true},{"text":"Wait until you're completely sure something's wrong","then":"The waiting stretches on for months, until the worry sends you to a clinic anyway."},{"text":"Agree it's probably nothing and drop it","then":"The question quiets down, but it resurfaces enough that you book a visit anyway."},{"text":"Ask the neighbour what she thinks it might be","then":"Her guess is kind but only a guess, so you book a clinic visit to know."}],"why":"Seeing a clinician now gets you clarity; you don't need certainty to ask."},{"prompt":"At the clinic, the doctor asks what's actually prompted the visit. What do you say?","options":[{"text":"Describe the worry honestly, even though it's still vague","then":"She listens carefully and starts with a proper, useful check.","best":true},{"text":"Say you're not sure. Maybe it's nothing","then":"The check happens, but her sense of what to look for stays vague too."},{"text":"Downplay it so the visit feels quick","then":"The shortened version means something real might go unchecked."},{"text":"Ask her to just guess what's wrong","then":"She explains she needs your description first to actually help."}],"why":"Describing the worry honestly, even if vague, gives her something real to work with."},{"prompt":"A relative later asks if the visit found anything serious. What do you say?","options":[{"text":"Say calmly that you've been seen and it's in hand","then":"The relative nods, glad the visit was taken seriously, and lets it rest.","best":true},{"text":"Say it's probably nothing, brushing it off fast","then":"The real update gets lost in the rush to reassure."},{"text":"Exaggerate it, since it feels safer to sound serious","then":"The relative worries more than the actual visit gave reason to."},{"text":"Dodge the question, hoping it drops before more come","then":"The relative reads the dodge as something to worry about, and asks around instead."}],"why":"A calm, general answer shares what you choose and keeps the rest of your visit private."},{"prompt":"A friend with a similar worry asks if it was worth going at all. What do you say?","options":[{"text":"Say yes. You needn't be certain to get checked or reassured","then":"Your friend books her own appointment that same week.","best":true},{"text":"Say maybe wait until it feels more urgent","then":"Her own worry quietly waits for a crisis that hasn't come yet."},{"text":"Say she should ask around first, then decide","then":"She asks three aunties, and gets three different guesses."},{"text":"Change the subject, unsure how to answer","then":"Your friend is left with the same uncertainty you started with."}],"why":"Naming that you needn't be certain first shows her that early clarity is worth seeking too."}],"debrief":"You needn't be certain to get checked; a clinician can reassure or guide you early.","relearn":"You needn't be certain to get checked; see a clinician early to be reassured."},
  {"id":"iw-1196","cat":"if-its-hard","type":"sort","hook":"Sort: a compassionate, accurate truth about infertility, or a harmful myth?","items":[{"id":"a","text":"Both partners should be evaluated"},{"id":"b","text":"It's always the woman's fault"},{"id":"c","text":"Support and options exist"},{"id":"d","text":"It's a curse you must hide"},{"id":"e","text":"It's common and no one's shame"},{"id":"f","text":"Treatment is a guaranteed fix"}],"bins":[{"id":"true","label":"Compassionate truth","valence":"pos"},{"id":"myth","label":"Harmful myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Both checked, support exists, common and no shame are truths; 'her fault', 'a curse', and 'guaranteed fix' are myths.","persona":"Reshma","source":"truth vs myth"},
  {"id":"iw-1197","cat":"if-its-hard","type":"sort","hook":"Sort: a grounded route when conceiving is hard, or a false-hope trap to avoid?","items":[{"id":"a","text":"A clinician's honest evaluation"},{"id":"b","text":"A 'guaranteed baby' package"},{"id":"c","text":"Low-cost help via RKSK"},{"id":"d","text":"A baba's paid 'miracle'"},{"id":"e","text":"Exploring adoption (Many Ways to Family)"},{"id":"f","text":"A costly cure with no honest odds"}],"bins":[{"id":"grounded","label":"Grounded route","valence":"pos"},{"id":"trap","label":"False-hope trap","valence":"neg"}],"key":{"a":"grounded","b":"trap","c":"grounded","d":"trap","e":"grounded","f":"trap"},"relearn":"A clinician, RKSK, and adoption are grounded routes; 'guaranteed' packages, paid miracles, and dishonest cures are traps.","persona":"Reshma","source":"route vs trap"},
  {"id":"iw-1198","cat":"if-its-hard","type":"sort","hook":"Sort: a supportive thing to say to someone struggling to conceive, or a hurtful one?","items":[{"id":"a","text":"\"It's common, and it's not your fault\""},{"id":"b","text":"\"You must have done something wrong\""},{"id":"c","text":"\"I'm here, take your time\""},{"id":"d","text":"\"When's the good news, then?\""},{"id":"e","text":"\"Let's look at options calmly\""},{"id":"f","text":"\"Maybe it's a punishment\""}],"bins":[{"id":"kind","label":"Supportive","valence":"pos"},{"id":"hurtful","label":"Hurtful","valence":"neg"}],"key":{"a":"kind","b":"hurtful","c":"kind","d":"hurtful","e":"kind","f":"hurtful"},"relearn":"'Not your fault', 'I'm here', 'options calmly' support; blame, 'good news?' jabs, and 'punishment' hurt.","persona":"Reshma","source":"kind vs hurtful"},
  {"id":"iw-1199","cat":"if-its-hard","type":"sort","hook":"Sort: a calm, true fact about treatment, or a false-promise myth?","items":[{"id":"a","text":"Treatments help many couples"},{"id":"b","text":"IVF always works first try"},{"id":"c","text":"Odds depend on your case"},{"id":"d","text":"A bigger bill guarantees a baby"},{"id":"e","text":"A clinic should explain odds honestly"},{"id":"f","text":"One failure means it never will"}],"bins":[{"id":"fact","label":"Calm truth","valence":"pos"},{"id":"falsepromise","label":"False promise","valence":"neg"}],"key":{"a":"fact","b":"falsepromise","c":"fact","d":"falsepromise","e":"fact","f":"falsepromise"},"relearn":"Treatments help many, odds vary, clinics should be honest: true; 'always works', 'bill guarantees', 'one failure dooms it': false.","persona":"Reshma","source":"fact vs false promise"},
  {"id":"iw-1200","cat":"if-its-hard","type":"sort","hook":"Sort: a healthy way to carry this, or one that deepens the hurt?","items":[{"id":"a","text":"Leaning on your partner"},{"id":"b","text":"Hiding it in shame"},{"id":"c","text":"Talking to a counsellor"},{"id":"d","text":"Blaming yourself nightly"},{"id":"e","text":"Allowing yourself to grieve"},{"id":"f","text":"Cutting off everyone who cares"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"deepens","label":"Deepens the hurt","valence":"neg"}],"key":{"a":"healthy","b":"deepens","c":"healthy","d":"deepens","e":"healthy","f":"deepens"},"relearn":"Leaning on your partner, a counsellor, and grieving help; hiding, self-blame, and isolation deepen the hurt.","persona":"Reshma","source":"carry it well"},
  {"id":"iw-1201","cat":"if-its-hard","type":"sort","hook":"Sort: a fair, accurate idea about who infertility affects, or an unfair myth?","items":[{"id":"a","text":"It affects men and women"},{"id":"b","text":"It's only ever a female problem"},{"id":"c","text":"Male factors are often involved"},{"id":"d","text":"Young couples are immune"},{"id":"e","text":"Both should be checked"},{"id":"f","text":"Only the wife needs tests"}],"bins":[{"id":"fair","label":"Fair & accurate","valence":"pos"},{"id":"unfair","label":"Unfair myth","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Infertility affects both, male factors are often involved, both get checked: accurate; 'only female', 'young are immune', 'only wife tested': myths.","persona":"Karthik","source":"who it affects"},
  {"id":"iw-1202","cat":"if-its-hard","type":"sort","hook":"Sort: a real source of support when conceiving is hard, or a source of pressure to skip?","items":[{"id":"a","text":"A patient, listening partner"},{"id":"b","text":"Relatives counting the months"},{"id":"c","text":"A non-judgemental counsellor"},{"id":"d","text":"Neighbours' pitying remarks"},{"id":"e","text":"A clinician you trust"},{"id":"f","text":"\"Good news?\" at every visit"}],"bins":[{"id":"support","label":"Real support","valence":"pos"},{"id":"pressure","label":"Pressure to skip","valence":"neg"}],"key":{"a":"support","b":"pressure","c":"support","d":"pressure","e":"support","f":"pressure"},"relearn":"A patient partner, counsellor, and trusted clinician support you; relatives counting months, pity, and 'good news?' pressure.","persona":"Reshma","source":"support vs pressure"},
  {"id":"iw-1203","cat":"if-its-hard","type":"sort","hook":"Sort: a true thing about a family without a biological child, or a cruel false frame?","items":[{"id":"a","text":"It can be whole and loving"},{"id":"b","text":"\"They've failed at life\""},{"id":"c","text":"Adoption is a real path"},{"id":"d","text":"\"Their marriage is empty\""},{"id":"e","text":"Worth isn't measured by a child"},{"id":"f","text":"\"Less of a man or woman\""}],"bins":[{"id":"true","label":"True & kind","valence":"pos"},{"id":"cruel","label":"Cruel false frame","valence":"neg"}],"key":{"a":"true","b":"cruel","c":"true","d":"cruel","e":"true","f":"cruel"},"relearn":"Whole and loving, adoption is real, worth isn't a child: true; 'failed', 'empty marriage', 'less of a person': cruel false frames.","persona":"any","source":"whole family"},
  {"id":"iw-1204","cat":"if-its-hard","type":"match","hook":"Match each route when conceiving is hard to what it actually offers.","pairs":[{"left":"Evaluation of both partners","right":"Finding out why, for him and her"},{"left":"Assisted reproduction like IVF","right":"A real option for some, never a guarantee"},{"left":"Adoption (Many Ways to Family)","right":"A whole, valid path to a family"},{"left":"A counsellor","right":"Support to carry the feelings"},{"left":"RKSK / public hospital","right":"Affordable evaluation and guidance"}],"relearn":"Evaluation, IVF, adoption, counselling, and RKSK each offer something real when conceiving is hard.","persona":"Reshma","source":"routes offered"},
  {"id":"iw-1205","cat":"if-its-hard","type":"match","hook":"Match each hurtful line to a kind, true thing to say instead.","pairs":[{"left":"\"It must be her fault\"","right":"\"Let's both get checked\""},{"left":"\"You're cursed\"","right":"\"It's medical, not a curse\""},{"left":"\"Just relax and it'll happen\"","right":"\"A clinician can find the cause\""},{"left":"\"You've failed\"","right":"\"Your worth isn't a baby\""},{"left":"\"Stop wasting money on treatment\"","right":"\"We'll decide together, no shame\""}],"relearn":"Each hurtful line has a kind, true reply: check both, it's medical, see a clinician, worth isn't a child, decide together.","persona":"Reshma","source":"kinder lines"},
  {"id":"iw-1206","cat":"if-its-hard","type":"match","hook":"Match each worry to a calm, accurate reassurance.","pairs":[{"left":"\"Am I the only one?\"","right":"\"No, it's common\""},{"left":"\"Is it too late to ask?\"","right":"\"You can get checked while unsure\""},{"left":"\"Is it my fault?\"","right":"\"It has medical causes, not moral ones\""},{"left":"\"Is IVF a sure thing?\"","right":"\"It helps many, but isn't guaranteed\""},{"left":"\"Can a family still be whole?\"","right":"\"Yes, in many forms\""}],"relearn":"Common, check while unsure, medical not moral, IVF helps but isn't guaranteed, family whole in many forms.","persona":"Reshma","source":"worry to reassurance"},
  {"id":"iw-1207","cat":"if-its-hard","type":"match","hook":"Match each step to the right time to consider it.","pairs":[{"left":"Basic evaluation","right":"After about a year of trying"},{"left":"Both partners checked","right":"From the very first appointment"},{"left":"Second opinion","right":"Before a costly 'guarantee'"},{"left":"Counselling","right":"Whenever the strain feels heavy"},{"left":"Exploring adoption","right":"Anytime it feels right for you"}],"relearn":"Evaluate after a year, check both from the start, second-opinion any 'guarantee', counsel when heavy, adopt when right.","persona":"Karthik","source":"step timing"},
  {"id":"iw-1208","cat":"if-its-hard","type":"match","hook":"Match each person to what they most need to hear.","pairs":[{"left":"A wife blaming herself","right":"\"It's not your fault, we're a team\""},{"left":"A husband avoiding tests","right":"\"Getting checked opens options\""},{"left":"A couple out of money","right":"\"RKSK offers low-cost help\""},{"left":"A friend shamed by relatives","right":"\"You have my support\""},{"left":"A partner exhausted by treatment","right":"\"Pausing isn't failing\""}],"relearn":"Each person needs the right words: not your fault, options open, low-cost help, my support, pausing isn't failing.","persona":"Reshma","source":"what they need"},
  {"id":"iw-1209","cat":"if-its-hard","type":"match","hook":"Match each myth about infertility to the calm truth that corrects it.","pairs":[{"left":"\"It's rare\"","right":"It's actually quite common"},{"left":"\"Always the woman's fault\"","right":"Male factors are often involved"},{"left":"\"IVF always works\"","right":"It helps many, never guaranteed"},{"left":"\"No biological child means failure\"","right":"Family is whole in many forms"},{"left":"\"Hide it in shame\"","right":"Support helps you carry it"}],"relearn":"Common not rare, often male factors, IVF helps not guarantees, family whole in many forms, support over shame.","persona":"Reshma","source":"myth to truth"},
  {"id":"iw-1210","cat":"if-its-hard","type":"match","hook":"Match each real help route to the moment it fits.","pairs":[{"left":"Government hospital","right":"Affordable fertility evaluation"},{"left":"RKSK","right":"Reproductive-health guidance in India"},{"left":"A trusted clinician","right":"Honest options for your case"},{"left":"Many Ways to Family","right":"Adoption and other paths"},{"left":"A counsellor","right":"Holding the emotional weight"}],"relearn":"Government hospital, RKSK, a clinician, Many Ways to Family, and a counsellor each fit a real need.","persona":"Reshma","source":"route to moment"},
  {"id":"iw-1211","cat":"if-its-hard","type":"reflect","hook":"Lensy: infertility is common, it's no one's shame, and you don't have to face it alone. Sit right?","prompt":"What do you think?","options":["Sits right","Not alone","Not my shame"],"affirm":"Infertility is common and never shameful; support, evaluation, and options exist, and you needn't face it alone.","relearn":"Infertility is common and no one's shame; support and options exist, and you're not alone.","persona":"Reshma","source":"not alone"},
  {"id":"iw-1212","cat":"if-its-hard","type":"reflect","hook":"Lensy: a family can be whole in many forms: with a biological child, an adopted one, or just the two of you. Land okay?","prompt":"What's your take?","options":["Lands okay","Many forms","Good to know"],"affirm":"A family is whole in many forms; a biological child is one path, not the measure of a family's worth.","relearn":"A family is whole in many forms; a biological child is one path, not the measure of its worth.","persona":"any","source":"whole in many forms"},
  {"id":"iw-1213","cat":"if-its-hard","type":"reflect","hook":"Lensy: difficulty conceiving is not a verdict on your worth, your love, or your relationship. Hear that?","prompt":"What do you think?","options":["I hear it","Not a verdict","True"],"affirm":"Difficulty conceiving is a medical matter, never a verdict on your worth, your love, or your relationship.","relearn":"Difficulty conceiving is medical, never a verdict on your worth, your love, or your relationship.","persona":"Reshma","source":"not a verdict"},
  {"id":"iw-1214","cat":"if-its-hard","type":"reflect","hook":"Lensy: you can get checked while still unsure. You don't owe anyone certainty before asking for help. Freeing?","prompt":"What's your take?","options":["Freeing","No certainty owed","Good"],"affirm":"You can get checked while unsure; you needn't wait for certainty or a crisis to ask for help.","relearn":"You can get checked while unsure; you needn't wait for certainty or a crisis to ask for help.","persona":"Reshma","source":"check while unsure"},
  {"id":"iw-1215","cat":"if-its-hard","type":"reflect","hook":"Lensy: treatments can help, and they may not. Either way, your full life is still ahead of you. Sit with that?","prompt":"What do you think?","options":["I can","Full life ahead","Yes"],"affirm":"Treatments help many but aren't guaranteed; whichever way it goes, a full and meaningful life remains yours.","relearn":"Treatments help many but aren't guaranteed; either way, a full, meaningful life remains yours.","persona":"Reshma","source":"full life ahead"},
  {"id":"iw-1216","cat":"if-its-hard","type":"reflect","hook":"Lensy: choosing to pause or stop treatment, after honest thought, is a brave and valid choice. Feel allowed?","prompt":"What's your take?","options":["Allowed","Valid choice","Yes"],"affirm":"Pausing or stopping treatment after honest reflection is a valid, caring choice, not a failure or giving up.","relearn":"Pausing or stopping treatment after honest reflection is a valid, caring choice, never a failure.","persona":"Reshma","source":"pausing is valid"},
  {"id":"iw-1217","cat":"if-its-hard","type":"reflect","hook":"Lensy: whatever the relatives say, this is yours and your partner's to face, together, your way. Clear?","prompt":"What do you think?","options":["Clear","Our way","Together"],"affirm":"How you face difficulty conceiving is yours and your partner's, together, your way, free of relatives' scripts.","relearn":"How you face difficulty conceiving is yours and your partner's, together, your way.","persona":"Reshma","source":"your way"},
  {"id":"iw-1218","cat":"if-its-hard","type":"reflect","hook":"Lensy: if you're grieving a loss or a hope, that grief is real and it deserves gentleness, not blame. Heard?","prompt":"What's your take?","options":["Heard","Deserves gentleness","Yes"],"affirm":"Grief over a loss or an unmet hope is real and deserves gentleness and support, never blame or shame.","relearn":"Grief over a loss or unmet hope is real; it deserves gentleness and support, never blame.","persona":"Reshma","source":"grief deserves gentleness"},
  {"id":"iw-1219","cat":"if-its-hard","type":"spot","hook":"Spot the two red flags: the harmful things being said to a couple facing infertility.","scene":[{"id":"a","text":"\"It's common and not your fault\"","trick":false},{"id":"b","text":"\"You must be cursed\"","trick":true},{"id":"c","text":"\"Let's look at options calmly\"","trick":false},{"id":"d","text":"\"It's surely the wife's failing\"","trick":true},{"id":"e","text":"\"You're not alone in this\"","trick":false}],"why":"'You must be cursed' and 'surely the wife's failing' are the harmful red flags: shame and blame, both false.","relearn":"Catch the shame-and-blame lines; infertility is common, medical, and not the wife's failing.","persona":"Reshma","source":"catch the cruelty"},
  {"id":"iw-1220","cat":"if-its-hard","type":"spot","hook":"Spot the two red flags: the false promises in a fertility clinic's pitch.","scene":[{"id":"a","text":"\"We'll explain your honest odds\"","trick":false},{"id":"b","text":"\"Pay upfront for a guaranteed baby\"","trick":true},{"id":"c","text":"\"We'll evaluate both partners\"","trick":false},{"id":"d","text":"\"More money means a sure success\"","trick":true},{"id":"e","text":"\"You're welcome to a second opinion\"","trick":false}],"why":"'Guaranteed baby' and 'more money means sure success' are the red flags: no clinic can promise that.","relearn":"Catch the 'guarantee' and 'pay-more-for-success' lines; honest clinics explain real odds, never promises.","persona":"Reshma","source":"catch false promise"},
  {"id":"iw-1221","cat":"if-its-hard","type":"spot","hook":"Spot the two red flags: the responses that pile pressure on someone struggling to conceive.","scene":[{"id":"a","text":"\"Take your time, I'm here\"","trick":false},{"id":"b","text":"\"When's the good news, hurry up\"","trick":true},{"id":"c","text":"\"It's common, you're not alone\"","trick":false},{"id":"d","text":"\"Try a second marriage instead\"","trick":true},{"id":"e","text":"\"Let's see a clinician together\"","trick":false}],"why":"'Hurry up, good news?' and 'try a second marriage' are the red flags: pressure and cruelty, not support.","relearn":"Catch the rush-and-replace lines; support sounds like 'take your time' and 'let's see a clinician together'.","persona":"Razia","source":"catch the pressure"},
  {"id":"iw-1222","cat":"if-its-hard","type":"spot","hook":"Spot the two red flags: the false ideas about who infertility affects.","scene":[{"id":"a","text":"It can affect men and women","trick":false},{"id":"b","text":"It's only ever the woman's body","trick":true},{"id":"c","text":"Male factors are often involved","trick":false},{"id":"d","text":"Young couples can never have it","trick":true},{"id":"e","text":"Both partners should be checked","trick":false}],"why":"'Only the woman's body' and 'young couples never have it' are the red flags: both are false.","relearn":"Catch the 'only her' and 'not the young' myths; infertility affects both, and young couples too.","persona":"Karthik","source":"catch who-it-affects myth"},
  {"id":"iw-1223","cat":"if-its-hard","type":"spot","hook":"Spot the two red flags: the unhealthy ways to carry the weight of infertility.","scene":[{"id":"a","text":"Leaning on your partner","trick":false},{"id":"b","text":"Hiding it in shame from everyone","trick":true},{"id":"c","text":"Talking to a counsellor","trick":false},{"id":"d","text":"Blaming yourself every night","trick":true},{"id":"e","text":"Letting yourself grieve","trick":false}],"why":"'Hiding it in shame' and 'blaming yourself nightly' are the red flags: isolation and self-blame deepen the hurt.","relearn":"Catch the shame-hiding and self-blame; leaning on others, counselling, and grieving help you carry it.","persona":"Reshma","source":"catch the unhealthy"},
  {"id":"iw-1224","cat":"if-its-hard","type":"spot","hook":"Spot the two red flags: the false 'cures' promising a sure child.","scene":[{"id":"a","text":"A clinician's honest options","trick":false},{"id":"b","text":"A baba's paid 'miracle baby'","trick":true},{"id":"c","text":"Low-cost help from RKSK","trick":false},{"id":"d","text":"A fast that 'guarantees' a child","trick":true},{"id":"e","text":"A second opinion before paying","trick":false}],"why":"The paid 'miracle baby' and the 'guaranteed' fast are the red flags: false cures that prey on hope.","relearn":"Catch the paid 'miracle' and 'guaranteed' fast; real help is a clinician, RKSK, and honest options.","persona":"Reshma","source":"catch the false cure"},
  {"id":"iw-1225","cat":"if-its-hard","type":"spot","hook":"Spot the two red flags: the false beliefs about a family without a biological child.","scene":[{"id":"a","text":"It can be whole and loving","trick":false},{"id":"b","text":"\"Their marriage must be empty\"","trick":true},{"id":"c","text":"Adoption is a real, valid path","trick":false},{"id":"d","text":"\"They've failed at life\"","trick":true},{"id":"e","text":"Worth isn't measured by a child","trick":false}],"why":"'Their marriage must be empty' and 'they've failed at life' are the red flags: cruel and false.","relearn":"Catch the 'empty' and 'failed' frames; a family is whole in many forms, and worth isn't a child.","persona":"any","source":"catch the false frame"},
  {"id":"iw-1226","cat":"if-its-hard","type":"role-play","persona":"Karthik","source":"hold not fix","hook":"You and your wife just got a hard fertility result.","setup":"You hold her and speak gently.","steps":[{"prompt":"She says: \"I feel so broken right now.\"","options":[{"text":"\"You're not broken. We face this together, with help.\"","then":"She holds your hand, and her shoulders drop a little.","best":true},{"text":"\"Maybe we just weren't meant to have kids.\"","then":"She goes still, and the words settle like an ending."},{"text":"\"You'll feel better once the next round starts up.\"","then":"She pulls back a little. \"I'm not talking about the next round.\""},{"text":"\"Let's just not think about it tonight.\"","then":"She nods, but her eyes stay wet. \"It won't go away by morning.\""}],"why":"Naming that she's not broken, and not alone, meets the feeling instead of rushing past it."},{"prompt":"Later, she asks: \"What if this never works for us?\"","options":[{"text":"\"We'll find our way together, whatever it looks like.\"","then":"She exhales, hearing that you're not going anywhere.","best":true},{"text":"\"It will work. Don't think like that.\"","then":"She shakes her head. \"You can't promise that. Nobody can.\""},{"text":"\"Let's cross that bridge if we actually get there.\"","then":"She looks away. \"I'm already standing on that bridge.\""},{"text":"\"I don't know, honestly.\"","then":"Her eyes fill. \"So we're both just lost, then.\""}],"why":"Promising to find your way together, whatever happens, answers the fear honestly and gently."},{"prompt":"Later she says: \"I don't want anyone else to know about the result yet.\"","options":[{"text":"\"It stays between us until you're ready.\"","then":"She relaxes, trusting that her pace will be kept.","best":true},{"text":"\"Okay, but what do I tell people who ask me?\"","then":"She rubs her forehead. \"I can't think about other people right now.\""},{"text":"\"We probably can't hide it forever, though.\"","then":"She stiffens. \"I said not yet. I didn't say forever.\""},{"text":"\"Not even my mother? She keeps asking me.\"","then":"She looks straight at you. \"Especially not her. Not yet.\""}],"why":"Keeping it between you, on her timeline, respects a choice that's hers to make."}],"relearn":"Naming that she's not broken and not alone holds her and keeps you a team facing it together, with help."},
  {"id":"iw-1227","cat":"if-its-hard","type":"role-play","persona":"Reshma","source":"private boundary","hook":"An aunt is holding court in front of the whole gathering of guests.","setup":"The whole table falls quiet, waiting to hear what you'll say.","steps":[{"prompt":"The aunt asks: \"Three years and still no news? What's the matter?\"","options":[{"text":"\"We're handling it privately. Thank you for caring.\"","then":"She blinks, then nods. \"Of course, beta.\" The talk moves on.","best":true},{"text":"\"We don't know. Maybe there's something wrong with us both.\"","then":"The aunt gasps. \"Both of you? Have you seen a proper doctor?\""},{"text":"\"Why do you even need to know that?\"","then":"The aunt looks stung. \"I'm only asking because I care.\""},{"text":"\"We're trying. Please pray for us.\"","then":"She turns to the table. \"You heard her. Everyone, pray for them.\""}],"why":"A calm 'we're handling it privately' holds the boundary without inviting the room into your grief."},{"prompt":"Later in the evening, the aunt returns to it: \"Nobody in our family ever had this problem.\"","options":[{"text":"\"It's no one's fault. And it stays private.\"","then":"She purses her lips. \"Well. If you say so.\"","best":true},{"text":"\"Maybe it is something on my side, then.\"","then":"She nods knowingly. \"I thought so. Get yourself seen to.\""},{"text":"\"And your family is perfect, is it?\"","then":"She draws back, offended. \"I was only saying!\" The table goes quiet."},{"text":"\"Every family is different, I suppose.\"","then":"She shrugs. \"Different, yes. But this never happened with us.\""}],"why":"Saying it's no one's fault, and still private, answers the blame without opening your life to the room."},{"prompt":"A cousin later whispers: \"Is everything really okay between you two?\"","options":[{"text":"\"We're okay. This part is just private right now.\"","then":"She squeezes your hand. \"Okay. I'm here if you need me.\"","best":true},{"text":"\"Honestly, I don't even know anymore these days.\"","then":"Her eyes widen. \"Oh no. Should I ask Mummy to talk to you?\""},{"text":"\"Why does everyone keep asking us that?\"","then":"She backs off, hurt. \"Sorry. I only meant it kindly.\""},{"text":"\"We're fine. Don't worry about us at all.\"","then":"She tilts her head. \"You sure? You don't look fine.\""}],"why":"Reassuring her plainly, while keeping the private part private, answers her worry kindly."},{"prompt":"As the guests leave, your husband quietly asks: \"That was a lot. Are you okay?\"","options":[{"text":"\"Not really. Can we agree what we'll say next time?\"","then":"He takes your hand. \"Yes. Let's work it out tonight, together.\"","best":true},{"text":"\"I'm fine. It's nothing I can't handle.\"","then":"He hesitates. \"You'd tell me if it wasn't?\""},{"text":"\"I wish you'd said more to shut her down.\"","then":"He looks stung. \"I didn't know what you wanted me to say.\""},{"text":"\"Let's just skip these gatherings from now on.\"","then":"He sighs. \"Every wedding and function? Then what?\""}],"why":"Being honest with him, and planning a shared answer, keeps you steady together next time."}],"relearn":"A calm 'we're handling it privately' holds your boundary without inviting the room into your grief."},
  {"id":"iw-1228","cat":"if-its-hard","type":"role-play","persona":"Razia","source":"defend the marriage","hook":"Your brother's marriage has been under pressure since he and his wife haven't conceived.","setup":"The whole family is in the room when it comes up again.","steps":[{"prompt":"Your uncle says: \"He should just remarry and have children properly.\"","options":[{"text":"\"That isn't right. They can decide together.\"","then":"Your uncle blinks, caught off guard. \"I'm only thinking of the family.\"","best":true},{"text":"\"That's his decision to make, not really ours.\"","then":"Your uncle nods. \"Exactly. And he'll decide right, if we remind him.\""},{"text":"\"Maybe he should think about it, honestly.\"","then":"Your uncle turns to the others. \"See? Even she agrees.\""},{"text":"\"Let's not talk about this right now.\"","then":"Your uncle waves a hand. \"Fine. But someone must talk sense into him.\""}],"why":"Naming the push to leave her as wrong, and the choice as theirs, defends her plainly."},{"prompt":"Your uncle insists: \"A family needs an heir. You understand that.\"","options":[{"text":"\"An heir isn't a reason to end a marriage.\"","then":"He pauses. \"Hm. Nobody has put it like that before.\"","best":true},{"text":"\"Maybe you're right. It really is a lot of pressure on him.\"","then":"He nods firmly. \"Good. Then help me talk to him.\""},{"text":"\"That's an old way of thinking.\"","then":"He bristles. \"Old ways kept this family going for generations.\""},{"text":"\"I'd rather not get into this today.\"","then":"He shrugs. \"Then I'll get into it with him myself.\""}],"why":"Naming that an heir is no reason to end a marriage answers the pressure directly."},{"prompt":"Later, your brother asks: \"Do you think staying with her is what I should do?\"","options":[{"text":"\"That's for you and her to decide, not the family.\"","then":"He nods, steadier. \"Then I should talk to her, not to them.\"","best":true},{"text":"\"I can't decide that for you.\"","then":"He rubs his face. \"I know. I just don't know who to listen to.\""},{"text":"\"Everyone will judge you either way, so do what you want.\"","then":"He sighs. \"So I'm on my own with this.\""},{"text":"\"Just give it more time and see.\"","then":"He nods, but his jaw stays tight. \"Time for what, though?\""}],"why":"Naming it as his and her decision, not the family's, backs the couple without deciding for him."}],"relearn":"Naming that pressuring him to leave her is wrong, and that the couple decides together, defends her and their bond."},
  {"id":"iw-1229","cat":"if-its-hard","type":"role-play","persona":"Reshma","source":"no judgement","hook":"A friend pulls you aside, scared she might be infertile.","setup":"You're alone in her kitchen, and she won't look up.","steps":[{"prompt":"She whispers: \"Please don't think less of me for this.\"","options":[{"text":"\"There's nothing to judge. I'm here for you.\"","then":"She grips your hand, and some of the fear leaves her face.","best":true},{"text":"\"Why would I ever think that?\"","then":"She nods, but her hands stay tight. \"I still can't say the word out loud.\""},{"text":"\"You should have gotten checked earlier.\"","then":"She flinches, hearing blame where she needed comfort."},{"text":"\"I'm sure it's not even true.\"","then":"She gives a thin smile. \"But what if it is true?\""}],"why":"Naming that there's nothing to judge meets her fear directly, with plain support."},{"prompt":"She asks: \"Do you think it's my fault somehow?\"","options":[{"text":"\"It's common, and it's never anyone's fault.\"","then":"She exhales, like she's been waiting to hear exactly that.","best":true},{"text":"\"I don't know. Maybe stress or diet?\"","then":"She winces. \"Stress? Diet? So it is something I did.\""},{"text":"\"Let's not think about fault at all.\"","then":"She swallows. \"But I keep thinking about it. I need someone to say it.\""},{"text":"\"These things just happen sometimes.\"","then":"She frowns a little. \"Just happen? So I still don't know if it was me.\""}],"why":"Naming it as common and no one's fault answers the exact fear in her question."},{"prompt":"She asks: \"Should I even bother seeing a doctor about it?\"","options":[{"text":"\"Yes, and you don't need to be certain first.\"","then":"She nods, and mentions a clinic near her office.","best":true},{"text":"\"Only if you're really sure something's wrong.\"","then":"She hesitates, deciding today still isn't sure enough."},{"text":"\"Let's look up your symptoms online first.\"","then":"She scrolls for an hour, and comes away more frightened and no closer to an answer."},{"text":"\"Maybe wait and see for a while longer.\"","then":"Another few weeks pass with the same fear unanswered."}],"why":"Telling her she needn't be certain first makes the first step feel possible now."},{"prompt":"Weeks later she says: \"I still haven't told my husband any of this.\"","options":[{"text":"\"That's okay. Tell him when it feels right to you.\"","then":"She relaxes, relieved the timing is still hers to choose.","best":true},{"text":"\"You really should tell him soon.\"","then":"She nods but feels the timeline pulled out of her hands."},{"text":"\"Shall I tell him for you? He should know.\"","then":"She pulls back. \"No. It's mine to tell. Please don't.\""},{"text":"\"He'll find out eventually anyway.\"","then":"She goes quiet. \"Eventually. That's exactly what scares me.\""}],"why":"Leaving the timing to her respects a choice that's hers to make, not yours to schedule."}],"relearn":"\"It's common. Not your fault. I'm here.\" meets her fear with support, not blame."},
  {"id":"iw-1230","cat":"if-its-hard","type":"role-play","persona":"Reshma","source":"ask for honesty","hook":"At a fertility clinic, the counsellor seems more focused on selling than informing you.","setup":"Your husband sits beside you, holding the brochure.","steps":[{"prompt":"The counsellor says: \"This premium package gives you the best chance.\"","options":[{"text":"\"What's the honest success rate for our case?\"","then":"She hesitates. \"Every case is different. Let me finish the package first.\"","best":true},{"text":"\"Okay, we'll just take the premium one then.\"","then":"She slides a form across. \"Wonderful. Sign here, then pay at the desk.\""},{"text":"\"Is there really no other honest option at all?\"","then":"She flips a page. \"There are add-ons, but premium is what most couples choose.\""},{"text":"\"That sounds expensive. Can we get a discount?\"","then":"She smiles. \"I can take a little off, but only on the premium.\""}],"why":"Asking for the honest success rate gets real information instead of a sales pitch."},{"prompt":"She adds: \"This offer is only valid if you book today.\"","options":[{"text":"\"Not today. First, what are our real chances?\"","then":"She pauses, then answers plainly. \"For your case, it's lower than the brochure suggests.\"","best":true},{"text":"\"Then let's book it now, before it goes.\"","then":"She reaches for the payment slip. \"Card or cash?\""},{"text":"\"Can you just promise it will work for us?\"","then":"She smiles too quickly. \"Our results speak for themselves.\""},{"text":"\"Okay, but only if you add a discount.\"","then":"She knocks a little off. \"Done. Shall I book it?\""}],"why":"Refusing the rush and asking your own odds gets you real numbers, not a deadline."},{"prompt":"Before you sign anything, your husband whispers: \"What do you think we should do?\"","options":[{"text":"\"Let's take the details home and ask our own doctor.\"","then":"He nods, relieved. \"Yes. Let's not sign anything today.\"","best":true},{"text":"\"She's the expert. Let's just trust her and sign.\"","then":"He hesitates, then picks up the pen. \"If you're sure.\""},{"text":"\"I'm honestly not sure what to think now.\"","then":"He squeezes your hand. \"Me neither. So what do we tell her?\""},{"text":"\"Let's just pick whatever's cheapest.\"","then":"He frowns. \"Cheapest, without knowing if any of it works?\""}],"why":"Checking the offer with your own doctor first tests the pitch against honest, independent advice."}],"relearn":"Asking for honest, case-specific success rates protects you from a costly false guarantee."},
  {"id":"iw-1231","cat":"if-its-hard","type":"role-play","persona":"Karthik","source":"go together","hook":"Something about the fertility clinic has your partner anxious.","setup":"Tonight you're both on the sofa, a phone lying between you.","steps":[{"prompt":"They say: \"I keep putting off calling the clinic.\"","options":[{"text":"\"Let's call together, and get us both checked.\"","then":"They relax. \"Together? Okay. Let's do it now.\"","best":true},{"text":"\"You should call soon. It's been a while.\"","then":"They sigh. \"I know. Will you sit with me while I call?\""},{"text":"\"I'll call and book it for you.\"","then":"They hesitate. \"No, I should do it. Just stay with me?\""},{"text":"\"Take your time, no rush at all.\"","then":"They pause. \"If I wait, I'll never do it. Stay while I call?\""}],"why":"Offering to call together shares the fear instead of leaving it on them alone."},{"prompt":"On the call, the receptionist asks: \"Is this appointment for one of you, or both?\"","options":[{"text":"\"Both of us. We're doing this together.\"","then":"The receptionist books a joint slot without another question.","best":true},{"text":"\"Just for my partner, I think.\"","then":"The receptionist types. \"One slot, for your partner, then.\""},{"text":"\"I'm not totally sure, actually.\"","then":"The receptionist pauses. \"Shall I just book one for now?\""},{"text":"\"Whatever's easier for you to book.\"","then":"The receptionist says: \"Then I'll book the one slot.\""}],"why":"Naming it as both of you keeps the shared step actually shared, not defaulted to one."},{"prompt":"In the waiting room, your partner asks: \"What if they find something wrong with me?\"","options":[{"text":"\"Then we'll face it together, whatever it is.\"","then":"They squeeze your hand, steadier than a moment ago.","best":true},{"text":"\"Don't think like that. It'll probably be fine.\"","then":"They look away. \"You can't know that.\""},{"text":"\"We'll deal with that if it happens.\"","then":"They nod, but their knee keeps bouncing. \"I just keep thinking about it.\""},{"text":"\"I'm sure it's nothing, honestly.\"","then":"They half smile. \"You're guessing, though.\""}],"why":"Promising to face whatever comes, together, answers the fear more than a guess at the outcome would."},{"prompt":"Afterward, a relative asks: \"So, whose fault is it that there's no news yet?\"","options":[{"text":"\"No one's. We're handling it together, calmly.\"","then":"The relative blinks. \"Well. As long as you two are together on it.\"","best":true},{"text":"\"Mine, probably, if I'm honest.\"","then":"The relative clicks her tongue. \"Ah. So it's you.\""},{"text":"\"Does it really matter whose fault it is?\"","then":"The relative shrugs. \"Of course it matters. Someone must be the reason.\""},{"text":"\"We'd rather not get into that.\"","then":"The relative raises an eyebrow. \"Fine. I'll ask your mother, then.\""}],"why":"Naming that no one's at fault, plainly, answers the blame question without leaving room for it."}],"relearn":"Offering to go together and get both checked shares the fear and finds the fuller picture."},
  {"id":"iw-1232","cat":"if-its-hard","type":"role-play","persona":"Reshma","source":"trust the doctor","hook":"Your mother has strong ideas about how to fix your fertility troubles.","setup":"Over tea, she brings up the baba again.","steps":[{"prompt":"She says: \"Beta, this baba has helped so many families. Just try it.\"","options":[{"text":"\"I know you mean well, but we trust our doctor.\"","then":"She sighs. \"Doctors don't know everything, beta.\"","best":true},{"text":"\"Fine, we'll stop the treatment and try the baba.\"","then":"She claps her hands. \"I'll tell him you're coming on Sunday.\""},{"text":"\"Maybe we could do both at once?\"","then":"She nods eagerly. \"Both, yes. Once he's working, you won't need the doctor.\""},{"text":"\"You always believe these things too easily.\"","then":"Her face falls. \"I'm your mother. I only want to help.\""}],"why":"Naming that you trust your doctor, kindly, keeps your care grounded without dismissing her."},{"prompt":"A week later, she says: \"The baba says the doctor's medicines block his blessings.\"","options":[{"text":"\"We're staying with the doctor's plan, Ma.\"","then":"She purses her lips, then lets it go. \"As you wish.\"","best":true},{"text":"\"Okay, just once, only to keep the peace.\"","then":"She smiles, relieved. \"Just once. And skip the tablets that week.\""},{"text":"\"Maybe later, once we're less busy.\"","then":"She takes out her phone. \"I'll book him for next month, then.\""},{"text":"\"Why do you keep pushing this on us?\"","then":"She bristles. \"Because nobody else in this house is trying!\""}],"why":"Holding kindly to the doctor's plan keeps real care going without a fight."},{"prompt":"Later, your partner asks: \"Do you think she'll bring it up again?\"","options":[{"text":"\"Maybe, but we'll answer calmly if she does.\"","then":"Your partner nods. \"Same answer from both of us, then.\"","best":true},{"text":"\"I hope not. I'm tired of explaining it.\"","then":"Your partner sighs. \"Me too. But what do we say when she does?\""},{"text":"\"Let's just avoid the topic with her from now on.\"","then":"Your partner hesitates. \"She'll just corner one of us alone, then.\""},{"text":"\"You handle it next time. It's exhausting.\"","then":"Your partner stiffens. \"She's your mother. Why is it on me?\""}],"why":"Agreeing to answer calmly if she brings it up again keeps the boundary steady."}],"relearn":"A respectful 'we trust our doctor' honours the relationship while keeping care grounded in real medicine."},
  {"id":"iw-1350","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"who to ask","relearn":"For fertility, preconception or infertility, a qualified clinician or public services like RKSK is the route, not random web answers.","hook":"\"For anything fertility-related, the internet knows as much as a doctor.\"","myth":{"un":"For anything fertility-related, the internet knows as much as a doctor.","re":"A qualified clinician or public services like RKSK can check you and answer your own situation; the web can't.","why":"Personal care needs a person who can examine and follow up."}},
  {"id":"iw-1351","cat":"tools-and-help","type":"strike-rewrite","persona":"Reshma","source":"no crisis needed","relearn":"You needn't be sure or wait for a crisis; you can see a clinician while still unsure, just to ask or be reassured.","hook":"\"You only go to a doctor about this once something's actually gone wrong.\"","myth":{"un":"You only go to a doctor about this once something's actually gone wrong.","re":"You can see a clinician while still unsure, just to ask or be reassured; you needn't wait for a crisis.","why":"Early questions are care, not an emergency."}},
  {"id":"iw-1352","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"RKSK is real","relearn":"Public reproductive-health services like RKSK exist and are a real, named route, not only private clinics.","hook":"\"There's no public help for this, it's all expensive private clinics.\"","myth":{"un":"There's no public help for this, it's all expensive private clinics.","re":"Public reproductive-health services like RKSK exist and are a real, named route you can use.","why":"India runs public adolescent and reproductive-health programmes."}},
  {"id":"iw-1353","cat":"tools-and-help","type":"strike-rewrite","persona":"Reshma","source":"help, no shame","relearn":"Infertility is common and never your shame; the help route is offered without any judgement.","hook":"\"Asking for help with infertility means admitting something shameful about you.\"","myth":{"un":"Asking for help with infertility means admitting something shameful about you.","re":"Infertility is common and never your shame; the help route is offered without any judgement.","why":"A common, shared experience is not a confession."}},
  {"id":"iw-1354","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"g60 route","relearn":"Adoption and other paths are real and valid; Many Ways to Family covers them, a biological child is one route, not the only one.","hook":"\"If your own body can't, that's simply the end of the road to a family.\"","myth":{"un":"If your own body can't, that's simply the end of the road to a family.","re":"Adoption and other paths are real and valid; Many Ways to Family covers them. A biological child is one route, not the only one.","why":"A family is whole in many forms."}},
  {"id":"iw-1355","cat":"tools-and-help","type":"strike-rewrite","persona":"Sneha","source":"reflection not verdict","relearn":"A reflection tool weighs your wishes, readiness and honest facts; it's a calm way in, not a deadline or a verdict.","hook":"\"Either you just know you want kids, or there's nothing to think about.\"","myth":{"un":"Either you just know you want kids, or there's nothing to think about.","re":"A reflection tool, weighing your wishes, readiness and honest facts, is a calm way in, not a deadline or a verdict.","why":"Big choices deserve quiet thought, not a coin flip."}},
  {"id":"iw-1356","cat":"tools-and-help","type":"strike-rewrite","persona":"Pooja","source":"routed not left","relearn":"Good help is routed, not informed-and-left; it points you to a clinician, RKSK and g60, not just facts.","hook":"\"An app that just dumps facts on you has done its whole job.\"","myth":{"un":"An app that just dumps facts on you has done its whole job.","re":"Good help is routed, not informed-and-left; it points you on to a clinician, RKSK and other paths, not just facts.","why":"Knowing where to go beats a wall of facts."}},
  {"id":"iw-1357","cat":"tools-and-help","type":"strike-rewrite","persona":"Karthik","source":"both go","relearn":"A fertility check-up is a both-partners visit; a clinician can check either or both, it isn't only her appointment.","hook":"\"If you ever get checked, that's the wife's appointment to go to.\"","myth":{"un":"If you ever get checked, that's the wife's appointment to go to.","re":"A fertility check-up is a both-partners visit; a clinician can check either or both, it isn't only hers.","why":"Fertility involves two people, so does the check."}},
  {"id":"iw-1358","cat":"tools-and-help","type":"branch","persona":"Reshma","source":"first step quietly","hook":"You want help but feel you must have it all figured out before you can go.","steps":[{"prompt":"A cousin says clinics ask a lot of questions you can't answer yet. What do you do?","options":[{"text":"Ask at a nearby health centre what your options are","then":"The worker at the health centre welcomes you in without asking for a full picture first.","best":true},{"text":"Wait until you've solved it all alone first","then":"The waiting stretches on for weeks, until the worry sends you to the centre anyway."},{"text":"Read everything online before going anywhere","then":"The reading raises more questions than answers, so you walk to the centre to ask."},{"text":"Ask the cousin to explain it all to you instead of going","then":"She shares what she knows, and you still end up at the centre soon after."}],"why":"One quiet question to a health centre or RKSK is enough to start, no full picture needed."},{"prompt":"At the centre, the worker asks what brought you in today. What do you say?","options":[{"text":"Say plainly you're unsure and want a first question answered","then":"She walks you gently through what comes next, one step at a time.","best":true},{"text":"Say you're not sure why you even came","then":"The worker smiles and starts with the basics, and it takes longer to find your first question."},{"text":"Pretend you already know more than you do","then":"The guidance she gives may skip past what you actually needed."},{"text":"Ask her to just tell you everything at once, right now","then":"The flood of information is hard to hold onto afterward."}],"why":"Naming honestly that you're unsure gives her exactly what she needs to guide you well."},{"prompt":"A relative later asks what you found out. What do you say?","options":[{"text":"Say you took a first small step, and leave it at that","then":"The relative seems glad you started, and doesn't push for more.","best":true},{"text":"Say nothing, feeling you haven't done enough yet","then":"The relative assumes you've done nothing, and starts suggesting her own remedies."},{"text":"Promise you'll have it all sorted very soon","then":"The promise adds pressure to a process that takes its own time."},{"text":"Deflect and hope she stops asking","then":"She senses the deflection and starts asking around instead."}],"why":"Naming the one small step shows progress needn't be the whole picture, and the rest stays yours."}],"debrief":"A quiet first question to a clinician or RKSK is enough to start.","relearn":"You can take a quiet first step to a clinician or RKSK while unsure; you needn't have it all figured out first."},
  {"id":"iw-1359","cat":"tools-and-help","type":"branch","persona":"any","source":"which source","hook":"You have a real fertility question and aren't sure where to take it.","steps":[{"prompt":"A scary post on your feed claims to have the answer. What do you do?","options":[{"text":"Ask a qualified clinician or a public service like RKSK","then":"You book time with a clinician instead of trusting the post.","best":true},{"text":"Trust whatever the loudest post on your feed says","then":"The post feeds the worry for days, until you book a clinician after all."},{"text":"Ask ten different friends what they think","then":"Ten friends give ten answers, so you book a clinician to settle it."},{"text":"Search until you find a post that says what you hope","then":"The comfort fades by morning, and you book a clinician after all."}],"why":"A clinician or a service like RKSK answers your real situation; a scare post never can."},{"prompt":"The clinician asks what specifically prompted your question. What do you say?","options":[{"text":"Name the actual post and ask what's true in it","then":"She separates the panic from the real facts, calmly and clearly.","best":true},{"text":"Say you don't remember exactly, just worried","then":"She answers generally, since the specific worry stays unnamed."},{"text":"Ask her to just confirm the post is right","then":"She gently explains the post oversimplifies things quite a bit."},{"text":"Say it doesn't matter. Just answer everything","then":"The broad answer misses the one thing that actually worried you."}],"why":"Naming the exact claim lets her answer the real worry, not a vague version of it."},{"prompt":"A week later, a similar scary post appears again. What's your move?","options":[{"text":"Note the claim to ask your clinician next visit","then":"The post loses its grip once it's just a question on your list.","best":true},{"text":"Panic again as if you'd never asked before","then":"The fear floods back, and you lose another evening to it."},{"text":"Forward it to a friend to see what she thinks","then":"She worries too, and now two of you share the same unanswered fear."},{"text":"Believe it this time, since it's the second post","then":"The repetition starts to feel like proof, and the worry grows."}],"why":"Turning a scare post into a calm question for your clinician keeps facts ahead of fear."}],"debrief":"Take your own fertility questions to a clinician or RKSK, not to a scare-post.","relearn":"For your own fertility questions, ask a clinician, not a scare-driven post; a qualified person beats a viral one."},
  {"id":"iw-1360","cat":"tools-and-help","type":"branch","persona":"any","source":"weigh it calmly","hook":"You finally want to weigh the children question instead of avoiding it.","steps":[{"prompt":"A friend says overthinking it will only make it harder. What do you do?","options":[{"text":"Sit down and reflect on your wishes and readiness","then":"The question starts feeling clearer instead of heavier.","best":true},{"text":"Decide on a whim next time someone nags you","then":"The whim feels quick, but doubt creeps in, and you sit down to reflect after all."},{"text":"Avoid it a little longer, since it feels easier","then":"The avoidance buys quiet for a while, until you finally sit down to reflect."},{"text":"Ask your friend to just tell you what to do","then":"Her answer fits her life, not yours, so you decide to reflect on your own instead."}],"why":"A calm reflection of your own wishes and readiness makes the choice genuinely yours."},{"prompt":"Reflecting, you notice a fact you're unsure about. What do you do?","options":[{"text":"Note it down to check with a clinician later","then":"The uncertain fact gets a real answer instead of a guess.","best":true},{"text":"Assume the scariest version is probably true","then":"The assumption adds worry that the actual facts might not support."},{"text":"Skip past it, since it feels uncomfortable","then":"The gap stays there, quietly shaping the decision anyway."},{"text":"Ask social media what the fact might mean","then":"The answers vary wildly, and none are really about you."}],"why":"Noting the gap to check later keeps your reflection honest instead of built on a guess."},{"prompt":"Your partner asks what you've actually landed on so far. What do you say?","options":[{"text":"Share your honest reflection, still open to theirs","then":"They open up too, and the picture starts forming together.","best":true},{"text":"Say you've basically decided, to sound sure","then":"They go quiet, assuming there's little left for them to add."},{"text":"Ask them to decide first so you can react","then":"They hesitate, then share theirs, and you find yourself just agreeing."},{"text":"Say you'd rather not share it yet","then":"The shared decision stalls, waiting on a reveal that keeps not happening."}],"why":"Sharing your honest, still open reflection invites a real shared conversation, not a verdict."},{"prompt":"A relative later asks if you've finally made up your mind. How do you answer?","options":[{"text":"Say you're weighing it calmly, and it may take time","then":"The relative nods, and the pressure doesn't quite land.","best":true},{"text":"Say you'll announce it when it's official","then":"It sounds settled, though nothing inside has actually settled yet."},{"text":"Say you're sick of being asked, honestly","then":"The relative backs off, though the tension lingers after."},{"text":"Say probably soon, just to satisfy her","then":"The vague promise invites the exact same question again soon."}],"why":"Naming that you're weighing it calmly, on your own time, keeps the decision honestly yours."}],"debrief":"Weigh it with a calm reflection of wishes, readiness and facts.","relearn":"Weigh the whether/when/how-many choice with a calm reflection of your wishes, readiness and facts, not on impulse."},
  {"id":"iw-1361","cat":"tools-and-help","type":"branch","persona":"any","source":"info vs advice","hook":"Something you read here felt important and you're tempted to act on it as a medical instruction.","steps":[{"prompt":"The app mentions a supplement that might help. What do you do?","options":[{"text":"Treat it as info to think with. Ask a clinician the specifics","then":"You note the specifics to bring to the doctor at your next appointment.","best":true},{"text":"Self-treat straight off what the app said","then":"You take it without checking, until side effects send you to a clinician anyway."},{"text":"Ask a friend if she's tried the supplement","then":"Her experience isn't really evidence, so you book a clinician appointment to be sure."},{"text":"Ignore it completely, unsure if it's reliable at all","then":"The lead goes unchecked, until it resurfaces at a later appointment."}],"why":"Info helps you ask better questions; only a clinician can say what actually applies to you."},{"prompt":"At the appointment, the clinician asks what prompted your question. What do you say?","options":[{"text":"Name what you read and ask if it applies to you","then":"She explains clearly what's relevant and what isn't, for you.","best":true},{"text":"Say you're not sure, just wanted to check in general","then":"The answer stays broad, since the actual prompt wasn't named."},{"text":"Ask her to just confirm the app is right","then":"She explains the app is a starting point, not the final word."},{"text":"Say it doesn't matter where you read it","then":"The conversation misses the chance to check the specific claim."}],"why":"Naming the exact thing you read lets her answer the real question, not a general one."},{"prompt":"A relative, hearing about your appointment, says you should have just trusted the app instead. What do you say?","options":[{"text":"Say an app informs. A clinician actually advises.","then":"The relative pauses, hearing the line drawn plainly.","best":true},{"text":"Agree the app is probably enough","then":"The relative nods, and next time suggests you skip the clinic altogether."},{"text":"Argue about which source is more trustworthy","then":"The debate goes nowhere, and the actual question stays unanswered."},{"text":"Say you'll just do both from now on","then":"Both routes get followed loosely, and neither one carefully."}],"why":"Naming the app as info and the clinician as advice keeps the line clear for anyone pushing back."},{"prompt":"Weeks later, a friend asks if the app's tip actually worked. What do you say?","options":[{"text":"Tell her to ask her own doctor before trying it","then":"Your friend notes it down to ask her own doctor, not just the app.","best":true},{"text":"Say the app basically sorted it out alone anyway","then":"Your friend trusts the app the same way, skipping her own doctor."},{"text":"Say you're honestly not sure what helped","then":"Your friend shrugs, and orders the supplement anyway."},{"text":"Tell her to just try it and see how she feels","then":"Your friend orders it that night, without asking anyone."}],"why":"Pointing her to her own doctor passes on the real route, whatever the tip did for you."}],"debrief":"Use this as info to think with; take diagnosis and treatment to a clinician.","relearn":"This game is information to think with; for a diagnosis or treatment, take it to a clinician."},
  {"id":"iw-1362","cat":"tools-and-help","type":"branch","persona":"Reshma","source":"private route","hook":"You want to ask a clinic about trouble conceiving, but there's no privacy at home.","steps":[{"prompt":"Your mother-in-law is always nearby when you'd want to call a clinic. What do you do?","options":[{"text":"Use a discreet route, a health centre, in confidence","then":"You head to a health centre instead, and nobody at home needs to know.","best":true},{"text":"Give up because home has no privacy","then":"The worry stays unanswered for a while, until you try the health centre after all."},{"text":"Ask her directly if you can just have some privacy","then":"She agrees, but hovers nearby, so you decide to visit the health centre instead."},{"text":"Whisper the call quickly when she's not looking","then":"The rushed call gets cut short, and the nurse suggests you visit the health centre."}],"why":"A health centre or RKSK gives you a confidential route, without needing privacy at home."},{"prompt":"At the centre, the worker asks if you'd like a private room to talk. What do you say?","options":[{"text":"Say yes, and take the time to ask everything","then":"You leave with real answers to questions you'd carried for weeks.","best":true},{"text":"Say it's fine. You don't need much time","then":"Some real questions stay unasked, in the rush to keep it short."},{"text":"Say you'd rather just get a pamphlet","then":"The pamphlet covers the basics, but not your specific worry."},{"text":"Ask if you can come back another day instead","then":"The worker says of course, but the days slip by and the questions wait longer."}],"why":"Taking the private room and the time uses the confidential route fully, not just partly."},{"prompt":"Back home, your mother-in-law asks where you were all morning. What do you say?","options":[{"text":"Say it was a health check-up and leave it there","then":"She accepts the general answer, and your privacy stays intact.","best":true},{"text":"Say you owe her a full account, and start explaining","then":"The visit, the questions and the worry all spill out, and it becomes talk in the house."},{"text":"Ask your husband to answer her for you","then":"He is caught off guard, and your morning becomes a question between the two of you."},{"text":"Snap that it's none of her business","then":"She looks hurt, and mentions to your husband at dinner that you were short with her."}],"why":"A short, general answer keeps your details yours and needs no long explanation."}],"debrief":"With no privacy at home, a health centre or RKSK is a quiet, confidential route to ask.","relearn":"If privacy is hard, a public health centre or RKSK gives a discreet route to ask; you can seek help quietly."},
  {"id":"iw-1363","cat":"tools-and-help","type":"branch","persona":"Pooja","source":"go together","hook":"You suggest a basic fertility check-up for the two of you.","steps":[{"prompt":"He assumes only you'll go for the check-up. What do you do?","options":[{"text":"Book it as a both-of-us visit. A clinician can check either.","then":"He looks surprised, then agrees it makes sense to go together.","best":true},{"text":"Go alone and carry the whole thing yourself","then":"You're set to go alone, until he decides at the last minute to come too."},{"text":"Insist he go alone instead, to be fair","then":"He resists going alone, and you end up booking a joint visit after all."},{"text":"Drop the idea rather than push the point","then":"The check-up waits a few days, until you both decide to just go together."}],"why":"A both-of-us visit makes fertility a shared step instead of a solo errand."},{"prompt":"At the clinic, the receptionist asks if you're both being seen today. What do you say?","options":[{"text":"Say yes, since you're both here to be checked","then":"The receptionist books two slots, and he settles in beside you.","best":true},{"text":"Say just you, since he's only there for support","then":"The receptionist books one slot, and he sits in the waiting room alone."},{"text":"Say you're not sure what he wants to do","then":"He shrugs too, and the moment to decide together slips by."},{"text":"Say he'll decide once you're both inside","then":"Inside, the doctor asks him directly, and he looks to you, unsure."}],"why":"Naming that you're both being seen keeps the shared visit actually shared, not just attended."},{"prompt":"On the way home, he says the whole visit felt harder than he expected. What do you say?","options":[{"text":"Ask what felt hardest, and share your side","then":"He talks about the waiting and the questions, and you trade the hard parts.","best":true},{"text":"Say you found it easy, so it's fine","then":"He goes quiet, and doesn't mention it again."},{"text":"Joke that now he knows how it feels","then":"He gives a thin smile and looks out of the window."},{"text":"Say you're surprised he found it hard at all","then":"He shrugs it off, and changes the subject to dinner."}],"why":"Asking what felt hard, and sharing your side, keeps the step something you carry together."},{"prompt":"A relative later asks why he even needed to go too. What do you say?","options":[{"text":"Say a clinician can check either of you","then":"The relative nods, and the old assumption quietly updates.","best":true},{"text":"Say he just came along for support","then":"The relative nods, satisfied that the check-up is still your job."},{"text":"Say you're not sure why, honestly","then":"The relative shrugs, and keeps calling it your check-up."},{"text":"Say it was his idea, not really yours","then":"The relative laughs and says he must be a very modern husband."}],"why":"Naming that a clinician checks either partner corrects the old assumption plainly."}],"debrief":"Make the fertility check-up a both-of-us visit; a clinician can check either or both.","relearn":"Go to the fertility check-up together. A clinician can check both partners, not just one."},
  {"id":"iw-1364","cat":"tools-and-help","type":"branch","persona":"any","source":"another path","hook":"Conceiving has been hard and you wonder if there's another way to a family.","steps":[{"prompt":"A friend mentions adoption almost as an afterthought. What do you do?","options":[{"text":"Explore Many Ways to Family. Adoption and other routes are real","then":"You find real, concrete paths you hadn't properly considered before.","best":true},{"text":"Believe it's a biological child or no family at all","then":"You put the question away for now, and the other routes stay unexamined."},{"text":"Change the subject and hope it fades","then":"The question waits, unexplored, until it comes back on its own."},{"text":"Ask the friend to stop bringing it up","then":"The topic goes quiet, though the door it opened stays unexplored."}],"why":"Exploring Many Ways to Family shows real routes exist, not just the one you'd assumed."},{"prompt":"A few days later, your partner asks if and how you'd want to look into other paths. What do you say?","options":[{"text":"Say you'd like to learn together, at your own pace","then":"You both start reading, going only as fast as feels right.","best":true},{"text":"Say you'll look into it alone, to spare them","then":"You read late into the night alone, and they feel shut out."},{"text":"Say you'd rather they decide, since you're too tired","then":"The decision lands on one of you instead of being shared."},{"text":"Say adoption would only ever be second best","then":"Your partner goes quiet, and the idea feels smaller than it did a minute ago."}],"why":"Wanting to learn together, at your own pace, keeps the choice genuinely shared and unforced."},{"prompt":"A relative says a real family means your own blood. What do you say?","options":[{"text":"Say a family is whole in many forms, this included","then":"The relative has no easy reply, and the comment doesn't return.","best":true},{"text":"Say maybe they're right that blood matters most","then":"The relative nods, and repeats it at the next visit."},{"text":"Get defensive and end the conversation sharply","then":"The tension lingers, though the actual belief goes unchallenged."},{"text":"Say you're not even considering it, to end it","then":"The relative nods, satisfied, and the family stops mentioning adoption around you."}],"why":"Naming that family is whole in many forms answers the old idea directly and calmly."},{"prompt":"Months later, a friend asks how things are with the whole question. What do you say?","options":[{"text":"Share honestly where you actually are with it","then":"Your friend offers real, specific support instead of vague sympathy.","best":true},{"text":"Say it's basically done, to sound further along","then":"The overstatement leaves less room for the support you actually need."},{"text":"Share only the hopeful parts and skip the hard ones","then":"Your friend cheers you on, and never learns what is actually weighing on you."},{"text":"Downplay it as no big deal","then":"Your friend takes you at your word, and skips checking in for months."}],"why":"An honest update, steps and all, lets real support actually reach you."}],"debrief":"A biological child is one route, not the only one; Many Ways to Family covers the rest.","relearn":"If a biological child is hard, adoption and other paths are real; Many Ways to Family is the route to them."},
  {"id":"iw-1365","cat":"tools-and-help","type":"branch","persona":"any","source":"honest expectations","hook":"A glossy clinic ad promises 'guaranteed results' and you're tempted to trust it.","steps":[{"prompt":"The ad's headline keeps circling in your mind. What do you do?","options":[{"text":"Ask a clinician for honest expectations and odds for you","then":"She agrees to walk you through what's realistic before you go anywhere else.","best":true},{"text":"Believe the guaranteed ad and skip the honest talk","then":"You plan around a promise no clinic can actually make."},{"text":"Ask friends if they've seen results like the ad","then":"Their stories vary wildly, and none answer your actual odds."},{"text":"Book the clinic without asking any questions","then":"The appointment happens before the real numbers are ever discussed."}],"why":"A clinician gives honest, personal odds; an ad's promise is a sales line, not a fact."},{"prompt":"At a consultation, the doctor asks what you're hoping treatment will do. What do you say?","options":[{"text":"Mention the ad and ask what's realistic for you","then":"She gives you honest odds for your situation, not the ad's promise.","best":true},{"text":"Say you're counting on the guaranteed result","then":"She pauses, and says gently that no clinic can honestly promise that."},{"text":"Say you're not sure, just looking around","then":"The conversation stays general, without the specific answer you need."},{"text":"Ask only about the cost, not the odds","then":"She lists the fees, and the odds of success never come up."}],"why":"Naming the ad and asking what's realistic for you gets honest odds, not marketing."},{"prompt":"A relative later says the clinic sounds like a sure thing. What do you say?","options":[{"text":"Say treatments help many, but nothing's a guarantee","then":"The relative hears the honest version, not the ad's version.","best":true},{"text":"Agree it sounds promising, to keep things upbeat","then":"The relative tells the whole family it's guaranteed, and the questions start."},{"text":"Say you're not sure what to believe anymore","then":"The relative starts sending you more clinic ads to help you decide."},{"text":"Avoid the topic to dodge more questions","then":"The relative repeats the ad's claim to someone else instead."}],"why":"Naming honestly that treatments help many, without guaranteeing, keeps expectations real."}],"debrief":"Ask a clinician for honest odds, not a guarantee; treatments help many but aren't sure.","relearn":"Ask a clinician for honest odds, not a guarantee; treatments help many but aren't a sure fix."},
  {"id":"iw-1366","cat":"tools-and-help","type":"sort","persona":"any","source":"real help vs not","relearn":"A clinician, RKSK and a calm reflection are real help; scare-posts, a 'guaranteed-baby' ad and relatives' deadlines aren't.","hook":"Sort each one: a real, trustworthy route to help, or not actual help at all?","items":[{"id":"a","text":"A qualified clinician"},{"id":"b","text":"Public services like RKSK"},{"id":"c","text":"A calm reflection of your wishes and facts"},{"id":"d","text":"Scare-driven fertility posts"},{"id":"e","text":"A 'guaranteed-baby' clinic ad"},{"id":"f","text":"Relatives' constant deadlines"}],"bins":[{"id":"help","label":"Real help","valence":"pos"},{"id":"not","label":"Not real help","valence":"neg"}],"key":{"a":"help","b":"help","c":"help","d":"not","e":"not","f":"not"}},
  {"id":"iw-1367","cat":"tools-and-help","type":"sort","persona":"Reshma","source":"see clinician when","relearn":"See a clinician for the medical and uncertain; reflection and partner talk are for the personal-decision side.","hook":"Sort each: take it to a clinician/RKSK, or it's yours to reflect on, not a clinic visit?","items":[{"id":"a","text":"Months of trying with no luck"},{"id":"b","text":"Preconception health questions"},{"id":"c","text":"Unsure but want to be reassured"},{"id":"d","text":"Whether you even want children"},{"id":"e","text":"How many feels right for you"},{"id":"f","text":"Whether you're emotionally ready"}],"bins":[{"id":"clinic","label":"See a clinician","valence":"tell"},{"id":"reflect","label":"Yours to reflect on","valence":"neutral"}],"key":{"a":"clinic","b":"clinic","c":"clinic","d":"reflect","e":"reflect","f":"reflect"}},
  {"id":"iw-1368","cat":"tools-and-help","type":"sort","persona":"any","source":"info vs advice line","relearn":"Information helps you think and ask; diagnosis, treatment and dosage are a clinician's job, not an app's.","hook":"Sort each: something this game can give you, or only a clinician can?","items":[{"id":"a","text":"General fertility facts to think with"},{"id":"b","text":"Questions worth asking a doctor"},{"id":"c","text":"Calm context for a decision"},{"id":"d","text":"A diagnosis of your situation"},{"id":"e","text":"A treatment plan and dosage"},{"id":"f","text":"A personal medical directive"}],"bins":[{"id":"game","label":"This game can help","valence":"pos"},{"id":"clin","label":"Only a clinician","valence":"tell"}],"key":{"a":"game","b":"game","c":"game","d":"clin","e":"clin","f":"clin"}},
  {"id":"iw-1369","cat":"tools-and-help","type":"sort","persona":"Pooja","source":"calm vs anxiety","relearn":"Calm planning uses facts you own, your timeline and a clinician; anxiety comes from deadlines, doomscrolling and 'too late'.","hook":"Sort each: a calm-planning move, or something that just feeds anxiety?","items":[{"id":"a","text":"Learning the basics together, calmly"},{"id":"b","text":"Booking a clinician to ask"},{"id":"c","text":"Keeping the choice on your timeline"},{"id":"d","text":"Doomscrolling fertility scare posts"},{"id":"e","text":"Treating a guideline as a deadline"},{"id":"f","text":"Repeating 'it's already too late'"}],"bins":[{"id":"calm","label":"Calm planning","valence":"pos"},{"id":"anx","label":"Feeds anxiety","valence":"uhoh"}],"key":{"a":"calm","b":"calm","c":"calm","d":"anx","e":"anx","f":"anx"}},
  {"id":"iw-1370","cat":"tools-and-help","type":"sort","persona":"any","source":"trust the source","relearn":"A clinician, RKSK and honest expectations are trustworthy; 'guaranteed-baby' ads, sex-selection offers and scare media aren't.","hook":"Sort each source for this decision: trustworthy, or one to be wary of?","items":[{"id":"a","text":"A qualified clinician"},{"id":"b","text":"Public services like RKSK"},{"id":"c","text":"Honest expectations about treatment odds"},{"id":"d","text":"A clinic promising guaranteed babies"},{"id":"e","text":"An offer to reveal the baby's sex"},{"id":"f","text":"Scare-driven social media"}],"bins":[{"id":"trust","label":"Trustworthy","valence":"pos"},{"id":"wary","label":"Be wary","valence":"neg"}],"key":{"a":"trust","b":"trust","c":"trust","d":"wary","e":"wary","f":"wary"}},
  {"id":"iw-1371","cat":"tools-and-help","type":"sort","persona":"Sneha","source":"what reflection weighs","relearn":"A reflection weighs your own wishes, readiness and honest facts; it's not weighing relatives' wishes or what friends did.","hook":"Sort each: something a calm reflection actually weighs, or noise that doesn't belong in it?","items":[{"id":"a","text":"What you genuinely want"},{"id":"b","text":"Your honest readiness"},{"id":"c","text":"Calm, accurate facts"},{"id":"d","text":"What relatives demand"},{"id":"e","text":"Keeping up with friends' families"},{"id":"f","text":"Fear of what people will say"}],"bins":[{"id":"weigh","label":"Belongs in it","valence":"pos"},{"id":"noise","label":"Outside noise","valence":"neg"}],"key":{"a":"weigh","b":"weigh","c":"weigh","d":"noise","e":"noise","f":"noise"}},
  {"id":"iw-1372","cat":"tools-and-help","type":"match","persona":"any","source":"need to route","relearn":"Each need has a route: facts to a clinician, decision to reflection, infertility to RKSK, other paths to g60, pressure to a boundary.","hook":"Match each need to the route that actually fits it.","pairs":[{"left":"Personal fertility facts","right":"A qualified clinician"},{"left":"Whether and when to decide","right":"A calm reflection tool"},{"left":"Trouble conceiving","right":"RKSK or a health centre"},{"left":"Other paths to a family","right":"Many Ways to Family"},{"left":"'Good news' pressure","right":"A firm, calm boundary"}]},
  {"id":"iw-1373","cat":"tools-and-help","type":"match","persona":"any","source":"who does what","relearn":"Know each service's job: clinician examines, RKSK is public support, reflection clarifies, g60 covers other paths, this game informs.","hook":"Match each service or tool to the job it does.","pairs":[{"left":"A clinician","right":"Examines and advises on your case"},{"left":"RKSK","right":"Public reproductive-health support"},{"left":"The reflection tool","right":"Clarifies what you want, pressure-free"},{"left":"Many Ways to Family","right":"Routes to adoption and other paths"},{"left":"This game","right":"General information to think with"}]},
  {"id":"iw-1374","cat":"tools-and-help","type":"match","persona":"any","source":"info or advice","relearn":"Tell information from medical advice: facts, questions and context are info; diagnosis, treatment and dosage are a clinician's.","hook":"Match each item to whether it's information or actual medical advice.","pairs":[{"left":"General fertility facts","right":"Information to think with"},{"left":"Questions to ask a doctor","right":"Information to bring to a visit"},{"left":"A diagnosis of your case","right":"Medical advice, see a clinician"},{"left":"A treatment and dosage","right":"Medical advice; only a clinician"},{"left":"Reassurance you're not alone","right":"Support, not a prescription"}]},
  {"id":"iw-1375","cat":"tools-and-help","type":"match","persona":"Reshma","source":"worry to comfort","relearn":"Each infertility worry has a calm truth: it's common, no one's fault, roughly equal, not the end, and help exists.","hook":"Match each infertility worry to the calm truth that meets it.","pairs":[{"left":"'It must be just me'","right":"Roughly equal between the sexes"},{"left":"'It's my shameful fault'","right":"Common, and never your shame"},{"left":"'There's no help'","right":"RKSK and clinicians can help"},{"left":"'It's the end of family'","right":"Other paths exist, via g60"},{"left":"'I must face it alone'","right":"Support and evaluation exist"}]},
  {"id":"iw-1376","cat":"tools-and-help","type":"match","persona":"Pooja","source":"calm vs scare","relearn":"Pair each scare line with its calm-planning reframe: facts you own, your timeline, honest odds, and a clinician's word.","hook":"Match each scare line to the calm reframe that replaces it.","pairs":[{"left":"'Your clock is ticking, hurry'","right":"Facts to plan on your own terms"},{"left":"'A guideline is your deadline'","right":"A guideline, not a personal deadline"},{"left":"'Treatment is guaranteed'","right":"Honest odds from a clinician"},{"left":"'It's already too late'","right":"Ask a clinician for your real picture"},{"left":"'Just keep doomscrolling'","right":"Calm facts you actually own"}]},
  {"id":"iw-1377","cat":"tools-and-help","type":"match","persona":"Karthik","source":"shared routes","relearn":"Fertility help is shared: both go to the check-up, both learn the basics, both decide timing, both carry it.","hook":"Match each 'her job' myth to the shared truth that replaces it.","pairs":[{"left":"'Only she gets checked'","right":"A clinician can check both partners"},{"left":"'Fertility is her department'","right":"A both-of-us thing to learn"},{"left":"'Timing is her worry'","right":"A decision you make together"},{"left":"'She carries any bad news'","right":"You face a hard result as a team"},{"left":"'She books the appointment'","right":"Go to the visit together"}]},
  {"id":"iw-1378","cat":"tools-and-help","type":"match","persona":"any","source":"step to next step","relearn":"Each starting point has a next step: unsure to ask, trouble to a clinician, other paths to g60, pressure to a boundary.","hook":"Match each starting point to a sensible next step.","pairs":[{"left":"Unsure and want reassurance","right":"Ask a clinician while still unsure"},{"left":"Months of trying, no luck","right":"Get evaluated, together"},{"left":"Wondering about adoption","right":"Explore Many Ways to Family"},{"left":"Facing constant pressure","right":"Set one calm, firm boundary"},{"left":"Just want to decide well","right":"Use the reflection tool"}]},
  {"id":"iw-1379","cat":"tools-and-help","type":"spot","persona":"any","source":"spot the bad route","relearn":"A clinician, RKSK and honest reflection are real routes; a 'guaranteed-baby' clinic and a sex-determination offer are red flags.","hook":"Spot the two red-flag 'routes' to avoid among these.","scene":[{"id":"a","text":"Asking a qualified clinician","trick":false},{"id":"b","text":"A clinic promising a guaranteed baby","trick":true},{"id":"c","text":"Using public services like RKSK","trick":false},{"id":"d","text":"An offer to reveal the baby's sex","trick":true},{"id":"e","text":"A calm reflection of your wishes","trick":false}],"why":"A 'guaranteed-baby' clinic sells false hope and a sex-determination offer is illegal under the PCPNDT Act; the rest are real routes."},
  {"id":"iw-1380","cat":"tools-and-help","type":"spot","persona":"any","source":"spot the not-advice","relearn":"An app can inform and route; it can't diagnose, prescribe dosage or treat, those two are a clinician's job, not an app's.","hook":"Spot the two things an app must never claim to do here.","scene":[{"id":"a","text":"Share general fertility facts","trick":false},{"id":"b","text":"Diagnose your exact condition","trick":true},{"id":"c","text":"Suggest questions for your doctor","trick":false},{"id":"d","text":"Prescribe a treatment and dosage","trick":true},{"id":"e","text":"Point you to a clinician and RKSK","trick":false}],"why":"Diagnosing and prescribing are medical acts only a clinician can do; an app can inform and route, not treat."},
  {"id":"iw-1381","cat":"tools-and-help","type":"spot","persona":"Reshma","source":"spot the shame","relearn":"Infertility help comes without judgement; 'your fault' and 'too shameful to ask' are the false lines to drop, not the facts.","hook":"Spot the two shaming lines to drop when seeking help.","scene":[{"id":"a","text":"'Infertility is common, never your fault'","trick":false},{"id":"b","text":"'This is your shameful fault'","trick":true},{"id":"c","text":"'You can get checked while unsure'","trick":false},{"id":"d","text":"'It's too shameful to even ask'","trick":true},{"id":"e","text":"'Support and options exist'","trick":false}],"why":"'Your shameful fault' and 'too shameful to ask' are false and block care; the rest are the truths that open the help route."},
  {"id":"iw-1382","cat":"tools-and-help","type":"spot","persona":"Pooja","source":"spot the panic","relearn":"Calm planning means facts you own and a clinician's word; 'hurry', 'too late' and treating a guideline as a deadline are panic.","hook":"Spot the two panic-merchant lines hiding among the calm ones.","scene":[{"id":"a","text":"'Learn the basics together, calmly'","trick":false},{"id":"b","text":"'Hurry, your clock is ticking'","trick":true},{"id":"c","text":"'Ask a clinician for your real picture'","trick":false},{"id":"d","text":"'It's basically already too late'","trick":true},{"id":"e","text":"'A guideline isn't a personal deadline'","trick":false}],"why":"'Hurry, your clock is ticking' and 'already too late' are panic, not care; the rest are calm planning."},
  {"id":"iw-1383","cat":"tools-and-help","type":"spot","persona":"any","source":"spot false promise","relearn":"Honest help gives real odds and other paths; 'IVF is guaranteed' and 'a biological child is the only family' are the false ones.","hook":"Spot the two false promises among these statements about help.","scene":[{"id":"a","text":"'Treatments help many, but aren't sure'","trick":false},{"id":"b","text":"'IVF is a guaranteed fix'","trick":true},{"id":"c","text":"'You can get checked while unsure'","trick":false},{"id":"d","text":"'A biological child is the only family'","trick":true},{"id":"e","text":"'Other paths are real, via g60'","trick":false}],"why":"'IVF is guaranteed' sells false hope and 'the only family' erases real paths; the rest are honest and true."},
  {"id":"iw-1384","cat":"tools-and-help","type":"spot","persona":"Karthik","source":"spot her-job myth","relearn":"Fertility help is shared: both partners go, learn and decide; 'only she goes' and 'her department' are the myths to catch.","hook":"Spot the two 'it's her job' myths to catch.","scene":[{"id":"a","text":"'A clinician can check both of us'","trick":false},{"id":"b","text":"'Only she needs to get checked'","trick":true},{"id":"c","text":"'We learn the basics together'","trick":false},{"id":"d","text":"'Fertility is purely her department'","trick":true},{"id":"e","text":"'We go to the visit as a team'","trick":false}],"why":"'Only she gets checked' and 'her department' wrongly offload a shared thing; a clinician can check both and you go together."},
  {"id":"iw-1385","cat":"tools-and-help","type":"spot","persona":"any","source":"spot routed vs left","relearn":"Help that routes you points on to a clinician, RKSK or g60; 'just figure it out alone' and 'no next step' leave you stranded.","hook":"Spot the two lines that leave you stranded instead of routed.","scene":[{"id":"a","text":"'Here's where to go: a clinician'","trick":false},{"id":"b","text":"'Now just figure it out alone'","trick":true},{"id":"c","text":"'RKSK can support you next'","trick":false},{"id":"d","text":"'That's it, no next step for you'","trick":true},{"id":"e","text":"'Many Ways to Family covers the rest'","trick":false}],"why":"'Figure it out alone' and 'no next step' abandon you; real help routes you on to a clinician, RKSK or g60."},
  {"id":"iw-1386","cat":"tools-and-help","type":"reflect","persona":"any","source":"who you'd ask","relearn":"There's no wrong door, a clinician, RKSK, or a quiet reflection first; the point is you have real routes you can use.","hook":"Lensy: if a real fertility question came up tomorrow, where might you take it?","prompt":"What feels right for you?","options":["A clinician","RKSK or a health centre","Reflect on it first, then ask"],"affirm":"Any of these is a real route, a clinician, RKSK, or quiet reflection first; the point is you needn't carry it alone."},
  {"id":"iw-1387","cat":"tools-and-help","type":"reflect","persona":"any","source":"reassured to know","relearn":"Knowing the routes exist, clinician, RKSK, reflection, g60, is its own quiet reassurance; you decide which you'd reach for.","hook":"Lensy: now you know the routes exist. How does that sit with you?","prompt":"What's your honest take?","options":["Reassuring to know","Good to have options","I'll keep them in mind"],"affirm":"Just knowing the routes exist, clinician, RKSK, reflection, g60, is a quiet reassurance you can carry."},
  {"id":"iw-1388","cat":"tools-and-help","type":"reflect","persona":"Sneha","source":"your own pace","relearn":"You set the pace, ask now, reflect first, or simply hold the routes; no one decides for you when to use them.","hook":"Lensy: there's no rush to use any of this. What pace suits you?","prompt":"What sounds like you?","options":["Ask soon","Reflect for a while first","Just hold the option"],"affirm":"You set the pace, ask now, reflect first, or simply hold the routes; they wait for you, not the other way round."},
  {"id":"iw-1389","cat":"tools-and-help","type":"reflect","persona":"Reshma","source":"asking is okay","relearn":"Asking for help is allowed and unshameful; reaching out, taking a quiet step, or just deciding to is each valid.","hook":"Lensy: reaching out for help on this is allowed, and never shameful. What might it look like for you?","prompt":"What feels possible?","options":["Ask quietly somewhere safe","Take a small first step","Just decide it's okay to ask"],"affirm":"Whatever the step, asking is allowed and never shameful; help is offered without judgement."},
  {"id":"iw-1390","cat":"tools-and-help","type":"reflect","persona":"any","source":"info to ask better","relearn":"This is information to think with, not orders; you take it to ask better questions, your own way, of a real clinician.","hook":"Lensy: this game gives you things to think and ask about, not orders. How will you use it?","prompt":"What's your plan?","options":["Ask my doctor better questions","Think it through calmly","Share it with my partner"],"affirm":"However you use it, it's information to help you think and ask better, your own way, of a real clinician."},
  {"id":"iw-1391","cat":"tools-and-help","type":"reflect","persona":"Karthik","source":"share the load","relearn":"Sharing the load looks different for everyone, learning, going along, or carrying news together; any move toward shared is real.","hook":"Lensy: if any of this becomes a shared thing with your partner, where might you start?","prompt":"What might you do?","options":["Learn the basics together","Go to a check-up together","Carry any news as a team"],"affirm":"Any of these makes it shared, learning, going along, or carrying news together; the load isn't hers alone."},
  {"id":"iw-1392","cat":"tools-and-help","type":"reflect","persona":"any","source":"keep what helps","relearn":"You keep whatever helped here, the routes, the reflection, the calm; it's yours now, to use whenever and however you choose.","hook":"Lensy: of everything here, what feels worth keeping for yourself?","prompt":"What stays with you?","options":["The routes to real help","The calm way to decide","That I'm not alone in it"],"affirm":"Whatever you keep, the routes, the reflection, the calm, it's yours now, to use whenever you choose."},
  {"id":"iw-1393","cat":"tools-and-help","type":"reflect","persona":"any","source":"no certainty needed","relearn":"You needn't be certain to reach out; being unsure is a fine reason to ask, reflect, or simply learn more.","hook":"Lensy: you don't have to be sure of anything to reach out. Does that change things?","prompt":"What's your take?","options":["Yes, that's freeing","I'll ask even while unsure","Good to know there's no test"],"affirm":"Being unsure is a fine reason to ask, reflect, or learn more; there's no certainty you must reach first."},
  {"id":"iw-1394","cat":"tools-and-help","type":"role-play","persona":"Pooja","source":"suggest check-up","hook":"A basic fertility check-up has been on your mind, but you're not sure how to bring it up.","setup":"On Sunday morning, you mention it over breakfast.","steps":[{"prompt":"He asks: \"Wait, is something wrong?\"","options":[{"text":"\"No. I'd just like us both to know where we stand.\"","then":"He relaxes. \"Oh. Okay. I can do that.\"","best":true},{"text":"\"Not really. I just think you should get checked.\"","then":"He frowns. \"Me? Why just me?\""},{"text":"\"Nothing's wrong. Forget I said anything.\"","then":"He pauses. \"No, wait. If you want a check-up, let's talk about it.\""},{"text":"\"Maybe. I read something that scared me.\"","then":"He sits up, worried. \"Scared you how? What did it say?\""}],"why":"Framing it as calm and shared, not alarmed, keeps the suggestion easy to actually say yes to."},{"prompt":"Later that day, he asks: \"Do we both go, or does one of us go first?\"","options":[{"text":"\"Both of us. It's shared, not a turn.\"","then":"He nods. \"Okay. Let's book two slots, same week.\"","best":true},{"text":"\"I guess I will, since I brought it up.\"","then":"He looks relieved. \"Okay, you go first, and I'll see after.\""},{"text":"\"Whoever's free first, I suppose.\"","then":"He checks his calendar. \"Probably you, then. My month's packed.\""},{"text":"\"You can go first if you're less busy.\"","then":"He nods vaguely. \"Sure, I'll find a slot sometime.\""}],"why":"Naming it as both of you, not a turn, keeps the check-up genuinely shared."},{"prompt":"A week later, a friend asks: \"Why would he need a check-up too?\"","options":[{"text":"\"A clinician checks either of us. It's shared.\"","then":"She raises her eyebrows. \"Huh. I never thought of that.\"","best":true},{"text":"\"It's mostly about me, honestly.\"","then":"She nods. \"That's what I assumed too.\""},{"text":"\"I'm not totally sure, honestly.\"","then":"She shrugs. \"Seems like extra hassle for him, then.\""},{"text":"\"To keep him from feeling left out.\"","then":"She laughs. \"So it's just for show, then?\""}],"why":"Naming that a clinician checks either of you corrects the old assumption plainly."}],"relearn":"Suggesting a both-of-us check-up frames fertility as shared and gets you a fuller, calmer picture together."},
  {"id":"iw-1395","cat":"tools-and-help","type":"role-play","persona":"Reshma","source":"ask for a route","hook":"You confide in a trusted health worker that you'd like to ask about conceiving, but quietly.","setup":"She has stopped by while the house is empty for an hour.","steps":[{"prompt":"She says: \"Go on. I'm listening.\"","options":[{"text":"\"Could you tell me where I can ask about this privately?\"","then":"She writes down a nearby clinic and mentions RKSK, quietly.","best":true},{"text":"\"Nothing really. I shouldn't have said anything.\"","then":"She waits. \"It's safe to ask me. Take your time.\""},{"text":"\"Just tell me everything you know, right now.\"","then":"She smiles. \"That's a lot. Let's start with where you can go.\""},{"text":"\"I read something online. Is that true?\"","then":"She listens. \"Maybe, maybe not. Better to ask someone who can check.\""}],"why":"Asking for a private route directly gets you an actual place to go, not just general talk."},{"prompt":"She says: \"There's a centre nearby. Would that work for you?\"","options":[{"text":"\"Yes, and can I go without anyone at home knowing?\"","then":"She nods. \"Yes. What you say there stays there.\"","best":true},{"text":"\"Maybe. I'll ask my sister-in-law what she thinks.\"","then":"She pauses. \"You can, but will she keep it to herself?\" In the end, you go alone."},{"text":"\"I guess so, if it's not too far.\"","then":"She nods. \"It's close. Go when you can.\" You go that Friday."},{"text":"\"I'll think about it and let you know.\"","then":"She squeezes your hand. \"Mornings are quietest.\" That week, you go."}],"why":"Asking directly about privacy confirms the route actually protects you, not just that it exists."},{"prompt":"At the centre, the nurse asks: \"What would you like to know first?\"","options":[{"text":"\"Whatever's true about my own chances, plainly.\"","then":"She nods. \"Then let's start with a few questions about you.\"","best":true},{"text":"\"Whatever you think I should know.\"","then":"She reaches for a leaflet. \"Well, most couples start here.\""},{"text":"\"Nothing. I'm not sure why I came.\"","then":"She waits a moment. \"Then shall I just check your blood pressure?\""},{"text":"\"Just confirm nothing is wrong with me.\"","then":"She shakes her head gently. \"I can't promise that without checking.\""}],"why":"Naming your own real question, plainly, gets you an answer that's actually about you."},{"prompt":"Back home, a relative asks: \"Where were you all morning?\"","options":[{"text":"\"Just a health errand, nothing major.\"","then":"She shrugs. \"Okay. Lunch is getting cold.\"","best":true},{"text":"\"Nowhere important. Don't worry about it.\"","then":"She narrows her eyes. \"Nowhere, for three hours?\""},{"text":"\"I went to ask about having children, actually.\"","then":"Her eyebrows shoot up. \"Children? Wait till I tell everyone!\""},{"text":"\"I forget, just running errands.\"","then":"She laughs. \"You forgot where you were? Come on, tell me.\""}],"why":"A simple, true answer protects the privacy you went out of your way to find."}],"relearn":"Asking someone trusted for a quiet route to RKSK or a clinic gets you help without exposing yourself at home."},
  {"id":"iw-1396","cat":"tools-and-help","type":"role-play","persona":"any","source":"decline guarantee","hook":"A clinic salesperson is talking fast, and you're not sure what's real.","setup":"The salesperson wants an answer before you leave the room.","steps":[{"prompt":"The salesperson says: \"This package guarantees your results. Sign today.\"","options":[{"text":"\"I'd like honest odds, not a guarantee.\"","then":"He pauses. \"Well, the numbers depend on the couple.\"","best":true},{"text":"\"If it's guaranteed, sign me up right now.\"","then":"He slides the form over. \"Excellent. Just your signature here.\""},{"text":"\"Can you throw in a discount at least?\"","then":"He grins. \"A small discount, if you sign today.\""},{"text":"\"I need to think about it for a bit.\"","then":"He frowns. \"What's there to think about? It's guaranteed.\""}],"why":"Asking for honest odds instead of a guarantee gets you real numbers, not a sales line."},{"prompt":"He adds: \"Today's price ends at six, you know.\"","options":[{"text":"\"Then I'll miss it. I need honest odds first.\"","then":"He sighs. \"Fine. Honestly, it works for some couples, not all.\"","best":true},{"text":"\"Sorry, maybe I'm overthinking this.\"","then":"He smiles. \"You are. Shall I get the form?\""},{"text":"\"Can you hold that price till tomorrow?\"","then":"He shakes his head. \"Only if you pay the deposit now.\""},{"text":"\"Everyone should get honest odds, not just me.\"","then":"He shrugs. \"Maybe. But today's price is for you.\""}],"why":"Letting a deadline pass to get honest odds first resists the rush to sign."},{"prompt":"Outside, a friend asks: \"So, are you going to sign up?\"","options":[{"text":"\"Not before my own doctor looks at the offer.\"","then":"She nods. \"Take the brochure along. See what she says.\"","best":true},{"text":"\"Yes. A guarantee is hard to pass up.\"","then":"She hesitates. \"Did they say what happens if it doesn't work?\""},{"text":"\"I'm honestly not sure what I'm doing.\"","then":"She shrugs. \"Well, don't let him rush you.\""},{"text":"\"I said no to everything, just in case.\"","then":"She pauses. \"Even to asking what's realistic?\""}],"why":"Checking the offer with your own doctor tests the pitch against honest, independent advice."}],"relearn":"Declining a 'guaranteed' pitch and asking for honest odds keeps you planning on real information, not a sales promise."},
  {"id":"iw-1397","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"own going first","hook":"A basic fertility check-up has come up, and old habits are creeping back in.","setup":"Your wife is scrolling clinic listings on the sofa beside you.","steps":[{"prompt":"She says: \"I guess I'll book it for myself this week.\"","options":[{"text":"\"I'll get checked too. Let's go together.\"","then":"She looks up, surprised. \"You'd do that? Okay. Together.\"","best":true},{"text":"\"Good, let me know how it goes.\"","then":"She nods, a little flat. \"Sure.\" On the day, you go along anyway."},{"text":"\"I'll come along for support, at least.\"","then":"She smiles faintly. \"Okay. At least I won't be sitting there alone.\""},{"text":"\"You should, since it's mostly about you anyway.\"","then":"She goes quiet. \"Right. Mostly me.\" She books it, and you go along on the day."}],"why":"Getting checked too, and going together, makes it a shared step, not hers alone."},{"prompt":"The doctor asks: \"So, who's being evaluated today?\"","options":[{"text":"\"Both of us. We're doing this together.\"","then":"The doctor nods. \"Then we'll look at both of you today.\"","best":true},{"text":"\"Her, mainly. I'm just here.\"","then":"The doctor nods. \"Then we'll start with her, and see about you later.\""},{"text":"\"I hadn't really thought about it.\"","then":"The doctor looks between you. \"Shall we start with your wife, then?\""},{"text":"\"Whichever one of us you'd like first.\"","then":"The doctor smiles. \"Ladies first, then. We'll see about you.\""}],"why":"Naming both of you plainly keeps the shared visit shared, not just attended."},{"prompt":"Later she says: \"Honestly, I didn't expect you to actually come.\"","options":[{"text":"\"This is ours to face together, not just yours.\"","then":"She exhales, like she'd been carrying more than she said.","best":true},{"text":"\"Well, someone had to keep you company.\"","then":"Her smile slips. \"Company. Okay.\""},{"text":"\"I wasn't sure I should, honestly.\"","then":"She looks away. \"Oh. I thought you wanted to.\""},{"text":"\"I figured you'd want me there.\"","then":"She nods. \"I did. But do you want to be there?\""}],"why":"Naming it as something you're both facing answers her surprise by owning your half plainly."},{"prompt":"A relative later asks: \"Why should a man get checked at all?\"","options":[{"text":"\"It's a both-of-us matter. Men get checked too.\"","then":"The relative blinks. \"Hm. Nobody told us that in our day.\"","best":true},{"text":"\"Just to be safe, I suppose.\"","then":"The relative waves it off. \"Safe from what? It's always the woman.\""},{"text":"\"My wife wanted me to, honestly.\"","then":"The relative chuckles. \"Ah, so she's the boss now.\""},{"text":"\"I'm honestly not sure. It was just suggested.\"","then":"The relative nods. \"Then there's no need. Let her handle it.\""}],"why":"Naming fertility as a both-of-us matter answers the old assumption directly."}],"relearn":"Offering to get checked too, alongside her, shows fertility is a both-partners matter and takes the weight off her alone."},
  {"id":"iw-1398","cat":"tools-and-help","type":"role-play","persona":"Sneha","source":"point to RKSK","hook":"A friend has been quietly anxious about her fertility for weeks.","setup":"Over chai at her flat, she finally brings it up.","steps":[{"prompt":"She says: \"I don't even know where to start with this.\"","options":[{"text":"\"Talk to a clinician or RKSK. They'll answer.\"","then":"She writes the suggestion down, relieved to have somewhere real to start.","best":true},{"text":"\"Just read up online. You'll figure it out.\"","then":"She sighs. \"I've read so much already. It only scares me more.\""},{"text":"\"Try not to worry about it too much.\"","then":"She shakes her head. \"I've tried. It doesn't just switch off.\""},{"text":"\"Ask your mother what she thinks.\"","then":"She winces. \"Mummy will just tell me to pray and wait.\""}],"why":"Naming a clinician or RKSK gives her a real, calm place to take the worry, not just sympathy."},{"prompt":"She asks: \"What if a doctor tells me something scary?\"","options":[{"text":"\"Then you'll know, and know what to do next.\"","then":"She sits with that a moment, and nods slowly.","best":true},{"text":"\"I'm sure it'll be fine. Don't overthink it.\"","then":"She looks down. \"You don't know that, though.\""},{"text":"\"Maybe wait until you feel readier, then.\"","then":"She exhales. \"Maybe. I'll see how I feel.\""},{"text":"\"I'd probably be scared too, honestly.\"","then":"She nods. \"So what do I do with that?\""}],"why":"Naming that knowing opens a next step answers her fear better than reassurance alone."},{"prompt":"A few weeks later, she says: \"I finally booked the appointment.\"","options":[{"text":"\"That's a real step. Want company after?\"","then":"She smiles, glad to have you there either way.","best":true},{"text":"\"Good, let me know what they say.\"","then":"She nods, quieter. \"Okay. I'll message you after.\""},{"text":"\"See, that wasn't so hard, was it?\"","then":"Her smile fades. \"It was, actually. Really hard.\""},{"text":"\"Finally, I was starting to worry.\"","then":"She laughs awkwardly. \"Sorry for worrying you, I guess.\""}],"why":"Offering company or a chat after meets her where she actually is, not where you expected her to be."}],"relearn":"Pointing a worried friend to RKSK or a clinician hands her a real route, not just sympathy or scary advice."},
  {"id":"iw-1399","cat":"tools-and-help","type":"role-play","persona":"any","source":"name not-advice","hook":"A relative keeps steering you away from seeing an actual doctor.","setup":"The same argument comes up again today.","steps":[{"prompt":"The relative says: \"The app already told you what to do. Why go further?\"","options":[{"text":"\"An app helps me think; a clinician advises.\"","then":"The relative pauses, hearing the line drawn plainly.","best":true},{"text":"\"You're right. Maybe the app is enough.\"","then":"The relative smiles. \"See? Save yourself the trip.\""},{"text":"\"I don't know. Maybe you have a point.\"","then":"The relative nods. \"Trust me. I've seen these things before.\""},{"text":"\"Fine, I'll do both just to end this.\"","then":"The relative frowns. \"Both? That's twice the fuss.\""}],"why":"Naming the app as info and the clinician as advice keeps a plain, useful line for anyone pushing back."},{"prompt":"The relative says: \"Doctors just want your money anyway.\"","options":[{"text":"\"Maybe some do, but I still need real answers.\"","then":"The relative has no easy comeback for that, and drops it.","best":true},{"text":"\"You might be right. That's fair.\"","then":"The relative nods, pleased. You keep the appointment anyway, a little less sure."},{"text":"\"That's a strange thing to say, honestly.\"","then":"The relative bristles. \"Strange? It's the truth.\""},{"text":"\"I guess I could skip it this once.\"","then":"The relative beams. \"Sensible.\" Still, you keep the appointment."}],"why":"Naming your real need for answers, calmly, holds the line without a fight."},{"prompt":"The doctor asks: \"What made you come in today?\"","options":[{"text":"\"I wanted a clinician's actual advice, not the app.\"","then":"She nods, and checks the specifics the app couldn't.","best":true},{"text":"\"Honestly, I almost didn't come at all.\"","then":"The visit happens, though the real reason stays a little muddled."},{"text":"\"I'm not totally sure why, honestly.\"","then":"The visit starts without a clear question to actually work from."},{"text":"\"The app told me everything already.\"","then":"She gently explains why the app's version isn't the full picture."}],"why":"Naming that you wanted real clinical advice gives the visit a clear, useful starting point."}],"relearn":"Naming that an app informs but a clinician advises keeps you taking the specifics to the person who can actually treat you."},
  {"id":"iw-1400","cat":"tools-and-help","type":"role-play","persona":"Reshma","source":"ask while unsure","hook":"A worry about conceiving has been sitting with you for weeks, unspoken.","setup":"Today you finally tell your friend Farah about it.","steps":[{"prompt":"Farah asks: \"Is it really worth bothering the doctor over this?\"","options":[{"text":"\"I don't have to be sure. I'll go to be reassured.\"","then":"Farah nods. \"Then call now. I'll sit with you.\"","best":true},{"text":"\"Probably not. I'll just wait it out.\"","then":"Farah shrugs. \"You've waited weeks already.\" A few days later, you book anyway."},{"text":"\"I don't know. Maybe I'm overreacting.\"","then":"Farah frowns. \"You're not. Go and ask.\" Two days later, you book it."},{"text":"\"You're right. It's probably nothing.\"","then":"Farah nods, but you can't settle, and you book a visit that week."}],"why":"Naming that you needn't be sure first gives yourself permission to ask and be reassured."},{"prompt":"The receptionist asks: \"What's the reason for your visit?\"","options":[{"text":"\"A worry I'd like checked, even if it's small.\"","then":"She nods, typing. \"That's what we're here for.\"","best":true},{"text":"\"I'm not sure it's a real reason, honestly.\"","then":"She pauses, pen hovering. \"Shall I just put 'general'?\""},{"text":"\"Nothing specific, just checking in general.\"","then":"She writes 'routine check'. \"Take a seat, please.\""},{"text":"\"Probably nothing, sorry to bother you.\"","then":"She shrugs. \"No bother. Just fill in this form.\""}],"why":"Naming the worry plainly, even a small one, gets it treated as worth a real answer."},{"prompt":"The doctor says: \"I'm glad you came in, even just to check.\"","options":[{"text":"\"Thank you. Can we go through what's worrying me?\"","then":"She pulls her chair closer. \"Of course. Start wherever you like.\"","best":true},{"text":"\"I probably shouldn't have wasted your time.\"","then":"She shakes her head. \"You haven't. But what's worrying you?\""},{"text":"\"I guess I panicked over nothing.\"","then":"She raises an eyebrow. \"Let's check before we call it nothing.\""},{"text":"\"I'll try not to bother you again.\"","then":"She pauses. \"Please do come back if it's on your mind.\""}],"why":"Taking her welcome and naming the worry lets the visit help, instead of apologising it away."}],"relearn":"Saying you needn't be sure to get checked lets you seek reassurance early instead of carrying worry alone for months."},
  {"id":"iw-1401","cat":"tools-and-help","type":"role-play","persona":"any","source":"route to g60","hook":"A couple you know has been through a hard fertility journey.","setup":"She's been quiet since the last round of treatment ended.","steps":[{"prompt":"She says: \"I think our dream of a family is just over.\"","options":[{"text":"\"I'm so sorry. When you're ready, there are other paths too.\"","then":"She looks up, eyes wet. \"Other paths? I hadn't let myself think of that.\"","best":true},{"text":"\"Well, maybe it just wasn't meant to be.\"","then":"Her eyes fill. \"So that's it, then.\""},{"text":"\"You could still try a few more rounds of treatment, right?\"","then":"She shakes her head slowly. \"We've got nothing left for more rounds.\""},{"text":"\"I'm so sorry. You should look into adoption now.\"","then":"She flinches. \"Now? I can barely think.\""}],"why":"Sorrow first, then a gentle 'when you're ready', meets her grief without rushing her."},{"prompt":"Her husband asks: \"People keep mentioning adoption. Is it even the same as having our own?\"","options":[{"text":"\"A different path, but the child is fully yours.\"","then":"He nods slowly. \"Fully ours,\" he repeats, turning the idea over for the first time.","best":true},{"text":"\"It's basically identical to having your own, honestly.\"","then":"He frowns. \"Identical? The process alone sounds nothing like ours.\""},{"text":"\"Not really, but it's better than nothing.\"","then":"His jaw tightens. \"Better than nothing. Right.\""},{"text":"\"I don't know. I've never looked into it.\"","then":"He nods, unsatisfied. \"Nobody we know has, either.\""}],"why":"Naming it as a different route to a child who is fully theirs respects it without ranking it below."},{"prompt":"She asks: \"Where would we even start looking into that?\"","options":[{"text":"\"Ask your clinician, and read official adoption information.\"","then":"She writes it down. \"Official information. Okay. That feels like somewhere real.\"","best":true},{"text":"\"I'm sure you'll figure it out eventually, somehow.\"","then":"She sighs. \"That's what I'm afraid of.\""},{"text":"\"Just search it online sometime.\"","then":"She nods tiredly. \"There's so much out there. Where, though?\""},{"text":"\"Ask around the family. Someone always knows someone.\"","then":"She hesitates. \"And have everyone discussing it at every function?\""}],"why":"A clinician and official adoption information are real starts. Many Ways to Family covers the rest."},{"prompt":"A relative later says: \"Real family is only blood, you know.\"","options":[{"text":"\"A family is whole in many forms, this included.\"","then":"The relative opens her mouth, then closes it. \"Well. If they're happy.\"","best":true},{"text":"\"Maybe, but they don't have much choice left now.\"","then":"The relative nods. \"Poor things. Second best, then.\""},{"text":"\"That's a cruel thing to say about them.\"","then":"The relative bristles. \"Cruel? I'm only being honest!\""},{"text":"\"I'd rather not get into this today.\"","then":"The relative shrugs. \"Someone should tell them, then.\""}],"why":"Naming that family is whole in many forms answers the old idea directly, on their behalf."},{"prompt":"Months later, she says: \"We've actually started the adoption process.\"","options":[{"text":"\"That's real and worth celebrating, however it unfolds.\"","then":"She beams. \"Thank you. You're the first to say it like that.\"","best":true},{"text":"\"I hope it works out like the other way would have.\"","then":"Her smile falters. \"It's not a copy of the other way.\""},{"text":"\"Good for you, I suppose.\"","then":"She hesitates. \"You don't sound very happy for us.\""},{"text":"\"Finally, that took a while.\"","then":"Her face tightens. \"It took what it took.\""}],"why":"Naming it as real and worth celebrating meets her news without measuring it against what didn't happen."}],"relearn":"Naming adoption and other paths as real, via Many Ways to Family, keeps a hard road from feeling like the end of family."},
  {"id":"iw-1402","cat":"tools-and-help","type":"role-play","persona":"Karthik","source":"learn together","hook":"Neither of you really knows the fertility basics yet.","setup":"It's Sunday morning, and she's making a list of questions.","steps":[{"prompt":"She says: \"I'll read up on this and brief you later.\"","options":[{"text":"\"Let's learn it together. It's a both-of-us thing.\"","then":"She pauses, then pulls up a chair next to you instead.","best":true},{"text":"\"Sounds good. Let me know what matters.\"","then":"She hesitates. \"Actually, could you just read it with me?\""},{"text":"\"Honestly, I don't think I need to know all that.\"","then":"She frowns. \"It's your fertility too. Sit with me?\""},{"text":"\"Okay. I trust you to figure it out.\"","then":"She sighs. \"I'd rather not carry this alone. Read with me?\""}],"why":"Learning together turns her solo homework into something you're actually building side by side."},{"prompt":"Reading together, she asks: \"Did you already know any of this?\"","options":[{"text":"\"Honestly, not much. I'm learning too.\"","then":"She relaxes, glad you're both starting from the same place.","best":true},{"text":"\"A bit. I picked things up here and there.\"","then":"She raises an eyebrow. \"Then explain this part to me?\""},{"text":"\"Not really. Isn't this more your area, though?\"","then":"She sets the phone down. \"Why would it be my area?\""},{"text":"\"Enough to get by, I think.\"","then":"She squints. \"Enough for what?\""}],"why":"Admitting you're learning too, honestly, makes the shared reading genuinely equal."},{"prompt":"A friend later asks: \"So, do you actually know the fertility basics now?\"","options":[{"text":"\"Yes, we learned them together, not just her.\"","then":"Your friend laughs. \"Look at you. I should do that with mine.\"","best":true},{"text":"\"She knows more than me, honestly.\"","then":"Your friend nods. \"Figures. They always do the reading.\""},{"text":"\"Enough, I guess. She handled most of it.\"","then":"Your friend grins. \"Same in our house. Wives handle that stuff.\""},{"text":"\"I couldn't really say. I wasn't paying attention.\"","then":"Your friend shrugs. \"Fair. It's mostly her thing anyway.\""}],"why":"Naming that you learned it together, plainly, makes the shared effort actually visible."}],"relearn":"Suggesting you both learn the basics, not leave it to her, makes fertility a shared, calm thing you face as a team."},
  {"id":"iw-1403","cat":"tools-and-help","type":"role-play","persona":"Pooja","source":"reflect together","hook":"The children question has been sitting between you both, unaddressed.","setup":"You invite them into a real conversation.","steps":[{"prompt":"They ask: \"Where do we even start with something this big?\"","options":[{"text":"\"Let's weigh what we both want, our readiness, the facts.\"","then":"They nod, relieved there's an actual way to begin.","best":true},{"text":"\"Let's just see what feels right in the moment, honestly.\"","then":"They shrug. \"Okay. But when is the moment?\""},{"text":"\"Maybe ask our parents what they did.\"","then":"They shake their head. \"Our parents' answers won't fit us, though.\""},{"text":"\"I don't know. You tell me.\"","then":"They sigh. \"I don't want to decide this alone.\""}],"why":"Naming wishes, readiness and facts together gives you an actual, shared way to start."},{"prompt":"They ask: \"What if we want different things?\"","options":[{"text":"\"Then we keep talking, honestly, until we find our answer.\"","then":"They relax, hearing that disagreement isn't a dead end here.","best":true},{"text":"\"Then I guess we do what I want.\"","then":"They stare at you. \"You'd just decide, and that's it?\""},{"text":"\"Let's just avoid finding out, for now.\"","then":"They look uneasy. \"So we don't talk about it? For how long?\""},{"text":"\"We'll figure it out eventually. I'm sure it'll work out.\"","then":"They nod, but their shoulders stay tight. \"I hope so. That's what I keep worrying about.\""}],"why":"Committing to keep talking honestly answers the fear of difference without deciding for either of you."},{"prompt":"Midway, they ask: \"Are we allowed to just not be sure yet?\"","options":[{"text":"\"Of course, readiness is honest, not a test to pass.\"","then":"They exhale, relieved uncertainty isn't a failing grade.","best":true},{"text":"\"We should probably have a clear answer by now, right?\"","then":"They shift. \"Then maybe I should pretend I'm sure.\""},{"text":"\"I guess we'll pick something eventually.\"","then":"They frown. \"Pick? It doesn't feel like picking a colour.\""},{"text":"\"Not really. People expect us to know.\"","then":"They look down. \"So we should just say we're sure?\""}],"why":"Naming readiness as honest reflection, not a test, makes room for a genuine not yet."},{"prompt":"A relative later asks: \"So, have you two actually landed on something?\"","options":[{"text":"\"We're weighing it honestly, together, no rush.\"","then":"The relative nods, and the pressure doesn't quite land this time.","best":true},{"text":"\"Not yet. Everyone keeps asking though.\"","then":"The relative sighs. \"We ask because we care.\""},{"text":"\"We'll announce it when it's official.\"","then":"The relative raises an eyebrow. \"Official? So something is decided?\""},{"text":"\"Honestly, we're a bit sick of the question.\"","then":"The relative stiffens. \"I was only asking.\""}],"why":"Naming it as an honest, shared, unhurried weighing keeps the answer calm and genuinely yours."}],"relearn":"Inviting your partner to weigh it together, wishes, readiness, facts, keeps the decision shared and pressure-free."},
  {"id":"iw-1404","cat":"tools-and-help","type":"role-play","persona":"any","source":"reassure no shame","hook":"Someone close to you has been struggling quietly with trouble conceiving.","setup":"You're sitting together after dinner, and they finally speak up.","steps":[{"prompt":"They say: \"I could never actually tell a doctor about this.\"","options":[{"text":"\"It's common and no one's fault. Asking is allowed.\"","then":"They exhale, like the shame has loosened just slightly.","best":true},{"text":"\"You really should, before it quietly gets worse.\"","then":"They stiffen. \"Worse? Now I'm even more afraid to go.\""},{"text":"\"I understand. It's a private thing.\"","then":"They nod. \"Yes. Private. That's why I can't ever say it.\""},{"text":"\"It's not that big a deal, honestly.\"","then":"They look away. \"Then why does it feel so big to me?\""}],"why":"Naming it as common and no one's fault answers the shame directly, not just the privacy."},{"prompt":"They ask: \"But what if the doctor judges me for it?\"","options":[{"text":"\"A good clinician won't judge. If one does, see another.\"","then":"They look a little steadier. \"Another one. I hadn't thought I could.\"","best":true},{"text":"\"I'm sure they've heard worse, honestly.\"","then":"They give a tight smile. \"Maybe. But I'm still the one sitting there.\""},{"text":"\"Ask a relative who's a doctor. At least he knows you.\"","then":"They shake their head. \"A relative? He's the last person I'd tell.\""},{"text":"\"You could always just not tell them everything, right?\"","then":"They pause. \"Then how will they know what to check?\""}],"why":"A good clinician won't judge, and you can see another if one does. That answers the exact fear."},{"prompt":"They say: \"Everyone I know already has kids, easily.\"","options":[{"text":"\"That's not the full picture. It's more common than it looks.\"","then":"They seem surprised, like they'd never heard that plainly before.","best":true},{"text":"\"Yeah, it can feel that way sometimes.\"","then":"They nod slowly. \"Everyone. It's just me, isn't it?\""},{"text":"\"Try not to compare yourself to others.\"","then":"They shrug. \"I know I shouldn't. I still do.\""},{"text":"\"I'm sure it'll happen for you as well, eventually, somehow.\"","then":"They smile faintly. \"You can't know that. Nobody can.\""}],"why":"Naming that infertility is more common than it looks answers the isolation with a real fact."},{"prompt":"They ask: \"Do you think less of me for struggling with this?\"","options":[{"text":"\"Not at all, and I'm glad you trusted me with it.\"","then":"They finally look you in the eye, something in them settling.","best":true},{"text":"\"Of course not. Why would you even ask?\"","then":"They lower their eyes. \"I asked because I needed to hear it.\""},{"text":"\"No, but maybe don't tell too many people about it.\"","then":"They nod. \"Right. So it is something to hide.\""},{"text":"\"I'm sure it's not even that serious.\"","then":"They look at their hands. \"It feels serious to me.\""}],"why":"Naming that nothing changes, and that you're glad they told you, meets the fear plainly."},{"prompt":"Weeks later they say: \"I finally booked an appointment.\"","options":[{"text":"\"That's a real, brave step, and I'm proud of you.\"","then":"They smile, the shame a little smaller than it was.","best":true},{"text":"\"Good, it was about time.\"","then":"Their smile fades. \"About time. Yes. I know I was slow.\""},{"text":"\"See, that wasn't so hard, was it?\"","then":"They shake their head. \"It was. I nearly cancelled twice.\""},{"text":"\"Let me know everything they say.\"","then":"They hesitate. \"Some of it I might want to keep to myself first.\""}],"why":"Naming the step as real and something to be proud of honours how hard it actually was."}],"relearn":"Reminding someone infertility is common and no one's fault keeps shame from stopping them reaching for real help."},
  {"id":"iw-1080","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"A one-year gap shows you're a serious family.\"","myth":{"un":"A one-year gap between children shows you're a serious family.","re":"The gap between children is yours to set on your health and recovery, not a badge to earn.","why":"Spacing is a health and life choice, not a status test."},"relearn":"The gap between children is yours to set on your health and recovery, not a badge to earn.","persona":"Pooja","source":"gap not a badge"},
  {"id":"iw-1081","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"Once you've started, you can't change your timing plan.\"","myth":{"un":"Once you've decided your timing, you can't change it.","re":"Timing can be revisited; choosing 'not yet' now doesn't lock you out of 'yes' later.","why":"Life changes, and so can your plan."},"relearn":"Timing can be revisited; 'not yet' now doesn't lock you out of 'yes' later.","persona":"any","source":"revisit timing"},
  {"id":"iw-1082","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"Two children is the proper number; one is incomplete.\"","myth":{"un":"Two children is the proper number; one is incomplete.","re":"One, several, or none is each a valid number; no quota is owed to anyone.","why":"How many is open and yours to choose."},"relearn":"One, several, or none is each a valid number of children; no quota is owed to anyone.","persona":"any","source":"how many is open"},
  {"id":"iw-1083","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"Wait too long after the first and the second 'won't feel right'.\"","myth":{"un":"Wait too long after the first and the second won't feel right.","re":"There's no universal correct gap; the right spacing is the one that fits your health and life.","why":"No clock sets the gap but yours."},"relearn":"There's no universal correct gap between children; the right spacing fits your health and life.","persona":"Pooja","source":"no correct gap"},
  {"id":"iw-1084","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"The mother-in-law decides when the next baby comes.\"","myth":{"un":"The mother-in-law decides when the next baby comes.","re":"When you have children is the couple's own decision, not a relative's to set.","why":"It's your life and your body, so it's your call."},"relearn":"When you have children is the couple's own decision, not a relative's to set.","persona":"Pooja","source":"couple's call"},
  {"id":"iw-1085","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"Settle the job and house first, or you're being irresponsible.\"","myth":{"un":"You must settle the job and house perfectly first, or you're irresponsible.","re":"Readiness is honest reflection on what matters to you, not waiting for everything to be perfect.","why":"Perfect timing never quite arrives."},"relearn":"Readiness is honest reflection on what matters to you, not waiting for everything to be perfect.","persona":"any","source":"readiness not perfect"},
  {"id":"iw-1086","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"A short gap is risky, so rush the next one before you're old.\"","myth":{"un":"A short gap is risky, so rush the next one before you're 'old'.","re":"Spacing for recovery is a calm health choice; rushing out of fear isn't planning.","why":"Recovery time is for you, not a race."},"relearn":"Spacing for recovery is a calm health choice; rushing out of fear isn't planning.","persona":"Pooja","source":"recovery not race"},
  {"id":"iw-1087","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"You owe the family a grandchild within the first year.\"","myth":{"un":"You owe the family a grandchild within the first year.","re":"No timeline is owed to anyone; when to have children is yours to set, together.","why":"A wish from relatives isn't a debt you carry."},"relearn":"No timeline is owed to anyone; when to have children is yours to set, together.","persona":"Pooja","source":"no timeline owed"},
  {"id":"iw-1088","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"Plan the birth month around the 'lucky' season.\"","myth":{"un":"You must plan the birth month around a 'lucky' season.","re":"Timing is yours to weigh on your readiness and health, not on an imposed auspicious date.","why":"Your plan answers to you, not a calendar."},"relearn":"Timing is yours to weigh on your readiness and health, not on an imposed auspicious date.","persona":"any","source":"not the calendar"},
  {"id":"iw-1089","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"Your cousin had two by now, so you're falling behind.\"","myth":{"un":"Your cousin had two by now, so you're falling behind.","re":"There's no race; your timeline is yours, set from your readiness, not someone else's count.","why":"Comparison isn't a reason to have a child."},"relearn":"There's no race; your timeline is set from your own readiness, not someone else's count.","persona":"Sneha","source":"no race"},
  {"id":"iw-1090","cat":"when-and-spacing","type":"strike-rewrite","hook":"\"Change your mind about waiting and you've wasted years.\"","myth":{"un":"If you change your mind about waiting, you've wasted years.","re":"Revisiting your timing isn't a waste; a decision you made well at the time was right then.","why":"You're allowed to update a choice as life shifts."},"relearn":"Revisiting your timing isn't a waste; you can update a choice as life shifts.","persona":"any","source":"not wasted"},
  {"id":"iw-1091","cat":"when-and-spacing","type":"sort","hook":"Sort: a sound reason to time or space children, or someone else's agenda?","items":[{"id":"a","text":"Your own readiness and stability"},{"id":"b","text":"Health and recovery between pregnancies"},{"id":"c","text":"Both partners feeling ready together"},{"id":"d","text":"An aunt's 'auspicious year' deadline"},{"id":"e","text":"Matching a cousin's number of kids"},{"id":"f","text":"Quieting the 'good news?' chorus"}],"bins":[{"id":"sound","label":"Sound reason","valence":"pos"},{"id":"agenda","label":"Someone else's agenda","valence":"neg"}],"key":{"a":"sound","b":"sound","c":"sound","d":"agenda","e":"agenda","f":"agenda"},"relearn":"Your readiness, health and shared agreement are sound reasons; deadlines, comparison and the 'good news' chorus are someone else's agenda.","persona":"any","source":"sound vs agenda"},
  {"id":"iw-1092","cat":"when-and-spacing","type":"sort","hook":"Sort: does this belong in an honest 'are we ready' check, or not?","items":[{"id":"a","text":"Your relationship feeling steady"},{"id":"b","text":"Your health and recovery"},{"id":"c","text":"What you both actually want"},{"id":"d","text":"Whether the neighbours approve"},{"id":"e","text":"Beating a friend's baby news"},{"id":"f","text":"Pleasing the relatives this Diwali"}],"bins":[{"id":"in","label":"Belongs in the check","valence":"pos"},{"id":"out","label":"Doesn't belong","valence":"neg"}],"key":{"a":"in","b":"in","c":"in","d":"out","e":"out","f":"out"},"relearn":"A readiness check is your relationship, health and shared wishes; approval, rivalry and pleasing relatives don't belong in it.","persona":"any","source":"real readiness check"},
  {"id":"iw-1093","cat":"when-and-spacing","type":"sort","hook":"Sort: calm planning around timing, or anxiety dressed as a deadline?","items":[{"id":"a","text":"Talking the timing through together"},{"id":"b","text":"Checking recovery needs with a clinician"},{"id":"c","text":"Naming what readiness means to you"},{"id":"d","text":"A relative's 'hurry, you're not young' line"},{"id":"e","text":"Rushing so people stop asking"},{"id":"f","text":"Setting a panic deadline from a scary post"}],"bins":[{"id":"plan","label":"Calm planning","valence":"pos"},{"id":"panic","label":"Anxiety as deadline","valence":"neg"}],"key":{"a":"plan","b":"plan","c":"plan","d":"panic","e":"panic","f":"panic"},"relearn":"Talking it through, checking recovery and naming readiness are calm planning; 'hurry' lines, rushing and panic deadlines are anxiety, not planning.","persona":"any","source":"plan vs panic"},
  {"id":"iw-1094","cat":"when-and-spacing","type":"sort","hook":"Sort: who really gets a say in your timing and number?","items":[{"id":"a","text":"You"},{"id":"b","text":"Your partner"},{"id":"c","text":"A clinician on health and recovery"},{"id":"d","text":"The relatives who keep asking"},{"id":"e","text":"Friends comparing family sizes"},{"id":"f","text":"Neighbours with opinions"}],"bins":[{"id":"say","label":"Has a say","valence":"pos"},{"id":"nosay","label":"No say","valence":"neg"}],"key":{"a":"say","b":"say","c":"say","d":"nosay","e":"nosay","f":"nosay"},"relearn":"You, your partner and a clinician on health have a say; relatives, comparing friends and neighbours don't.","persona":"any","source":"whose say"},
  {"id":"iw-1095","cat":"when-and-spacing","type":"sort","hook":"Sort: a fair reason to revisit your timing, or a pressure to refuse?","items":[{"id":"a","text":"Your health changed"},{"id":"b","text":"You both feel differently now"},{"id":"c","text":"Your circumstances are steadier"},{"id":"d","text":"An aunt shamed you at a wedding"},{"id":"e","text":"A 'clock is ticking' scare post"},{"id":"f","text":"Everyone else is doing it"}],"bins":[{"id":"fair","label":"Fair reason to revisit","valence":"pos"},{"id":"pressure","label":"Pressure to refuse","valence":"neg"}],"key":{"a":"fair","b":"fair","c":"fair","d":"pressure","e":"pressure","f":"pressure"},"relearn":"Your changed health, shared feelings and steadier life are fair reasons to revisit; shaming, scare posts and 'everyone else' are pressure.","persona":"any","source":"revisit vs pressure"},
  {"id":"iw-1096","cat":"when-and-spacing","type":"branch","persona":"Pooja","source":"dinner-table line","hook":"Your mother-in-law announces it's 'time for the next baby' at dinner.","steps":[{"prompt":"She says it again, looking at you and your husband. What do you say?","options":[{"text":"Say kindly that timing is yours and his to decide","then":"She pauses, then changes the subject, though not entirely convinced.","best":true},{"text":"Agree out loud just to end the awkward moment quickly","then":"She smiles, satisfied, and mentions it again at the next dinner."},{"text":"Look at your husband, hoping he'll answer for you instead","then":"He stays quiet, and the question lands back on you."},{"text":"Say you're 'thinking about it', mostly to buy some time","then":"She takes it as a promise and starts planning names."}],"why":"A warm, firm line holds your timing without starting a family fight."},{"prompt":"Later, she brings it up privately, saying she just wants to help. What do you do?","options":[{"text":"Thank her, and say it's your and your husband's call","then":"She softens a little. 'I only want what's best,' she says.","best":true},{"text":"Explain your reasons in careful detail to justify the wait","then":"She listens, but treats it as an opening to keep asking."},{"text":"Say nothing at all and hope she just drops it","then":"She takes the silence as room to bring it up again soon."},{"text":"Tell her it's really her son's decision, not yours to make","then":"She turns to your husband instead, and the pressure just shifts."}],"why":"Thanking her while naming the boundary keeps it caring and clear."},{"prompt":"At the next gathering, a relative asks if there's 'good news' yet. What do you do?","options":[{"text":"Give a light, firm 'we'll share news if and when there's some'","then":"The relative nods and moves on to another topic.","best":true},{"text":"Laugh it off with a vague 'maybe soon'","then":"Word spreads that a baby might be coming soon."},{"text":"Explain that you're waiting for the right time","then":"The relative offers unsolicited advice on what 'right' means."},{"text":"Avoid the gathering next time to dodge the question","then":"The question just waits for you at the one after."}],"why":"A light line that needs no answer closes the question calmly."}],"debrief":"When and how many is the couple's decision; a warm, firm line holds it without a family fight.","relearn":"When and how many is the couple's call; a warm boundary holds it."},
  {"id":"iw-1097","cat":"when-and-spacing","type":"branch","persona":"Pooja","source":"space for recovery","hook":"You'd like to space the next pregnancy for recovery; relatives push for it now.","steps":[{"prompt":"A relative says you shouldn't 'waste time' between children. What do you say?","options":[{"text":"Say you're planning the gap around your own recovery and health","then":"She looks unconvinced, but doesn't push further right now.","best":true},{"text":"Agree that you probably should hurry things along a little","then":"You feel a flicker of doubt about a plan that was working for you."},{"text":"Explain you're 'just tired' without ever mentioning recovery","then":"She suggests you'll feel better once you're pregnant again."},{"text":"Say your doctor simply told you to wait a while","then":"She asks which doctor, as if to find a different opinion."}],"why":"Naming recovery as your own reason keeps the plan about your health."},{"prompt":"Your partner asks how you actually feel about the timing. What do you tell him?","options":[{"text":"That you want the gap for recovery, with a clinician's input","then":"He agrees, and you book an appointment to ask together.","best":true},{"text":"That you're fine either way, whatever he actually prefers","then":"He isn't sure what you actually want, and suggests you both ask a clinician instead of guessing."},{"text":"That the relatives are just being difficult about it","then":"He agrees they're a lot, and suggests getting a clinician's take to settle it for yourselves."},{"text":"That you'll decide once the pressure finally dies down","then":"He worries that could take forever, and suggests asking a clinician sooner instead."}],"why":"Naming that you want the gap for recovery, and checking together, answers his question honestly."},{"prompt":"At the clinic, the doctor asks what's driving your timeline. What do you say?","options":[{"text":"That you want to plan the gap around your own health and recovery","then":"She lays out what recovery typically needs, so you can plan calmly.","best":true},{"text":"That relatives want a second one soon","then":"She notes it, but gently asks what you and your partner actually want."},{"text":"That you're not sure, and ask her to just decide","then":"She offers guidance, but says the choice is still yours to make."},{"text":"That you'd rather discuss it after you're home","then":"She wraps the visit up quickly, and the real conversation waits for later."}],"why":"Leading with your own health gets you real guidance, not just reassurance."}],"debrief":"Spacing for health and recovery is a legitimate, your-own choice, not the relatives' to override.","relearn":"Space pregnancies on your health and recovery, not on relatives' pressure."},
  {"id":"iw-1098","cat":"when-and-spacing","type":"branch","persona":"Karthik","source":"decide together","hook":"You and your partner disagree: she wants to start trying now, while you'd like to wait a year.","steps":[{"prompt":"Over dinner, she brings it up again, hoping to settle it tonight. What do you do?","options":[{"text":"Say you want to talk it through until you both agree","then":"She relaxes a little. 'Okay, let's actually talk,' she says.","best":true},{"text":"Say you'll just go along with whatever she wants","then":"She hesitates. 'I don't want it to only be my decision,' she says."},{"text":"Change the subject, hoping it settles itself","then":"The topic comes back up a few days later, still unresolved."},{"text":"Say couples always figure this out eventually anyway","then":"She looks unconvinced that vague reassurance answers her tonight."}],"why":"Talking it through until you agree makes the plan one you both own."},{"prompt":"She asks what's actually behind your wanting to wait a year. What do you say?","options":[{"text":"Your honest reasons, so she understands where you're coming from","then":"She listens, and the plan starts to feel like it's for both of you.","best":true},{"text":"That you're honestly not sure, just that it feels too soon somehow","then":"She's left guessing what would actually change your mind."},{"text":"That work has just been too busy right now for it","then":"She wonders if work will ever feel less busy than now."},{"text":"That you'd honestly rather not get into it right now","then":"She feels shut out of a decision that affects her too."}],"why":"Sharing your real reasons lets her weigh in instead of just guessing."},{"prompt":"Her friend mentions, in front of you both, that she and her partner agreed on timing right away, unlike you two. What do you do?","options":[{"text":"Remind your partner your plan doesn't need to match anyone else's","then":"She nods, relieved the comparison doesn't need an answer.","best":true},{"text":"Agree that maybe you should move faster","then":"The comparison starts quietly driving a decision that isn't ready."},{"text":"Say nothing, and let the comment sit","then":"The unspoken comparison lingers into the next conversation."},{"text":"Point out other couples who waited even longer","then":"You're now measuring your timeline against other people's instead."}],"why":"Naming that your plan doesn't need to match anyone else's protects it."}],"debrief":"There's no universal right time, only the time that's right for you, decided together.","relearn":"Decide timing together, not by whoever pushes hardest."},
  {"id":"iw-1099","cat":"when-and-spacing","type":"branch","persona":"any","source":"revisit yes","hook":"You chose 'not yet' last year; now your life is steadier and you're reconsidering.","steps":[{"prompt":"Your partner asks if anything's changed since last year. What do you say?","options":[{"text":"That you'd like to revisit the question honestly, together","then":"You both take a breath, and start the conversation fresh.","best":true},{"text":"That nothing's really changed at all, just out of old habit","then":"The old answer stays in place, even though it doesn't fit anymore."},{"text":"That you're not really sure, so let's not talk about it now","then":"The question sits unspoken between you a while longer."},{"text":"That you've decided to start, so no need to talk","then":"Your partner feels a shared decision was made without them."}],"why":"Revisiting the question honestly, together, makes 'not yet' a real, owned update."},{"prompt":"A friend, catching up, asks how you two are thinking about starting a family these days. What do you focus on?","options":[{"text":"What's actually different in your life now","then":"Naming it out loud, you realise it really has shifted.","best":true},{"text":"That you feel like you should have decided by now","then":"You start deciding from pressure instead of your actual life."},{"text":"That everyone else your age already has kids","then":"The comparison creeps back into a decision that was yours."},{"text":"That your parents would be thrilled by the news","then":"Their happiness starts to weigh on a choice that is yours to make."}],"why":"Naming what's actually different keeps the choice about your life, not the calendar."},{"prompt":"Your partner asks how you'd like to move forward from here. What do you say?","options":[{"text":"Go slowly, checking in with each other along the way","then":"You agree on a pace that feels honest, not rushed.","best":true},{"text":"Jump straight in, without another proper talk","then":"You move fast, and wonder later if you skipped the real talk."},{"text":"Say you'll talk 'someday' and leave it there","then":"The wait quietly stretches on, with neither of you circling back to it."},{"text":"Let your partner decide the pace","then":"Your partner isn't sure they should be the one deciding this alone."}],"why":"Moving slowly and checking in keeps the new answer honestly shared."}],"debrief":"Timing decisions can be revisited; choosing 'not yet' doesn't lock you out of 'yes' later.","relearn":"You can revisit timing; 'not yet' isn't permanent."},
  {"id":"iw-1100","cat":"when-and-spacing","type":"branch","persona":"Sneha","source":"not the feed","hook":"Friends keep posting baby news and you feel a pull to 'catch up', though you're not ready.","steps":[{"prompt":"You open the app and see another baby announcement. What do you do first?","options":[{"text":"Close the app and check in with how you actually feel","then":"You notice the pull fades once you stop scrolling.","best":true},{"text":"Like the post and scroll for more, feeling worse each time","then":"The feed keeps handing you more to compare yourself to."},{"text":"Message the friend asking how she 'knew she was ready'","then":"Her answer is honest, but it was never really about you."},{"text":"Screenshot it to send a friend later, unsure why","then":"You're not even sure what you want her to say about it."}],"why":"Stepping back from the feed lets you check your own readiness, not the comparison."},{"prompt":"At brunch, a friend mentions she's 'basically the last one left' without kids. What do you say?","options":[{"text":"That you're not racing anyone, and that's fine","then":"She looks relieved to hear someone else say it out loud.","best":true},{"text":"That you feel the same pressure she does","then":"You both spiral a little, feeding each other's worry."},{"text":"Nothing, and quietly agree in your head","then":"The comparison sits with you both for the rest of brunch."},{"text":"That she should just decide already","then":"She feels judged, when she was only being honest."}],"why":"Saying you're not racing anyone names the pressure without joining it."},{"prompt":"Your sister notices you've been quiet after scrolling lately. What do you tell her?","options":[{"text":"That the feed makes you compare instead of check in with yourself","then":"She suggests you mute a few accounts for a while.","best":true},{"text":"That you think you might be falling behind","then":"She isn't sure how to answer a worry that isn't really about your life."},{"text":"That it's nothing, really","then":"The quiet mood keeps returning after every scroll."},{"text":"That maybe you should just decide to have kids and catch up","then":"She asks gently whether that's what you actually want."}],"why":"Naming the feed as the real problem, not your life, points to an actual fix."},{"prompt":"A cousin asks, at a family event, if you're 'planning to catch up soon'. What do you say?","options":[{"text":"That you're on your own timeline, and it's not a race","then":"She nods, and the question doesn't come up again tonight.","best":true},{"text":"That you're thinking about it, to end the conversation","then":"She mentions it to two more relatives before the night's over."},{"text":"That everyone seems to be having kids these days","then":"The comment quietly adds to the pressure you're trying to shed."},{"text":"That you'll let her know when there's news","then":"She beams, sure now that news is coming, and asks again next time."}],"why":"A calm 'not a race' line closes the question without inviting more pressure."}],"debrief":"There's no race; your timeline is yours, set from readiness, not from keeping pace.","relearn":"Comparison isn't a reason to have a child now."},
  {"id":"iw-1101","cat":"when-and-spacing","type":"branch","persona":"any","source":"one is valid","hook":"You want one child; relatives insist you 'must' have more for the family.","steps":[{"prompt":"At a family dinner, someone says one child 'isn't enough'. What do you say?","options":[{"text":"Say one is the number that's right for your family","then":"The table quiets, and no one presses further tonight.","best":true},{"text":"Say you'll 'think about' a second one","then":"They take it as an opening and bring it up again soon."},{"text":"Laugh it off without really answering","then":"The comment gets repeated at the next family gathering too."},{"text":"List all the practical reasons for stopping at one","then":"They counter each reason, as if the number were up for debate."}],"why":"Naming one as the right number for your family holds it without a fight."},{"prompt":"A few weeks later, a relative says your child will be 'lonely' without a sibling. What do you focus on?","options":[{"text":"That your family is complete as it is","then":"You say it plainly, and it feels true saying it out loud.","best":true},{"text":"Whether that worry might actually be true","then":"A choice that felt settled starts to feel shaky again."},{"text":"Explaining all the ways your child socialises already","then":"You find yourself explaining more than you meant to."},{"text":"Agreeing it's a fair point, just to move on","then":"The comment sits with you longer than you expected."}],"why":"Saying the family is complete keeps the choice free of doubt."},{"prompt":"Your partner asks if the pressure is getting to you. What do you say?","options":[{"text":"Say honestly how it feels, and ask for backup","then":"He nods. 'Let's hold the line together,' he says.","best":true},{"text":"That maybe you should reconsider, just to keep the peace","then":"A decision you were sure of starts to wobble under pressure."},{"text":"That you're fine, brushing off the question","then":"The pressure keeps quietly wearing at you underneath."},{"text":"Ask him to talk to the relatives so you don't have to","then":"He does, but they turn back to you at the next dinner."}],"why":"Saying honestly how it feels, and asking for backup, invites real support, not just reassurance."},{"prompt":"At the next gathering, someone brings up 'planning for a second' again. What do you do?","options":[{"text":"Say plainly that one is your family's own choice to make","then":"The relative shrugs and finally lets it go.","best":true},{"text":"Give a vague 'maybe someday' to end it quickly","then":"The relative treats it as a real possibility and revisits it."},{"text":"Get visibly frustrated at having to answer again","then":"The room feels tense, and the real point gets lost."},{"text":"Ask your partner to answer for you this time","then":"He handles it kindly, but the question just returns to you later."}],"why":"A calm, steady answer needs no further defending."}],"debrief":"One, several or none is each valid; no quota is owed to anyone.","relearn":"How many children is yours; one is a complete, valid choice."},
  {"id":"iw-1102","cat":"when-and-spacing","type":"branch","persona":"any","source":"not auspicious date","hook":"Family talk keeps circling back to picking an 'auspicious year' to have a child.","steps":[{"prompt":"A relative shows you a chart of 'good years' to have a baby. What do you do?","options":[{"text":"Thank them, and say you're going by your own readiness and health","then":"They look a little disappointed, but don't push further right now.","best":true},{"text":"Say you'll 'keep it in mind', mostly just to be polite about it","then":"They start planning around the chart as if you'd agreed to it."},{"text":"Point out that the chart doesn't actually mean anything real","then":"They get defensive, and the conversation turns into an argument."},{"text":"Ask your partner what he honestly thinks of the whole chart","then":"He's unsure why the chart is part of the decision at all."}],"why":"Naming readiness and health as your standard holds the timing without a clash."},{"prompt":"A little later, they mention the 'good year' is ending soon, and time is short. What do you focus on?","options":[{"text":"That your own timeline doesn't run on their calendar","then":"Saying it plainly, you feel steadier than you expected.","best":true},{"text":"Whether you might be missing something by ignoring it","then":"A decision that felt clear starts to feel uncertain."},{"text":"Explaining why the year doesn't work for you logistically","then":"They suggest ways to 'make it work' anyway."},{"text":"Letting the deadline sit in the back of your mind","then":"It quietly nags at you every time the topic returns."}],"why":"Saying plainly that your timeline isn't set by a chart keeps the choice steady."},{"prompt":"Your partner asks if the chart talk is bothering you. What do you say?","options":[{"text":"That it doesn't change your plan, but it's tiring to keep hearing","then":"He agrees to help field it together from now on.","best":true},{"text":"That maybe there's something to it","then":"A plan you were both settled on starts to wobble."},{"text":"That it's fine, brushing the question off","then":"The tiredness stays, unspoken, and builds up quietly."},{"text":"That you wish your family would just drop it","then":"He agrees, though nothing about how to respond has changed."}],"why":"Naming the tiredness while holding the plan keeps you both aligned and honest."},{"prompt":"At the next function, the relative asks if you've 'reconsidered the timing'. What do you do?","options":[{"text":"Say your readiness and health are still the deciding factor","then":"The relative sighs, but changes the subject.","best":true},{"text":"Say you'll 'try to align' with it if you can","then":"The relative treats that as a soft yes, and expects updates."},{"text":"Avoid the relative for the rest of the evening","then":"The chart comes back up the next time you're in the same room."},{"text":"Explain the whole decision again from the start","then":"They nod, but the explaining hasn't actually closed the topic."}],"why":"A short, clear repeat closes the topic better than another full explanation."}],"debrief":"Timing is yours to weigh on readiness and health, not an imposed auspicious date.","relearn":"An imposed 'auspicious year' doesn't set your timing; you do."},
  {"id":"iw-1103","cat":"when-and-spacing","type":"branch","persona":"any","source":"wedding aunties","hook":"You're at a wedding, and everyone seems to have the same question tonight.","steps":[{"prompt":"The first aunty leans in and asks when the good news is coming. What do you say?","options":[{"text":"Say lightly that you'll decide if and when, and thank her for the love","then":"She smiles, satisfied for now, and lingers to chat about the wedding.","best":true},{"text":"Say 'soon' to get past the moment quickly","then":"She looks pleased, and mentions it to the aunty beside her."},{"text":"Explain in detail why you're not ready yet","then":"She listens, but treats your reasons as things to be talked out of."},{"text":"Say nothing and change the subject","then":"She repeats the question, thinking you didn't hear her."}],"why":"A light, firm line needs no explaining, and works for any aunty who asks."},{"prompt":"A second aunty, having overheard, asks the same thing moments later. What do you do?","options":[{"text":"Say lightly that you'll decide if and when","then":"She nods, easily satisfied by the calm answer.","best":true},{"text":"Come up with an excuse on the spot","then":"Word of your excuse starts going around the hall."},{"text":"Sigh and say you're tired of the question","then":"She stiffens, and a few aunties nearby turn to look."},{"text":"Point to the first aunty and say she already asked","then":"The two aunties compare notes, and the pressure doubles."}],"why":"A calm answer, however many times it's asked, keeps the boundary easy to hold."},{"prompt":"A third aunty drifts over and asks the same question. What do you say?","options":[{"text":"Smile and say the timing is yours and your partner's to decide","then":"She nods and drifts back into wedding talk.","best":true},{"text":"Laugh nervously and say maybe next year","then":"She takes \"next year\" as good as confirmed."},{"text":"Promise to tell her first when there's news","then":"She beams and says she'll be waiting to hear it from you first."},{"text":"Walk away without answering","then":"She goes on discussing it with the others after you leave."}],"why":"Naming the timing as yours and your partner's closes it without a scene."},{"prompt":"Later, your partner asks how the aunty conversation went. What do you tell him?","options":[{"text":"That it was tiring, but no one is owed a timeline","then":"He nods. \"Then we'll answer them together next time,\" he says.","best":true},{"text":"That it was exhausting, and next time you'll just say 'soon'","then":"He nods, but wonders if 'soon' will start to sound like a promise."},{"text":"That you're worried they'll think something's wrong","then":"He reassures you, though the worry doesn't fully settle."},{"text":"That you gave them whatever answer ended it fastest","then":"He wonders which answers are now making the rounds."}],"why":"Naming that no one is owed a timeline, however tiring tonight was, keeps the boundary yours."},{"prompt":"At the next family wedding, an aunty who wasn't there before asks the same thing. What do you do?","options":[{"text":"Say lightly that you'll decide if and when","then":"She nods and the conversation moves on easily.","best":true},{"text":"Get frustrated that the question follows you everywhere","then":"The frustration shows, and she looks surprised by it."},{"text":"Make up a firm date to finally satisfy everyone","then":"The made-up date becomes something people now expect."},{"text":"Avoid the topic by leaving the conversation early","then":"The question just waits for you at the next family event."}],"why":"The same light answer still works, without leaning on how earlier ones went."}],"debrief":"No answer is owed to the 'good news' chorus; a calm boundary holds without a fight.","relearn":"No timeline is owed to the 'when's the baby' chorus."},
  {"id":"iw-1104","cat":"when-and-spacing","type":"match","hook":"Match each timing or spacing idea to what it's really about.","pairs":[{"left":"Recovery time between pregnancies","right":"Your health and rest"},{"left":"An honest readiness check","right":"Deciding when, together"},{"left":"How many children","right":"Open, yours to choose"},{"left":"Revisiting 'not yet'","right":"Allowed as life changes"},{"left":"A relative's deadline","right":"Theirs to want, not yours to obey"}],"relearn":"Recovery, readiness, number, revisiting and relatives' deadlines all sort back to one rule: the timing is the couple's own.","persona":"any","source":"timing ideas"},
  {"id":"iw-1105","cat":"when-and-spacing","type":"match","hook":"Match each pushy line to the calm truth that answers it.","pairs":[{"left":"'When's the good news?'","right":"We'll decide if and when"},{"left":"'You're falling behind your cousin'","right":"There's no race"},{"left":"'It's the family's right to decide'","right":"It's the couple's own call"},{"left":"'One child isn't enough'","right":"One is a complete choice"},{"left":"'Hurry, you're not young'","right":"We plan on our terms"}],"relearn":"Each pushy line has a calm, true answer: it's our call, there's no race, our terms, and one is enough.","persona":"Razia","source":"line and answer"},
  {"id":"iw-1106","cat":"when-and-spacing","type":"match","hook":"Match each 'when' decision to whose it really is.","pairs":[{"left":"Whether you're ready yet","right":"You and your partner"},{"left":"How long to space children","right":"You, with health guidance"},{"left":"How many to have","right":"The couple, no quota owed"},{"left":"When to revisit the plan","right":"Yours, as life changes"},{"left":"The relatives' preferred date","right":"A wish, not a rule"}],"relearn":"Readiness, spacing, number and revisiting belong to the couple; the relatives' date is only a wish.","persona":"any","source":"whose when"},
  {"id":"iw-1107","cat":"when-and-spacing","type":"match","hook":"Match each spacing tool to the role it plays.","pairs":[{"left":"Contraception","right":"Choosing the gap"},{"left":"Recovery time","right":"Health between pregnancies"},{"left":"A clinician's input","right":"Calm facts on recovery"},{"left":"A shared readiness talk","right":"Deciding when, together"},{"left":"Revisiting later","right":"Updating as life shifts"}],"relearn":"Contraception, recovery, a clinician, a shared talk and revisiting are how couples plan when and how many, on their terms.","persona":"any","source":"spacing toolkit"},
  {"id":"iw-1108","cat":"when-and-spacing","type":"match","hook":"Match each phrase to whether it's a sound reason or a pressure.","pairs":[{"left":"Your own readiness","right":"Sound reason"},{"left":"Recovery between pregnancies","right":"Sound, health-based"},{"left":"Relatives wanting it now","right":"Someone else's agenda"},{"left":"Keeping up with friends","right":"Comparison, not planning"},{"left":"A scare-post deadline","right":"Anxiety, not a plan"}],"relearn":"Readiness and recovery are sound reasons; relatives, comparison and scare posts are pressure, not planning.","persona":"any","source":"reason vs pressure"},
  {"id":"iw-1109","cat":"when-and-spacing","type":"reflect","hook":"Lensy: when and how many children are yours to set, and to revisit as life changes. Sit okay?","prompt":"What's your take?","options":["Mine to set","Yes, revisitable","Sits okay"],"affirm":"When and how many children are yours to decide and revisit as your life and circumstances change.","relearn":"When and how many children are yours to set and revisit.","persona":"any","source":"yours to set"},
  {"id":"iw-1110","cat":"when-and-spacing","type":"reflect","hook":"Lensy: there's no universal 'right time', only the time that's right for you, together. Land?","prompt":"How does that land?","options":["Lands well","My right time","Together"],"affirm":"There is no universal right time for children, only the time that's right for you, decided together.","relearn":"There's no universal right time; only yours, decided together.","persona":"any","source":"your right time"},
  {"id":"iw-1111","cat":"when-and-spacing","type":"reflect","hook":"Lensy: spacing for your health and recovery is a real, your-own reason. Feel fair to you?","prompt":"What do you feel?","options":["Feels fair","It's mine","Yes"],"affirm":"Spacing pregnancies for your health and recovery is a legitimate consideration that's entirely your own.","relearn":"Spacing for health and recovery is a legitimate, your-own reason.","persona":"any","source":"spacing is yours"},
  {"id":"iw-1112","cat":"when-and-spacing","type":"reflect","hook":"Lensy: one, several, or none is each a valid number; no quota is owed to anyone. Okay?","prompt":"What's your take?","options":["Okay","Each is valid","No quota owed"],"affirm":"One, several, or none is each a valid number of children; no quota is owed to anyone.","relearn":"One, several, or none is each valid; no quota is owed.","persona":"any","source":"number is open"},
  {"id":"iw-1113","cat":"when-and-spacing","type":"reflect","hook":"Lensy: choosing 'not yet' now doesn't lock you out of 'yes' later. Reassuring?","prompt":"How does that sit?","options":["Reassuring","Sits well","Yes"],"affirm":"Timing decisions can be revisited; choosing 'not yet' now does not lock you out of 'yes' later.","relearn":"'Not yet' now doesn't lock out 'yes' later.","persona":"any","source":"not yet not locked"},
  {"id":"iw-1114","cat":"when-and-spacing","type":"reflect","hook":"Lensy: the decision is the couple's own; the family's wish isn't its right. Sit right?","prompt":"What do you think?","options":["Sits right","It's ours","Yes"],"affirm":"When and how many is the couple's own decision; 'it's the family's right to decide' is not true.","relearn":"When and how many is the couple's own; not the family's right.","persona":"any","source":"couple's own"},
  {"id":"iw-1115","cat":"when-and-spacing","type":"reflect","hook":"Lensy: readiness is honest reflection, not a perfect life you must finish first. Land okay?","prompt":"How does it land?","options":["Lands okay","Reflection, not perfection","Yes"],"affirm":"Readiness is honest reflection on what matters to you, not having everything perfect first.","relearn":"Readiness is honest reflection, not perfection.","persona":"any","source":"reflection not perfection"},
  {"id":"iw-1116","cat":"when-and-spacing","type":"reflect","hook":"Lensy: 'good news?' from relatives is a wish, not a deadline you owe. Feel freeing?","prompt":"What do you feel?","options":["Freeing","No deadline owed","Yes"],"affirm":"The relatives' 'good news?' is a wish, not a deadline; no timeline is owed to anyone.","relearn":"'Good news?' is a wish, not a deadline you owe.","persona":"any","source":"wish not deadline"},
  {"id":"iw-1117","cat":"when-and-spacing","type":"spot","hook":"Spot the two lines that push someone else's timing onto a couple.","scene":[{"id":"a","text":"\"Decide the gap on your own health and recovery.\"","trick":false},{"id":"b","text":"\"Have the next one this year, before people talk.\"","trick":true},{"id":"c","text":"\"When you both feel ready is the right time.\"","trick":false},{"id":"d","text":"\"You're behind your cousin, hurry up.\"","trick":true},{"id":"e","text":"\"You can revisit your plan as life changes.\"","trick":false}],"why":"'Before people talk' and 'behind your cousin' push someone else's timeline; the rest keep the timing yours.","relearn":"Timing pushed by gossip or comparison isn't a reason; the choice stays the couple's own.","persona":"any","source":"spot the push"},
  {"id":"iw-1118","cat":"when-and-spacing","type":"spot","hook":"Spot the two lines that turn a calm plan into a panic deadline.","scene":[{"id":"a","text":"\"Let's talk the timing through together.\"","trick":false},{"id":"b","text":"\"A scary post says hurry or it's too late.\"","trick":true},{"id":"c","text":"\"We can ask a clinician about recovery.\"","trick":false},{"id":"d","text":"\"Rush now so they stop asking us.\"","trick":true},{"id":"e","text":"\"Readiness is ours to name, no rush.\"","trick":false}],"why":"The scare-post 'too late' and 'rush so they stop asking' are panic deadlines; the others are calm planning.","relearn":"A guideline isn't a deadline; calm planning beats panic.","persona":"any","source":"spot the panic"},
  {"id":"iw-1119","cat":"when-and-spacing","type":"spot","hook":"Spot the two lines that hand the couple's timing to relatives.","scene":[{"id":"a","text":"\"When and how many is ours to decide.\"","trick":false},{"id":"b","text":"\"It's the elders' right to fix the date.\"","trick":true},{"id":"c","text":"\"We'll weigh our health and readiness.\"","trick":false},{"id":"d","text":"\"You must obey the family on this.\"","trick":true},{"id":"e","text":"\"We can revisit it as our life changes.\"","trick":false}],"why":"'Elders' right to fix the date' and 'you must obey the family' hand away the couple's decision; the others keep it theirs.","relearn":"When and how many is the couple's own decision, not the family's right.","persona":"Razia","source":"spot the handover"},
  {"id":"iw-1120","cat":"when-and-spacing","type":"spot","hook":"Spot the two lines that shame a valid family-size choice.","scene":[{"id":"a","text":"\"One child is a complete, valid choice.\"","trick":false},{"id":"b","text":"\"Only one? That's selfish and sad.\"","trick":true},{"id":"c","text":"\"How many is open and yours to set.\"","trick":false},{"id":"d","text":"\"A real family needs at least three.\"","trick":true},{"id":"e","text":"\"None, one or several is each valid.\"","trick":false}],"why":"'Only one is selfish' and 'a real family needs three' shame a valid choice; the rest affirm that the number is open.","relearn":"One, several or none is each valid; no number is owed.","persona":"any","source":"spot the shame"},
  {"id":"iw-1121","cat":"when-and-spacing","type":"spot","hook":"Spot the two lines that treat a guideline as a personal deadline.","scene":[{"id":"a","text":"\"Facts help us plan on our own terms.\"","trick":false},{"id":"b","text":"\"That guideline means you must start now.\"","trick":true},{"id":"c","text":"\"A guideline isn't our deadline.\"","trick":false},{"id":"d","text":"\"You've missed your window, hurry.\"","trick":true},{"id":"e","text":"\"We can revisit timing as life shifts.\"","trick":false}],"why":"'You must start now' and 'you've missed your window' weaponise a guideline; the others use facts calmly to plan.","relearn":"A guideline is a planning fact, not a personal deadline.","persona":"any","source":"spot the deadline"},
  {"id":"iw-1122","cat":"when-and-spacing","type":"spot","hook":"Spot the two lines that make timing one partner's job alone.","scene":[{"id":"a","text":"\"Let's agree on timing that works for us both.\"","trick":false},{"id":"b","text":"\"Sort the baby timing out, it's your worry.\"","trick":true},{"id":"c","text":"\"I want to weigh this together with you.\"","trick":false},{"id":"d","text":"\"Just tell me when, I'll go along with it.\"","trick":true},{"id":"e","text":"\"Our readiness is something we name together.\"","trick":false}],"why":"'It's your worry' and 'I'll just go along' dump timing on one partner; the others make it a shared decision.","relearn":"Timing is the couple's shared decision, not one partner's load.","persona":"Karthik","source":"spot the dump"},
  {"id":"iw-1123","cat":"when-and-spacing","type":"spot","hook":"Spot the two lines that pretend timing can never be revisited.","scene":[{"id":"a","text":"\"We can update our plan as things change.\"","trick":false},{"id":"b","text":"\"You said not yet once, so that's final.\"","trick":true},{"id":"c","text":"\"'Not yet' now can become 'yes' later.\"","trick":false},{"id":"d","text":"\"Change your mind and you've wasted years.\"","trick":true},{"id":"e","text":"\"Our circumstances changed, so let's revisit.\"","trick":false}],"why":"'That's final' and 'you've wasted years' deny revisiting; the others affirm the plan can change with life.","relearn":"Timing can be revisited; 'not yet' isn't a lock.","persona":"any","source":"spot the lock"},
  {"id":"iw-1124","cat":"when-and-spacing","type":"role-play","persona":"Karthik","source":"timing talk","hook":"You'd like to wait a year before trying for a baby.","setup":"Tonight she brings it up over dinner.","steps":[{"prompt":"She says: \"I really feel ready to start trying now.\"","options":[{"text":"\"I want this with you, and I'd like us to agree on timing together.\"","then":"She nods. \"Okay, I'm listening,\" she says.","best":true},{"text":"\"Let's just do whatever you want. I don't mind either way.\"","then":"She hesitates. \"I don't want to decide this alone,\" she says."},{"text":"\"A year is non-negotiable for me. Let's not discuss it further.\"","then":"She looks a little shut out by how final that sounds."},{"text":"\"I suppose we could start now, if it means that much to you.\"","then":"She senses the reluctance, unsure it's a real yes."}],"why":"Naming the shared want and your timing need opens a fair, honest talk."},{"prompt":"She asks: \"Why does it feel like a year, specifically, to you?\"","options":[{"text":"\"Let me actually think that through and tell you honestly.\"","then":"She waits, and the reason turns out clearer than you expected.","best":true},{"text":"\"I just have a feeling, that's all.\"","then":"She's left without much to go on."},{"text":"\"There's no real reason. I just want more time.\"","then":"She wonders what would actually change your mind."},{"text":"\"Because everyone says you should wait a while.\"","then":"She points out that's not really about the two of you."}],"why":"An honest, searched-for reason gives her something real to weigh."},{"prompt":"She says: \"Can we check in every few months and see how we both feel?\"","options":[{"text":"\"Yes, that sounds fair. Let's do that.\"","then":"She smiles. \"Deal,\" she says, relieved to have a plan.","best":true},{"text":"\"Sure, but let's not talk about it too much.\"","then":"She's unsure the check-ins will actually happen."},{"text":"\"Only if the answer stays 'wait' each time.\"","then":"She feels like the check-in isn't really open either way."},{"text":"\"Fine, whatever keeps the peace.\"","then":"She isn't sure this reflects what you actually think."}],"why":"An open, regular check-in keeps the timeline something you both actually own."}],"relearn":"Naming the shared want and your timing need opens a fair talk, not a silent concession."},
  {"id":"iw-1125","cat":"when-and-spacing","type":"role-play","persona":"Pooja","source":"second-child reply","hook":"You and your husband haven't set a timeline for expanding your family.","setup":"At a cousin's function, the question comes up again.","steps":[{"prompt":"A relative asks: \"Any plans for a second one yet?\"","options":[{"text":"\"We'll decide if and when that's right for us. Thanks for caring.\"","then":"She smiles and drifts back into the function's chatter.","best":true},{"text":"\"Soon, I suppose, whenever everyone here wants it to happen, really.\"","then":"She repeats it to two more relatives before the night's over."},{"text":"\"That's a bit of a personal question to ask me, isn't it?\"","then":"She looks a little wounded, though she meant it kindly."},{"text":"\"We haven't really talked about it much between ourselves.\"","then":"She offers to 'help' by bringing it up with your husband."}],"why":"\"If and when, on our terms\" needs no explaining and holds the timing calmly."},{"prompt":"Her sister chimes in: \"You don't want too big a gap between them, no?\"","options":[{"text":"\"We'll decide the gap ourselves, on our own health.\"","then":"She nods, unsure how to push back on that.","best":true},{"text":"\"Maybe you're right. We shouldn't wait too long.\"","then":"The comment quietly nags at you for the rest of the evening."},{"text":"\"That's really our decision, not yours.\"","then":"She looks stung, though she only meant to help."},{"text":"\"We'll see how things go.\"","then":"She treats the vagueness as room to bring it up again."}],"why":"Naming that it's your own call, on your own terms, answers the push without a fight."},{"prompt":"Later, your husband's mother asks softly: \"Is there anything you two need help deciding?\"","options":[{"text":"\"We're doing okay. We're deciding together, in our own time.\"","then":"She smiles. \"That's good to hear,\" she says, and lets it rest.","best":true},{"text":"\"We're fine. Don't worry about it.\"","then":"She isn't fully reassured, and checks in again soon."},{"text":"\"Honestly, we're tired of everyone asking.\"","then":"She apologises, though it lingers a little between you."},{"text":"\"I'm not sure, to be honest.\"","then":"She looks a little worried, unsure how to help."}],"why":"Saying you're deciding together, calmly, closes the worry kindly."}],"relearn":"A light 'if and when, on what's right for us' holds your timing without conflict."},
  {"id":"iw-1126","cat":"when-and-spacing","type":"role-play","persona":"Pooja","source":"warm hold","hook":"Your mother-in-law has strong opinions about your timeline for a second child.","setup":"She brings it up gently over tea.","steps":[{"prompt":"She says: \"I think it's time you two planned the next baby.\"","options":[{"text":"\"We love that you care. The timing is ours to decide together.\"","then":"She nods slowly. \"Alright, I trust you both,\" she says.","best":true},{"text":"\"Okay, if you say so, we'll go ahead and start trying soon.\"","then":"She's pleased, and starts mentioning it to relatives already."},{"text":"\"That's really not something you should be deciding for us.\"","then":"She looks hurt, though she only meant to help."},{"text":"\"We'll think about it, and let you know if anything changes.\"","then":"She takes that as a soft yes and checks in again soon."}],"why":"Warmth plus \"we'll decide together\" holds your timing without a clash."},{"prompt":"She adds: \"I just want to see the family grow while I'm still able to help.\"","options":[{"text":"\"We hear that, and we'll plan it on our own terms and time.\"","then":"She softens, comforted even as the boundary holds.","best":true},{"text":"\"You're right. Maybe we shouldn't wait too long, honestly.\"","then":"The comment starts quietly shaping a plan that isn't really yours yet."},{"text":"\"You'll be around either way. Don't worry.\"","then":"She isn't reassured, and the real question stays unanswered."},{"text":"\"Let's not talk about this right now.\"","then":"The topic just waits for the next quiet moment together."}],"why":"Naming your own terms and time keeps the plan yours, even while she's cared for."},{"prompt":"A week later she gently asks: \"Have you two thought more about it?\"","options":[{"text":"\"We have. We keep talking it through together, at our own pace.\"","then":"She smiles. \"That's all I needed to hear,\" she says.","best":true},{"text":"\"Not really. We've just been very busy with other things.\"","then":"She takes 'busy' as a reason to check in again sooner."},{"text":"\"We'll wait a while longer, but only if you agree to that.\"","then":"She says she'll think about it, and starts expecting a say in the timing."},{"text":"\"You really don't need to keep asking us this, honestly.\"","then":"She apologises, and the warmth between you cools a little."}],"why":"Naming that you keep talking it through, together, keeps the warmth intact."}],"relearn":"Warmth plus 'we'll decide together' holds your timing without a clash."},
  {"id":"iw-1127","cat":"when-and-spacing","type":"role-play","persona":"Pooja","source":"recovery talk","hook":"You'd like to space the next pregnancy for recovery; your partner's unsure.","setup":"You bring it up quietly one evening.","steps":[{"prompt":"He asks: \"Why wait? I thought we both wanted this soon.\"","options":[{"text":"\"I'd like more time to recover first. Can we plan the gap together?\"","then":"He softens. \"I didn't realise. Let's plan it out,\" he says.","best":true},{"text":"\"Never mind. Forget I said anything. Let's just not wait.\"","then":"He agrees, though you're left carrying the worry alone."},{"text":"\"You wouldn't understand what recovery actually takes, honestly.\"","then":"He looks stung, though he was only trying to understand."},{"text":"\"I don't really know. I just have a feeling we should wait.\"","then":"He's left without much to plan around with you."}],"why":"Naming your recovery need and inviting a shared plan keeps spacing a joint choice."},{"prompt":"He notices you've gone quiet, and asks: \"What would help you feel more at ease with the timing?\"","options":[{"text":"\"Let's check with a clinician together, so we both know what to expect.\"","then":"He agrees, relieved to have something concrete to plan around.","best":true},{"text":"\"I'll just tell you when I'm ready, whenever that turns out to be.\"","then":"He's unsure how to support a plan he isn't part of."},{"text":"\"Honestly, I'm not sure yet. I haven't really thought it through.\"","then":"He waits, unsure what he can actually do to help."},{"text":"\"Maybe we should ask your parents what they think.\"","then":"He says he'll ask, and the talk turns to what they want, not what you need."}],"why":"Bringing in a clinician together turns the gap into a plan you both understand."},{"prompt":"A month later, he gently checks in: \"How are you feeling about the timing now?\"","options":[{"text":"\"Let me say where I am, and let's keep checking in.\"","then":"He nods. \"That works for me,\" he says, glad to be included.","best":true},{"text":"\"Let's just start trying, so we can stop discussing it.\"","then":"He's relieved, though the recovery question is still open."},{"text":"\"I'd rather leave the timing to you now.\"","then":"He's surprised, and unsure it's fair for him to choose alone."},{"text":"\"You don't need to keep asking.\"","then":"He steps back, unsure if he's still part of the plan."}],"why":"Regular, honest check-ins keep him part of a decision about you both."}],"relearn":"Naming your recovery need and inviting a shared plan keeps spacing a joint, health-based choice."},
  {"id":"iw-1128","cat":"when-and-spacing","type":"role-play","persona":"Sneha","source":"clock reply","hook":"An aunt has strong opinions about your fertility timeline.","setup":"At a family lunch, she leans in with the usual warning.","steps":[{"prompt":"She says: \"Beta, you're getting late. The clock doesn't wait.\"","options":[{"text":"\"I'm planning this on my own terms, and I'm at peace with my timing.\"","then":"She blinks, unsure how to answer, and picks up her fork instead.","best":true},{"text":"\"You're right. Maybe I really am running out of time here.\"","then":"She nods, satisfied, and starts listing ways to speed things up."},{"text":"\"That's such an outdated thing to say to someone, honestly.\"","then":"She looks offended. \"I'm only saying it out of love,\" she says."},{"text":"\"Please, can we just not talk about this at lunch today?\"","then":"She agrees, but brings it up again before dessert."}],"why":"\"On my own terms\" answers the ticking-clock push without taking on the panic."},{"prompt":"Later, she adds: \"I just don't want you to have regrets later. That's all.\"","options":[{"text":"\"I hear that you care. I'm still deciding this calmly, in my own time.\"","then":"She softens a little, though she still looks unconvinced.","best":true},{"text":"\"Maybe I will regret it. Who knows.\"","then":"The worry starts to sound louder than it did an hour ago."},{"text":"\"I won't have regrets, so please stop.\"","then":"She says \"We'll see,\" and goes on with her advice anyway."},{"text":"\"You might be right. I haven't really thought it through at all.\"","then":"She takes that as an opening to keep advising you."}],"why":"Naming her care while staying steady on your own plan keeps you kind and clear."},{"prompt":"Weeks later, at another family lunch, she says: \"Still thinking about the clock, I hope?\"","options":[{"text":"\"I'm at peace with my own timing.\"","then":"She sighs, but seems to accept it a little more this time.","best":true},{"text":"\"I know, I know. I'm really trying to hurry.\"","then":"She takes it as a promise, and asks for updates each visit."},{"text":"\"Why do you keep bringing this up every time?\"","then":"She looks taken aback. \"I just worry about you,\" she says."},{"text":"\"Maybe you have a point after all.\"","then":"A plan that felt steady starts to wobble under repetition."}],"why":"Staying calm whenever it comes up keeps the boundary consistent."},{"prompt":"Your friend Meera later asks: \"How are you holding up with your aunt's comments?\"","options":[{"text":"\"Honestly, some days it wears on me. It helps that you ask.\"","then":"Meera nods. \"Then tell me before the next lunch, and I'll stay close,\" she says.","best":true},{"text":"\"It doesn't bother me. There's nothing to discuss.\"","then":"Meera nods and drops it, and you face the next lunch alone."},{"text":"\"Could you just tell her off, so I don't have to?\"","then":"Meera tries, but her sharp words turn the next lunch tense."},{"text":"\"Maybe she has a point, a little. I keep wondering lately.\"","then":"Doubt starts creeping into a decision that was settled."}],"why":"Being honest about how it wears on you lets a friend actually help."}],"relearn":"A calm 'on my own terms' answers the ticking-clock push without taking on the panic."},
  {"id":"iw-1129","cat":"when-and-spacing","type":"role-play","persona":"any","source":"keep number yours","hook":"A relative insists you should plan a bigger family.","setup":"At a family dinner, the topic comes up again.","steps":[{"prompt":"The relative says: \"One or two just isn't enough for a family.\"","options":[{"text":"\"How many is something we'll decide for ourselves, and we're happy with our choice.\"","then":"The relative pauses, then moves the conversation along.","best":true},{"text":"\"Maybe. We'll just plan a big family until you're finally satisfied.\"","then":"The relative isn't sure if you mean it, and asks again more seriously."},{"text":"\"That's a strange thing to say to us, honestly, isn't it?\"","then":"The relative looks taken aback, and a few others glance over."},{"text":"\"We'll think about it more, I suppose, and see how we feel.\"","then":"The relative treats 'thinking about it' as leaning toward more."}],"why":"\"How many is ours to decide\" keeps the number a couple's choice, not a quota owed."},{"prompt":"Another relative adds: \"A bigger family means more support later, no?\"","options":[{"text":"\"We understand that, and we're happy with how we're deciding this.\"","then":"They nod, though not fully convinced.","best":true},{"text":"\"That's true. Maybe we're being shortsighted about this whole thing.\"","then":"A choice that felt settled starts to feel uncertain again."},{"text":"\"Support isn't really the point of having children, if you ask me.\"","then":"The comment lands sharper than you meant it to."},{"text":"\"We'll see how things go, I suppose, and take it from there.\"","then":"They treat the vagueness as room to keep pushing."}],"why":"Naming that you're happy with how you're deciding holds the choice steady."},{"prompt":"At the next gathering, the same relative says: \"Have you two reconsidered at all?\"","options":[{"text":"\"The number is ours to decide, and we're settled on it.\"","then":"The relative finally seems to accept it and changes the subject.","best":true},{"text":"\"Fine, we'll consider a bigger family, just to end this.\"","then":"The relative takes it as a yes and starts asking when."},{"text":"\"Can we please stop having this conversation?\"","then":"The relative says \"Of course,\" and raises it again at the next dinner."},{"text":"\"Maybe you're right. We haven't really thought it through.\"","then":"Doubt creeps back into a choice you'd already made."}],"why":"A settled, consistent line keeps the decision steady under pressure."},{"prompt":"Your partner later asks: \"How are you feeling about the repeated pressure?\"","options":[{"text":"\"Honestly, it wears on me a bit. It helps when you back me up.\"","then":"He nods. \"Then let's carry it together from here,\" he says.","best":true},{"text":"\"Nothing they say gets to me, so let's leave it.\"","then":"He nods and drops it, and you face the next dinner alone."},{"text":"\"Could you go and tell them off tonight, so I don't have to?\"","then":"He tries, but his sharp words turn the dinner tense."},{"text":"\"Maybe we should just give them what they want.\"","then":"He's surprised, unsure where the sudden shift is coming from."}],"why":"Being honest about where you are, and asking for backup, lets your partner help carry it."}],"relearn":"\"How many is ours to decide\" keeps the number a couple's choice, not a quota owed."},
  {"id":"iw-1130","cat":"when-and-spacing","type":"role-play","persona":"Sneha","source":"no-race reply","hook":"Old friends keep hinting that you're behind on having kids.","setup":"At a reunion dinner, the topic comes up.","steps":[{"prompt":"A friend says: \"Wow, you're really the last one left without kids.\"","options":[{"text":"\"We're on our own timeline, and it feels right for us, no race here.\"","then":"She nods, a little surprised by how settled you sound.","best":true},{"text":"\"Yeah, I guess we'd better catch up soon then, huh?\"","then":"She takes that at face value and asks when you're starting."},{"text":"\"That's a pretty strange thing to point out, honestly.\"","then":"She looks a little embarrassed, though she meant it lightly."},{"text":"\"We're thinking about it, actually, more than you might expect.\"","then":"She treats 'thinking about it' as good as a plan already."}],"why":"\"On our own timeline, no race\" answers comparison without joining it."},{"prompt":"Another friend chimes in: \"Don't wait too long. It gets harder, you know.\"","options":[{"text":"\"We'd rather check real facts with a clinician than chase worry.\"","then":"She pauses, unsure how to respond to that.","best":true},{"text":"\"You're right. Maybe we should hurry a little.\"","then":"A calm plan starts to feel rushed by someone else's timeline."},{"text":"\"Can we please not talk about this tonight?\"","then":"The table goes quiet, and the mood shifts a little."},{"text":"\"We'll see, I suppose.\"","then":"The vagueness invites more comments through the evening."}],"why":"Choosing to check with a clinician, not panic, answers worry calmly."},{"prompt":"Later, someone in the group asks, looking your way: \"And what about you two, any news?\"","options":[{"text":"\"We're happy just listening tonight.\"","then":"The group moves on, and the comparison passes you by.","best":true},{"text":"\"Nothing yet, but we're working on it.\"","then":"She tells the others you're trying, and the questions start again."},{"text":"\"Honestly, this makes me feel a bit behind.\"","then":"The comparison lands harder than you meant to let it."},{"text":"\"Can we talk about literally anything else?\"","then":"The group shifts topics, a little unsure why it landed that way."}],"why":"Choosing not to compare keeps the evening from becoming about a deadline."},{"prompt":"On the way home, your partner asks: \"How did the evening feel for you?\"","options":[{"text":"\"Mostly fine, honestly. Stay close to me next time it comes up?\"","then":"He nods. \"Of course. We'll face it together,\" he says.","best":true},{"text":"\"It didn't bother me. There's nothing to talk about.\"","then":"He nods and drops it, and next time you face the group alone."},{"text":"\"Next time, could you do the talking so I don't have to?\"","then":"He does, but the group turns to you anyway with the same questions."},{"text":"\"Maybe we really should think about hurrying up a little bit more.\"","then":"He's surprised, since neither of you felt that way before tonight."}],"why":"Being honest about where you are, and asking for backup, lets your partner actually support you."}],"relearn":"\"On our own timeline, no race\" answers comparison without joining it."},
  {"id":"iw-1131","cat":"when-and-spacing","type":"role-play","persona":"any","source":"one calm line","hook":"At a family event, the baby question comes up again and again.","setup":"The room's already loud with catching-up chatter.","steps":[{"prompt":"The first relative asks: \"So when's the baby coming, hmm?\"","options":[{"text":"\"We'll share happy news if and when there is some. Thank you for the love.\"","then":"She smiles and moves on to catching up on other news.","best":true},{"text":"\"Um, soon, hopefully. I don't really know, to be honest.\"","then":"She takes 'soon' as encouraging and tells the next relative."},{"text":"\"Why does everyone always ask me this?\"","then":"She looks a little taken aback, though she meant it warmly."},{"text":"\"We're not sure yet, honestly. There's nothing to report.\"","then":"She treats the uncertainty as a maybe, and keeps checking in."}],"why":"One kind \"if and when there is some\" needs no answer and ends the round of pressure."},{"prompt":"A second relative, overhearing, asks: \"So when is the baby coming, then?\"","options":[{"text":"\"We'll share news if and when there's some.\"","then":"He nods, taking the calm answer in stride.","best":true},{"text":"\"We're working on it. It'll happen when it happens.\"","then":"He takes that as real progress and mentions it to others."},{"text":"\"You just heard me answer this a moment ago, didn't you?\"","then":"He looks a bit embarrassed, caught having overheard after all."},{"text":"\"Maybe. Who knows. Honestly, we'll just have to wait and see.\"","then":"The vagueness leaves the question open for him to ask again."}],"why":"Staying just as calm, however many times it's asked, keeps the boundary steady."},{"prompt":"A third relative leans in and asks: \"And what about you? Baby news?\"","options":[{"text":"\"We'll share if and when there's news to share.\"","then":"She laughs. \"Fair enough,\" she says, and lets it go.","best":true},{"text":"\"Honestly, I'm tired of saying this.\"","then":"She looks a little stung, though she only meant to be friendly."},{"text":"\"You all really need to stop asking this.\"","then":"The group goes quiet, and the mood shifts."},{"text":"\"I'll let you know the moment there's something.\"","then":"She now expects a call the day there's any news at all."}],"why":"The same calm reply, said kindly each time, closes the question without a scene."},{"prompt":"Later, your partner asks: \"How are you holding up after all that?\"","options":[{"text":"\"Mostly fine, honestly. Can you help me field it next time?\"","then":"He nods. \"Of course. We'll take turns answering,\" he says.","best":true},{"text":"\"It was nothing. There's nothing to talk about.\"","then":"He nods and drops it, and the next gathering finds you alone with it."},{"text":"\"Could you just tell them to stop asking, so I don't have to?\"","then":"He tries, but the request lands hard and the evening turns awkward."},{"text":"\"Maybe we should just tell them something to make it stop.\"","then":"He's unsure that would actually end the questions for good."}],"why":"Being honest about where you are, and asking for backup, is what actually invites support."}],"relearn":"One kind 'if and when there is some' needs no answer and ends the round of pressure."},
  {"id":"iw-900","cat":"whether-and-why","type":"strike-rewrite","hook":"\"A marriage without children is empty and unfinished.\"","myth":{"un":"A marriage without children is empty and unfinished.","re":"A marriage is whole on its own; children are a choice you add, not the part that completes it.","why":"Two people building a life together is already a full life."},"relearn":"A marriage is complete in itself; having children is a choice, not the thing that finishes it.","persona":"Sneha","source":"marriage is whole"},
  {"id":"iw-901","cat":"whether-and-why","type":"strike-rewrite","hook":"\"Once you turn thirty, having a child is the only thing left to do.\"","myth":{"un":"Once you turn thirty, having a child is the only thing left to do.","re":"A full life has many chapters; a child is one possible chapter, never the only thing left.","why":"Your worth and your future are not a single checklist item."},"relearn":"At any age your life has many paths; a child is one option, not the only thing left to do.","persona":"Sneha","source":"not the only thing"},
  {"id":"iw-902","cat":"whether-and-why","type":"strike-rewrite","hook":"\"Choosing not to have children means you'll be alone and uncared for in old age.\"","myth":{"un":"Choosing not to have children means you'll be alone and uncared for in old age.","re":"Care in old age comes from many bonds; having a child is no guarantee of it, and being childfree is no sentence to loneliness.","why":"A child isn't an insurance policy, and friends and chosen family are real support."},"relearn":"Children are not a retirement plan; childfree people build care and company in many ways.","persona":"Sneha","source":"not a retirement plan"},
  {"id":"iw-903","cat":"whether-and-why","type":"strike-rewrite","hook":"\"A real family always means a couple with kids.\"","myth":{"un":"A real family always means a couple with kids.","re":"A couple, a single person, a chosen circle: each is already a real family; kids add to a family, they don't define one.","why":"Family is about the bonds you keep, not a fixed headcount."},"relearn":"A family is real with or without children; the bond is what makes it one.","persona":"any","source":"family many forms"},
  {"id":"iw-904","cat":"whether-and-why","type":"strike-rewrite","hook":"\"Wanting a career instead of kids is just selfishness dressed up.\"","myth":{"un":"Wanting a career instead of kids is just selfishness dressed up.","re":"Choosing the life that fits you, like career, travel or quiet, is honest self-knowledge, not selfishness.","why":"Living the life that's actually yours doesn't harm anyone."},"relearn":"Shaping your life around your own goals is a valid choice, not selfishness.","persona":"Sneha","source":"not selfish"},
  {"id":"iw-905","cat":"whether-and-why","type":"strike-rewrite","hook":"\"Having a baby will fix a shaky relationship.\"","myth":{"un":"Having a baby will fix a shaky relationship.","re":"A child can't repair a strained relationship; it adds load. The relationship is worth tending for its own sake first.","why":"A baby is a new person, not a glue meant to hold adults together."},"relearn":"A child won't fix a strained relationship; tend the relationship for itself, not as a repair.","persona":"any","source":"not a fix"},
  {"id":"iw-906","cat":"whether-and-why","type":"strike-rewrite","hook":"\"You must be one hundred percent ready before you're allowed to want children.\"","myth":{"un":"You must be one hundred percent ready before you're allowed to want children.","re":"Readiness is honest reflection, not perfection; no one passes a test that proves they deserve the choice.","why":"Waiting for perfect certainty just means waiting forever."},"relearn":"Readiness is honest reflection, not a perfect score; there's no test you must pass to choose.","persona":"any","source":"no perfect test"},
  {"id":"iw-907","cat":"whether-and-why","type":"strike-rewrite","hook":"\"A divorced woman without children has nothing left to offer.\"","myth":{"un":"A divorced woman without children has nothing left to offer.","re":"A divorced, childfree life is a full life, not a leftover one; her worth never depended on a marriage or a child.","why":"A life isn't a waiting room between roles others assign."},"relearn":"Single, divorced and childfree are complete lives, never failure states or waiting rooms.","persona":"Sneha","source":"not a leftover"},
  {"id":"iw-908","cat":"whether-and-why","type":"strike-rewrite","hook":"\"Everyone changes their mind, so you'll obviously want kids one day.\"","myth":{"un":"Everyone changes their mind, so you'll obviously want kids one day.","re":"\"You'll change your mind\" isn't reassurance. It dismisses your choice as it stands today.","why":"Your decision deserves to be taken seriously now, not waved away."},"relearn":"\"You'll change your mind\" isn't a valid reassurance; your choice is real as it stands.","persona":"Sneha","source":"not change your mind"},
  {"id":"iw-909","cat":"whether-and-why","type":"strike-rewrite","hook":"\"It's your duty to give your parents a grandchild.\"","myth":{"un":"It's your duty to give your parents a grandchild.","re":"Whether to have a child is the couple's own decision; no grandchild is owed to anyone as a duty.","why":"Love for your parents doesn't make their wish your obligation."},"relearn":"A grandchild is not a duty you owe; whether to have children is the couple's own decision.","persona":"Razia","source":"no grandchild owed"},
  {"id":"iw-910","cat":"whether-and-why","type":"strike-rewrite","hook":"\"If your friends are all having babies, it's clearly time for you too.\"","myth":{"un":"If your friends are all having babies, it's clearly time for you too.","re":"Other people's timelines aren't yours; matching the group isn't a reason to start a family.","why":"A life-defining choice shouldn't run on someone else's calendar."},"relearn":"Friends having babies isn't your cue; whether and when is yours, not the group's timeline.","persona":"any","source":"not the group's clock"},
  {"id":"iw-911","cat":"whether-and-why","type":"strike-rewrite","hook":"\"A man isn't fully a man until he's a father.\"","myth":{"un":"A man isn't fully a man until he's a father.","re":"Manhood isn't proven by fatherhood; whether to have children is a real choice for him too, not a test of being a man.","why":"Worth and identity don't hinge on becoming a parent."},"relearn":"Manhood is not measured by fatherhood; whether to have children is a genuine choice for men too.","persona":"Karthik","source":"manhood not fatherhood"},
  {"id":"iw-912","cat":"whether-and-why","type":"strike-rewrite","hook":"\"Saying 'maybe never' about kids means something is wrong with you.\"","myth":{"un":"Saying 'maybe never' about kids means something is wrong with you.","re":"\"Never\" is a legitimate, healthy answer to the children question, not a sign anything is broken.","why":"A clear 'no' is as honest and valid as a clear 'yes'."},"relearn":"\"Never\" is a real, respectable answer; choosing it doesn't mean anything is wrong with you.","persona":"Sneha","source":"never is valid"},
  {"id":"iw-913","cat":"whether-and-why","type":"strike-rewrite","hook":"\"If you can afford it, you have no excuse not to have children.\"","myth":{"un":"If you can afford it, you have no excuse not to have children.","re":"Being able to afford a child is not a reason you must have one; whether to is still a free, personal choice.","why":"Capacity to do something isn't an obligation to do it."},"relearn":"Being able to afford a child doesn't make it required; whether to have one is still your choice.","persona":"any","source":"afford not obligation"},
  {"id":"iw-914","cat":"whether-and-why","type":"strike-rewrite","hook":"\"Adopting or fostering only counts if you couldn't have your own.\"","myth":{"un":"Adopting or fostering only counts if you couldn't have your own.","re":"Choosing 'another way' to build a family is a full, deliberate path, not a fallback for when biology fails.","why":"How you come to family doesn't rank one route above another."},"relearn":"\"Another way\" to family is a valid, chosen path in its own right, not a second-best fallback.","persona":"any","source":"another way valid"},
  {"id":"iw-915","cat":"whether-and-why","type":"sort","hook":"Lensy: sort each line: a real reason it's your choice, or a pressure dressed as a reason?","items":[{"id":"a","text":"\"I've honestly thought about what I want\""},{"id":"b","text":"\"The whole colony expects it by now\""},{"id":"c","text":"\"My partner and I agree on this\""},{"id":"d","text":"\"My in-laws keep dropping hints\""},{"id":"e","text":"\"It fits the life we're building\""},{"id":"f","text":"\"People will talk if we don't\""}],"bins":[{"id":"yours","label":"Truly your reason","valence":"pos"},{"id":"pressure","label":"Pressure dressed up","valence":"neg"}],"key":{"a":"yours","b":"pressure","c":"yours","d":"pressure","e":"yours","f":"pressure"},"relearn":"Your own reflection and agreement are real reasons; the colony, in-laws and gossip are pressure dressed up.","persona":"any","source":"reason vs pressure"},
  {"id":"iw-916","cat":"whether-and-why","type":"sort","hook":"Lensy: sort each life: a complete, valid one, or only 'complete' the way others frame it?","items":[{"id":"a","text":"A content childfree couple"},{"id":"b","text":"\"Poor thing, no kids to show\""},{"id":"c","text":"A happy single woman by choice"},{"id":"d","text":"\"They're not a real family yet\""},{"id":"e","text":"A peaceful childfree life"},{"id":"f","text":"\"Incomplete without a son\""}],"bins":[{"id":"complete","label":"Already complete","valence":"pos"},{"id":"frame","label":"Others' false frame","valence":"neg"}],"key":{"a":"complete","b":"frame","c":"complete","d":"frame","e":"complete","f":"frame"},"relearn":"Childfree and single-by-choice lives are already complete; 'poor thing' and 'not real' are others' false frames.","persona":"Sneha","source":"complete vs frame"},
  {"id":"iw-917","cat":"whether-and-why","type":"sort","hook":"Lensy: sort each answer to 'do you want kids?': a respected answer, or one that's wrongly dismissed?","items":[{"id":"a","text":"\"Yes, we're hoping to\""},{"id":"b","text":"\"No, never, and that's settled\""},{"id":"c","text":"\"Not yet, maybe later\""},{"id":"d","text":"\"We're choosing another way to family\""},{"id":"e","text":"\"Still honestly thinking it through\""},{"id":"f","text":"\"None of those count as a real answer\""}],"bins":[{"id":"valid","label":"A respected answer","valence":"pos"},{"id":"dismiss","label":"Wrongly dismissed","valence":"neg"}],"key":{"a":"valid","b":"valid","c":"valid","d":"valid","e":"valid","f":"dismiss"},"relearn":"Yes, never, not-yet, another-way and still-deciding are all respected answers; 'none count' is the only false line.","persona":"any","source":"all answers respected"},
  {"id":"iw-918","cat":"whether-and-why","type":"sort","hook":"Lensy: sort what makes you ready to decide: honest reflection, or a test you imagine you must pass?","items":[{"id":"a","text":"Thinking honestly about what you want"},{"id":"b","text":"\"Be a perfect parent before you start\""},{"id":"c","text":"Talking it over openly with your partner"},{"id":"d","text":"\"Have every doubt erased first\""},{"id":"e","text":"Knowing the choice can be revisited"},{"id":"f","text":"\"Pass everyone else's approval\""}],"bins":[{"id":"real","label":"Honest reflection","valence":"pos"},{"id":"fake","label":"An imagined test","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"Readiness is honest reflection and open talk; 'be perfect', 'no doubts' and 'everyone's approval' are imagined tests.","persona":"any","source":"reflection not test"},
  {"id":"iw-919","cat":"whether-and-why","type":"sort","hook":"Lensy: sort each remark from relatives: caring curiosity, or pressure about your choice?","items":[{"id":"a","text":"\"Whatever you two decide, we're with you\""},{"id":"b","text":"\"When's the good news? Don't make us wait\""},{"id":"c","text":"\"Take your time, it's your call\""},{"id":"d","text":"\"A house feels empty without a child\""},{"id":"e","text":"\"We just want you both happy\""},{"id":"f","text":"\"People your age all have kids by now\""}],"bins":[{"id":"care","label":"Genuine support","valence":"pos"},{"id":"push","label":"Pressure on you","valence":"neg"}],"key":{"a":"care","b":"push","c":"care","d":"push","e":"care","f":"push"},"relearn":"\"It's your call\" and \"we're with you\" are support; \"when's the good news\" and \"empty house\" are pressure.","persona":"Razia","source":"support vs pressure"},
  {"id":"iw-920","cat":"whether-and-why","type":"sort","hook":"Lensy: sort each thought: a healthy way to weigh the 'whether', or fear doing the deciding?","items":[{"id":"a","text":"\"What do we actually want our days to look like?\""},{"id":"b","text":"\"I'll just do it so people stop asking\""},{"id":"c","text":"\"Let's talk about it honestly, no rush\""},{"id":"d","text":"\"I'm scared to say no, so I'll say yes\""},{"id":"e","text":"\"Either answer can be a good life\""},{"id":"f","text":"\"If I refuse, everyone will judge me\""}],"bins":[{"id":"clear","label":"Deciding freely","valence":"pos"},{"id":"fear","label":"Fear deciding","valence":"neg"}],"key":{"a":"clear","b":"fear","c":"clear","d":"fear","e":"clear","f":"fear"},"relearn":"Asking what you want and 'either answer is a good life' is free choice; 'so people stop asking' is fear deciding.","persona":"any","source":"free vs fear"},
  {"id":"iw-921","cat":"whether-and-why","type":"branch","persona":"any","source":"lunch announcement","hook":"At a family lunch, an uncle announces you'll 'surely give good news this year'.","steps":[{"prompt":"All eyes turn to you at the table. What do you say?","options":[{"text":"Smile and say it's something you'll both decide in your own time","then":"The table nods and moves back to other lunch talk.","best":true},{"text":"Laugh nervously and mumble 'we'll see', feeling cornered","then":"The hint lands as a promise, and the pressure sticks to you."},{"text":"Say nothing at all and hope the moment just passes","then":"The uncle asks again, thinking you didn't hear him."},{"text":"Explain all your reasons for waiting, in careful detail","then":"The table treats it as an opening to offer advice."}],"why":"A warm 'we'll decide in our own time' holds the line, no family war."},{"prompt":"After lunch, an aunt pulls you aside to 'check in properly'. What do you focus on?","options":[{"text":"Saying, kindly, that the choice is yours to make","then":"She nods, and seems to actually hear it.","best":true},{"text":"Whether you actually owe her a fuller explanation","then":"You find yourself explaining more than you meant to."},{"text":"Reassuring her that you're 'thinking about it' more","then":"She treats that as real movement toward a yes."},{"text":"Asking her to please just drop it already","then":"She looks hurt, though she meant it kindly."}],"why":"Repeating the same calm boundary, kindly, holds it without needing a defence."},{"prompt":"At the next family gathering, the topic comes up again. What do you do?","options":[{"text":"Give a calm, steady answer, unchanged by the pressure","then":"The family seems to finally accept that this is your answer.","best":true},{"text":"Give a new, different answer to sound more definite","then":"Now there are two different stories about your plans."},{"text":"Avoid the family gathering next time entirely","then":"The topic just waits for you at the one after."},{"text":"Ask your partner to field all questions from now on","then":"The pressure just shifts to your partner instead of easing."}],"why":"A steady, calm answer, held firmly, is what finally settles the question."}],"debrief":"A warm 'we'll decide in our own time' holds the line, no family war.","relearn":"Hold the boundary on a personal choice calmly, without mumbling agreement."},
  {"id":"iw-922","cat":"whether-and-why","type":"branch","persona":"Karthik","source":"whether before when","hook":"You've been planning the 'when' of kids for years but never honestly asked yourself 'whether'.","steps":[{"prompt":"A form at a routine checkup asks about your family plans. What do you notice?","options":[{"text":"That you haven't really answered this one yet","then":"The blank field makes the missing question impossible to ignore.","best":true},{"text":"That you'll just write the plan you've always assumed","then":"The form gets filled out on autopilot, though the blank question sits with you the rest of the day."},{"text":"That it's an odd thing for a form to even ask","then":"You brush past it, though the question lingers oddly in your mind."},{"text":"That you should have an answer ready by now","then":"You feel pressure to answer fast rather than honestly."}],"why":"Noticing the missing question turns a drifting default into a real one."},{"prompt":"That evening you raise it with your partner. What do you say?","options":[{"text":"That you'd like to sit with the real 'whether' question, together","then":"She pauses, then admits she's wondered the same thing.","best":true},{"text":"That the plan's already in motion, so why ask now","then":"The default keeps quietly running, until she brings it up again herself, insistent this time."},{"text":"That you assume she's already sure about it","then":"She's surprised you never actually asked her directly."},{"text":"That it's probably just overthinking things","then":"The question gets waved away, until it resurfaces a few days later, impossible to avoid."}],"why":"Asking 'whether', together, turns autopilot into an actual, owned decision."},{"prompt":"A week into talking, she asks what you've actually concluded. What do you tell her?","options":[{"text":"That you're genuinely still working through it, honestly","then":"She nods. 'That feels more real than the old plan,' she says.","best":true},{"text":"That you've decided yes, since it's simply easier to just say","then":"She's surprised by the sudden certainty, and asks what changed."},{"text":"That you'd rather stop discussing it for now","then":"The real decision stays undecided, quietly."},{"text":"That whatever she wants works fine for you","then":"She's left holding a decision that was meant to be shared."}],"why":"Staying honestly in the process keeps it a real decision, not a shortcut."}],"debrief":"Ask the 'whether' honestly and together before the 'when'.","relearn":"Ask 'whether' first and together; this choice deserves a real decision."},
  {"id":"iw-923","cat":"whether-and-why","type":"branch","persona":"Sneha","source":"not by fear","hook":"You feel sure you don't want children, steady in that choice.","steps":[{"prompt":"A relative says, again, that you'll regret this one day. What do you do?","options":[{"text":"Trust your own reflection and hold your choice","then":"Saying it firmly, you feel a little more settled in your answer.","best":true},{"text":"Wonder if she might actually have a point","then":"A clear decision starts to wobble under someone else's fear."},{"text":"Argue with her until she finally agrees with you","then":"The argument goes nowhere, and neither of you feels heard."},{"text":"Say you'll 'think about it more', just to end the talk","then":"She treats that as a crack in your certainty."}],"why":"Trusting your own reflection lets you own a clear decision, not other people's fear."},{"prompt":"A close friend asks if the regret warning ever gets to you. What do you say?","options":[{"text":"That it's just noise and you'd rather not get into it","then":"Your friend nods and lets it drop, so there is no chance to back you up."},{"text":"That it stings sometimes, but it's their fear, not a fact","then":"Saying it out loud, you find the warning weighs less than it did.","best":true},{"text":"That she shouldn't ask, since it only makes things worse","then":"Your friend goes quiet, sorry she asked, and the warning stays unspoken."},{"text":"That maybe everyone's right and you're wrong","then":"You start doubting a decision that was actually settled."}],"why":"Being honest about the sting, and naming the warning as their fear, helps you hold your choice."},{"prompt":"At a family event, someone brings up the 'regret' warning once more. What do you do?","options":[{"text":"Give a calm, settled answer, unmoved by the warning","then":"The comment lands with less weight than it used to.","best":true},{"text":"Give in and say you might reconsider someday","then":"The family treats that as an opening, not a closed door."},{"text":"Avoid the family event next time to dodge it","then":"The comment is just waiting for you at the next one."},{"text":"Get visibly upset at having to hear it again","then":"The moment turns tense, and the real point gets lost."}],"why":"A calm, settled answer, held steady, finally makes the comment lose its weight."}],"debrief":"\"You'll regret it\" is a fear, not a fact; a childfree choice is valid.","relearn":"Trust your own reflection; a childfree choice is valid now, not fear's to overrule."},
  {"id":"iw-924","cat":"whether-and-why","type":"branch","persona":"Sneha","source":"back her choice","hook":"A close friend tells you she's decided never to have kids.","steps":[{"prompt":"She watches your face carefully, waiting for a response. What do you say?","options":[{"text":"That it's a completely valid choice and you've got her back","then":"She exhales, visibly relieved, and starts talking more freely.","best":true},{"text":"Say she'll change her mind one day, since most people do","then":"She nods politely, but something closes off in the conversation."},{"text":"Question whether she's sure, since it's such a big decision","then":"She feels like she has to defend a choice she'd already made."},{"text":"Change the subject to something a bit easier","then":"She's left unsure whether you actually support her."}],"why":"Affirming her choice as it stands lets her decide free of guilt."},{"prompt":"Later, she mentions her own mother reacted badly to the news. What do you focus on?","options":[{"text":"How she's holding up, and that her choice still stands","then":"She softens, glad someone's asking about her, not just the decision.","best":true},{"text":"Whether her mother might actually have a point","then":"The conversation drifts into weighing her mother's objection instead of supporting her."},{"text":"Giving advice on how to convince her mother","then":"The conversation turns into strategy instead of support."},{"text":"Reassuring her that her mother will come around eventually","then":"She smiles, then says she isn't waiting for her mother to come around."}],"why":"Asking how she's doing, not doubting the choice, keeps your support real."},{"prompt":"Months later, a mutual friend asks if she's 'still saying that'. What do you say?","options":[{"text":"That it was never a phase, and you respect her as she is","then":"The friend hears it clearly, and the comment doesn't get repeated.","best":true},{"text":"That she might still change her mind, though you're not sure","then":"The comment travels back to your friend, and it stings."},{"text":"That it's really not your place to say anything","then":"The friend keeps asking others the same doubting question."},{"text":"That she's only saying it because her mother upset her","then":"The comment gets back to her, and she feels her decision was explained away."}],"why":"Naming it as settled, not a phase, protects her choice even when you're not there."}],"debrief":"Affirming her choice as it stands lets her decide free of guilt.","relearn":"\"You'll change your mind\" isn't reassurance; support a friend's childfree choice as it stands."},
  {"id":"iw-925","cat":"whether-and-why","type":"branch","persona":"Karthik","source":"different answers","hook":"You and your partner realise you genuinely want different answers on having children.","steps":[{"prompt":"She says it out loud first: she's not sure she wants this. What do you do?","options":[{"text":"Open an honest conversation about what's actually underneath it","then":"It's uncomfortable, but you both stay in the conversation.","best":true},{"text":"Say you assumed you'd both just end up having kids eventually","then":"She's surprised the assumption was never actually checked."},{"text":"Get defensive, since you want children more clearly","then":"She feels she has to justify a feeling that's honestly hers."},{"text":"Say you'll decide later, when it's less awkward","then":"The real conversation keeps getting postponed."}],"why":"Facing a big difference together, honestly, beats pretending it away."},{"prompt":"A few days later, she circles back and asks what having children actually means to you, personally. What do you say?","options":[{"text":"The honest truth, even the parts that are hard to say","then":"She listens closely, and it helps her understand your side.","best":true},{"text":"That it's just what people do eventually","then":"She's left with an answer that isn't really about you."},{"text":"That you haven't really thought about it too deeply","then":"She's unsure what she's actually weighing against."},{"text":"That it would make your parents happy","then":"Her worry that this is about everyone but you both grows."}],"why":"An honest answer, even a hard one, is what actually helps her understand you."},{"prompt":"Weeks in, neither of you has moved. What do you suggest?","options":[{"text":"Keep talking regularly instead of letting it sit unresolved","then":"She agrees; the ongoing talks feel better than the silence before.","best":true},{"text":"Give her a firm deadline to finally decide","then":"She feels rushed on something that isn't hers alone to solve."},{"text":"Stop bringing it up to keep the peace","then":"The real difference just waits, unspoken, underneath everything."},{"text":"Say whoever wants it more should get their way","then":"One of you gets an answer; the other carries quiet resentment."}],"why":"Ongoing talk, instead of silence, keeps the difference something you're working through."},{"prompt":"A friend asks how you two are handling such a big difference. What do you say?","options":[{"text":"That you want to keep facing it honestly, together, even without an answer yet","then":"The friend nods. 'That's honestly the hard part done,' she says.","best":true},{"text":"That you're sure it'll work itself out eventually","then":"The friend gently points out big things rarely just resolve alone."},{"text":"That you're avoiding the topic for now","then":"The friend worries the avoidance is doing more harm than good."},{"text":"That one of you will probably just give in","then":"The friend asks, gently, if that really sounds fair to you both."}],"why":"Naming that you want to keep facing it together, even unresolved, is real progress."}],"debrief":"A difference this big needs honest, repeated talk, not overriding.","relearn":"Differences about children need honest, ongoing talk, not one partner overriding."},
  {"id":"iw-926","cat":"whether-and-why","type":"branch","persona":"any","source":"not the next item","hook":"After your wedding, relatives start treating a baby as the obvious next item on the list.","steps":[{"prompt":"At a post-wedding visit, a relative asks 'what's next' with a knowing smile. What do you say?","options":[{"text":"That whether and when is a choice you two will make together","then":"The relative nods, a little surprised, but doesn't push.","best":true},{"text":"Laugh and let the implication stand, unanswered","then":"The 'next item' framing quietly sticks around the family."},{"text":"Say you're 'not sure yet', to sound a bit open","then":"The relative treats 'not sure' as a maybe that's coming soon."},{"text":"List all your other current life plans instead","then":"The relative nods but circles back to the baby question anyway."}],"why":"Naming it as a choice, not the next step, resets the default into a real decision."},{"prompt":"Another relative starts describing the 'stages' after marriage, kids included. What do you focus on?","options":[{"text":"Gently noting that stage is a choice, not automatic","then":"The relative pauses, as if genuinely hearing it for the first time.","best":true},{"text":"Letting the stages talk pass without comment","then":"The assumed timeline quietly becomes the expected one."},{"text":"Agreeing you're probably 'due' for that stage soon","then":"You're now nodding along to a plan you never actually chose."},{"text":"Changing the subject to avoid the conversation","then":"The 'stages' framing just returns at the next family visit."}],"why":"Gently naming the assumption is what actually starts to shift it."},{"prompt":"Months later, your parents ask if you've 'started thinking about it' yet. What do you say?","options":[{"text":"That you and your partner will decide, and you'll share news if there's any","then":"They accept it, though a little disappointed not to hear more.","best":true},{"text":"That you've been 'meaning to' start thinking about it","then":"They take that as real movement and start asking more often."},{"text":"That it's really none of their business","then":"The bluntness lands harder than you meant, and stings a little."},{"text":"That you're waiting for the 'right time' to feel obvious","then":"They offer their own idea of what that right time should be."}],"why":"A calm, honest boundary respects them while keeping the choice yours."},{"prompt":"At a family function, someone else picks up the 'next item' framing again. What do you do?","options":[{"text":"Say, kindly, that it's a choice you'll make, not a step you owe","then":"The comment finally seems to lose its pull on the room.","best":true},{"text":"Let it slide again, since arguing feels exhausting","then":"The framing just keeps circulating, unchallenged, at every function."},{"text":"Get frustrated and call out the whole family for assuming this","then":"The room goes quiet, and the real point gets lost in the tension."},{"text":"Joke along with it to keep things light","then":"The joke gets repeated as if it were closer to true than it is."}],"why":"A calm, kind answer, held firmly, is what finally settles the framing."}],"debrief":"A child isn't an automatic next step after marriage; it's the couple's choice.","relearn":"A baby isn't the automatic next step after a wedding; whether and when is yours."},
  {"id":"iw-927","cat":"whether-and-why","type":"branch","persona":"any","source":"not a defect","hook":"You're leaning childfree, but worry you're 'supposed to' want kids and something's wrong with you.","steps":[{"prompt":"A relative mentions offhand that 'everyone wants kids eventually'. What do you do?","options":[{"text":"Quietly remind yourself that not wanting them is normal too","then":"The comment lands, but it doesn't stick the way it used to.","best":true},{"text":"Wonder, again, if something's wrong with you","then":"The old worry resurfaces, uninvited, for the rest of the day."},{"text":"Argue the point loudly to prove them wrong","then":"The argument leaves you more rattled than settled."},{"text":"Laugh it off without really registering it","then":"The comment gets buried instead of actually addressed."}],"why":"Reminding yourself the feeling is valid frees the choice from an untrue worry."},{"prompt":"A friend asks, kindly, if you've always felt this way about kids. What do you say?","options":[{"text":"Honestly, including the moments of doubt along the way","then":"She listens without judgement, and the honesty feels like relief.","best":true},{"text":"That you're not totally sure it'll stay this way","then":"The friend takes the maybe as more open than you really feel."},{"text":"That you'd rather not talk about something so personal","then":"The question stays unexamined, sitting quietly with you."},{"text":"That everyone else seems so sure, so maybe you're the odd one","then":"The comparison adds weight to a worry that isn't really true."}],"why":"Honesty, doubts included, is what actually helps a friend see you clearly."},{"prompt":"That night, the old 'something's wrong with me' thought returns. What do you do?","options":[{"text":"Remind yourself, plainly, that this feeling is valid, not a fault","then":"The thought quiets a little, and you sleep easier.","best":true},{"text":"Try to talk yourself into wanting children instead","then":"Overriding the honest feeling just buries it deeper."},{"text":"Google whether not wanting kids is 'normal'","then":"The search brings more noise than the reassurance you needed."},{"text":"Ignore the thought and hope it goes away on its own","then":"It resurfaces again, a little louder, a few nights later."}],"why":"Naming the feeling as valid, plainly, is what actually quiets the old worry."},{"prompt":"At a family gathering, someone questions why you 'don't want the normal things'. What do you say?","options":[{"text":"That not wanting children is a normal, valid feeling, not a defect","then":"The comment lands with less power than the ones before.","best":true},{"text":"That you're 'still figuring it out', to sound less certain","then":"The relative treats the uncertainty as room to keep asking."},{"text":"That there's really nothing 'normal' about their assumptions either","then":"The exchange turns sharper than you meant it to."},{"text":"Walk away without a word and leave them guessing","then":"The question is left hanging, unanswered, for later."}],"why":"Saying the feeling is normal, not a defect, lets you carry it without shame."}],"debrief":"Not wanting children is a valid feeling, not a fault; weigh it free of shame.","relearn":"Not wanting children is normal and valid; nothing is wrong with you."},
  {"id":"iw-928","cat":"whether-and-why","type":"branch","persona":"Razia","source":"don't be the pressure","hook":"Your sister chose to stay childfree and a relative asks you to 'talk some sense into her'.","steps":[{"prompt":"The relative corners you first, before you've even seen your sister. What do you say?","options":[{"text":"Decline, and say it's your sister's own choice to respect","then":"The relative looks surprised, but doesn't argue back right away.","best":true},{"text":"Say you'll 'see what you can do' about it","then":"The relative treats that as a promise and expects an update soon."},{"text":"Agree that it does seem like an odd choice","then":"You've just handed the relative more fuel for their own campaign."},{"text":"Avoid answering and quietly slip away","then":"The relative simply corners your sister next instead."}],"why":"Declining to be the pressure keeps you an ally, not one more voice against her."},{"prompt":"Later, your sister asks if anyone's been 'at you' about her choice. What do you tell her?","options":[{"text":"Be honest, and affirm that it's her decision","then":"She relaxes, glad to hear you're clearly on her side.","best":true},{"text":"That you didn't want to worry her with it","then":"She senses something's being kept from her, and it unsettles her."},{"text":"A softened version, to avoid an awkward talk altogether","then":"She's left with half the story and half the reassurance."},{"text":"Nothing at all, hoping it just blows over","then":"She finds out from someone else, and wonders why you didn't say."}],"why":"Being honest, and clearly on her side now, is what she needed to hear."},{"prompt":"The relative tries again at the next family visit, more insistent this time. What do you do?","options":[{"text":"Say, kindly but firmly, that it's not your place to push her","then":"The relative sighs, clearly frustrated, but backs off for now.","best":true},{"text":"Suggest the relative talk to her directly instead","then":"The relative does, and your sister ends up defending herself again."},{"text":"Say you'll \"mention it again sometime\"","then":"The relative keeps checking back in, thinking it's still on the table."},{"text":"Get short with the relative to end the conversation fast","then":"The tension in the room lingers longer than the comment did."}],"why":"Repeating the same firm boundary, kindly, keeps you steady on her side."},{"prompt":"Later, your sister brings up the relative again and asks where you actually stand. What do you say?","options":[{"text":"Say plainly that her choice is hers, and you'll always say so","then":"She relaxes, relieved to have one clear, steady ally.","best":true},{"text":"Say you hope the family eventually comes around","then":"She nods, though she says she isn't waiting on the family to come around."},{"text":"Say it's not a big deal and change the subject","then":"She's left unsure how solid your support actually is."},{"text":"Say you're mostly just trying to keep the peace","then":"She wonders if your support depends on how loud the pressure gets."}],"why":"Naming the choice as hers, without conditions, is real, lasting support."},{"prompt":"Months later, a new relative brings up the 'convince her' request again. What do you do?","options":[{"text":"Give a clear answer: it's her choice, not yours to push","then":"The relative seems to accept it without much pushback.","best":true},{"text":"Explain the whole history again to justify your position","then":"The long explanation gives the topic more air than it needs."},{"text":"Say you're 'tired of this conversation' and leave it there","then":"The relative takes the tiredness as a sign the topic's still open."},{"text":"Ask your sister to explain herself to this one too","then":"She's asked, again, to defend a choice that was never in question."}],"why":"The same clear answer, held consistently, is what finally settles the question."}],"debrief":"Her childfree choice is hers to respect; don't carry others' pressure to her.","relearn":"Respect another adult's childfree choice; don't be recruited as the pressure."},
  {"id":"iw-929","cat":"whether-and-why","type":"reflect","hook":"Lensy: whether to have children is genuinely yours and your partner's to decide. How does owning that feel?","prompt":"What's coming up for you?","options":["It's ours to choose","Steadying","A relief","Mine to own"],"affirm":"Whether to have children is the couple's own decision, not family's, not society's. Owning it is yours by right.","relearn":"Whether to have children belongs to you and your partner, not to family or society.","persona":"any","source":"yours to own 2"},
  {"id":"iw-930","cat":"whether-and-why","type":"reflect","hook":"Lensy: a childfree life is a full, complete life. Sit with that for a moment. What do you notice?","prompt":"What comes to mind?","options":["It's already complete","Freeing to hear","No less of a life","Quietly true"],"affirm":"A childfree life is whole and valid; womanhood is not motherhood, and a full life takes many shapes.","relearn":"A childfree life is complete and valid; it isn't selfish, sad, or incomplete.","persona":"Sneha","source":"childfree complete reflect"},
  {"id":"iw-931","cat":"whether-and-why","type":"reflect","hook":"Lensy: 'not yet', 'never', and 'another way' are all real answers. Which feels closest to you today?","prompt":"Where are you right now?","options":["Not yet","Maybe never","Another way","Still deciding"],"affirm":"Every one of those is a legitimate, respected answer, and you can revisit it as life changes.","relearn":"'Not yet', 'never' and 'another way' are all real, respectable answers, and they can change over time.","persona":"any","source":"which answer today"},
  {"id":"iw-932","cat":"whether-and-why","type":"reflect","hook":"Lensy: there's no test you must pass to deserve this choice. How does letting go of 'perfectly ready' land?","prompt":"What do you feel?","options":["Lighter","Permission granted","Less pressure","I can just decide"],"affirm":"Readiness is honest reflection, not perfection; you don't have to earn the right to choose.","relearn":"Readiness is honest reflection, not a test you must pass to deserve the choice.","persona":"any","source":"no test to pass"},
  {"id":"iw-933","cat":"whether-and-why","type":"reflect","hook":"Lensy: 'you'll change your mind' tries to wave your choice away. How does standing by it as it is feel?","prompt":"What's your take?","options":["It's valid now","Solid","I trust myself","Heard"],"affirm":"Your choice deserves to be taken seriously today. 'You'll change your mind' isn't a reason to doubt it.","relearn":"Your choice is valid as it stands; 'you'll change your mind' isn't a reason to doubt yourself.","persona":"Sneha","source":"valid as it is"},
  {"id":"iw-934","cat":"whether-and-why","type":"reflect","hook":"Lensy: single, childfree and divorced are all full lives, never 'waiting rooms'. What does that stir?","prompt":"What comes up?","options":["A full life","Not a waiting room","Enough as it is","Reassuring"],"affirm":"A single, childfree or divorced life is complete, not a pause before some 'real' life begins.","relearn":"Single, childfree and divorced lives are complete lives, never failure states or waiting rooms.","persona":"Sneha","source":"not a waiting room"},
  {"id":"iw-935","cat":"whether-and-why","type":"reflect","hook":"Lensy: this choice can be revisited. 'Not yet' today doesn't lock you out of 'yes' later. How's that to hold?","prompt":"What do you notice?","options":["No door is shut","Reassuring","Room to breathe","I can revisit it"],"affirm":"Choosing 'not yet' now doesn't close 'yes' later; the decision stays open and yours to revisit.","relearn":"Choosing 'not yet' now doesn't lock you out of 'yes' later; the choice can be revisited.","persona":"any","source":"can revisit"},
  {"id":"iw-936","cat":"whether-and-why","type":"reflect","hook":"Lensy: no answer is owed to the 'when's the good news' chorus. How does keeping your answer to yourself feel?","prompt":"What's coming up?","options":["I owe no one","Freeing","My business","Calm"],"affirm":"You don't owe the good-news chorus an answer; your choice is legitimate exactly as it stands.","relearn":"No answer is owed to the 'good news' chorus; the choice is legitimate as it stands.","persona":"any","source":"no answer owed"},
  {"id":"iw-937","cat":"whether-and-why","type":"role-play","persona":"Pooja","source":"aunty at gathering","hook":"At a get-together, an aunty is known for asking pointed questions in front of everyone.","setup":"The room goes quiet, waiting for your answer.","steps":[{"prompt":"Aunty asks: \"So, when are you two starting a family?\"","options":[{"text":"\"That's something we'll decide for ourselves, aunty. Thanks for caring about us.\"","then":"She nods, a little surprised, and turns back to her tea.","best":true},{"text":"\"Soon, soon. Don't worry about it, aunty, really.\"","then":"She smiles but isn't fully satisfied, and glances at the aunty beside her."},{"text":"\"That's really not your business to ask, aunty.\"","then":"She goes stiff, and the room stays quiet a moment longer."},{"text":"\"We're still thinking about it, quite a bit lately.\"","then":"She takes that as an answer that's leaning toward yes soon."}],"why":"A warm \"we'll decide for ourselves\" holds the boundary without a fight."},{"prompt":"A little later, she adds: \"You've been married a year already, you know.\"","options":[{"text":"\"We know, and we're happy with our own pace on this.\"","then":"She pauses, unsure how to argue with that.","best":true},{"text":"\"You're right. Maybe we're a bit behind schedule.\"","then":"A plan that felt settled starts to feel rushed."},{"text":"\"Time isn't really the measure of anything, aunty.\"","then":"The exchange turns sharper than you meant it to."},{"text":"\"I suppose. Whatever happens happens.\"","then":"She treats the vagueness as an opening to ask again soon."}],"why":"Naming your own pace, kindly, answers the push without taking it on."},{"prompt":"Later, she catches you alone and asks softly: \"Is everything alright?\"","options":[{"text":"\"All is well, aunty, thank you. We're deciding together, in our own time.\"","then":"She relaxes. \"That's all I wanted to know,\" she says.","best":true},{"text":"\"We're fine. Honestly, don't worry about it at all.\"","then":"She isn't fully reassured, and asks again another day."},{"text":"\"Honestly, aunty, these questions are why we dread these gatherings.\"","then":"She looks stung. \"I only asked because I care,\" she says."},{"text":"\"I don't really know, to be honest with you.\"","then":"She looks a little worried on your behalf."}],"why":"Naming that you're deciding together, calmly, closes the worry with warmth."}],"relearn":"A warm 'we'll decide for ourselves' holds the boundary on a personal choice without a fight."},
  {"id":"iw-938","cat":"whether-and-why","type":"role-play","persona":"any","source":"why even marry","hook":"A colleague thinks marriage without children doesn't make sense.","setup":"You look up from your desk, a little caught off guard.","steps":[{"prompt":"Your colleague asks: \"Why even marry if you don't want kids? What's the point?\"","options":[{"text":"\"We married for our life together. Kids are a separate choice.\"","then":"He pauses, thinking it over. \"Hm. That's one way to see it,\" he says.","best":true},{"text":"\"I guess you're right. Maybe we should reconsider it.\"","then":"He takes that as agreement with a view you don't actually hold."},{"text":"\"That's a really rude thing to say to me.\"","then":"The exchange turns tense, and the actual point gets lost."},{"text":"\"We're still figuring that part out, to be honest.\"","then":"He nods, then takes the uncertainty as an opening. \"So you might change your mind?\""}],"why":"Marriage is whole on its own; saying children are a separate choice is calm and clear."},{"prompt":"Over lunch, he brings it up again: \"Isn't the whole point of marriage to build a family?\"","options":[{"text":"\"For some, yes. For us, marriage is already a full life.\"","then":"He nods slowly. \"I never thought of it that way,\" he says.","best":true},{"text":"\"Maybe. I hadn't really thought about it that way before now.\"","then":"You start second-guessing a choice that was already settled."},{"text":"\"That's a very old-fashioned way to see marriage.\"","then":"He feels judged, and the conversation gets defensive."},{"text":"\"I'll explain it properly another time.\"","then":"He says he'll hold you to that, and brings it up again a few days later."}],"why":"Naming marriage as already complete answers the assumption without defending it."},{"prompt":"A few days later, in front of others, he says, half-joking: \"So, reconsidered marriage without kids yet?\"","options":[{"text":"\"Our marriage is already whole.\"","then":"He laughs it off. \"Alright, alright, fair point,\" he says.","best":true},{"text":"\"Ha, I'll think about it. Now can we drop it?\"","then":"He grins, takes that as a maybe, and says he'll ask again next week."},{"text":"\"I don't know. Maybe you have a point.\"","then":"Doubt about a settled choice creeps back in, unbidden."},{"text":"\"Why do you even care about this so much anyway?\"","then":"The exchange turns awkward in front of the others."}],"why":"A short, steady answer, said calmly, is what settles the joke."}],"relearn":"Marriage is whole on its own; you can say children are a separate choice, calmly and clearly."},
  {"id":"iw-939","cat":"whether-and-why","type":"role-play","persona":"Pooja","source":"empty house remark","hook":"Your mother-in-law has been dropping quiet hints about wanting grandchildren.","setup":"She says it quietly one evening, over tea.","steps":[{"prompt":"She sighs: \"The house feels so empty without the sound of a child.\"","options":[{"text":"\"I hear you. Whether and when is ours to decide together.\"","then":"She nods, comforted even though the answer stays unchanged.","best":true},{"text":"\"You're right. We're being selfish, and we'll hurry up soon.\"","then":"She's relieved, and starts to expect it soon."},{"text":"\"The house isn't empty at all. We're right here.\"","then":"She looks a little hurt, though she meant it as longing."},{"text":"\"We'll think about it, honestly, quite a bit more.\"","then":"She treats 'thinking about it' as a step closer to yes."}],"why":"Acknowledging the feeling while holding the boundary keeps things warm and clear."},{"prompt":"She adds: \"I just miss having little ones around, like when my son was small.\"","options":[{"text":"\"That makes sense. We'll decide whether and when, together.\"","then":"She smiles softly, and the moment feels warmer, not tense.","best":true},{"text":"\"Maybe we should think about it a bit sooner, then.\"","then":"A private timeline starts bending around her nostalgia."},{"text":"\"That's really not a very good reason for us to decide anything.\"","then":"The comment lands harsher than the warmth she was offering."},{"text":"\"We'll see how things go, and take it from there.\"","then":"She takes the vagueness as an invitation to bring it up again."}],"why":"Naming the choice as still yours, kindly, keeps it real even while she's heard."},{"prompt":"A few weeks later, she says, more gently this time: \"Have you two thought any more about it?\"","options":[{"text":"\"We're still deciding this together, at our own pace.\"","then":"She nods. \"I trust you both,\" she says, and finally lets it rest.","best":true},{"text":"\"We'll wait a bit longer, unless you think we shouldn't.\"","then":"She says she'd rather you didn't, and starts weighing in on the timing."},{"text":"\"You really don't need to keep bringing this up now.\"","then":"She apologises, and the warmth between you cools a little."},{"text":"\"Maybe soon. Honestly, we'll just have to wait and see.\"","then":"She takes that as a hopeful sign and checks in again."}],"why":"The same steady, warm answer finally settles the longing without pressure."}],"relearn":"You can acknowledge the feeling and still say whether and when is the couple's own choice."},
  {"id":"iw-940","cat":"whether-and-why","type":"role-play","persona":"Sneha","source":"not a phase","hook":"A friend has strong doubts about your childfree plan.","setup":"She brings it up again over coffee.","steps":[{"prompt":"She says: \"Come on, isn't this childfree thing just a phase?\"","options":[{"text":"\"It isn't a phase for me. I've thought about it honestly, and I'd love your respect.\"","then":"She pauses, and nods. \"Okay. I hear you,\" she says.","best":true},{"text":"\"Maybe you're right. Maybe it really is just a phase.\"","then":"She takes that as confirmation and brings it up again soon."},{"text":"\"Why can't you just accept my decision as it is?\"","then":"The coffee turns a little tense, and the point gets lost."},{"text":"\"I don't really want to talk about this right now.\"","then":"She assumes the silence means you're still deciding."}],"why":"Naming your choice as considered, not a phase, and asking to be respected, is honest and clear."},{"prompt":"She adds: \"I just don't want you to regret it later. That's all.\"","options":[{"text":"\"I understand you're worried, and I've thought this through carefully.\"","then":"She softens, and the conversation feels less like an argument.","best":true},{"text":"\"Maybe I will regret it one day. Who really knows.\"","then":"The worry starts to sound louder than it did a moment ago."},{"text":"\"That's really not your call to worry about, honestly.\"","then":"She looks stung, though she meant it as care."},{"text":"\"You might be right. I haven't really thought it through enough yet.\"","then":"Doubt creeps into a choice that was actually settled."}],"why":"Naming her worry as care, while staying steady, keeps the conversation calm."},{"prompt":"Weeks later, half-joking, she says: \"Still not a phase, huh?\"","options":[{"text":"\"It's not a phase, and I'd like that respected.\"","then":"She laughs a little. \"Fair enough, I'll stop,\" she says.","best":true},{"text":"\"I know, I know. Maybe I'll change eventually. Who really knows.\"","then":"She takes it as a promise and keeps expecting an update."},{"text":"\"Why do you keep bringing this up over and over?\"","then":"She looks a little taken aback, though she meant it lightly."},{"text":"\"Maybe you have a point after all, come to think of it.\"","then":"A settled choice starts to feel uncertain again, just from hearing it enough times."}],"why":"The same steady answer, repeated kindly, is what finally makes the joke stop."}],"relearn":"You can name your choice as considered, not a phase, and ask plainly to be respected."},
  {"id":"iw-941","cat":"whether-and-why","type":"role-play","persona":"Karthik","source":"or just drifting","hook":"Your partner seems suddenly unsettled about the question of having children.","setup":"She looks at you, waiting, a little nervous.","steps":[{"prompt":"She asks: \"Be honest: are we choosing this, or just drifting into it?\"","options":[{"text":"\"Let's decide this together, honestly, not just drift into it.\"","then":"She relaxes a little. \"Yes, let's do that,\" she says.","best":true},{"text":"\"Let's not overthink this. It'll just happen on its own, surely.\"","then":"She looks unsettled. \"That's exactly what worries me,\" she says."},{"text":"\"Of course I want them. Why would you even ask?\"","then":"She's not sure the quick answer was really thought through."},{"text":"\"Honestly, I haven't really thought about it much.\"","then":"She's left uncertain where you actually stand."}],"why":"Choosing together, honestly, beats drifting into a decision this big."},{"prompt":"She asks: \"What would it look like for us to actually decide, then?\"","options":[{"text":"\"Sitting down, honestly, and asking each other what we really want.\"","then":"She nods. \"Okay. Let's start now,\" she says.","best":true},{"text":"\"I guess just going with the flow for a while longer.\"","then":"She's worried that's exactly the drifting she named."},{"text":"\"Maybe we ask our parents what they'd like to see.\"","then":"She goes quiet. \"I don't want their wishes to decide this for us,\" she says."},{"text":"\"Whatever feels easiest for the both of us, really.\"","then":"She's unsure 'easiest' is the same as 'honest' here."}],"why":"Sitting down and asking each other honestly is what actually replaces drifting."},{"prompt":"A few days later, she asks: \"What have you actually been thinking?\"","options":[{"text":"\"I've been honestly sitting with it, and want to keep talking.\"","then":"She smiles. \"That actually helps,\" she says.","best":true},{"text":"\"I've decided yes, since that felt simpler for us.\"","then":"She's surprised by the sudden certainty, and not sure what led there."},{"text":"\"I haven't really had time to think about it yet.\"","then":"She wonders if the conversation is quietly stalling again."},{"text":"\"Whatever you've decided already is fine with me.\"","then":"She's left holding a decision meant to be shared."}],"why":"Staying honestly in the process is what keeps the conversation real, not rushed."},{"prompt":"She checks in again: \"How are you feeling about all this now?\"","options":[{"text":"\"Settled on choosing together. I'll say if that changes.\"","then":"She nods. \"Let's keep checking in like this,\" she says, relieved the drift has stopped.","best":true},{"text":"\"Fine, so we don't need to keep discussing it further.\"","then":"The conversation you two had begun quietly stops there."},{"text":"\"Fine, whatever you feel is what I feel.\"","then":"She wonders whose feelings she's really hearing."},{"text":"\"Let's just let it happen naturally from here on.\"","then":"The drifting she was worried about creeps back in."}],"why":"Saying where you are, and promising to say when it changes, keeps the decision shared."}],"relearn":"Choosing together, honestly, beats drifting; you can invite the real conversation instead of dodging it."},
  {"id":"iw-942","cat":"whether-and-why","type":"role-play","persona":"Razia","source":"defend her years","hook":"A relative confronts your sister about being single, right in front of you.","setup":"You've barely said hello when it happens.","steps":[{"prompt":"The relative says: \"You're wasting your best years, being single like this.\"","options":[{"text":"\"She's living a full life on her own terms.\"","then":"The relative pauses, unsure how to respond to that.","best":true},{"text":"\"Yeah, she really should think about settling down soon.\"","then":"Your sister's face falls, hearing you agree in front of everyone."},{"text":"\"That's a really unkind thing to say to her.\"","then":"The exchange turns tense, and the room feels awkward."},{"text":"\"She's just really focused on her career right now.\"","then":"The relative nods, as if a career excuse makes the single life acceptable."}],"why":"Naming her life as full and on her own clock defends her without a fight."},{"prompt":"Your sister pulls you aside afterward and asks: \"Do you think she's right?\"","options":[{"text":"\"Not at all. Your life is full exactly as it already is.\"","then":"She exhales. Whatever you thought before, hearing this now is what she needed.","best":true},{"text":"\"Of course not, but maybe you could think about it more.\"","then":"The mixed message leaves her unsure where you really stand."},{"text":"\"Let's not make a scene. It's just family talking.\"","then":"She's left wondering if you'd defend her again if it mattered."},{"text":"\"Don't worry about what they say, honestly, ever.\"","then":"She half-smiles, though she's still not sure where you actually stand."}],"why":"A clear, unmixed answer actually reassures her she's not alone in this."},{"prompt":"At the next gathering, the same relative says: \"Still no news of her settling down?\"","options":[{"text":"\"Her life is complete, and it's hers to live.\"","then":"The relative finally seems to drop the subject for good.","best":true},{"text":"\"Maybe give it a rest this time, for the family's sake.\"","then":"The relative takes that as room to try again later."},{"text":"\"Are you really bringing this up again, honestly?\"","then":"The moment turns tense, and the real point gets lost."},{"text":"\"She'll settle down eventually. I'm sure of it.\"","then":"The relative smiles, taking it as a sign she was right all along."}],"why":"The same firm answer, held consistently, finally settles the testing."},{"prompt":"Later, your sister asks: \"Did that seem fair to you?\"","options":[{"text":"\"Your worth was never on their timeline to begin with.\"","then":"She relaxes, relieved to hear you say it so plainly.","best":true},{"text":"\"Family just worries too much sometimes, honestly.\"","then":"It softens the relative's comment more than you meant to."},{"text":"\"I just didn't want things to get awkward.\"","then":"She wonders if your support depends on how loud the pressure gets."},{"text":"\"I hope they just stop asking about it eventually.\"","then":"She nods, though she's the one still facing the questions each time."}],"why":"Naming her worth as never tied to a timeline is real, lasting support."}],"relearn":"You can stand up for a single, childfree life as full, since her worth has no expiry date."},
  {"id":"iw-943","cat":"whether-and-why","type":"role-play","persona":"any","source":"family complete comeback","hook":"At a festival, an old debate about family comes up again.","setup":"The comment lands in front of a few relatives.","steps":[{"prompt":"Someone says: \"A family isn't complete without a baby, you know.\"","options":[{"text":"\"Our family already feels complete. A child would be a choice we add.\"","then":"They pause, and the comment doesn't quite land as expected.","best":true},{"text":"\"I suppose you're right. We do feel something's missing.\"","then":"The relative nods, satisfied their point was proven."},{"text":"\"That's a really outdated way to think about family.\"","then":"The exchange turns sharper than the festival mood invites."},{"text":"\"We're still figuring that whole part out, honestly.\"","then":"The relative treats 'figuring out' as agreement in progress."}],"why":"Naming the family as already complete answers the comment without defending it."},{"prompt":"Another relative adds: \"You'll understand once you have one of your own.\"","options":[{"text":"\"Maybe, but a family can already feel whole without one.\"","then":"They shrug, unconvinced but not pushing further.","best":true},{"text":"\"You're probably right. We haven't experienced it yet.\"","then":"The comment plants a small doubt that wasn't there a moment ago."},{"text":"\"How would you even know what I'll end up feeling?\"","then":"The exchange gets a little heated for a festival gathering."},{"text":"\"Sure, maybe someday. Who really knows for certain.\"","then":"It's taken as agreement rather than the deflection you meant."}],"why":"Naming that your family doesn't need one to feel whole holds the line."},{"prompt":"Later, a cousin quietly asks: \"Do the comments actually bother you?\"","options":[{"text":"\"Some days, some not. Either way, we're complete.\"","then":"She nods. \"You're right about that,\" she says.","best":true},{"text":"\"Honestly, sometimes I wonder if they have a point.\"","then":"A steady feeling starts to waver under the weight of others."},{"text":"\"Not really. I just ignore it and move right along.\"","then":"She nods and asks nothing more, though the topic will be back next year."},{"text":"\"It's fine. I'm used to it by now, every single year.\"","then":"She frowns, unsure whether 'used to it' means fine."}],"why":"Checking in honestly with yourself keeps a steady feeling actually true."},{"prompt":"At the next festival, the same relative says: \"Still no baby news, then?\"","options":[{"text":"\"Our family is complete. A child would be a choice we'd add, not a piece we're missing.\"","then":"The relative finally seems to accept it and moves on.","best":true},{"text":"\"Maybe you're onto something after all, now that I think about it.\"","then":"A choice that felt settled starts to feel uncertain again."},{"text":"\"Can we please not do this every single year, honestly?\"","then":"The comment lingers a little longer than the tension itself."},{"text":"\"Sure, sure, whatever you say, if that's what you think.\"","then":"The relative takes that as tacit agreement and repeats it."}],"why":"The same calm answer, held consistently, finally settles the yearly comment."}],"relearn":"A family is complete in many forms; you can say a child is a choice you'd add, not the missing piece."},
  {"id":"iw-944","cat":"whether-and-why","type":"role-play","persona":"Razia","source":"won't convince her","hook":"Your brother pulls you aside with an awkward request about his wife.","setup":"The family is gathering for dinner, and he keeps his voice low.","steps":[{"prompt":"He says: \"Can you talk to her? Convince her to have kids sooner?\"","options":[{"text":"\"That's between the two of you to decide.\"","then":"He looks a little disappointed, but doesn't argue back.","best":true},{"text":"\"Sure, I'll have a word and bring her around to it.\"","then":"He's relieved, and now expects you to actually deliver."},{"text":"\"Why can't you just talk to her about it yourself?\"","then":"He gets defensive, feeling the question turned on him."},{"text":"\"I'll see what I can do, I suppose, when I get a chance.\"","then":"He treats that as a soft yes and checks in with you later."}],"why":"Declining to be recruited as pressure keeps the decision theirs, not yours to push."},{"prompt":"He adds: \"I just think she's overthinking it, honestly.\"","options":[{"text":"\"Maybe, or maybe she's thinking it through. Either way, it's for you two.\"","then":"He pauses, and seems to actually consider that.","best":true},{"text":"\"You might be right. She does seem a bit hesitant.\"","then":"He nods, taking it as confirmation of his own doubt about her."},{"text":"\"That's a bit unfair to say about her, honestly.\"","then":"The conversation turns a little tense between you two."},{"text":"\"I don't really know what's going on in her head.\"","then":"He takes the shrug as an opening to keep pushing you."}],"why":"Naming that it's theirs to decide, either way, refuses to echo a doubt."},{"prompt":"At dinner, he leans over and says: \"Say something to her tonight, will you?\"","options":[{"text":"\"It's between the two of you, and I won't push her.\"","then":"He drops the subject, at least for the rest of the evening.","best":true},{"text":"\"Maybe just a gentle word wouldn't really hurt, though.\"","then":"He takes that as an opening and keeps waiting for you to act."},{"text":"\"Can we please not do this at the dinner table?\"","then":"The moment feels tense, though the real request goes unanswered."},{"text":"\"Fine, I'll mention it to her sometime, I suppose.\"","then":"He now expects an update, and the pressure has shifted to you."}],"why":"A calm, firm boundary, however often the request comes, settles it."},{"prompt":"His wife pulls you aside and asks: \"Have you heard anything? I feel like everyone's on me about this.\"","options":[{"text":"\"He asked me to push. It's for you two, and you're doing nothing wrong. I'm here.\"","then":"She exhales, relieved to hear it from you, and says she'd like to talk it through.","best":true},{"text":"\"It's fine. I just didn't want to get involved.\"","then":"It sounds neutral, but she's not sure where you actually stand."},{"text":"\"Maybe hear him out. He does want this so much.\"","then":"She feels the weight of his wish land on her instead."},{"text":"\"It's probably just his nerves. It'll pass.\"","then":"She feels brushed off, and decides not to bring it up again."}],"why":"Being honest about the ask, backing her choice and offering to listen is real support."}],"relearn":"You can refuse to be recruited as pressure; whether and when is the couple's own decision."},
  {"id":"iw-945","cat":"whether-and-why","type":"match","hook":"Lensy: match each honest answer about children to what it truly is.","pairs":[{"left":"\"Yes, we want to\"","right":"A valid, joyful path"},{"left":"\"No, we're childfree\"","right":"An equally complete life"},{"left":"\"Not yet, maybe later\"","right":"A fine place to be, no rush"},{"left":"\"We'll build family another way\"","right":"A real, chosen route"},{"left":"\"Still honestly deciding\"","right":"Reflection, not a failing"}],"relearn":"Yes, childfree, not-yet, another-way and still-deciding are each valid; none is a failure.","persona":"any","source":"answers to truth"},
  {"id":"iw-946","cat":"whether-and-why","type":"match","hook":"Lensy: match each pressuring line to the calm truth that answers it.","pairs":[{"left":"\"You'll regret it someday\"","right":"Regret isn't guaranteed in any direction"},{"left":"\"You'll change your mind\"","right":"My choice is valid as it stands now"},{"left":"\"A woman is incomplete without kids\"","right":"Womanhood is not motherhood"},{"left":"\"It's the obvious next step\"","right":"It's a separate, deliberate choice"},{"left":"\"Everyone has kids eventually\"","right":"A default isn't the same as a decision"}],"relearn":"Each pressuring line has a calm truth: regret isn't certain, my choice is valid, a default isn't a decision.","persona":"Sneha","source":"pressure to truth"},
  {"id":"iw-947","cat":"whether-and-why","type":"match","hook":"Lensy: match who actually owns this choice, and who doesn't.","pairs":[{"left":"You and your partner","right":"The ones who decide"},{"left":"Relatives wanting grandchildren","right":"A wish, not a vote"},{"left":"Neighbours and gossip","right":"No say at all"},{"left":"Society's 'everyone does it'","right":"A default, not a decision"},{"left":"The 'good news' chorus","right":"Owed no answer"}],"relearn":"You and your partner decide; relatives, neighbours, society and the chorus get a wish at most, not a say.","persona":"any","source":"who owns the choice"},
  {"id":"iw-948","cat":"whether-and-why","type":"match","hook":"Lensy: match each life path to the truth that fits it.","pairs":[{"left":"A childfree life","right":"Complete and valid"},{"left":"A single life by choice","right":"A full life, not a wait"},{"left":"A life still deciding","right":"No rush, no deadline"},{"left":"A divorced, childfree life","right":"Whole, never a leftover"},{"left":"A life choosing another way","right":"A real route to family"}],"relearn":"Childfree, single, deciding, divorced and another-way lives are each whole, never waiting rooms or leftovers.","persona":"Sneha","source":"path to truth"},
  {"id":"iw-949","cat":"whether-and-why","type":"match","hook":"Lensy: match each worry about deciding to the calm reframe that answers it.","pairs":[{"left":"\"I must be totally sure first\"","right":"Readiness is reflection, not perfection"},{"left":"\"If I say no now, that's final\"","right":"The choice can be revisited later"},{"left":"\"Everyone's judging my answer\"","right":"No answer is owed to anyone"},{"left":"\"I should want what others want\"","right":"This is yours and your partner's call"},{"left":"\"Choosing feels selfish\"","right":"Living your real life harms no one"}],"relearn":"Readiness is reflection, the choice can be revisited, no answer is owed, and it's your call, not selfish.","persona":"any","source":"worry to reframe"},
  {"id":"iw-950","cat":"whether-and-why","type":"match","hook":"Lensy: match each reason behind the choice to whether it's truly yours or someone else's.","pairs":[{"left":"\"It fits the life we want\"","right":"A reason that's truly yours"},{"left":"\"The family is waiting\"","right":"Someone else's agenda"},{"left":"\"We've thought it through together\"","right":"A choice you both own"},{"left":"\"People will talk otherwise\"","right":"Other people's opinion"},{"left":"\"We're ready in our own way\"","right":"Your own honest readiness"}],"relearn":"'It fits us' and 'we're ready our way' are your reasons; 'family is waiting' and 'people will talk' are not.","persona":"any","source":"yours or theirs"},
  {"id":"iw-951","cat":"whether-and-why","type":"spot","hook":"Lensy: spot the two lines that pressure your choice instead of respecting it.","scene":[{"id":"a","text":"\"Whatever you both decide, we support you.\"","trick":false},{"id":"b","text":"\"You're not getting any younger, hurry up.\"","trick":true},{"id":"c","text":"\"Take all the time you need.\"","trick":false},{"id":"d","text":"\"A marriage is meaningless without kids.\"","trick":true},{"id":"e","text":"\"It's completely your call.\"","trick":false}],"why":"'Hurry up, you're not younger' and 'meaningless without kids' are pressure; the rest respect your choice.","relearn":"Lines that rush you or call your life meaningless are pressure; real support leaves the choice yours.","persona":"any","source":"spot the pressure"},
  {"id":"iw-952","cat":"whether-and-why","type":"spot","hook":"Lensy: spot the two lines that wrongly frame a childfree life as a failure.","scene":[{"id":"a","text":"\"A childfree life can be full and happy.\"","trick":false},{"id":"b","text":"\"Poor thing, no children to show for it.\"","trick":true},{"id":"c","text":"\"Womanhood isn't the same as motherhood.\"","trick":false},{"id":"d","text":"\"She's incomplete until she's a mother.\"","trick":true},{"id":"e","text":"\"Not wanting kids is a valid choice.\"","trick":false}],"why":"'Poor thing' and 'incomplete until a mother' frame childfree as failure; the others affirm it as valid.","relearn":"'Poor thing' and 'incomplete' are pressure's false frames; a childfree life is full and valid.","persona":"Sneha","source":"spot false frame"},
  {"id":"iw-953","cat":"whether-and-why","type":"spot","hook":"Lensy: spot the two replies that dismiss someone's childfree choice instead of respecting it.","scene":[{"id":"a","text":"\"That's a valid choice. I respect it.\"","trick":false},{"id":"b","text":"\"You'll change your mind, everyone does.\"","trick":true},{"id":"c","text":"\"Thanks for trusting me with this.\"","trick":false},{"id":"d","text":"\"You'll end up lonely and regret it.\"","trick":true},{"id":"e","text":"\"Your choice, your call, fully.\"","trick":false}],"why":"'You'll change your mind' and 'you'll end up lonely' dismiss the choice; the others respect it.","relearn":"'You'll change your mind' and 'you'll be lonely' dismiss a choice; respecting it means taking it as it stands.","persona":"Sneha","source":"spot dismissal"},
  {"id":"iw-954","cat":"whether-and-why","type":"spot","hook":"Lensy: spot the two beliefs that treat children as a default, not a choice.","scene":[{"id":"a","text":"\"Whether to have kids is a real decision.\"","trick":false},{"id":"b","text":"\"After marriage, a baby just naturally follows.\"","trick":true},{"id":"c","text":"\"A default isn't the same as a decision.\"","trick":false},{"id":"d","text":"\"Loving each other means kids are inevitable.\"","trick":true},{"id":"e","text":"\"You can choose either way, honestly.\"","trick":false}],"why":"'A baby just follows' and 'kids are inevitable' treat children as a default; the others keep it a choice.","relearn":"Treating children as an automatic 'next step' is the default myth; whether is a real choice.","persona":"any","source":"spot the default"},
  {"id":"iw-955","cat":"whether-and-why","type":"spot","hook":"Lensy: spot the two lines that try to decide this for you instead of leaving it yours.","scene":[{"id":"a","text":"\"This is yours and your partner's to decide.\"","trick":false},{"id":"b","text":"\"It's the family's right to decide when you have kids.\"","trick":true},{"id":"c","text":"\"No one else gets a vote on this.\"","trick":false},{"id":"d","text":"\"You owe your in-laws a grandchild.\"","trick":true},{"id":"e","text":"\"Take your time; it's your call.\"","trick":false}],"why":"'The family's right to decide' and 'you owe a grandchild' steal the choice; the rest keep it yours.","relearn":"No one else owns this choice; 'the family decides' and 'you owe a grandchild' are false.","persona":"Razia","source":"spot who decides"},
  {"id":"iw-956","cat":"whether-and-why","type":"spot","hook":"Lensy: spot the two lines that turn 'still deciding' into a fault instead of a fine place to be.","scene":[{"id":"a","text":"\"Taking time to decide is completely fine.\"","trick":false},{"id":"b","text":"\"Still unsure? Something must be wrong with you.\"","trick":true},{"id":"c","text":"\"You can revisit this choice later.\"","trick":false},{"id":"d","text":"\"You've waited too long; it's basically settled now.\"","trick":true},{"id":"e","text":"\"Reflection isn't a failing.\"","trick":false}],"why":"'Something must be wrong' and 'you've waited too long' fault deciding; the others let it be fine.","relearn":"Still deciding is a fine place to be; 'something's wrong' and 'too late' are false pressure.","persona":"any","source":"spot deciding-as-fault"},
  {"id":"iw-957","cat":"whether-and-why","type":"spot","hook":"Lensy: spot the two lines that pressure a man into fatherhood as proof of being a man.","scene":[{"id":"a","text":"\"Whether to be a father is your choice too.\"","trick":false},{"id":"b","text":"\"A man isn't complete until he has a son.\"","trick":true},{"id":"c","text":"\"Manhood isn't measured by fatherhood.\"","trick":false},{"id":"d","text":"\"Real men carry on the family line, no excuses.\"","trick":true},{"id":"e","text":"\"You and your partner decide this together.\"","trick":false}],"why":"'Not complete without a son' and 'real men carry the line' pressure fatherhood; the rest leave it free.","relearn":"Manhood isn't proven by fatherhood; whether to have children is a man's free choice.","persona":"Karthik","source":"spot manhood pressure"},
];

